import { INITIAL_MARKETS } from './constants';

// Default Settings
const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: ""
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'glass' | 'dark' | 'win10' | 'light'>('win10');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>(INITIAL_MARKETS);
  const [isConnected, setIsConnected] = useState(false);

  // Realtime Listeners
  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    const unsubscribeSettings = onValue(settingsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) setSettings(data);
    });

    const unsubscribeMarkets = onValue(marketsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setMarkets(Object.values(data));
      } else {
         setMarkets(INITIAL_MARKETS);
      }
    });

    const unsubscribeConnected = onValue(connectedRef, (snap) => {
        setIsConnected(!!snap.val());
    });

    return () => {
        unsubscribeSettings();
        unsubscribeMarkets();
        unsubscribeConnected();
    };
  }, []);

  const handleLogout = () => {
    setUser(null);
  };

  if (!user) {
    return <Login onLogin={setUser} theme={theme} />;
  }

  // Dynamic Theme Classes
  const getThemeClasses = () => {
    switch(theme) {
        case 'glass': return "bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 min-h-screen text-white";
        case 'dark': return "bg-gray-900 text-white min-h-screen";
        case 'win10': return "bg-[#0078D7] min-h-screen font-sans";
        default: return "bg-gray-100 text-gray-800 min-h-screen";
    }
  };

  const getContainerClasses = () => {
      switch(theme) {
          case 'glass': return "glass rounded-xl shadow-2xl";
          case 'dark': return "bg-gray-800 border border-gray-700 rounded-lg";
          case 'win10': return "bg-white text-black shadow-lg rounded-none border-2 border-[#005a9e]";
          default: return "bg-white shadow-lg rounded-lg";
      }
  };

  return (
    <div className={`${getThemeClasses()} flex flex-col overflow-hidden`}>
      {/* Ticker */}
      {settings.tickerEnabled && (
        <div className="bg-black text-yellow-400 py-1 overflow-hidden whitespace-nowrap border-b border-yellow-600">
           <div className="animate-marquee inline-block px-4">
              {settings.tickerText}
           </div>
        </div>
      )}

      {/* Header */}
      <header className={`p-4 flex justify-between items-center ${theme === 'glass' ? 'bg-white/10' : theme === 'dark' ? 'bg-gray-800' : 'bg-white text-black shadow-md'}`}>
        <div className="flex items-center gap-4">
            <h1 className="text-2xl font-bold">{settings.appName}</h1>
            <div className={`flex items-center gap-1 text-xs px-2 py-1 rounded-full ${isConnected ? 'bg-green-500/20 text-green-600' : 'bg-red-500/20 text-red-600'}`} title={isConnected ? "متصل بالخادم" : "غير متصل"}>
                {isConnected ? <Wifi size={14} /> : <WifiOff size={14} />}
                <span className="hidden md:inline">{isConnected ? "متصل" : "غير متصل"}</span>
            </div>
        </div>
        <div className="flex items-center gap-4">
            {settings.whatsappNumber && (
                <a href={`https://wa.me/${settings.whatsappNumber}`} target="_blank" rel="noreferrer" className="flex items-center gap-2 bg-green-500 hover:bg-green-600 text-white px-3 py-1 rounded-full transition">
                    <Phone size={18} />
                    <span>تواصل واتس آب</span>
                </a>
            )}
            <div className="text-sm">
                مرحباً، <span className="font-bold">{user.name}</span>
            </div>
            <button onClick={handleLogout} className="text-red-500 hover:text-red-700">
                <LogOut size={20} />
            </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden">
        {/* Sidebar */}
        <Sidebar 
            currentView={currentView} 
            setView={setCurrentView} 
            user={user} 
            theme={theme}
            containerClass={theme === 'glass' ? 'bg-white/10 backdrop-blur-md' : theme === 'dark' ? 'bg-gray-800' : 'bg-gray-50 border-l border-gray-200'}
        />

        {/* Main Content */}
        <main className="flex-1 p-4 overflow-y-auto">
            <div className={`p-6 min-h-full ${getContainerClasses()} transition-all duration-300`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorPrices' && <CompetitorPrices user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorReports' && <CompetitorReports user={user} markets={markets} theme={theme} />}
                {currentView === 'settings' && (
                    <Settings 
                        user={user} 
                        settings={settings} 
                        markets={markets}
                        theme={theme} 
                        setTheme={setTheme}
                    />
                )}
            </div>
        </main>
      </div>

      <footer className="p-2 text-center text-xs opacity-70">
        مع تحيات المطور Amir Lamay
      </footer>

      <style>{`
        @keyframes marquee {
            0% { transform: translateX(100%); }
            100% { transform: translateX(-100%); }
        }
        .animate-marquee {
            animation: marquee 20s linear infinite;
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, SaleRecord } from '../types';
import { Trash2, Edit, FileSpreadsheet } from 'lucide-react';
import { exportToCSV, formatDate } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);

    // Filters
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    useEffect(() => {
        const salesRef = ref(db, 'sales');
        onValue(salesRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                const loadedSales: SaleRecord[] = Object.keys(data).map(key => ({
                    id: key,
                    ...data[key]
                }));
                setSales(loadedSales.sort((a, b) => b.timestamp - a.timestamp));
            } else {
                setSales([]);
            }
        });
    }, []);

    useEffect(() => {
        let result = sales;

        if (filterDate) {
            // Basic string match for date or ISO search
            result = result.filter(s => s.date.includes(filterDate) || new Date(s.timestamp).toISOString().slice(0,10) === filterDate);
        }
        if (filterEmployee) {
            result = result.filter(s => s.employeeName.includes(filterEmployee));
        }
        if (filterMarket) {
            result = result.filter(s => s.market === filterMarket);
        }

        // Removed restriction: Now all users can view all sales as requested.
        // if (!user.canViewAllSales && user.role !== 'admin') { ... }

        setFilteredSales(result);
    }, [sales, filterDate, filterEmployee, filterMarket, user]);

    const handleDelete = async (id: string) => {
        if (window.confirm("هل أنت متأكد من حذف هذا السجل؟")) {
            await remove(ref(db, `sales/${id}`));
        }
    };

    const handleExport = () => {
        const exportData = filteredSales.flatMap(sale => 
            (sale.items || []).map(item => ({
                "التاريخ": sale.date,
                "الماركت": sale.market,
                "الموظف": sale.employeeName,
                "الصنف": item.name,
                "السعر": item.price,
                "الكمية": item.qty,
                "الاجمالي": sale.total
            }))
        );
        exportToCSV(exportData, `Sales_Report_${new Date().toISOString().slice(0,10)}`);
    };

    const inputClass = "border p-2 rounded w-full text-black";

    return (
        <div className="space-y-4">
            <h2 className="text-2xl font-bold mb-4">سجل المبيعات</h2>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-white/5 p-4 rounded-lg">
                <input 
                    type="date" 
                    className={inputClass}
                    value={filterDate}
                    onChange={e => setFilterDate(e.target.value)}
                />
                <input 
                    type="text" 
                    placeholder="بحث باسم الموظف"
                    className={inputClass}
                    value={filterEmployee}
                    onChange={e => setFilterEmployee(e.target.value)}
                />
                <select 
                    className={inputClass}
                    value={filterMarket}
                    onChange={e => setFilterMarket(e.target.value)}
                >
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <button 
                    onClick={handleExport}
                    className="bg-green-600 text-white p-2 rounded flex justify-center items-center gap-2 hover:bg-green-700"
                >
                    <FileSpreadsheet /> تصدير اكسيل
                </button>
            </div>

            <div className="overflow-x-auto">
                {filteredSales.map(sale => (
                    <div key={sale.id} className={`mb-4 p-4 rounded-lg border ${theme === 'dark' ? 'bg-gray-800 border-gray-700' : 'bg-white border-gray-200 shadow'}`}>
                        <div className="flex justify-between items-center border-b pb-2 mb-2">
                            <div>
                                <span className="font-bold text-lg text-blue-500">{sale.market}</span>
                                <span className="mx-2 text-gray-400">|</span>
                                <span>{sale.date}</span>
                                <span className="mx-2 text-gray-400">|</span>
                                <span className="text-sm">بواسطة: {sale.employeeName}</span>
                            </div>
                            <div className="flex gap-2">
                                {(user.role === 'admin' || user.name === sale.employeeName) && (
                                    <button onClick={() => handleDelete(sale.id!)} className="text-red-500 hover:bg-red-100 p-1 rounded">
                                        <Trash2 size={18} />
                                    </button>
                                )}
                            </div>
                        </div>
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="opacity-50 text-right">
                                    <th>الصنف</th>
                                    <th>الكمية</th>
                                    <th>السعر</th>
                                </tr>
                            </thead>
                            <tbody>
                                {(sale.items || []).map((item, idx) => (
                                    <tr key={idx} className="border-b border-gray-100/10">
                                        <td className="py-1">{item.name}</td>
                                        <td>{item.qty}</td>
                                        <td>{item.price}</td>
                                    </tr>
                                ))}
                            </tbody>
                            <tfoot>
                                <tr className="font-bold">
                                    <td colSpan={2} className="pt-2 text-left pl-4">الاجمالي:</td>
                                    <td className="pt-2">{sale.total} ج.م</td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default SalesLog;

import React from 'react';
import { User } from '../types';
import { 
    ShoppingCart, FileText, PackagePlus, ClipboardList, 
    TrendingUp, BarChart2, Settings as SettingsIcon 
} from 'lucide-react';

interface SidebarProps {
    currentView: string;
    setView: (view: string) => void;
    user: User;
    theme: string;
    containerClass: string;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, user, theme, containerClass }) => {

    const menuItems = [
        { id: 'sales', label: 'المبيعات اليومية', icon: ShoppingCart },
        { id: 'salesLog', label: 'سجل المبيعات', icon: FileText },
        { id: 'inventoryReg', label: 'تسجيل المخزون', icon: PackagePlus },
        { id: 'inventoryLog', label: 'سجل المخزون', icon: ClipboardList },
        { id: 'competitorPrices', label: 'أسعار المنافسين', icon: TrendingUp },
        { id: 'competitorReports', label: 'تقارير المنافسين', icon: BarChart2 },
        { id: 'settings', label: 'الإعدادات', icon: SettingsIcon },
    ];

    const getButtonClass = (isActive: boolean) => {
        // Base classes for layout, spacing, and transition
        let classes = "group w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-300 ease-out font-medium relative overflow-hidden ";

        if (theme === 'win10') {
            classes += isActive 
                ? "bg-[#0078D7] text-white shadow-lg translate-x-2 " 
                : "text-gray-700 hover:bg-gray-200 hover:translate-x-1 ";
        } else if (theme === 'dark') {
            classes += isActive 
                ? "bg-blue-600 text-white shadow-lg shadow-blue-500/20 translate-x-2 ring-1 ring-blue-400/30 " 
                : "text-gray-400 hover:bg-gray-800 hover:text-gray-100 hover:translate-x-1 ";
        } else if (theme === 'glass') {
            classes += isActive 
                ? "bg-gradient-to-r from-white/20 to-white/5 text-white shadow-lg border-r-4 border-white backdrop-blur-md translate-x-2 " 
                : "text-white/80 hover:bg-white/10 hover:text-white hover:translate-x-1 ";
        } else {
            // Light/Default
             classes += isActive 
                ? "bg-white text-blue-700 shadow-md translate-x-2 border-r-4 border-blue-500 " 
                : "text-gray-600 hover:bg-white hover:shadow-sm hover:text-blue-900 hover:translate-x-1 ";
        }

        return classes;
    };

    const headerClass = `text-xs font-bold uppercase tracking-wider mb-6 px-2 ${
        theme === 'glass' ? 'text-white/50' : theme === 'dark' ? 'text-gray-500' : 'text-gray-400'
    }`;

    return (
        <aside className={`w-64 md:w-72 p-6 flex flex-col ${containerClass} transition-all duration-300`}>
            <div className={headerClass}>
                القائمة الرئيسية
            </div>
            <nav className="flex-1 flex flex-col gap-3">
                {menuItems.map(item => (
                    <button
                        key={item.id}
                        onClick={() => setView(item.id)}
                        className={getButtonClass(currentView === item.id)}
                    >
                        {/* Active Indicator for specific themes */}
                        {currentView === item.id && theme !== 'win10' && theme !== 'glass' && (
                             <div className="absolute right-0 top-1/2 -translate-y-1/2 h-6 w-1 bg-current rounded-l-full opacity-60" />
                        )}

                        <item.icon size={22} strokeWidth={1.5} className="flex-shrink-0" />
                        <span className="text-base tracking-wide">{item.label}</span>
                    </button>
                ))}
            </nav>

            <div className={`mt-auto text-xs px-2 pt-4 border-t ${theme === 'dark' ? 'border-gray-700 text-gray-500' : 'border-gray-200/20 text-gray-400'}`}>
                v1.0.0
            </div>
        </aside>
    );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings } from '../types';
import { Save, Trash2, UserPlus, Shield, Edit2, Plus, X } from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<any[]>([]);
    const [newUser, setNewUser] = useState({ name: '', username: '', password: '', role: 'user', code: '', phone: '', canViewAllSales: false });

    // Lists Management
    const [marketList, setMarketList] = useState<{key: string, val: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, val: string}[]>([]);
    const [newItemVal, setNewItemVal] = useState('');
    const [editingItem, setEditingItem] = useState<{key: string, val: string, type: 'market'|'company'} | null>(null);

    useEffect(() => {
        setLocalSettings(settings);
    }, [settings]);

    useEffect(() => {
        // Load Users
        if (user.role === 'admin') {
            onValue(ref(db, 'users'), snapshot => {
                if (snapshot.exists()) {
                    const u: any[] = [];
                    snapshot.forEach(c => { u.push({ key: c.key, ...c.val() }); });
                    setUsers(u);
                } else {
                    setUsers([]);
                }
            });
        }

        // Load Markets Keys
        onValue(ref(db, 'settings/markets'), snapshot => {
            if(snapshot.exists()){
                const m: any[] = [];
                snapshot.forEach(c => { m.push({key: c.key, val: c.val()}) });
                setMarketList(m);
            } else {
                setMarketList([]);
            }
        });

        // Load Companies Keys
        onValue(ref(db, 'settings/companies'), snapshot => {
            if(snapshot.exists()){
                const c: any[] = [];
                snapshot.forEach(k => { c.push({key: k.key, val: k.val()}) });
                setCompanyList(c);
            } else {
                setCompanyList([]);
            }
        });

    }, [user.role]);

    if (user.role !== 'admin') {
        return <div className="text-center p-10 text-red-500 font-bold text-xl">عذراً، هذه الصفحة للمسؤولين فقط.</div>;
    }

    // --- General Settings ---
    const saveSettings = async () => {
        await set(ref(db, 'settings/app'), localSettings);
        alert('تم حفظ الإعدادات');
    };

    // --- User Management ---
    const handleAddUser = async () => {
        if (!newUser.username || !newUser.password || !newUser.name) return alert("الرجاء ملء البيانات الأساسية");
        await push(ref(db, 'users'), newUser);
        setNewUser({ name: '', username: '', password: '', role: 'user', code: '', phone: '', canViewAllSales: false });
        alert("تم اضافة المستخدم");
    };

    const handleDeleteUser = async (key: string) => {
        if (confirm("حذف المستخدم؟")) {
            await remove(ref(db, `users/${key}`));
        }
    };

    // --- List Management (Markets/Companies) ---
    const handleAddListItem = async (type: 'market' | 'company') => {
        if(!newItemVal) return;
        const path = type === 'market' ? 'settings/markets' : 'settings/companies';
        await push(ref(db, path), newItemVal);
        setNewItemVal('');
    };

    const handleDeleteListItem = async (key: string, type: 'market' | 'company') => {
        if(!confirm("هل أنت متأكد من الحذف؟")) return;
        const path = type === 'market' ? 'settings/markets' : 'settings/companies';
        await remove(ref(db, `${path}/${key}`));
    };

    const startEditItem = (item: {key: string, val: string}, type: 'market'|'company') => {
        setEditingItem({ ...item, type });
    };

    const saveEditItem = async () => {
        if(!editingItem) return;
        const path = editingItem.type === 'market' ? 'settings/markets' : 'settings/companies';
        await set(ref(db, `${path}/${editingItem.key}`), editingItem.val);
        setEditingItem(null);
    };

    const inputClass = "w-full p-2 rounded border border-gray-300 text-black";
    const sectionClass = `p-6 rounded-lg mb-6 ${theme === 'dark' ? 'bg-gray-800 border border-gray-700' : 'bg-white shadow'}`;

    return (
        <div className="max-w-4xl mx-auto space-y-6 pb-10">
            <h2 className="text-3xl font-bold mb-6">الإعدادات</h2>

            {/* General Settings */}
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-4 border-b pb-2">إعدادات عامة</h3>
                <div className="grid grid-cols-1 gap-4">
                    <div>
                        <label className="block mb-1">اسم البرنامج</label>
                        <input 
                            className={inputClass} 
                            value={localSettings.appName}
                            onChange={e => setLocalSettings({...localSettings, appName: e.target.value})}
                        />
                    </div>
                    <div>
                        <label className="block mb-1">نص الشريط المتحرك</label>
                        <input 
                            className={inputClass} 
                            value={localSettings.tickerText}
                            onChange={e => setLocalSettings({...localSettings, tickerText: e.target.value})}
                        />
                    </div>
                    <div className="flex items-center gap-2">
                        <input 
                            type="checkbox" 
                            checked={localSettings.tickerEnabled}
                            onChange={e => setLocalSettings({...localSettings, tickerEnabled: e.target.checked})}
                            className="w-5 h-5"
                        />
                        <label>تفعيل الشريط المتحرك</label>
                    </div>
                    <div>
                        <label className="block mb-1">رقم الواتس آب</label>
                        <input 
                            className={inputClass} 
                            value={localSettings.whatsappNumber}
                            onChange={e => setLocalSettings({...localSettings, whatsappNumber: e.target.value})}
                            placeholder="مثال: 201xxxxxxxxx"
                        />
                    </div>
                </div>
                <button onClick={saveSettings} className="mt-4 bg-blue-600 text-white px-6 py-2 rounded flex items-center gap-2">
                    <Save size={18} /> حفظ الإعدادات
                </button>
            </div>

            {/* Lists Management */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Markets */}
                <div className={sectionClass}>
                    <h3 className="text-xl font-bold mb-4 border-b pb-2">إدارة الماركت</h3>
                    <div className="flex gap-2 mb-4">
                        <input 
                            className={inputClass} 
                            placeholder="اسم ماركت جديد" 
                            value={newItemVal} 
                            onChange={e => setNewItemVal(e.target.value)}
                        />
                        <button onClick={() => handleAddListItem('market')} className="bg-green-600 text-white p-2 rounded"><Plus/></button>
                    </div>
                    <ul className="max-h-60 overflow-y-auto space-y-2">
                        {marketList.map(m => (
                            <li key={m.key} className="flex justify-between items-center bg-black/10 p-2 rounded">
                                <span>{m.val}</span>
                                <div className="flex gap-2">
                                    <button onClick={() => startEditItem(m, 'market')} className="text-blue-500"><Edit2 size={16}/></button>
                                    <button onClick={() => handleDeleteListItem(m.key, 'market')} className="text-red-500"><Trash2 size={16}/></button>
                                </div>
                            </li>
                        ))}
                    </ul>
                </div>

                {/* Companies */}
                <div className={sectionClass}>
                    <h3 className="text-xl font-bold mb-4 border-b pb-2">إدارة الشركات</h3>
                    <div className="flex gap-2 mb-4">
                        <input 
                            className={inputClass} 
                            placeholder="اسم شركة جديد" 
                            id="companyInput"
                        />
                        <button onClick={() => {
                            const val = (document.getElementById('companyInput') as HTMLInputElement).value;
                            if(val) {
                                push(ref(db, 'settings/companies'), val);
                                (document.getElementById('companyInput') as HTMLInputElement).value = '';
                            }
                        }} className="bg-green-600 text-white p-2 rounded"><Plus/></button>
                    </div>
                    <ul className="max-h-60 overflow-y-auto space-y-2">
                        {companyList.map(c => (
                            <li key={c.key} className="flex justify-between items-center bg-black/10 p-2 rounded">
                                <span>{c.val}</span>
                                <div className="flex gap-2">
                                    <button onClick={() => startEditItem(c, 'company')} className="text-blue-500"><Edit2 size={16}/></button>
