import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, SaleRecord, ProductItem } from '../types';
import { Trash2, Edit, FileSpreadsheet, Save, X } from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [editingSale, setEditingSale] = useState<SaleRecord | null>(null);

    // Filters
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    useEffect(() => {
        const salesRef = ref(db, 'sales');
        onValue(salesRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                const loadedSales: SaleRecord[] = Object.keys(data).map(key => ({
                    id: key,
                    ...data[key]
                }));
                setSales(loadedSales.sort((a, b) => b.timestamp - a.timestamp));
            } else {
                setSales([]);
            }
        });
    }, []);

    useEffect(() => {
        let result = sales;

        if (filterDate) {
            result = result.filter(s => s.date.includes(filterDate) || new Date(s.timestamp).toISOString().slice(0,10) === filterDate);
        }
        if (filterEmployee) {
            result = result.filter(s => s.employeeName.includes(filterEmployee));
        }
        if (filterMarket) {
            result = result.filter(s => s.market === filterMarket);
        }

        setFilteredSales(result);
    }, [sales, filterDate, filterEmployee, filterMarket, user]);

    const handleDelete = async (id: string) => {
        if (window.confirm("هل أنت متأكد من حذف هذا السجل؟")) {
            await remove(ref(db, `sales/${id}`));
        }
    };

    const handleExport = () => {
        const exportData = filteredSales.flatMap(sale => 
            (sale.items || []).map(item => ({
                "التاريخ": sale.date,
                "الماركت": sale.market,
                "الموظف": sale.employeeName,
                "الصنف": item.name,
                "السعر": item.price,
                "الكمية": item.qty,
                "الاجمالي": sale.total
            }))
        );
        exportToCSV(exportData, `Sales_Report_${new Date().toISOString().slice(0,10)}`);
    };

    // --- Edit Logic ---
    const startEdit = (sale: SaleRecord) => {
        setEditingSale(JSON.parse(JSON.stringify(sale))); // Deep copy
    };

    const handleEditItemChange = (index: number, field: keyof ProductItem, value: any) => {
        if (!editingSale) return;
        const newItems = [...editingSale.items];
        // @ts-ignore
        newItems[index][field] = value;

        // Recalculate total
        const newTotal = newItems.reduce((sum, item) => sum + (Number(item.price) || 0), 0);

        setEditingSale({
            ...editingSale,
            items: newItems,
            total: newTotal
        });
    };

    const saveEdit = async () => {
        if (!editingSale || !editingSale.id) return;
        try {
            await update(ref(db, `sales/${editingSale.id}`), {
                items: editingSale.items,
                total: editingSale.total,
                market: editingSale.market // Allow market change if needed, but primarily items
            });
            setEditingSale(null);
            alert("تم تعديل الفاتورة بنجاح");
        } catch (e) {
            console.error(e);
            alert("حدث خطأ أثناء التعديل");
        }
    };

    const inputClass = "border p-2 rounded w-full text-black";

    return (
        <div className="space-y-4">
            <h2 className="text-2xl font-bold mb-4">سجل المبيعات</h2>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-white/5 p-4 rounded-lg">
                <input 
                    type="date" 
                    className={inputClass}
                    value={filterDate}
                    onChange={e => setFilterDate(e.target.value)}
                />
                <input 
                    type="text" 
                    placeholder="بحث باسم الموظف"
                    className={inputClass}
                    value={filterEmployee}
                    onChange={e => setFilterEmployee(e.target.value)}
                />
                <select 
                    className={inputClass}
                    value={filterMarket}
                    onChange={e => setFilterMarket(e.target.value)}
                >
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <button 
                    onClick={handleExport}
                    className="bg-green-600 text-white p-2 rounded flex justify-center items-center gap-2 hover:bg-green-700"
                >
                    <FileSpreadsheet /> تصدير اكسيل
                </button>
            </div>

            <div className="overflow-x-auto">
                {filteredSales.map(sale => (
                    <div key={sale.id} className={`mb-4 p-4 rounded-lg border ${theme === 'dark' ? 'bg-gray-800 border-gray-700' : 'bg-white border-gray-200 shadow'}`}>
                        <div className="flex justify-between items-center border-b pb-2 mb-2">
                            <div>
                                <span className="font-bold text-lg text-blue-500">{sale.market}</span>
                                <span className="mx-2 text-gray-400">|</span>
                                <span>{sale.date}</span>
                                <span className="mx-2 text-gray-400">|</span>
                                <span className="text-sm">بواسطة: {sale.employeeName}</span>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => startEdit(sale)} className="text-blue-500 hover:bg-blue-100 p-1 rounded">
                                    <Edit size={18} />
                                </button>
                                {(user.role === 'admin' || user.name === sale.employeeName) && (
                                    <button onClick={() => handleDelete(sale.id!)} className="text-red-500 hover:bg-red-100 p-1 rounded">
                                        <Trash2 size={18} />
                                    </button>
                                )}
                            </div>
                        </div>
                        <table className="w-full text-sm">
                            <thead>
                                <tr className="opacity-50 text-right">
                                    <th>الصنف</th>
                                    <th>الكمية</th>
                                    <th>السعر</th>
                                </tr>
                            </thead>
                            <tbody>
                                {(sale.items || []).map((item, idx) => (
                                    <tr key={idx} className="border-b border-gray-100/10">
                                        <td className="py-1">{item.name}</td>
                                        <td>{item.qty}</td>
                                        <td>{item.price}</td>
                                    </tr>
                                ))}
                            </tbody>
                            <tfoot>
                                <tr className="font-bold">
                                    <td colSpan={2} className="pt-2 text-left pl-4">الاجمالي:</td>
                                    <td className="pt-2">{sale.total} ج.م</td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                ))}
            </div>

            {/* Edit Modal */}
            {editingSale && (
                <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 overflow-y-auto p-4">
                    <div className={`w-full max-w-2xl rounded-lg shadow-2xl p-6 ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`}>
                        <div className="flex justify-between items-center mb-6 border-b pb-2">
                            <h3 className="text-xl font-bold">تعديل المبيعات - {editingSale.market}</h3>
                            <button onClick={() => setEditingSale(null)} className="text-gray-500 hover:text-red-500"><X /></button>
                        </div>

                        <div className="max-h-[60vh] overflow-y-auto space-y-2 mb-4">
                            {editingSale.items.map((item, idx) => (
                                <div key={idx} className="grid grid-cols-12 gap-2 items-center border-b pb-2 border-gray-500/20">
                                    <div className="col-span-6 text-sm font-bold">{item.name}</div>
                                    <div className="col-span-3">
                                        <label className="text-xs opacity-50 block">الكمية</label>
                                        <input 
                                            type="number" 
                                            value={item.qty} 
                                            onChange={e => handleEditItemChange(idx, 'qty', e.target.value)}
                                            className="w-full p-1 border rounded text-black bg-gray-50"
                                        />
                                    </div>
                                    <div className="col-span-3">
                                        <label className="text-xs opacity-50 block">السعر</label>
                                        <input 
                                            type="number" 
                                            value={item.price} 
                                            onChange={e => handleEditItemChange(idx, 'price', e.target.value)}
                                            className="w-full p-1 border rounded text-black bg-gray-50"
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="flex justify-between items-center pt-4 border-t">
                             <div className="font-bold text-lg">
                                الإجمالي الجديد: <span className="text-green-600">{editingSale.total} ج.م</span>
                             </div>
                             <div className="flex gap-2">
                                <button onClick={() => setEditingSale(null)} className="px-4 py-2 bg-gray-300 text-black rounded hover:bg-gray-400">إلغاء</button>
                                <button onClick={saveEdit} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 flex items-center gap-2"><Save size={16}/> حفظ التعديلات</button>
                             </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SalesLog;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, InventoryRecord } from '../types';
import { exportToCSV } from '../utils';
import { FileSpreadsheet, Trash2, Edit, Save, X } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const InventoryLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [logs, setLogs] = useState<InventoryRecord[]>([]);
    const [selectedMarket, setSelectedMarket] = useState('');
    const [editingLog, setEditingLog] = useState<InventoryRecord | null>(null);

    useEffect(() => {
        const invRef = ref(db, 'inventory');
        onValue(invRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                const arr = Object.keys(data).map(key => ({
                    id: key,
                    ...data[key]
                })) as InventoryRecord[];
                setLogs(arr.sort((a,b) => b.timestamp - a.timestamp));
            } else {
                setLogs([]);
            }
        });
    }, []);

    const filteredLogs = selectedMarket ? logs.filter(l => l.market === selectedMarket) : logs;

    const handleExport = () => {
        const data = filteredLogs.flatMap(log => 
            (log.items || []).map(item => ({
                "التاريخ": log.date,
                "الماركت": log.market,
                "بواسطة": log.employeeName,
                "الصنف": item.name,
                "الكمية": item.qty
            }))
        );
        exportToCSV(data, 'Inventory_Report');
    };

    const handleDelete = async (id: string) => {
        if(confirm("هل أنت متأكد من حذف هذا السجل؟")) {
            await remove(ref(db, `inventory/${id}`));
        }
    };

    const saveEdit = async () => {
        if(!editingLog || !editingLog.id) return;
        try {
            await update(ref(db, `inventory/${editingLog.id}`), {
                items: editingLog.items
            });
            setEditingLog(null);
            alert("تم تعديل المخزون");
        } catch (e) {
            console.error(e);
        }
    };

    const updateEditItem = (index: number, qty: number) => {
        if(!editingLog) return;
        const newItems = [...editingLog.items];
        newItems[index].qty = qty;
        setEditingLog({...editingLog, items: newItems});
    };

    return (
        <div className="space-y-4">
            <h2 className="text-2xl font-bold">سجل المخزون</h2>
            <div className="flex gap-4 mb-4">
                <select 
                    className="p-2 border rounded w-full md:w-1/3 text-black"
                    value={selectedMarket}
                    onChange={e => setSelectedMarket(e.target.value)}
                >
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <button onClick={handleExport} className="bg-green-600 text-white px-4 py-2 rounded flex items-center gap-2">
                    <FileSpreadsheet /> تصدير
                </button>
            </div>

            <div className="space-y-4">
                {filteredLogs.map((log, idx) => (
                    <div key={log.id} className={`p-4 rounded border ${theme === 'dark' ? 'bg-gray-800' : 'bg-white shadow'}`}>
                        <div className="flex justify-between font-bold border-b pb-2 mb-2 text-blue-500">
                            <div>
                                <span className="ml-2">{log.market}</span>
                                <span className="opacity-50 font-normal">| {log.date}</span>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => setEditingLog(log)} className="text-blue-500 hover:text-blue-700"><Edit size={18} /></button>
                                <button onClick={() => handleDelete(log.id!)} className="text-red-500 hover:text-red-700"><Trash2 size={18} /></button>
                            </div>
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-3 gap-2 text-sm">
                            {(log.items || []).map((item, i) => (
                                <div key={i} className="flex justify-between bg-black/5 p-1 rounded px-2">
                                    <span>{item.name}</span>
                                    <span className="font-bold">{item.qty}</span>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            {/* Edit Modal */}
            {editingLog && (
                <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 overflow-y-auto p-4">
                    <div className={`w-full max-w-lg rounded-lg shadow-2xl p-6 ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`}>
                        <div className="flex justify-between items-center mb-4 border-b pb-2">
                            <h3 className="font-bold text-xl">تعديل المخزون</h3>
                            <button onClick={() => setEditingLog(null)}><X /></button>
                        </div>
                        <div className="max-h-[60vh] overflow-y-auto space-y-2 mb-4">
                            {editingLog.items.map((item, idx) => (
                                <div key={idx} className="flex justify-between items-center p-2 border-b border-gray-100/10">
                                    <span>{item.name}</span>
                                    <input 
                                        type="number" 
                                        value={item.qty} 
                                        onChange={e => updateEditItem(idx, Number(e.target.value))}
                                        className="w-20 p-1 border rounded text-center text-black"
                                    />
                                </div>
                            ))}
                        </div>
                        <div className="flex justify-end gap-2">
                            <button onClick={() => setEditingLog(null)} className="px-4 py-2 bg-gray-500 text-white rounded">إلغاء</button>
                            <button onClick={saveEdit} className="px-4 py-2 bg-blue-600 text-white rounded flex items-center gap-2"><Save size={16}/> حفظ</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

