import React, { useState, useEffect } from 'react';
import { ref, push, set } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Plus, Trash2, Save } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [notification, setNotification] = useState('');

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
    ];

    const addNewRow = (category: string, defaultName: string = '') => {
        const newItem: ProductItem = {
            id: Date.now().toString() + Math.random(),
            category,
            name: defaultName,
            price: 0,
            qty: 0
        };
        setSalesItems(prev => [...prev, newItem]);
    };

    const handleAddProduct = (category: string) => {
        addNewRow(category, '');
    };

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        allCategories.forEach(cat => {
            cat.items.forEach(itemName => {
                initialItems.push({
                    id: itemName + Math.random(),
                    category: cat.key,
                    name: itemName,
                    price: 0,
                    qty: 0
                });
            });
        });
        setSalesItems(initialItems);
    }, []);


    const updateItem = (id: string, field: keyof ProductItem, value: any) => {
        setSalesItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const deleteItem = (id: string) => {
        setSalesItems(prev => prev.filter(item => item.id !== id));
    };

    // Updated Calculation Logic: Sum of (Unit Price * Quantity)
    const calculateTotal = () => {
        return salesItems.reduce((sum, item) => {
            const price = Number(item.price) || 0;
            const qty = Number(item.qty) || 0;
            return sum + (price * qty);
        }, 0);
    };

    const handleSave = async () => {
        if (!selectedMarket) {
            alert("الرجاء اختيار الماركت");
            return;
        }

        // Filter items where Total > 0 (Price > 0 AND Qty > 0)
        const soldItems = salesItems.filter(item => (Number(item.price) > 0 && Number(item.qty) > 0));

        if (soldItems.length === 0) {
            alert("لا يوجد مبيعات مكتملة (سعر وعدد) للحفظ");
            return;
        }

        const saleData = {
            market: selectedMarket,
            employeeName: user.name,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: soldItems,
            total: calculateTotal()
        };

        try {
            const newSaleRef = push(ref(db, 'sales'));
            await set(newSaleRef, saleData);
            setNotification('تم حفظ المبيعات بنجاح!');

            // Reset fields
            setSalesItems(prev => prev.map(item => ({...item, price: 0, qty: 0})));
            setTimeout(() => setNotification(''), 3000);
        } catch (error) {
            console.error(error);
            alert("حدث خطأ أثناء الحفظ");
        }
    };

    const handleAddMarket = async () => {
        const name = prompt("ادخل اسم الماركت الجديد:");
        if (name) {
             const newRef = push(ref(db, 'settings/markets'));
             await set(newRef, name);
        }
    };

    const inputClass = theme === 'win10' || theme === 'light' 
        ? "border border-gray-300 p-2 rounded w-full text-black" 
        : "bg-white/10 border border-white/20 p-2 rounded w-full text-white placeholder-gray-400";

    const sectionHeaderClass = "bg-gray-400 text-black font-bold p-2 rounded mt-4 mb-2 text-center shadow-sm";

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-2xl font-bold">المبيعات اليومية</h2>
                <div className="text-xl font-bold bg-green-500 text-white px-4 py-2 rounded shadow w-full md:w-auto text-center">
                    إجمالي الفاتورة: {calculateTotal().toLocaleString()} ج.م
                </div>
            </div>

            {/* Market Selection */}
            <div className="flex items-end gap-2">
                <div className="flex-1">
                    <label className="block mb-1 font-semibold">اسم الماركت</label>
                    <select 
                        value={selectedMarket} 
                        onChange={(e) => setSelectedMarket(e.target.value)}
                        className={inputClass}
                    >
                        <option value="">اختر الماركت...</option>
                        {markets.map((m, idx) => <option key={idx} value={m}>{m}</option>)}
                    </select>
                </div>
                <button onClick={handleAddMarket} className="bg-blue-500 hover:bg-blue-600 text-white p-2 rounded mb-[2px]">
                    <Plus size={24} />
                </button>
            </div>

            {/* Products Lists */}
            {allCategories.map(cat => (
                <div key={cat.key}>
                    <div className={sectionHeaderClass}>{cat.name}</div>

                    {/* Header Row - Updated Columns */}
                    <div className="grid grid-cols-12 gap-1 mb-2 font-bold opacity-70 text-xs md:text-sm px-1 text-center">
                        <div className="col-span-4 text-right pr-2">الصنف</div>
                        <div className="col-span-2">سعر القطعة</div>
                        <div className="col-span-2">العدد</div>
                        <div className="col-span-3">الإجمالي</div>
                        <div className="col-span-1"></div>
                    </div>

                    <div className="space-y-2">
                        {salesItems.filter(item => item.category === cat.key).map((item) => {
                            const rowTotal = (Number(item.price) || 0) * (Number(item.qty) || 0);

                            return (
                                <div key={item.id} className="grid grid-cols-12 gap-1 items-center bg-black/5 p-1 rounded">
                                    {/* Product Name */}
                                    <div className="col-span-4">
                                        {cat.items.includes(item.name) ? (
                                            <div className="p-2 text-xs md:text-sm font-medium leading-tight truncate" title={item.name}>{item.name}</div>
                                        ) : (
                                            <input 
                                                type="text" 
                                                value={item.name}
                                                onChange={(e) => updateItem(item.id, 'name', e.target.value)}
                                                className={`${inputClass} text-xs h-9`} 
                                                placeholder="اسم الصنف"
                                            />
                                        )}
                                    </div>

                                    {/* Unit Price */}
                                    <div className="col-span-2">
                                        <input 
                                            type="number" 
                                            value={item.price || ''} 
                                            onChange={(e) => updateItem(item.id, 'price', parseFloat(e.target.value))}
                                            className={`${inputClass} text-center h-9 text-xs`}
                                            placeholder="0"
                                        />
                                    </div>

                                    {/* Quantity */}
                                    <div className="col-span-2">
                                        <input 
                                            type="number" 
                                            value={item.qty || ''} 
                                            onChange={(e) => updateItem(item.id, 'qty', parseFloat(e.target.value))}
                                            className={`${inputClass} text-center h-9 text-xs`}
                                            placeholder="0"
                                        />
                                    </div>

                                    {/* Row Total (Read Only) */}
                                    <div className="col-span-3">
                                        <div className={`h-9 flex items-center justify-center font-bold text-xs md:text-sm rounded ${theme === 'light' ? 'bg-gray-200' : 'bg-white/10'}`}>
                                            {rowTotal > 0 ? rowTotal.toLocaleString() : '-'}
                                        </div>
                                    </div>

                                    {/* Delete Action */}
                                    <div className="col-span-1 flex justify-center">
                                        <button onClick={() => deleteItem(item.id)} className="text-red-500 hover:text-red-700 bg-red-100/50 p-1.5 rounded">
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                    <button 
                        onClick={() => handleAddProduct(cat.key)}
                        className="mt-2 text-sm bg-indigo-500/10 hover:bg-indigo-500 hover:text-white text-indigo-500 border border-indigo-500 px-3 py-1 rounded flex items-center gap-1 transition w-full md:w-auto justify-center"
                    >
                        <Plus size={14} /> اضف منتج
                    </button>
                </div>
            ))}

            <div className="mt-8 flex justify-center sticky bottom-4 z-10">
                <button 
                    onClick={handleSave}
                    className="bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-8 rounded-full shadow-xl flex items-center gap-2 text-lg transform hover:scale-105 transition w-full md:w-auto justify-center"
                >
                    <Save size={24} />
                    حفظ وترحيل
                </button>
            </div>

            {notification && (
                <div className="fixed bottom-4 left-4 right-4 md:right-auto bg-green-600 text-white px-6 py-3 rounded-lg shadow-lg animate-bounce text-center z-50">
                    {notification}
                </div>
            )}
        </div>
    );
};

export default DailySales;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, SaleRecord, ProductItem } from '../types';
import { Trash2, Edit, FileSpreadsheet, Save, X } from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [editingSale, setEditingSale] = useState<SaleRecord | null>(null);

    // Filters
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    useEffect(() => {
        const salesRef = ref(db, 'sales');
        onValue(salesRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                const loadedSales: SaleRecord[] = Object.keys(data).map(key => ({
                    id: key,
                    ...data[key]
                }));
                setSales(loadedSales.sort((a, b) => b.timestamp - a.timestamp));
            } else {
                setSales([]);
            }
        });
    }, []);

    useEffect(() => {
        let result = sales;

        if (filterDate) {
            result = result.filter(s => s.date.includes(filterDate) || new Date(s.timestamp).toISOString().slice(0,10) === filterDate);
        }
        if (filterEmployee) {
            result = result.filter(s => s.employeeName.includes(filterEmployee));
        }
        if (filterMarket) {
            result = result.filter(s => s.market === filterMarket);
        }

        setFilteredSales(result);
    }, [sales, filterDate, filterEmployee, filterMarket, user]);

    const handleDelete = async (id: string) => {
        if (window.confirm("هل أنت متأكد من حذف هذا السجل؟")) {
            await remove(ref(db, `sales/${id}`));
        }
    };

    const handleExport = () => {
        const exportData = filteredSales.flatMap(sale => 
            (sale.items || []).map(item => ({
                "التاريخ": sale.date,
                "الماركت": sale.market,
                "الموظف": sale.employeeName,
                "الصنف": item.name,
                "سعر القطعة": item.price,
                "العدد": item.qty,
                "الإجمالي للصنف": (Number(item.price) * Number(item.qty)) || 0,
                "اجمالي الفاتورة": sale.total
            }))
        );
        exportToCSV(exportData, `Sales_Report_${new Date().toISOString().slice(0,10)}`);
    };

    // --- Edit Logic ---
    const startEdit = (sale: SaleRecord) => {
        setEditingSale(JSON.parse(JSON.stringify(sale))); // Deep copy
    };

    const handleEditItemChange = (index: number, field: keyof ProductItem, value: any) => {
        if (!editingSale) return;
        const newItems = [...editingSale.items];
        // @ts-ignore
        newItems[index][field] = value;

        // Recalculate total based on (Price * Qty) logic
        const newTotal = newItems.reduce((sum, item) => sum + ((Number(item.price) || 0) * (Number(item.qty) || 0)), 0);

        setEditingSale({
            ...editingSale,
            items: newItems,
            total: newTotal
        });
    };

    const saveEdit = async () => {
        if (!editingSale || !editingSale.id) return;
        try {
            await update(ref(db, `sales/${editingSale.id}`), {
                items: editingSale.items,
                total: editingSale.total,
                market: editingSale.market 
            });
            setEditingSale(null);
            alert("تم تعديل الفاتورة بنجاح");
        } catch (e) {
            console.error(e);
            alert("حدث خطأ أثناء التعديل");
        }
    };

    const inputClass = "border p-2 rounded w-full text-black";

    return (
        <div className="space-y-4">
            <h2 className="text-2xl font-bold mb-4">سجل المبيعات</h2>

            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-white/5 p-4 rounded-lg">
                <input 
                    type="date" 
                    className={inputClass}
                    value={filterDate}
                    onChange={e => setFilterDate(e.target.value)}
                />
                <input 
                    type="text" 
                    placeholder="بحث باسم الموظف"
                    className={inputClass}
                    value={filterEmployee}
                    onChange={e => setFilterEmployee(e.target.value)}
                />
                <select 
                    className={inputClass}
                    value={filterMarket}
                    onChange={e => setFilterMarket(e.target.value)}
                >
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <button 
                    onClick={handleExport}
                    className="bg-green-600 text-white p-2 rounded flex justify-center items-center gap-2 hover:bg-green-700"
                >
                    <FileSpreadsheet /> تصدير اكسيل
                </button>
            </div>

            <div className="overflow-x-auto">
                {filteredSales.map(sale => (
                    <div key={sale.id} className={`mb-4 p-4 rounded-lg border ${theme === 'dark' ? 'bg-gray-800 border-gray-700' : 'bg-white border-gray-200 shadow'}`}>
                        <div className="flex justify-between items-center border-b pb-2 mb-2">
                            <div>
                                <span className="font-bold text-lg text-blue-500">{sale.market}</span>
                                <span className="mx-2 text-gray-400">|</span>
                                <span>{sale.date}</span>
                                <span className="mx-2 text-gray-400">|</span>
                                <span className="text-sm">بواسطة: {sale.employeeName}</span>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => startEdit(sale)} className="text-blue-500 hover:bg-blue-100 p-1 rounded">
                                    <Edit size={18} />
                                </button>
                                {(user.role === 'admin' || user.name === sale.employeeName) && (
                                    <button onClick={() => handleDelete(sale.id!)} className="text-red-500 hover:bg-red-100 p-1 rounded">
                                        <Trash2 size={18} />
                                    </button>
                                )}
                            </div>
                        </div>
                        <table className="w-full text-sm text-center">
                            <thead>
                                <tr className="opacity-50 border-b border-gray-500/20">
                                    <th className="text-right pb-2">الصنف</th>
                                    <th className="pb-2">سعر القطعة</th>
                                    <th className="pb-2">العدد</th>
                                    <th className="pb-2">الإجمالي</th>
                                </tr>
                            </thead>
                            <tbody>
                                {(sale.items || []).map((item, idx) => (
                                    <tr key={idx} className="border-b border-gray-100/10">
                                        <td className="py-2 text-right">{item.name}</td>
                                        <td>{item.price}</td>
                                        <td>{item.qty}</td>
                                        <td className="font-bold text-gray-500 dark:text-gray-400">
                                            {((Number(item.price) || 0) * (Number(item.qty) || 0)).toLocaleString()}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                            <tfoot>
                                <tr className="font-bold text-lg">
                                    <td colSpan={3} className="pt-2 text-left pl-4">إجمالي الفاتورة:</td>
                                    <td className="pt-2 text-green-600">{sale.total.toLocaleString()} ج.م</td>
                                </tr>
                            </tfoot>
                        </table>
                    </div>
                ))}
            </div>

            {/* Edit Modal */}
            {editingSale && (
                <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 overflow-y-auto p-4">
                    <div className={`w-full max-w-2xl rounded-lg shadow-2xl p-6 ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`}>
                        <div className="flex justify-between items-center mb-6 border-b pb-2">
                            <h3 className="text-xl font-bold">تعديل المبيعات - {editingSale.market}</h3>
                            <button onClick={() => setEditingSale(null)} className="text-gray-500 hover:text-red-500"><X /></button>
                        </div>

                        <div className="max-h-[60vh] overflow-y-auto space-y-2 mb-4">
                            <div className="grid grid-cols-12 gap-2 font-bold opacity-70 mb-2 px-1 text-center text-xs">
                                <div className="col-span-5 text-right">الصنف</div>
                                <div className="col-span-2">السعر</div>
                                <div className="col-span-2">العدد</div>
                                <div className="col-span-3">الاجمالي</div>
                            </div>
                            {editingSale.items.map((item, idx) => (
                                <div key={idx} className="grid grid-cols-12 gap-2 items-center border-b pb-2 border-gray-500/20">
                                    <div className="col-span-5 text-sm font-bold truncate">{item.name}</div>
                                    <div className="col-span-2">
                                        <input 
                                            type="number" 
                                            value={item.price} 
                                            onChange={e => handleEditItemChange(idx, 'price', e.target.value)}
                                            className="w-full p-1 border rounded text-black bg-gray-50 text-center text-sm"
                                            placeholder="سعر"
                                        />
                                    </div>
                                    <div className="col-span-2">
                                        <input 
                                            type="number" 
                                            value={item.qty} 
                                            onChange={e => handleEditItemChange(idx, 'qty', e.target.value)}
                                            className="w-full p-1 border rounded text-black bg-gray-50 text-center text-sm"
                                            placeholder="عدد"
                                        />
                                    </div>
                                    <div className="col-span-3 text-center text-sm font-bold">
                                        {((Number(item.price) || 0) * (Number(item.qty) || 0)).toLocaleString()}
                                    </div>
                                </div>
                            ))}
                        </div>

                        <div className="flex justify-between items-center pt-4 border-t">
                             <div className="font-bold text-lg">
                                الإجمالي الجديد: <span className="text-green-600">{editingSale.total.toLocaleString()} ج.م</span>
                             </div>
                             <div className="flex gap-2">
                                <button onClick={() => setEditingSale(null)} className="px-4 py-2 bg-gray-300 text-black rounded hover:bg-gray-400">إلغاء</button>
                                <button onClick={saveEdit} className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 flex items-center gap-2"><Save size={16}/> حفظ التعديلات</button>
                             </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SalesLog;

import React, { useState, useEffect } from 'react';
import { ref, push, set } from "firebase/database";
import { db } from '../firebase';
import { User } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

interface InventoryItem {
    id: string;
    name: string;
    qty: number;
    category: string;
    isCustom: boolean;
}

const InventoryRegistration: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [items, setItems] = useState<InventoryItem[]>([]);

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial', allowAdd: true },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen', allowAdd: true },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet', allowAdd: false },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin', allowAdd: true },
    ];

    useEffect(() => {
        const initItems: InventoryItem[] = [];
        allCategories.forEach(cat => {
            cat.items.forEach(prod => {
                initItems.push({
                    id: prod, // Use name as ID for standard items
                    name: prod,
                    qty: 0,
                    category: cat.key,
                    isCustom: false
                });
            });
        });
        setItems(initItems);
    }, []);

    const updateItem = (id: string, field: 'qty' | 'name', value: any) => {
        setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const handleAddCustomItem = (category: string) => {
        const customCount = items.filter(i => i.category === category && i.isCustom).length;
        if (customCount >= 20) {
            alert("لقد وصلت للحد الأقصى للإضافات (20 صنف)");
            return;
        }

        const newItem: InventoryItem = {
            id: `custom_${Date.now()}_${Math.random()}`,
            name: '',
            qty: 0,
            category,
            isCustom: true
        };
        setItems(prev => [...prev, newItem]);
    };

    const removeCustomItem = (id: string) => {
        setItems(prev => prev.filter(i => i.id !== id));
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");

        // Validation: Custom items must have names if qty > 0
        const invalidItems = items.filter(i => i.qty > 0 && i.isCustom && !i.name.trim());
        if (invalidItems.length > 0) return alert("يرجى كتابة اسم الأصناف المضافة التي لها كمية");

        const inventoryData = {
            market: selectedMarket,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: items.filter(i => i.qty > 0).map(i => ({
                name: i.name,
                qty: i.qty,
                category: i.category
            }))
        };

        if (inventoryData.items.length === 0) return alert("الكميات كلها صفر");

        try {
            await push(ref(db, 'inventory'), inventoryData);
            alert("تم حفظ المخزون");
            // Reset quantities only, keeping the form structure
            setItems(prev => prev.map(i => ({...i, qty: 0})));
        } catch (e) {
            console.error(e);
