import React from 'react';
import { User, AppSettings } from '../types';
import { 
    ShoppingCart, FileText, PackagePlus, ClipboardList, 
    TrendingUp, BarChart2, Settings as SettingsIcon, CalendarOff 
} from 'lucide-react';

interface SidebarProps {
    currentView: string;
    setView: (view: string) => void;
    user: User;
    theme: string;
    containerClass: string;
    settings: AppSettings;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, user, theme, containerClass, settings }) => {

    // Define all possible items
    const allItems = [
        { id: 'sales', label: 'المبيعات اليومية', icon: ShoppingCart, alwaysShow: true },
        { id: 'salesLog', label: 'سجل المبيعات', icon: FileText, permission: settings.permissions?.showSalesLog },
        { id: 'inventoryReg', label: 'تسجيل المخزون', icon: PackagePlus, permission: settings.permissions?.showInventoryReg },
        { id: 'inventoryLog', label: 'سجل المخزون', icon: ClipboardList, permission: settings.permissions?.showInventoryLog },
        { id: 'competitorPrices', label: 'أسعار المنافسين', icon: TrendingUp, alwaysShow: true },
        { id: 'competitorReports', label: 'تقارير المنافسين', icon: BarChart2, permission: settings.permissions?.showCompetitorReports },
        { id: 'leaveBalance', label: 'رصيد الإجازات', icon: CalendarOff, alwaysShow: true },
        { id: 'settings', label: 'الإعدادات', icon: SettingsIcon, adminOnly: true },
    ];

    // Filter items logic
    const menuItems = allItems.filter(item => {
        // Admin sees everything
        if (user.role === 'admin') return true;

        // If item is admin only, hide from users
        if (item.adminOnly) return false;

        // If item has a specific permission check
        if (item.permission !== undefined) {
            return item.permission === true;
        }

        // Default to showing items marked as alwaysShow (like DailySales)
        return true;
    });

    const getButtonClass = (isActive: boolean) => {
        // Base classes for layout, spacing, and transition
        let classes = "group w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-300 ease-out font-medium relative overflow-hidden ";

        if (theme === 'win10') {
            classes += isActive 
                ? "bg-[#0078D7] text-white shadow-lg translate-x-2 " 
                : "text-gray-700 hover:bg-gray-200 hover:translate-x-1 ";
        } else if (theme === 'dark') {
            classes += isActive 
                ? "bg-blue-600 text-white shadow-lg shadow-blue-500/20 translate-x-2 ring-1 ring-blue-400/30 " 
                : "text-gray-400 hover:bg-gray-800 hover:text-gray-100 hover:translate-x-1 ";
        } else if (theme === 'glass') {
            classes += isActive 
                ? "bg-gradient-to-r from-white/20 to-white/5 text-white shadow-lg border-r-4 border-white backdrop-blur-md translate-x-2 " 
                : "text-white/80 hover:bg-white/10 hover:text-white hover:translate-x-1 ";
        } else {
            // Light/Default
             classes += isActive 
                ? "bg-white text-blue-700 shadow-md translate-x-2 border-r-4 border-blue-500 " 
                : "text-gray-600 hover:bg-white hover:shadow-sm hover:text-blue-900 hover:translate-x-1 ";
        }

        return classes;
    };

    const headerClass = `text-xs font-bold uppercase tracking-wider mb-6 px-2 ${
        theme === 'glass' ? 'text-white/50' : theme === 'dark' ? 'text-gray-500' : 'text-gray-400'
    }`;

    return (
        <aside className={`w-64 md:w-72 p-6 flex flex-col ${containerClass} transition-all duration-300`}>
            <div className={headerClass}>
                القائمة الرئيسية
            </div>
            <nav className="flex-1 flex flex-col gap-3">
                {menuItems.map(item => (
                    <button
                        key={item.id}
                        onClick={() => setView(item.id)}
                        className={getButtonClass(currentView === item.id)}
                    >
                        {/* Active Indicator for specific themes */}
                        {currentView === item.id && theme !== 'win10' && theme !== 'glass' && (
                             <div className="absolute right-0 top-1/2 -translate-y-1/2 h-6 w-1 bg-current rounded-l-full opacity-60" />
                        )}

                        <item.icon size={22} strokeWidth={1.5} className="flex-shrink-0" />
                        <span className="text-base tracking-wide">{item.label}</span>
                    </button>
                ))}
            </nav>

            <div className={`mt-auto text-xs px-2 pt-4 border-t ${theme === 'dark' ? 'border-gray-700 text-gray-500' : 'border-gray-200/20 text-gray-400'}`}>
                v1.1.0
            </div>
        </aside>
    );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, update, remove } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { Trash2, Edit, CalendarPlus, X, Save, History } from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<LeaveBalance[]>([]);
    const [usersList, setUsersList] = useState<{key: string, name: string}[]>([]);

    // Modal States
    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showEditBalanceModal, setShowEditBalanceModal] = useState(false);

    // Form States
    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams'>('annual');

    const [editingBalance, setEditingBalance] = useState<LeaveBalance | null>(null);

    // Initial Loading
    useEffect(() => {
        // Load All Users for dropdown
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: any[] = [];
                snapshot.forEach(c => { u.push({ key: c.key, name: c.val().name }); });
                setUsersList(u);
            }
        });

        // Load Balances
        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const b: LeaveBalance[] = Object.values(snapshot.val());

                // Privacy Filter
                if (user.role === 'admin') {
                    setBalances(b);
                } else {
                    // Find current user's key/id to match
                    // Since we store userId in balance, we filter by it.
                    // We need to map the current logged in user to the ID used in balances
                    // Assuming user.username or we find the ID from users list.
                    // For simplicity, let's match by employeeName if userId is tricky, or filter after.
                    setBalances(b.filter(x => x.employeeName === user.name));
                }
            } else {
                setBalances([]);
            }
        });
    }, [user]);

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate || leaveDays <= 0) return alert("يرجى اكمال البيانات");

        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;

        // 1. Get current balance
        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        let currentBalance: LeaveBalance = balances.find(b => b.userId === selectedUser) || {
            userId: selectedUser,
            employeeName: targetUser.name,
            annual: 21, casual: 7, sick: 0, exams: 0 // Default defaults
        };

        // 2. Deduct
        if (currentBalance[leaveType] < leaveDays && leaveType !== 'sick' && leaveType !== 'exams') {
             if(!confirm(`الرصيد الحالي (${currentBalance[leaveType]}) أقل من المطلوب (${leaveDays}). هل تريد المتابعة بالسالب؟`)) return;
        }

        const newBalance = {
            ...currentBalance,
            [leaveType]: Number(currentBalance[leaveType]) - Number(leaveDays)
        };

        // 3. Save Balance
        await set(balanceRef, newBalance);

        // 4. Record History
        const historyData: LeaveRecord = {
            userId: selectedUser,
            employeeName: targetUser.name,
            date: leaveDate,
            days: Number(leaveDays),
            type: leaveType,
            timestamp: Date.now()
        };
        await push(ref(db, 'leave_history'), historyData);

        alert("تم تسجيل الاجازة وخصم الرصيد");
        setShowAddLeaveModal(false);
        setLeaveDays(1);
        setLeaveDate('');
    };

    const handleEditBalance = async () => {
        if (!editingBalance) return;
        await set(ref(db, `leave_balances/${editingBalance.userId}`), editingBalance);
        setShowEditBalanceModal(false);
        setEditingBalance(null);
    };

    const handleDeleteBalance = async (userId: string) => {
        if(confirm("هل أنت متأكد من حذف سجل أرصدة هذا الموظف؟")) {
            await remove(ref(db, `leave_balances/${userId}`));
        }
    };

    // Helper to initialize balance if not exists for a user (Admin feature)
    const initBalance = async (u: {key: string, name: string}) => {
        const confirmInit = confirm(`هل تريد إنشاء سجل رصيد افتراضي لـ ${u.name}؟ (21 سنوي / 7 عارضة)`);
        if(confirmInit) {
            const data: LeaveBalance = {
                userId: u.key,
                employeeName: u.name,
                annual: 21,
                casual: 7,
                sick: 0,
                exams: 0
            };
            await set(ref(db, `leave_balances/${u.key}`), data);
        }
    };

    const inputClass = "border p-2 rounded text-black w-full";
    const modalClass = `fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm`;
    const modalContentClass = `w-full max-w-md p-6 rounded-lg shadow-2xl ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`;

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <h2 className="text-2xl font-bold flex items-center gap-2">
                    <CalendarPlus className="text-blue-500" /> 
                    رصيد الإجازات
                </h2>

                <button 
                    onClick={() => setShowAddLeaveModal(true)}
                    className="bg-red-600 hover:bg-red-700 text-white px-6 py-2 rounded-full font-bold shadow-lg flex items-center gap-2 transition transform hover:scale-105"
                >
                    <CalendarPlus size={20} />
                    تواريخ الإجازات (خصم)
                </button>
            </div>

            {/* Balances Table */}
            <div className="overflow-x-auto rounded-lg shadow-lg">
                <table className={`w-full text-center border-collapse ${theme === 'dark' ? 'text-white' : 'text-gray-800'}`}>
                    <thead>
                        <tr className={`${theme === 'dark' ? 'bg-gray-700' : 'bg-blue-600 text-white'}`}>
                            <th className="p-4">اسم الموظف</th>
                            <th className="p-4 bg-green-500/20">سنوي</th>
                            <th className="p-4 bg-yellow-500/20">عارضة</th>
                            <th className="p-4 bg-red-500/20">مرضي</th>
                            <th className="p-4 bg-purple-500/20">امتحانات</th>
                            <th className="p-4">إجراءات</th>
                        </tr>
                    </thead>
                    <tbody>
                        {balances.map((balance) => (
                            <tr key={balance.userId} className={`border-b ${theme === 'dark' ? 'border-gray-700 bg-gray-800 hover:bg-gray-750' : 'bg-white border-gray-100 hover:bg-gray-50'}`}>
                                <td className="p-4 font-bold">{balance.employeeName}</td>
                                <td className="p-4 font-bold text-green-600 dark:text-green-400 text-lg">{balance.annual}</td>
                                <td className="p-4 font-bold text-yellow-600 dark:text-yellow-400 text-lg">{balance.casual}</td>
                                <td className="p-4 font-bold text-red-600 dark:text-red-400 text-lg">{balance.sick}</td>
                                <td className="p-4 font-bold text-purple-600 dark:text-purple-400 text-lg">{balance.exams}</td>
                                <td className="p-4 flex justify-center gap-2">
                                    {(user.role === 'admin') && (
                                        <>
                                            <button 
                                                onClick={() => { setEditingBalance(balance); setShowEditBalanceModal(true); }}
                                                className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200"
                                            >
                                                <Edit size={16} />
                                            </button>
                                            <button 
                                                onClick={() => handleDeleteBalance(balance.userId)}
                                                className="p-2 bg-red-100 text-red-600 rounded hover:bg-red-200"
                                            >
                                                <Trash2 size={16} />
                                            </button>
                                        </>
                                    )}
                                </td>
                            </tr>
                        ))}
                        {balances.length === 0 && (
                            <tr>
                                <td colSpan={6} className="p-8 text-center opacity-50">لا توجد أرصدة مسجلة</td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            {/* Admin Feature: Add Balance for User not in list */}
            {user.role === 'admin' && (
                <div className="mt-8 p-4 bg-gray-100 dark:bg-gray-800 rounded-lg">
                    <h3 className="font-bold mb-2 text-sm opacity-70">إدارة أرصدة الموظفين الجدد</h3>
                    <div className="flex flex-wrap gap-2">
                        {usersList.filter(u => !balances.find(b => b.userId === u.key)).map(u => (
                            <button 
                                key={u.key}
                                onClick={() => initBalance(u)}
                                className="text-xs bg-gray-200 dark:bg-gray-700 px-3 py-1 rounded hover:bg-gray-300 transition"
                            >
                                + {u.name}
                            </button>
                        ))}
                    </div>
                </div>
            )}

            {/* Modal: Add Leave (Deduct) */}
            {showAddLeaveModal && (
                <div className={modalClass}>
                    <div className={modalContentClass}>
                        <div className="flex justify-between items-center mb-6 border-b pb-2">
                            <h3 className="text-xl font-bold flex items-center gap-2"><CalendarPlus /> تسجيل إجازة (خصم)</h3>
                            <button onClick={() => setShowAddLeaveModal(false)}><X className="text-gray-500 hover:text-red-500"/></button>
                        </div>

                        <div className="space-y-4">
                            <div>
                                <label className="block mb-1 text-sm font-bold">الموظف</label>
                                <select 
                                    className={inputClass} 
                                    value={selectedUser} 
                                    onChange={e => setSelectedUser(e.target.value)}
                                >
                                    <option value="">اختر الحساب...</option>
                                    {(user.role === 'admin' ? usersList : usersList.filter(u => u.name === user.name)).map(u => (
                                        <option key={u.key} value={u.key}>{u.name}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block mb-1 text-sm font-bold">تاريخ الإجازة</label>
                                <input 
                                    type="date" 
                                    className={inputClass}
                                    value={leaveDate}
                                    onChange={e => setLeaveDate(e.target.value)}
                                />
                            </div>

                            <div className="flex gap-4">
                                <div className="flex-1">
                                    <label className="block mb-1 text-sm font-bold">عدد الأيام</label>
                                    <input 
                                        type="number" 
                                        min="0.5"
                                        step="0.5"
                                        className={inputClass}
                                        value={leaveDays}
                                        onChange={e => setLeaveDays(parseFloat(e.target.value))}
                                    />
                                </div>
                                <div className="flex-1">
                                    <label className="block mb-1 text-sm font-bold">نوع الإجازة</label>
                                    <select 
                                        className={inputClass}
                                        value={leaveType}
                                        onChange={e => setLeaveType(e.target.value as any)}
                                    >
                                        <option value="annual">سنوي</option>
                                        <option value="casual">عارضة</option>
                                        <option value="sick">مرضي</option>
                                        <option value="exams">امتحانات</option>
                                    </select>
                                </div>
                            </div>

                            <button 
                                onClick={handleAddLeave}
                                className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-3 rounded mt-4 shadow-lg transition"
                            >
                                اضف إجازة (خصم من الرصيد)
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal: Edit Balance (Admin) */}
            {showEditBalanceModal && editingBalance && (
                 <div className={modalClass}>
                    <div className={modalContentClass}>
                        <div className="flex justify-between items-center mb-6 border-b pb-2">
                            <h3 className="text-xl font-bold">تعديل الأرصدة: {editingBalance.employeeName}</h3>
                            <button onClick={() => {setShowEditBalanceModal(false); setEditingBalance(null)}}><X/></button>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            <div>
                                <label className="block text-sm">سنوي</label>
                                <input 
                                    type="number" 
                                    className={inputClass} 
                                    value={editingBalance.annual}
                                    onChange={e => setEditingBalance({...editingBalance, annual: Number(e.target.value)})} 
                                />
                            </div>
                            <div>
                                <label className="block text-sm">عارضة</label>
                                <input 
                                    type="number" 
                                    className={inputClass} 
                                    value={editingBalance.casual}
                                    onChange={e => setEditingBalance({...editingBalance, casual: Number(e.target.value)})} 
                                />
                            </div>
                            <div>
                                <label className="block text-sm">مرضي</label>
                                <input 
                                    type="number" 
                                    className={inputClass} 
                                    value={editingBalance.sick}
                                    onChange={e => setEditingBalance({...editingBalance, sick: Number(e.target.value)})} 
                                />
                            </div>
                            <div>
                                <label className="block text-sm">امتحانات</label>
                                <input 
                                    type="number" 
                                    className={inputClass} 
                                    value={editingBalance.exams}
                                    onChange={e => setEditingBalance({...editingBalance, exams: Number(e.target.value)})} 
                                />
                            </div>
                        </div>
                        <button 
                            onClick={handleEditBalance}
                            className="w-full bg-blue-600 text-white font-bold py-2 rounded mt-6"
                        >
                            حفظ التعديلات
                        </button>
                    </div>
                 </div>
            )}
        </div>
    );
};

export default LeaveBalanceComponent;

import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set } from "firebase/database";
import { User, AppSettings } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

// Default Settings
const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, // Hidden by default for users
    showInventoryReg: false, // Hidden by default for users
    showCompetitorReports: false // Hidden by default for users
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'glass' | 'dark' | 'win10' | 'light'>('win10');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>(INITIAL_MARKETS);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showThemeSelector, setShowThemeSelector] = useState(false);

  // Realtime Listeners
  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    const unsubscribeSettings = onValue(settingsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
          // Merge with defaults to ensure permissions object exists if old data
          setSettings({...DEFAULT_SETTINGS, ...data});
      }
    });

    const unsubscribeMarkets = onValue(marketsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setMarkets(Object.values(data));
      } else {
         setMarkets(INITIAL_MARKETS);
      }
    });

    const unsubscribeConnected = onValue(connectedRef, (snap) => {
        setIsConnected(!!snap.val());
    });

    return () => {
        unsubscribeSettings();
        unsubscribeMarkets();
        unsubscribeConnected();
    };
  }, []);

  const handleLogout = () => {
    setUser(null);
  };

  if (!user) {
    return <Login onLogin={setUser} theme={theme} />;
  }

  // Dynamic Theme Classes
  const getThemeClasses = () => {
    switch(theme) {
        case 'glass': return "bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 min-h-screen text-white";
        case 'dark': return "bg-gray-900 text-white min-h-screen";
        case 'win10': return "bg-[#0078D7] min-h-screen font-sans";
        default: return "bg-gray-100 text-gray-800 min-h-screen";
    }
  };

  const getContainerClasses = () => {
      switch(theme) {
          case 'glass': return "glass rounded-xl shadow-2xl";
          case 'dark': return "bg-gray-800 border border-gray-700 rounded-lg";
          case 'win10': return "bg-white text-black shadow-lg rounded-none border-2 border-[#005a9e]";
          default: return "bg-white shadow-lg rounded-lg";
      }
  };

  return (
    <div className={`${getThemeClasses()} flex flex-col overflow-hidden`}>
      {/* Ticker */}
      {settings.tickerEnabled && (
        <div className="bg-black text-yellow-400 py-1 overflow-hidden whitespace-nowrap border-b border-yellow-600">
           <div className="animate-marquee inline-block px-4">
              {settings.tickerText}
           </div>
        </div>
      )}

      {/* Header */}
      <header className={`p-4 flex justify-between items-center ${theme === 'glass' ? 'bg-white/10' : theme === 'dark' ? 'bg-gray-800' : 'bg-white text-black shadow-md'}`}>
        <div className="flex items-center gap-4">
            {/* Mobile Menu Toggle */}
            <button 
                onClick={() => setIsSidebarOpen(!isSidebarOpen)} 
                className="md:hidden p-2 rounded hover:bg-black/10 transition-colors"
                aria-label="Toggle Menu"
            >
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>

            <h1 className="text-xl md:text-2xl font-bold truncate max-w-[200px] md:max-w-none">{settings.appName}</h1>

            <div className={`flex items-center gap-1 text-xs px-2 py-1 rounded-full ${isConnected ? 'bg-green-500/20 text-green-600' : 'bg-red-500/20 text-red-600'}`} title={isConnected ? "متصل بالخادم" : "غير متصل"}>
                {isConnected ? <Wifi size={14} /> : <WifiOff size={14} />}
                <span className="hidden md:inline">{isConnected ? "متصل" : "غير متصل"}</span>
            </div>
        </div>
        <div className="flex items-center gap-2 md:gap-4">
            {settings.whatsappNumber && (
                <a href={`https://wa.me/${settings.whatsappNumber}`} target="_blank" rel="noreferrer" className="flex items-center gap-2 bg-green-500 hover:bg-green-600 text-white px-3 py-1 rounded-full transition text-xs md:text-sm">
                    <Phone size={16} />
                    <span className="hidden md:inline">تواصل واتس آب</span>
                </a>
            )}

            {/* Theme Selector Trigger */}
            <button 
                onClick={() => setShowThemeSelector(true)}
                className="p-2 rounded-full hover:bg-black/10 transition-colors" 
                title="تغيير المظهر"
            >
                <Palette size={20} />
            </button>

            <div className="text-sm hidden md:block">
                مرحباً، <span className="font-bold">{user.name}</span>
            </div>
            <button onClick={handleLogout} className="text-red-500 hover:text-red-700 p-1">
                <LogOut size={20} />
            </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        {/* Mobile Overlay */}
        {isSidebarOpen && (
            <div 
                className="absolute inset-0 bg-black/50 z-20 md:hidden backdrop-blur-sm"
                onClick={() => setIsSidebarOpen(false)}
            />
        )}

        {/* Sidebar */}
        <div className={`
            absolute top-0 bottom-0 right-0 z-30 h-full shadow-2xl transition-transform duration-300 ease-in-out
            md:relative md:transform-none md:shadow-none
            ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
        `}>
            <Sidebar 
                currentView={currentView} 
                setView={(view) => {
                    setCurrentView(view);
                    setIsSidebarOpen(false);
                }} 
                user={user} 
                theme={theme}
                settings={settings}
                containerClass={`${theme === 'glass' ? 'bg-white/10 backdrop-blur-md' : theme === 'dark' ? 'bg-gray-800' : 'bg-gray-50 border-l border-gray-200'} h-full`}
            />
        </div>

        {/* Main Content */}
        <main className="flex-1 p-2 md:p-4 overflow-y-auto w-full relative z-0">
            <div className={`p-3 md:p-6 min-h-full ${getContainerClasses()} transition-all duration-300`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
