                  <div className="grid grid-cols-2 gap-3">
                       <button onClick={() => {setTheme('win10'); setShowThemeSelector(false)}} className={`p-4 border-2 rounded-lg hover:border-blue-500 transition flex flex-col items-center gap-2 ${theme === 'win10' ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20' : 'border-transparent bg-gray-100 dark:bg-gray-700'}`}>
                          <div className="w-10 h-10 bg-[#0078D7] rounded shadow-md"></div>
                          <span className="font-semibold">Windows 10</span>
                       </button>
                       <button onClick={() => {setTheme('glass'); setShowThemeSelector(false)}} className={`p-4 border-2 rounded-lg hover:border-purple-500 transition flex flex-col items-center gap-2 ${theme === 'glass' ? 'border-purple-500 bg-purple-50 dark:bg-purple-900/20' : 'border-transparent bg-gray-100 dark:bg-gray-700'}`}>
                          <div className="w-10 h-10 bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 rounded shadow-md"></div>
                          <span className="font-semibold">Glass</span>
                       </button>
                       <button onClick={() => {setTheme('dark'); setShowThemeSelector(false)}} className={`p-4 border-2 rounded-lg hover:border-gray-500 transition flex flex-col items-center gap-2 ${theme === 'dark' ? 'border-gray-500 bg-gray-700 text-white' : 'border-transparent bg-gray-100 dark:bg-gray-700'}`}>
                          <div className="w-10 h-10 bg-gray-900 rounded border border-gray-600 shadow-md"></div>
                          <span className="font-semibold">Dark Mode</span>
                       </button>
                       <button onClick={() => {setTheme('light'); setShowThemeSelector(false)}} className={`p-4 border-2 rounded-lg hover:border-gray-400 transition flex flex-col items-center gap-2 ${theme === 'light' ? 'border-gray-400 bg-gray-200' : 'border-transparent bg-gray-100 dark:bg-gray-700'}`}>
                          <div className="w-10 h-10 bg-gray-100 rounded border shadow-md"></div>
                          <span className="font-semibold">Light</span>
                       </button>
                  </div>
              </div>
          </div>
      )}

      {/* Message Details Modal */}
      {selectedNotif && (
          <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
            <div className={`p-6 rounded-lg w-full max-w-lg shadow-2xl relative ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`}>
                <button 
                    onClick={() => setSelectedNotif(null)} 
                    className="absolute top-4 left-4 p-1 hover:bg-gray-200 dark:hover:bg-gray-700 rounded-full"
                >
                    <X size={20} />
                </button>

                <h3 className="text-xl font-bold mb-1 flex items-center gap-2 text-blue-500">
                    <MailOpen /> رسالة من {selectedNotif.sender}
                </h3>
                <span className="text-xs text-gray-500 mb-6 block border-b pb-2">
                    {new Date(selectedNotif.timestamp).toLocaleString('ar-EG')}
                </span>

                <div className="bg-gray-50 dark:bg-gray-900 p-4 rounded-lg border border-gray-200 dark:border-gray-700 max-h-96 overflow-y-auto whitespace-pre-wrap">
                    {selectedNotif.message}
                </div>

                <div className="mt-6 flex justify-end gap-3">
                    <button 
                        onClick={() => copyMessage(selectedNotif.message)}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-100 text-indigo-700 rounded hover:bg-indigo-200 transition"
                    >
                        <Copy size={16} /> نسخ النص
                    </button>
                    <button 
                        onClick={() => setSelectedNotif(null)}
                        className="px-6 py-2 bg-blue-600 text-white rounded font-bold hover:bg-blue-700"
                    >
                        حسناً
                    </button>
                </div>
            </div>
          </div>
      )}

      <style>{`
        @keyframes marquee {
            0% { transform: translateX(100%); }
            100% { transform: translateX(-100%); }
        }
        .animate-marquee {
            animation: marquee 20s linear infinite;
        }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, get, child } from "firebase/database";
import { User } from '../types';
import { Lock, User as UserIcon, Loader2 } from 'lucide-react';

interface Props {
    onLogin: (user: User) => void;
    theme: string;
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    // Check if user was previously logged in
    useEffect(() => {
        const savedUser = localStorage.getItem('soft_rose_user');
        if (savedUser) {
            try {
                onLogin(JSON.parse(savedUser));
            } catch (e) {
                localStorage.removeItem('soft_rose_user');
            }
        }
    }, [onLogin]);

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        // Trim inputs to remove accidental spaces from mobile keyboards
        const cleanUsername = username.trim();
        const cleanPassword = password.trim();

        if (!cleanUsername || !cleanPassword) {
            setError('يرجى إدخال اسم المستخدم وكلمة المرور');
            setLoading(false);
            return;
        }

        try {
            // Hardcoded fallback for emergency/initial access
            if (cleanUsername === 'admin' && cleanPassword === 'admin') {
                const adminUser: User = {
                    username: 'admin',
                    name: 'Admin',
                    role: 'admin',
                    canViewAllSales: true
                };
                localStorage.setItem('soft_rose_user', JSON.stringify(adminUser));
                onLogin(adminUser);
                return;
            }

            const dbRef = ref(db);
            const snapshot = await get(child(dbRef, `users`));

            if (snapshot.exists()) {
                const users = snapshot.val();
                // Safe lookup with trimming and case-insensitive check if needed
                const userKey = Object.keys(users).find(key => 
                    users[key].username?.toString().trim() === cleanUsername && 
                    users[key].password?.toString().trim() === cleanPassword
                );

                if (userKey) {
                    const userData = users[userKey];
                    localStorage.setItem('soft_rose_user', JSON.stringify(userData));
                    onLogin(userData);
                } else {
                    setError('اسم المستخدم أو كلمة المرور غير صحيحة. تأكد من عدم وجود مسافات زائدة.');
                }
            } else {
                setError('لا يوجد مستخدمين مسجلين في النظام.');
            }
        } catch (err) {
            console.error(err);
            setError('خطأ في الاتصال بقاعدة البيانات. تأكد من وجود إنترنت.');
        } finally {
            setLoading(false);
        }
    };

    const containerClass = theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white/80 backdrop-blur-md text-gray-800';

    return (
        <div className={`min-h-screen flex items-center justify-center p-4 ${theme === 'dark' ? 'bg-gray-900' : 'bg-gradient-to-br from-blue-400 to-purple-500'}`}>
            <div className={`w-full max-w-md p-8 rounded-2xl shadow-2xl ${containerClass}`}>
                <div className="flex flex-col items-center mb-8">
                    <div className="w-20 h-20 bg-blue-600 rounded-full flex items-center justify-center mb-4 shadow-lg">
                        <UserIcon size={40} className="text-white" />
                    </div>
                    <h2 className="text-3xl font-bold text-center">سوفت روز</h2>
                    <p className="text-sm opacity-60">نظام التجارة الحديثة</p>
                </div>

                <form onSubmit={handleLogin} className="space-y-5">
                    <div>
                        <label className="block mb-2 font-medium text-sm">اسم المستخدم</label>
                        <div className="relative">
                            <UserIcon className="absolute right-3 top-3 text-gray-400" size={18} />
                            <input 
                                type="text"
                                value={username}
                                onChange={e => setUsername(e.target.value)}
                                className="w-full pr-10 pl-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none text-black bg-gray-50/50"
                                placeholder="أدخل اسمك المسجل"
                                required
                                autoComplete="username"
                            />
                        </div>
                    </div>
                    <div>
                        <label className="block mb-2 font-medium text-sm">كلمة المرور</label>
                        <div className="relative">
                            <Lock className="absolute right-3 top-3 text-gray-400" size={18} />
                            <input 
                                type="password"
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                className="w-full pr-10 pl-4 py-3 rounded-xl border border-gray-300 focus:ring-2 focus:ring-blue-500 outline-none text-black bg-gray-50/50"
                                placeholder="••••••••"
                                required
                                autoComplete="current-password"
                            />
                        </div>
                    </div>

                    {error && (
                        <div className="bg-red-100 border border-red-200 text-red-700 px-4 py-2 rounded-lg text-xs text-center animate-pulse">
                            {error}
                        </div>
                    )}

                    <button 
                        type="submit" 
                        disabled={loading}
                        className="w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-3.5 rounded-xl transition transform active:scale-95 flex items-center justify-center gap-2 shadow-lg"
                    >
                        {loading ? (
                            <>
                                <Loader2 className="animate-spin" size={20} />
                                جاري التحقق...
                            </>
                        ) : 'دخول النظام'}
                    </button>
                </form>
                <div className="mt-8 text-center text-xs opacity-50">
                    في حال نسيان البيانات يرجى التواصل مع المدير
                </div>
            </div>
        </div>
    );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set, update } from "firebase/database";
import { User, AppSettings, AppNotification } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen, Copy, Check } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

// Default Settings
const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, // Hidden by default for users
    showInventoryReg: false, // Hidden by default for users
    showCompetitorReports: false // Hidden by default for users
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'glass' | 'dark' | 'win10' | 'light'>('win10');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>(INITIAL_MARKETS);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showThemeSelector, setShowThemeSelector] = useState(false);

  // Notification State
  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [selectedNotif, setSelectedNotif] = useState<AppNotification | null>(null);

  // Realtime Listeners
  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    const unsubscribeSettings = onValue(settingsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
          // Merge with defaults to ensure permissions object exists if old data
          setSettings({...DEFAULT_SETTINGS, ...data});
      }
    });

    const unsubscribeMarkets = onValue(marketsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setMarkets(Object.values(data));
      } else {
         setMarkets(INITIAL_MARKETS);
      }
    });

    const unsubscribeConnected = onValue(connectedRef, (snap) => {
        setIsConnected(!!snap.val());
    });

    return () => {
        unsubscribeSettings();
        unsubscribeMarkets();
        unsubscribeConnected();
    };
  }, []);

  // Notifications Listener (Only when logged in)
  useEffect(() => {
    if (!user) return;

    // Listen to notifications for this specific username
    const notifRef = ref(db, `notifications/${user.username}`);
    const unsubscribeNotif = onValue(notifRef, (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list: AppNotification[] = Object.keys(data).map(key => ({
                id: key,
                ...data[key]
            }));
            // Sort by new
            list.sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        } else {
            setNotifications([]);
            setUnreadCount(0);
        }
    });

    return () => unsubscribeNotif();
  }, [user]);

  const handleLogout = () => {
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  const handleOpenNotification = async (notif: AppNotification) => {
      setSelectedNotif(notif);
      setShowNotifDropdown(false);

      // Mark as read
      if (!notif.isRead && notif.id && user) {
          await update(ref(db, `notifications/${user.username}/${notif.id}`), { isRead: true });
      }
  };

  const copyMessage = (text: string) => {
      navigator.clipboard.writeText(text);
      alert("تم نسخ النص");
  };

  if (!user) {
    return <Login onLogin={setUser} theme={theme} />;
  }

  // Dynamic Theme Classes
  const getThemeClasses = () => {
    switch(theme) {
        case 'glass': return "bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 min-h-screen text-white";
        case 'dark': return "bg-gray-900 text-white min-h-screen";
        case 'win10': return "bg-[#0078D7] min-h-screen font-sans";
        default: return "bg-gray-100 text-gray-800 min-h-screen";
    }
  };

  const getContainerClasses = () => {
      switch(theme) {
          case 'glass': return "glass rounded-xl shadow-2xl";
          case 'dark': return "bg-gray-800 border border-gray-700 rounded-lg";
          case 'win10': return "bg-white text-black shadow-lg rounded-none border-2 border-[#005a9e]";
          default: return "bg-white shadow-lg rounded-lg";
      }
  };

  return (
    <div className={`${getThemeClasses()} flex flex-col overflow-hidden`}>
      {/* Ticker */}
      {settings.tickerEnabled && (
        <div className="bg-black text-yellow-400 py-1 overflow-hidden whitespace-nowrap border-b border-yellow-600">
           <div className="animate-marquee inline-block px-4">
              {settings.tickerText}
           </div>
        </div>
      )}

      {/* Header */}
      <header className={`p-4 flex justify-between items-center ${theme === 'glass' ? 'bg-white/10' : theme === 'dark' ? 'bg-gray-800' : 'bg-white text-black shadow-md'}`}>
        <div className="flex items-center gap-4">
            {/* Mobile Menu Toggle */}
            <button 
                onClick={() => setIsSidebarOpen(!isSidebarOpen)} 
                className="md:hidden p-2 rounded hover:bg-black/10 transition-colors"
                aria-label="Toggle Menu"
            >
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>

            <h1 className="text-xl md:text-2xl font-bold truncate max-w-[200px] md:max-w-none">{settings.appName}</h1>

            <div className={`flex items-center gap-1 text-xs px-2 py-1 rounded-full ${isConnected ? 'bg-green-500/20 text-green-600' : 'bg-red-500/20 text-red-600'}`} title={isConnected ? "متصل بالخادم" : "غير متصل"}>
                {isConnected ? <Wifi size={14} /> : <WifiOff size={14} />}
                <span className="hidden md:inline">{isConnected ? "متصل" : "غير متصل"}</span>
            </div>
        </div>
        <div className="flex items-center gap-2 md:gap-4">
            {settings.whatsappNumber && (
                <a href={`https://wa.me/${settings.whatsappNumber}`} target="_blank" rel="noreferrer" className="flex items-center gap-2 bg-green-500 hover:bg-green-600 text-white px-3 py-1 rounded-full transition text-xs md:text-sm">
                    <Phone size={16} />
                    <span className="hidden md:inline">تواصل واتس آب</span>
                </a>
            )}

            {/* Notification Bell */}
            <div className="relative">
                <button 
                    onClick={() => setShowNotifDropdown(!showNotifDropdown)}
                    className="p-2 rounded-full hover:bg-black/10 transition-colors relative"
                    title="الإشعارات"
                >
                    <Bell size={20} />
                    {unreadCount > 0 && (
                        <span className="absolute top-1 right-1 bg-red-600 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full animate-pulse border border-white">
                            {unreadCount}
                        </span>
                    )}
                </button>

                {/* Dropdown */}
                {showNotifDropdown && (
                    <div className="absolute left-0 mt-2 w-72 max-h-80 overflow-y-auto bg-white dark:bg-gray-800 rounded-lg shadow-xl border border-gray-200 dark:border-gray-700 z-50 text-right">
                        <div className="p-3 border-b dark:border-gray-700 font-bold text-sm text-gray-500 dark:text-gray-400">
                            الرسائل والإشعارات
                        </div>
                        {notifications.length === 0 ? (
                            <div className="p-4 text-center text-gray-500 text-sm">لا توجد إشعارات</div>
                        ) : (
                            notifications.map(n => (
                                <div 
                                    key={n.id} 
                                    onClick={() => handleOpenNotification(n)}
                                    className={`p-3 border-b dark:border-gray-700 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 transition flex gap-3 ${n.isRead ? 'opacity-60' : 'bg-blue-50 dark:bg-blue-900/20'}`}
                                >
                                    <div className="mt-1">
                                        <MailOpen size={16} className={n.isRead ? 'text-gray-400' : 'text-blue-500'} />
                                    </div>
                                    <div className="flex-1 overflow-hidden">
                                        <div className="flex justify-between items-center mb-1">
                                            <span className="font-bold text-sm text-gray-800 dark:text-gray-200">{n.sender}</span>
                                            <span className="text-[10px] text-gray-500">{new Date(n.timestamp).toLocaleDateString('ar-EG')}</span>
                                        </div>
                                        <p className="text-xs text-gray-600 dark:text-gray-300 truncate">{n.message}</p>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                )}
            </div>

            {/* Theme Selector Trigger */}
            <button 
                onClick={() => setShowThemeSelector(true)}
                className="p-2 rounded-full hover:bg-black/10 transition-colors" 
                title="تغيير المظهر"
            >
                <Palette size={20} />
            </button>

            <div className="text-sm hidden md:block">
                مرحباً، <span className="font-bold">{user.name}</span>
            </div>
            <button onClick={handleLogout} className="text-red-500 hover:text-red-700 p-1">
                <LogOut size={20} />
            </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        {/* Mobile Overlay */}
        {isSidebarOpen && (
            <div 
                className="absolute inset-0 bg-black/50 z-20 md:hidden backdrop-blur-sm"
                onClick={() => setIsSidebarOpen(false)}
            />
        )}

        {/* Sidebar */}
        <div className={`
            absolute top-0 bottom-0 right-0 z-30 h-full shadow-2xl transition-transform duration-300 ease-in-out
            md:relative md:transform-none md:shadow-none
            ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}
        `}>
            <Sidebar 
                currentView={currentView} 
                setView={(view) => {
                    setCurrentView(view);
                    setIsSidebarOpen(false);
                }} 
                user={user} 
                theme={theme}
                settings={settings}
                containerClass={`${theme === 'glass' ? 'bg-white/10 backdrop-blur-md' : theme === 'dark' ? 'bg-gray-800' : 'bg-gray-50 border-l border-gray-200'} h-full`}
            />
        </div>

        {/* Main Content */}
        <main className="flex-1 p-2 md:p-4 overflow-y-auto w-full relative z-0">
            <div className={`p-3 md:p-6 min-h-full ${getContainerClasses()} transition-all duration-300`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
