import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { Trash2, Edit, CalendarPlus, X, Save, History, ChevronRight, ChevronLeft, Info } from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<LeaveBalance[]>([]);
    const [usersList, setUsersList] = useState<{key: string, name: string}[]>([]);
    const [allHistory, setAllHistory] = useState<LeaveRecord[]>([]);

    // Modal States
    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showEditBalanceModal, setShowEditBalanceModal] = useState(false);
    const [showHistoryDetailsModal, setShowHistoryDetailsModal] = useState(false);

    // Period Control State
    const [currentPeriodStart, setCurrentPeriodStart] = useState<Date>(() => {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        // If today is 21 or after, period starts this month 21st.
        // If today is before 21, period started last month 21st.
        if (now.getDate() >= 21) {
            return new Date(year, month, 21);
        } else {
            return new Date(year, month - 1, 21);
        }
    });

    // Form States
    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams'>('annual');
    const [editingBalance, setEditingBalance] = useState<LeaveBalance | null>(null);
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);

    // Load Data
    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: any[] = [];
                snapshot.forEach(c => { u.push({ key: c.key, name: c.val().name }); });
                setUsersList(u);
            }
        });

        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const b: LeaveBalance[] = Object.values(snapshot.val());
                setBalances(user.role === 'admin' ? b : b.filter(x => x.employeeName === user.name));
            } else {
                setBalances([]);
            }
        });

        onValue(ref(db, 'leave_history'), snapshot => {
            if (snapshot.exists()) {
                const h: LeaveRecord[] = Object.values(snapshot.val());
                setAllHistory(h);
            } else {
                setAllHistory([]);
            }
        });
    }, [user]);

    // Period Logic
    const getPeriodEnd = (start: Date) => {
        const end = new Date(start);
        end.setMonth(end.getMonth() + 1);
        end.setDate(20);
        return end;
    };

    const changePeriod = (direction: number) => {
        const newStart = new Date(currentPeriodStart);
        newStart.setMonth(newStart.getMonth() + direction);
        setCurrentPeriodStart(newStart);
    };

    const filterHistoryByPeriodAndUser = (userId: string) => {
        const periodEnd = getPeriodEnd(currentPeriodStart);
        return allHistory.filter(record => {
            const recordDate = new Date(record.date);
            return record.userId === userId && 
                   recordDate >= currentPeriodStart && 
                   recordDate <= periodEnd;
        });
    };

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate || leaveDays <= 0) return alert("يرجى اكمال البيانات");
        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;

        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        let currentBalance: LeaveBalance = balances.find(b => b.userId === selectedUser) || {
            userId: selectedUser, employeeName: targetUser.name,
            annual: 21, casual: 7, sick: 0, exams: 0
        };

        if (currentBalance[leaveType] < leaveDays && leaveType !== 'sick' && leaveType !== 'exams') {
             if(!confirm(`الرصيد الحالي (${currentBalance[leaveType]}) أقل من المطلوب (${leaveDays}). هل تريد المتابعة بالسالب؟`)) return;
        }

        const newBalance = { ...currentBalance, [leaveType]: Number(currentBalance[leaveType]) - Number(leaveDays) };
        await set(balanceRef, newBalance);

        const historyData: LeaveRecord = {
            userId: selectedUser, employeeName: targetUser.name,
            date: leaveDate, days: Number(leaveDays), type: leaveType, timestamp: Date.now()
        };
        await push(ref(db, 'leave_history'), historyData);

        alert("تم تسجيل الاجازة وخصم الرصيد");
        setShowAddLeaveModal(false);
        setLeaveDays(1);
        setLeaveDate('');
    };

    const handleEditBalance = async () => {
        if (!editingBalance) return;
        await set(ref(db, `leave_balances/${editingBalance.userId}`), editingBalance);
        setShowEditBalanceModal(false);
        setEditingBalance(null);
    };

    const handleDeleteBalance = async (userId: string) => {
        if(confirm("هل أنت متأكد من حذف سجل أرصدة هذا الموظف؟")) {
            await remove(ref(db, `leave_balances/${userId}`));
        }
    };

    const openHistory = (userId: string, name: string) => {
        setHistoryUserView({ userId, name });
        setShowHistoryDetailsModal(true);
    };

    const inputClass = "border p-2 rounded text-black w-full";
    const modalClass = `fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm`;
    const modalContentClass = `w-full max-w-2xl p-6 rounded-lg shadow-2xl ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`;

    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات' };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <h2 className="text-2xl font-bold flex items-center gap-2">
                    <History className="text-blue-500" /> 
                    أرصدة الموظفين
                </h2>
                <div className="flex gap-2">
                    <button 
                        onClick={() => setShowAddLeaveModal(true)}
                        className="bg-red-600 hover:bg-red-700 text-white px-6 py-2 rounded-full font-bold shadow-lg flex items-center gap-2 transition transform hover:scale-105"
                    >
                        <CalendarPlus size={20} />
                        تسجيل إجازة
                    </button>
                </div>
            </div>

            <div className="bg-blue-50 dark:bg-blue-900/20 p-3 rounded-lg flex items-center gap-2 text-sm text-blue-700 dark:text-blue-300 mb-4 border border-blue-200">
                <Info size={18} />
                <span>نصيحة: اضغط على أي رقم في الجدول لعرض تفاصيل إجازات الموظف المسجلة خلال الدورة الشهرية (21 إلى 20).</span>
            </div>

            {/* Balances Table */}
            <div className="overflow-x-auto rounded-lg shadow-lg">
                <table className={`w-full text-center border-collapse ${theme === 'dark' ? 'text-white' : 'text-gray-800'}`}>
                    <thead>
                        <tr className={`${theme === 'dark' ? 'bg-gray-700' : 'bg-blue-600 text-white'}`}>
                            <th className="p-4">اسم الموظف</th>
                            <th className="p-4 bg-green-500/20">سنوي</th>
                            <th className="p-4 bg-yellow-500/20">عارضة</th>
                            <th className="p-4 bg-red-500/20">مرضي</th>
                            <th className="p-4 bg-purple-500/20">امتحانات</th>
                            <th className="p-4">إجراءات</th>
                        </tr>
                    </thead>
                    <tbody>
                        {balances.map((balance) => (
                            <tr key={balance.userId} className={`border-b ${theme === 'dark' ? 'border-gray-700 bg-gray-800 hover:bg-gray-750' : 'bg-white border-gray-100 hover:bg-gray-50'}`}>
                                <td className="p-4 font-bold">{balance.employeeName}</td>
                                <td className="p-4"><button onClick={() => openHistory(balance.userId, balance.employeeName)} className="font-bold text-green-600 dark:text-green-400 text-xl hover:scale-125 transition block w-full">{balance.annual}</button></td>
                                <td className="p-4"><button onClick={() => openHistory(balance.userId, balance.employeeName)} className="font-bold text-yellow-600 dark:text-yellow-400 text-xl hover:scale-125 transition block w-full">{balance.casual}</button></td>
                                <td className="p-4"><button onClick={() => openHistory(balance.userId, balance.employeeName)} className="font-bold text-red-600 dark:text-red-400 text-xl hover:scale-125 transition block w-full">{balance.sick}</button></td>
                                <td className="p-4"><button onClick={() => openHistory(balance.userId, balance.employeeName)} className="font-bold text-purple-600 dark:text-purple-400 text-xl hover:scale-125 transition block w-full">{balance.exams}</button></td>
                                <td className="p-4">
                                    {user.role === 'admin' && (
                                        <div className="flex justify-center gap-2">
                                            <button onClick={() => { setEditingBalance(balance); setShowEditBalanceModal(true); }} className="p-2 bg-blue-100 text-blue-600 rounded hover:bg-blue-200"><Edit size={16} /></button>
                                            <button onClick={() => handleDeleteBalance(balance.userId)} className="p-2 bg-red-100 text-red-600 rounded hover:bg-red-200"><Trash2 size={16} /></button>
                                        </div>
                                    )}
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Modal: History Details (21 to 20 Logic) */}
            {showHistoryDetailsModal && historyUserView && (
                <div className={modalClass}>
                    <div className={modalContentClass}>
                        <div className="flex justify-between items-center mb-6 border-b pb-2">
                            <div>
                                <h3 className="text-xl font-bold">سجل إجازات: {historyUserView.name}</h3>
                            </div>
                            <button onClick={() => setShowHistoryDetailsModal(false)}><X/></button>
                        </div>

                        {/* Period Selector Header */}
                        <div className="bg-blue-600 text-white p-4 rounded-xl shadow-md mb-6">
                            <div className="flex justify-between items-center">
                                <button onClick={() => changePeriod(-1)} className="p-1 hover:bg-white/20 rounded-full transition"><ChevronRight size={24}/></button>
                                <div className="text-center">
                                    <div className="text-xs opacity-80 mb-1">إجازات الفترة من</div>
                                    <div className="font-bold text-lg">
                                        {currentPeriodStart.toLocaleDateString('ar-EG')} - {getPeriodEnd(currentPeriodStart).toLocaleDateString('ar-EG')}
                                    </div>
                                </div>
                                <button onClick={() => changePeriod(1)} className="p-1 hover:bg-white/20 rounded-full transition"><ChevronLeft size={24}/></button>
                            </div>
                        </div>

                        <div className="max-h-80 overflow-y-auto">
                            <table className="w-full text-center border-collapse">
                                <thead className="sticky top-0 bg-gray-100 dark:bg-gray-900">
                                    <tr className="border-b">
                                        <th className="p-2 text-xs opacity-60">التاريخ</th>
                                        <th className="p-2 text-xs opacity-60">النوع</th>
                                        <th className="p-2 text-xs opacity-60">المدة</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filterHistoryByPeriodAndUser(historyUserView.userId).length > 0 ? (
                                        filterHistoryByPeriodAndUser(historyUserView.userId).map((rec, i) => (
                                            <tr key={i} className="border-b border-gray-500/10 hover:bg-black/5">
                                                <td className="p-3">{rec.date}</td>
                                                <td className="p-3 font-bold">{typeLabels[rec.type]}</td>
                                                <td className="p-3 bg-blue-500/10 rounded">{rec.days} يوم</td>
                                            </tr>
                                        ))
                                    ) : (
                                        <tr><td colSpan={3} className="p-8 opacity-40 italic">لا توجد إجازات مسجلة لهذه الفترة</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>

                        <div className="mt-6 flex justify-end border-t pt-4">
                            <button onClick={() => setShowHistoryDetailsModal(false)} className="px-6 py-2 bg-gray-500 text-white rounded-lg">إغلاق</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal: Add Leave (Standard) */}
            {showAddLeaveModal && (
                <div className={modalClass}>
                    <div className={modalContentClass}>
                        <div className="flex justify-between items-center mb-6 border-b pb-2">
                            <h3 className="text-xl font-bold flex items-center gap-2"><CalendarPlus /> تسجيل إجازة (خصم)</h3>
                            <button onClick={() => setShowAddLeaveModal(false)}><X/></button>
                        </div>
                        <div className="space-y-4">
                            <div>
                                <label className="block mb-1 text-sm font-bold">الموظف</label>
                                <select className={inputClass} value={selectedUser} onChange={e => setSelectedUser(e.target.value)}>
                                    <option value="">اختر الحساب...</option>
                                    {(user.role === 'admin' ? usersList : usersList.filter(u => u.name === user.name)).map(u => (
                                        <option key={u.key} value={u.key}>{u.name}</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block mb-1 text-sm font-bold">تاريخ الإجازة</label>
                                <input type="date" className={inputClass} value={leaveDate} onChange={e => setLeaveDate(e.target.value)} />
                            </div>
                            <div className="flex gap-4">
                                <div className="flex-1">
                                    <label className="block mb-1 text-sm font-bold">عدد الأيام</label>
                                    <input type="number" min="0.5" step="0.5" className={inputClass} value={leaveDays} onChange={e => setLeaveDays(parseFloat(e.target.value))} />
                                </div>
                                <div className="flex-1">
                                    <label className="block mb-1 text-sm font-bold">نوع الإجازة</label>
                                    <select className={inputClass} value={leaveType} onChange={e => setLeaveType(e.target.value as any)}>
                                        <option value="annual">سنوي</option>
                                        <option value="casual">عارضة</option>
                                        <option value="sick">مرضي</option>
                                        <option value="exams">امتحانات</option>
                                    </select>
                                </div>
                            </div>
                            <button onClick={handleAddLeave} className="w-full bg-red-600 hover:bg-red-700 text-white font-bold py-3 rounded mt-4 shadow-lg transition">حفظ وخصم من الرصيد</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Modal: Edit Balance (Admin Only) */}
            {showEditBalanceModal && editingBalance && (
                 <div className={modalClass}>
                    <div className={modalContentClass}>
                        <div className="flex justify-between items-center mb-6 border-b pb-2">
                            <h3 className="text-xl font-bold">تعديل الأرصدة: {editingBalance.employeeName}</h3>
                            <button onClick={() => {setShowEditBalanceModal(false); setEditingBalance(null)}}><X/></button>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            {['annual', 'casual', 'sick', 'exams'].map(key => (
                                <div key={key}>
                                    <label className="block text-sm">{typeLabels[key as keyof typeof typeLabels]}</label>
                                    <input type="number" className={inputClass} value={(editingBalance as any)[key]} onChange={e => setEditingBalance({...editingBalance, [key]: Number(e.target.value)})} />
                                </div>
                            ))}
                        </div>
                        <button onClick={handleEditBalance} className="w-full bg-blue-600 text-white font-bold py-2 rounded mt-6 shadow-lg">حفظ التعديلات</button>
                    </div>
                 </div>
            )}
        </div>
    );
};

