                                            </div>
                                        </div>
                                        <div className="flex items-center gap-4">
                                            <div className="text-right">
                                                <div className="font-black text-lg">{rec.days}</div>
                                                <div className="text-[8px] opacity-50 uppercase text-center">يوم</div>
                                            </div>
                                            {user.role === 'admin' && (
