                            <div className="text-center">
                                <div className="text-[10px] opacity-70 font-bold uppercase tracking-widest mb-1 text-center">دورة الإجازات</div>
                                <div className="font-bold text-sm flex items-center gap-2">
                                    <Calendar size={14} />
