                        setItems(getZeinaDefaults());
                    } else if (selectedCompany === 'Papia Familia') {
                        setItems(getPapiaFamiliaDefaults());
                    } else {
                        setItems([]); // Clear for other companies
                    }
                }
            });
            return () => unsubscribe();
        } else {
            setItems([]);
