export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue, remove } from "firebase/database";
import { User } from '../types';
import { 
    COMPANIES, 
    PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, 
    FINE_FACIAL, FINE_KITCHEN, FINE_TOILET,
    ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET,
    PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET,
    WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET
} from '../constants';
import { Save, Plus, Trash, Trash2, X } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);

    // Structure: items for current view
    const [items, setItems] = useState<{category: string, name: string, price: number}[]>([]);

    // Load Companies list
    useEffect(() => {
        onValue(ref(db, 'settings/companies'), s => {
            if(s.exists()) setCompanies(Object.values(s.val()));
        });
    }, []);

    // Helper to generate a safe Firebase path for templates
    const getTemplatePath = () => {
        if (!selectedMarket || !selectedCompany || !user.username) return null;
        // Sanitize strings to be safe for Firebase paths
        const safeUser = user.username.replace(/[.#$/[\]]/g, "_");
        const safeMarket = selectedMarket.replace(/[.#$/[\]]/g, "_");
        const safeCompany = selectedCompany.replace(/[.#$/[\]]/g, "_");
        return `competitor_templates/${safeUser}/${safeMarket}/${safeCompany}`;
    };

    // Helper: Generate Default Items from a list
    const generateDefaultsFromList = (facial: string[], kitchen: string[], toilet: string[]) => {
        const defaultItems: {category: string, name: string, price: number}[] = [];
        facial.forEach(name => defaultItems.push({ category: 'مناديل سحب (Facial)', name, price: 0 }));
        kitchen.forEach(name => defaultItems.push({ category: 'مناديل مطبخ (Kitchen)', name, price: 0 }));
        toilet.forEach(name => defaultItems.push({ category: 'تواليت (Toilet)', name, price: 0 }));
        return defaultItems;
    };

    // Load Template when Market/Company changes
    useEffect(() => {
        const path = getTemplatePath();
        if (path) {
            const templateRef = ref(db, path);
            const unsubscribe = onValue(templateRef, (snapshot) => {
                if (snapshot.exists()) {
                    setItems(snapshot.val());
                } else {
                    // Logic: If no template exists for this user, load company defaults
                    if (selectedCompany === 'Soft Rose') {
                        setItems(generateDefaultsFromList(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET));
                    } else if (selectedCompany === 'Fine') {
                        setItems(generateDefaultsFromList(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET));
                    } else if (selectedCompany === 'Zeina') {
                        setItems(generateDefaultsFromList(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET));
                    } else if (selectedCompany === 'Papia Familia') {
                        setItems(generateDefaultsFromList(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET));
                    } else if (selectedCompany === 'White') {
                        setItems(generateDefaultsFromList(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET));
                    } else {
                        setItems([]); // Clear for other companies
                    }
                }
            });
            return () => unsubscribe();
        } else {
            setItems([]);
        }
    }, [selectedMarket, selectedCompany, user.username]);

    // Update Template in Firebase
    const updateTemplate = async (newItems: any[]) => {
        const path = getTemplatePath();
        if (path) {
            await set(ref(db, path), newItems);
        }
    };

    const addItem = (category: string) => {
        if (!selectedMarket || !selectedCompany) {
            alert("يرجى اختيار الماركت والشركة أولاً");
            return;
        }
        const newItems = [...items, { category, name: '', price: 0 }];
        setItems(newItems);
        updateTemplate(newItems);
    };

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...items];
        // @ts-ignore
        newItems[index][field] = value;
        setItems(newItems);
        // We update template on name change to save the "Item Name", 
        // price updates are also saved but are transient until "Save Report".
        updateTemplate(newItems);
    };

    const deleteItem = (index: number) => {
        if (confirm("هل تريد حذف هذا الصنف من القائمة المثبتة؟")) {
            const newItems = items.filter((_, i) => i !== index);
            setItems(newItems);
            updateTemplate(newItems);
        }
    };

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");

        const validItems = items.filter(i => i.name && i.price > 0);

        if (validItems.length === 0) {
            return alert("لا يوجد أصناف مسعرة للحفظ");
        }

        const data = {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            employeeName: user.name,
            items: validItems
        };

        await push(ref(db, 'competitor_prices'), data);
        alert("تم حفظ تقرير أسعار المنافسين");

        // Optional: Reset prices to 0 after report submission but keep names?
        // For now, based on request "Fix items", we leave them as is.
    };

    const addCompany = async () => {
        if (user.role !== 'admin') return;
        const name = prompt("اسم الشركة:");
        if(name) await push(ref(db, 'settings/companies'), name);
    };

    const handleAddMarket = async () => {
        const name = prompt("ادخل اسم الماركت الجديد:");
        if (name) {
             await push(ref(db, 'settings/markets'), name);
        }
    };

    const deleteMarket = async () => {
        if(user.role !== 'admin') return;
        alert("خاصية الحذف تحتاج تحديد الماركت من الاعدادات");
    };

    const categories = ['مناديل سحب (Facial)', 'مناديل مطبخ (Kitchen)', 'تواليت (Toilet)'];

    const inputClass = "border p-2 rounded w-full text-black";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-white/5 p-4 rounded-lg text-black">
                <div>
                    <label className="block mb-1 font-bold text-gray-700 dark:text-gray-300">الماركت</label>
                    <div className="flex gap-2">
                        <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                            <option value="">اختر الماركت</option>
                            {markets.map(m => <option key={m} value={m}>{m}</option>)}
                        </select>

                        <button onClick={handleAddMarket} className="bg-blue-600 text-white p-2 rounded shrink-0" title="إضافة ماركت جديد">
                            <Plus size={18}/>
                        </button>

                        {user.role === 'admin' && (
                            <button onClick={deleteMarket} className="bg-red-500 text-white p-2 rounded shrink-0"><Trash size={18}/></button>
                        )}
                    </div>
                </div>
                <div>
                    <label className="block mb-1 font-bold text-gray-700 dark:text-gray-300">الشركة</label>
                    <div className="flex gap-2">
                         <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                            <option value="">اختر الشركة</option>
                            {companies.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                         {user.role === 'admin' && (
                            <button onClick={addCompany} className="bg-blue-500 text-white p-2 rounded shrink-0"><Plus size={18}/></button>
                        )}
                    </div>
                </div>
            </div>

            {/* Hint Message */}
            {selectedMarket && selectedCompany && (
                <div className="text-sm text-blue-600 bg-blue-50 p-3 rounded-lg border border-blue-100">
                    ملاحظة: الأصناف المثبتة خاصة بحسابك فقط لهذا الماركت والشركة.
                    {selectedCompany === 'Soft Rose' && <span className="block font-bold mt-1">تم تحميل منتجات Soft Rose.</span>}
                    {selectedCompany === 'Fine' && <span className="block font-bold mt-1">تم تحميل منتجات Fine.</span>}
                    {selectedCompany === 'Zeina' && <span className="block font-bold mt-1">تم تحميل منتجات Zeina.</span>}
                    {selectedCompany === 'Papia Familia' && <span className="block font-bold mt-1">تم تحميل منتجات Papia & Familia.</span>}
                    {selectedCompany === 'White' && <span className="block font-bold mt-1">تم تحميل منتجات White.</span>}
                </div>
            )}

            {categories.map(cat => (
                <div key={cat} className="border border-gray-200/20 p-4 rounded-xl bg-white/5">
                    <h3 className="font-bold mb-4 text-yellow-600 border-b border-gray-200/10 pb-2 text-lg">{cat}</h3>

                    {/* Header Row for alignment */}
                    <div className="flex gap-2 mb-2 px-1 text-[10px] md:text-xs font-bold opacity-60 uppercase">
                        <div className="flex-1">اسم الصنف</div>
                        <div className="w-24 md:w-32 text-center">السعر</div>
                        <div className="w-8"></div>
                    </div>

                    <div className="space-y-2">
                        {items.map((item, idx) => item.category === cat && (
                            <div key={idx} className="flex flex-row gap-2 items-center">
                                <div className="flex-1 min-w-0">
                                    <input 
                                        placeholder="اسم الصنف" 
                                        className={`${inputClass} text-xs md:text-sm h-10`} 
                                        value={item.name} 
                                        onChange={e => updateItem(idx, 'name', e.target.value)}
                                    />
                                </div>
                                <div className="w-24 md:w-32 flex-shrink-0">
                                    <input 
                                        type="number" 
                                        placeholder="السعر" 
                                        className={`${inputClass} text-center text-xs md:text-sm h-10`} 
                                        value={item.price || ''}
                                        onChange={e => updateItem(idx, 'price', e.target.value)}
                                    />
                                </div>
                                <button 
                                    onClick={() => deleteItem(idx)}
                                    className="p-1.5 text-red-500 hover:bg-red-50 rounded transition shrink-0"
                                    title="حذف الصنف"
                                >
                                    <Trash2 size={16} />
                                </button>
                            </div>
                        ))}
                    </div>
                    <button 
                        onClick={() => addItem(cat)} 
                        className="mt-4 text-xs bg-gray-100 hover:bg-white text-black px-4 py-2 rounded-lg shadow-sm border border-gray-200 transition w-full md:w-auto flex items-center justify-center gap-1"
                    >
                        <Plus size={14}/> اضف منتج جديد
                    </button>
                </div>
            ))}

            <button onClick={handleSaveReport} className="bg-green-600 hover:bg-green-700 w-full py-4 text-white rounded-2xl font-bold shadow-xl text-lg transition transform active:scale-[0.98] flex items-center justify-center gap-2">
                <Save size={24} /> حفظ التقرير وترحيله
            </button>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, CompetitorPrice } from '../types';
import { exportToCSV } from '../utils';
import { COMPANIES } from '../constants';
import { Trash2, Edit, Save, X, FileSpreadsheet, LayoutHorizontal } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorReports: React.FC<Props> = ({ user, markets, theme }) => {
    const [data, setData] = useState<CompetitorPrice[]>([]);
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [editingReport, setEditingReport] = useState<CompetitorPrice | null>(null);

    useEffect(() => {
        onValue(ref(db, 'settings/companies'), s => {
            if(s.exists()) setCompanies(Object.values(s.val()));
        });
        onValue(ref(db, 'competitor_prices'), s => {
            if(s.exists()) {
                let arr = Object.keys(s.val()).map(key => ({
                    id: key,
                    ...s.val()[key]
                })) as CompetitorPrice[];

                // DATA PRIVACY
                if (user.role !== 'admin') {
                    arr = arr.filter(d => d.employeeName === user.name);
                }

                setData(arr);
            } else {
                setData([]);
            }
        });
    }, [user]);

    const filtered = data.filter(d => 
        (!selectedMarket || d.market === selectedMarket) &&
        (!selectedCompany || d.company === selectedCompany)
    );

    // Standard Export (Filtered data)
    const handleExport = () => {
        if (filtered.length === 0) return alert("لا توجد بيانات لتصديرها");
        const csv = filtered.flatMap(d => (d.items || []).map(i => ({
            "الماركت": d.market,
            "الشركة": d.company,
            "التاريخ": d.date,
            "بواسطة": d.employeeName || '-',
            "القسم": i.category,
            "المنتج": i.name,
            "السعر": i.price
        })));
        const fileName = selectedCompany ? `تقرير_منافسين_${selectedCompany}` : 'تقرير_المنافسين_العام';
        exportToCSV(csv, fileName);
    };

    // Horizontal Comparison Export (All companies side by side for a market)
    const handleExportHorizontal = () => {
        if (!selectedMarket) return alert("يرجى اختيار الماركت أولاً للمقارنة");

        // Group data by company for the selected market
        const marketData = data.filter(d => d.market === selectedMarket);
        const companyGroups: Record<string, {name: string, price: number}[]> = {};

        marketData.forEach(report => {
            if (!companyGroups[report.company]) companyGroups[report.company] = [];
            companyGroups[report.company].push(...report.items);
        });

        const activeCompanies = Object.keys(companyGroups);
        if (activeCompanies.length === 0) return alert("لا توجد بيانات لهذا الماركت");

        // Find max items to determine row count
        const maxRows = Math.max(...activeCompanies.map(c => companyGroups[c].length));

        const csvRows: any[] = [];

        for (let i = 0; i < maxRows; i++) {
            const row: Record<string, any> = {};
            activeCompanies.forEach(company => {
                const item = companyGroups[company][i];
                row[`${company} - الصنف`] = item ? item.name : "";
                row[`${company} - السعر`] = item ? item.price : "";
            });
            csvRows.push(row);
        }

        exportToCSV(csvRows, `مقارنة_عرضية_${selectedMarket}`);
    };

    const handleDelete = async (id: string) => {
        if(confirm("حذف هذا التقرير؟")) {
            await remove(ref(db, `competitor_prices/${id}`));
        }
    };

    const saveEdit = async () => {
        if(!editingReport || !editingReport.id) return;
        try {
            await update(ref(db, `competitor_prices/${editingReport.id}`), {
                items: editingReport.items
            });
            setEditingReport(null);
            alert("تم التعديل");
        } catch(e) { console.error(e); }
    };

    const updateEditItem = (index: number, price: number) => {
        if(!editingReport) return;
        const newItems = [...editingReport.items];
        newItems[index].price = price;
        setEditingReport({...editingReport, items: newItems});
    };

    const inputClass = "border p-2 rounded text-black w-full text-sm md:text-base";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">تقارير المنافسين</h2>

            <div className="bg-white/5 p-4 rounded-xl space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs mb-1 opacity-70">فلترة بالماركت</label>
                        <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                            <option value="">كل الماركتات</option>
                            {markets.map(m => <option key={m} value={m}>{m}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs mb-1 opacity-70">فلترة بالشركة</label>
                        <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                            <option value="">كل الشركات</option>
                            {companies.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                </div>

                <div className="flex flex-col md:flex-row gap-3 pt-2">
                    <button 
                        onClick={handleExport} 
                        className="flex-1 bg-green-600 hover:bg-green-700 text-white px-4 py-2.5 rounded-lg flex items-center justify-center gap-2 font-bold transition shadow-lg"
                    >
                        <FileSpreadsheet size={20} /> تصدير إكسيل (طولي)
                    </button>

                    {selectedMarket && (
                        <button 
                            onClick={handleExportHorizontal} 
                            className="flex-1 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 rounded-lg flex items-center justify-center gap-2 font-bold transition shadow-lg border-2 border-blue-400/30"
                        >
                            <LayoutHorizontal size={20} /> تصدير مقارنة عرضية (ماركت {selectedMarket})
                        </button>
                    )}
                </div>
            </div>

            <div className="space-y-4">
                {filtered.length === 0 ? (
                    <div className="text-center py-10 opacity-50 italic">لا توجد تقارير مطابقة للبحث</div>
                ) : filtered.map((record, i) => (
                    <div key={record.id || i} className={`p-4 rounded-xl border transition-all hover:shadow-md ${theme === 'dark' ? 'bg-gray-800 border-gray-700' : 'bg-white border-gray-100 shadow'}`}>
                        <div className="font-bold text-lg mb-2 flex justify-between items-center">
                            <div className="flex flex-col">
                                <span className="text-blue-600">{record.company}</span>
                                <span className="text-xs font-normal opacity-70">{record.market} | {record.date}</span>
                                <span className="text-[10px] text-gray-400">بواسطة: {record.employeeName}</span>
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => setEditingReport(record)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg transition"><Edit size={18}/></button>
                                {(user.role === 'admin' || user.name === record.employeeName) && (
                                     <button onClick={() => handleDelete(record.id!)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition"><Trash2 size={18}/></button>
                                )}
                            </div>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-center">
                                <thead className="bg-gray-500/5">
                                    <tr className="border-b border-gray-500/10">
                                        <th className="p-2 text-right">المنتج</th>
                                        <th className="p-2">السعر</th>
                                        <th className="p-2 hidden md:table-cell">القسم</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {(record.items || []).map((item, idx) => (
                                        <tr key={idx} className="border-b border-gray-500/5 hover:bg-black/5">
                                            <td className="p-2 text-right">{item.name}</td>
                                            <td className="p-2 font-bold text-green-600">{item.price}</td>
                                            <td className="p-2 opacity-70 text-xs hidden md:table-cell">{item.category}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                ))}
            </div>

            {/* Edit Modal */}
            {editingReport && (
                <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 overflow-y-auto p-4 backdrop-blur-sm">
                    <div className={`w-full max-w-xl rounded-2xl shadow-2xl p-6 ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`}>
                        <div className="flex justify-between items-center mb-4 border-b pb-2">
                            <h3 className="font-bold text-xl">تعديل أسعار {editingReport.company}</h3>
                            <button onClick={() => setEditingReport(null)} className="p-1 hover:bg-red-50 rounded-full transition"><X /></button>
                        </div>
                        <div className="max-h-[60vh] overflow-y-auto space-y-2 mb-4 pr-1 custom-scrollbar">
                            {editingReport.items.map((item, idx) => (
                                <div key={idx} className="flex justify-between items-center p-3 border border-gray-100/10 rounded-lg bg-black/5 gap-2">
                                    <span className="flex-1 text-sm font-medium">{item.name}</span>
                                    <div className="w-24">
                                        <input 
                                            type="number" 
                                            value={item.price} 
                                            onChange={e => updateEditItem(idx, Number(e.target.value))}
                                            className="w-full p-2 border rounded-lg text-center text-black font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                                            placeholder="السعر"
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="flex justify-end gap-2 pt-4 border-t">
                            <button onClick={() => setEditingReport(null)} className="px-6 py-2 bg-gray-200 text-black rounded-xl font-bold hover:bg-gray-300 transition">إلغاء</button>
                            <button onClick={saveEdit} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 transition shadow-lg"><Save size={18}/> حفظ التعديل</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CompetitorReports;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, CompetitorPrice } from '../types';
import { exportToCSV } from '../utils';
import { COMPANIES } from '../constants';
import { Trash2, Edit, Save, X, FileSpreadsheet, Columns2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorReports: React.FC<Props> = ({ user, markets, theme }) => {
    const [data, setData] = useState<CompetitorPrice[]>([]);
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [editingReport, setEditingReport] = useState<CompetitorPrice | null>(null);

    useEffect(() => {
        onValue(ref(db, 'settings/companies'), s => {
            if(s.exists()) setCompanies(Object.values(s.val()));
        });
        onValue(ref(db, 'competitor_prices'), s => {
            if(s.exists()) {
                let arr = Object.keys(s.val()).map(key => ({
                    id: key,
                    ...s.val()[key]
                })) as CompetitorPrice[];

                // DATA PRIVACY
                if (user.role !== 'admin') {
                    arr = arr.filter(d => d.employeeName === user.name);
                }

                setData(arr);
            } else {
                setData([]);
            }
        });
    }, [user]);

    const filtered = data.filter(d => 
        (!selectedMarket || d.market === selectedMarket) &&
        (!selectedCompany || d.company === selectedCompany)
    );

    // Standard Export (Filtered data)
    const handleExport = () => {
        if (filtered.length === 0) return alert("لا توجد بيانات لتصديرها");
        const csv = filtered.flatMap(d => (d.items || []).map(i => ({
            "الماركت": d.market,
            "الشركة": d.company,
            "التاريخ": d.date,
            "بواسطة": d.employeeName || '-',
            "القسم": i.category,
            "المنتج": i.name,
            "السعر": i.price
        })));
        const fileName = selectedCompany ? `تقرير_منافسين_${selectedCompany}` : 'تقرير_المنافسين_العام';
        exportToCSV(csv, fileName);
    };

    // Horizontal Comparison Export (All companies side by side for a market)
    const handleExportHorizontal = () => {
        if (!selectedMarket) return alert("يرجى اختيار الماركت أولاً للمقارنة");

        // Group data by company for the selected market
        const marketData = data.filter(d => d.market === selectedMarket);
        const companyGroups: Record<string, {name: string, price: number}[]> = {};

        marketData.forEach(report => {
            if (!companyGroups[report.company]) companyGroups[report.company] = [];
            companyGroups[report.company].push(...report.items);
        });

        const activeCompanies = Object.keys(companyGroups);
        if (activeCompanies.length === 0) return alert("لا توجد بيانات لهذا الماركت");

        // Find max items to determine row count
        const maxRows = Math.max(...activeCompanies.map(c => companyGroups[c].length));

        const csvRows: any[] = [];

        for (let i = 0; i < maxRows; i++) {
            const row: Record<string, any> = {};
            activeCompanies.forEach(company => {
                const item = companyGroups[company][i];
                row[`${company} - الصنف`] = item ? item.name : "";
                row[`${company} - السعر`] = item ? item.price : "";
            });
            csvRows.push(row);
        }

        exportToCSV(csvRows, `مقارنة_عرضية_${selectedMarket}`);
    };

    const handleDelete = async (id: string) => {
        if(confirm("حذف هذا التقرير؟")) {
            await remove(ref(db, `competitor_prices/${id}`));
        }
    };

    const saveEdit = async () => {
        if(!editingReport || !editingReport.id) return;
        try {
            await update(ref(db, `competitor_prices/${editingReport.id}`), {
                items: editingReport.items
            });
            setEditingReport(null);
            alert("تم التعديل");
        } catch(e) { console.error(e); }
    };

    const updateEditItem = (index: number, price: number) => {
        if(!editingReport) return;
        const newItems = [...editingReport.items];
        newItems[index].price = price;
        setEditingReport({...editingReport, items: newItems});
    };

    const inputClass = "border p-2 rounded text-black w-full text-sm md:text-base";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">تقارير المنافسين</h2>

            <div className="bg-white/5 p-4 rounded-xl space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs mb-1 opacity-70">فلترة بالماركت</label>
                        <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                            <option value="">كل الماركتات</option>
                            {markets.map(m => <option key={m} value={m}>{m}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs mb-1 opacity-70">فلترة بالشركة</label>
                        <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                            <option value="">كل الشركات</option>
                            {companies.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                </div>

                <div className="flex flex-col md:flex-row gap-3 pt-2">
                    <button 
                        onClick={handleExport} 
                        className="flex-1 bg-green-600 hover:bg-green-700 text-white px-4 py-2.5 rounded-lg flex items-center justify-center gap-2 font-bold transition shadow-lg"
                    >
                        <FileSpreadsheet size={20} /> تصدير إكسيل (طولي)
                    </button>

                    {selectedMarket && (
                        <button 
                            onClick={handleExportHorizontal} 
                            className="flex-1 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 rounded-lg flex items-center justify-center gap-2 font-bold transition shadow-lg border-2 border-blue-400/30"
                        >
                            <Columns2 size={20} /> تصدير مقارنة عرضية (ماركت {selectedMarket})
                        </button>
                    )}
                </div>
            </div>

            <div className="space-y-4">
                {filtered.length === 0 ? (
                    <div className="text-center py-10 opacity-50 italic">لا توجد تقارير مطابقة للبحث</div>
                ) : filtered.map((record, i) => (
                    <div key={record.id || i} className={`p-4 rounded-xl border transition-all hover:shadow-md ${theme === 'dark' ? 'bg-gray-800 border-gray-700' : 'bg-white border-gray-100 shadow'}`}>
                        <div className="font-bold text-lg mb-2 flex justify-between items-center">
                            <div className="flex flex-col">
                                <span className="text-blue-600">{record.company}</span>
                                <span className="text-xs font-normal opacity-70">{record.market} | {record.date}</span>
                                <span className="text-[10px] text-gray-400">بواسطة: {record.employeeName}</span>
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => setEditingReport(record)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg transition"><Edit size={18}/></button>
                                {(user.role === 'admin' || user.name === record.employeeName) && (
                                     <button onClick={() => handleDelete(record.id!)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition"><Trash2 size={18}/></button>
                                )}
                            </div>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-center">
                                <thead className="bg-gray-500/5">
                                    <tr className="border-b border-gray-500/10">
                                        <th className="p-2 text-right">المنتج</th>
                                        <th className="p-2">السعر</th>
                                        <th className="p-2 hidden md:table-cell">القسم</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {(record.items || []).map((item, idx) => (
                                        <tr key={idx} className="border-b border-gray-500/5 hover:bg-black/5">
                                            <td className="p-2 text-right">{item.name}</td>
                                            <td className="p-2 font-bold text-green-600">{item.price}</td>
                                            <td className="p-2 opacity-70 text-xs hidden md:table-cell">{item.category}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                ))}
            </div>

            {/* Edit Modal */}
            {editingReport && (
                <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 overflow-y-auto p-4 backdrop-blur-sm">
                    <div className={`w-full max-w-xl rounded-2xl shadow-2xl p-6 ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`}>
                        <div className="flex justify-between items-center mb-4 border-b pb-2">
                            <h3 className="font-bold text-xl">تعديل أسعار {editingReport.company}</h3>
                            <button onClick={() => setEditingReport(null)} className="p-1 hover:bg-red-50 rounded-full transition"><X /></button>
                        </div>
                        <div className="max-h-[60vh] overflow-y-auto space-y-2 mb-4 pr-1 custom-scrollbar">
                            {editingReport.items.map((item, idx) => (
                                <div key={idx} className="flex justify-between items-center p-3 border border-gray-100/10 rounded-lg bg-black/5 gap-2">
                                    <span className="flex-1 text-sm font-medium">{item.name}</span>
                                    <div className="w-24">
                                        <input 
                                            type="number" 
                                            value={item.price} 
                                            onChange={e => updateEditItem(idx, Number(e.target.value))}
                                            className="w-full p-2 border rounded-lg text-center text-black font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                                            placeholder="السعر"
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="flex justify-end gap-2 pt-4 border-t">
                            <button onClick={() => setEditingReport(null)} className="px-6 py-2 bg-gray-200 text-black rounded-xl font-bold hover:bg-gray-300 transition">إلغاء</button>
                            <button onClick={saveEdit} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 transition shadow-lg"><Save size={18}/> حفظ التعديل</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CompetitorReports;

import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set, update, onDisconnect, serverTimestamp } from "firebase/database";
import { User, AppSettings, AppNotification } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen, Copy, Check } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, 
    showInventoryReg: false, 
    showCompetitorReports: false 
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'glass' | 'dark' | 'win10' | 'light'>('win10');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showThemeSelector, setShowThemeSelector] = useState(false);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [selectedNotif, setSelectedNotif] = useState<AppNotification | null>(null);

  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    onValue(settingsRef, (snapshot) => {
      if (snapshot.exists()) setSettings({...DEFAULT_SETTINGS, ...snapshot.val()});
    });

    onValue(marketsRef, (snapshot) => {
      if (snapshot.exists()) {
        const data = snapshot.val();
        const allMarkets: any[] = Object.keys(data).map(key => {
          if (typeof data[key] === 'string') return { name: data[key], createdBy: 'system' };
          return data[key];
        });

        if (user) {
          if (user.role === 'admin') {
            setMarkets(allMarkets.map(m => m.name));
          } else {
            const filtered = allMarkets.filter(m => m.createdBy === 'system' || m.createdBy === user.username);
            setMarkets(filtered.map(m => m.name));
          }
        }
      } else {
        setMarkets(INITIAL_MARKETS);
      }
    });

    onValue(connectedRef, (snap) => setIsConnected(!!snap.val()));
  }, [user?.username]);

  useEffect(() => {
    if (!user) return;
    const usersRef = ref(db, 'users');
    onValue(usersRef, (snapshot) => {
        if (snapshot.exists()) {
            const usersData = snapshot.val();
            const userKey = Object.keys(usersData).find(key => usersData[key].username === user.username);
            if (userKey) {
                const updatedUser = usersData[userKey];
                if (JSON.stringify(updatedUser) !== JSON.stringify(user)) {
                    setUser(updatedUser);
                    localStorage.setItem('soft_rose_user', JSON.stringify(updatedUser));
                }
            }
        }
    });

    const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
    const userStatusRef = ref(db, `status/${safeKey}`);
    set(userStatusRef, { online: true, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    onDisconnect(userStatusRef).set({ online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });

    onValue(ref(db, `notifications/${user.username}`), (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list = Object.keys(data).map(key => ({ id: key, ...data[key] })).sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        } else {
            setNotifications([]); setUnreadCount(0);
        }
    });
  }, [user?.username]);

  const handleLogout = async () => {
    if (user) {
        const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `status/${safeKey}`), { online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    }
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  if (!user) return <Login onLogin={setUser} theme={theme} />;

  const getThemeClasses = () => {
    switch(theme) {
        case 'glass': return "bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 min-h-screen text-white";
        case 'dark': return "bg-gray-900 text-white min-h-screen";
        case 'win10': return "bg-[#0078D7] min-h-screen font-sans";
        default: return "bg-gray-100 text-gray-800 min-h-screen";
    }
  };

  const getContainerClasses = () => {
      switch(theme) {
          case 'glass': return "glass rounded-xl shadow-2xl";
          case 'dark': return "bg-gray-800 border border-gray-700 rounded-lg";
          case 'win10': return "bg-white text-black shadow-lg rounded-none border-2 border-[#005a9e]";
          default: return "bg-white shadow-lg rounded-lg";
      }
  };

  return (
    <div className={`${getThemeClasses()} flex flex-col overflow-hidden`}>
      {settings.tickerEnabled && (
        <div className="bg-black text-yellow-400 py-1 overflow-hidden whitespace-nowrap border-b border-yellow-600">
           <div className="animate-marquee inline-block px-4">{settings.tickerText}</div>
        </div>
      )}

      <header className={`p-4 flex justify-between items-center ${theme === 'glass' ? 'bg-white/10' : theme === 'dark' ? 'bg-gray-800' : 'bg-white text-black shadow-md'}`}>
        <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="md:hidden p-2 rounded hover:bg-black/10 transition-colors">
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="text-xl md:text-2xl font-bold truncate max-w-[200px] md:max-w-none">{settings.appName}</h1>
            <div className={`flex items-center gap-1 text-xs px-2 py-1 rounded-full ${isConnected ? 'bg-green-500/20 text-green-600' : 'bg-red-500/20 text-red-600'}`}>
                {isConnected ? <Wifi size={14} /> : <WifiOff size={14} />}
                <span className="hidden md:inline">{isConnected ? "متصل" : "غير متصل"}</span>
            </div>
        </div>
        <div className="flex items-center gap-2 md:gap-4">
            {settings.whatsappNumber && (
                <a href={`https://wa.me/${settings.whatsappNumber}`} target="_blank" rel="noreferrer" className="flex items-center gap-2 bg-green-500 hover:bg-green-600 text-white px-3 py-1 rounded-full transition text-xs md:text-sm">
                    <Phone size={16} />
                    <span className="hidden md:inline">تواصل واتس آب</span>
                </a>
            )}
            <div className="relative">
                <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className="p-2 rounded-full hover:bg-black/10 transition-colors relative">
                    <Bell size={20} />
                    {unreadCount > 0 && <span className="absolute top-1 right-1 bg-red-600 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full animate-pulse border border-white">{unreadCount}</span>}
                </button>
                {showNotifDropdown && (
                    <div className="absolute left-0 mt-2 w-72 max-h-80 overflow-y-auto bg-white dark:bg-gray-800 rounded-lg shadow-xl border border-gray-200 dark:border-gray-700 z-50 text-right">
                        <div className="p-3 border-b dark:border-gray-700 font-bold text-sm text-gray-500 dark:text-gray-400">الرسائل والإشعارات</div>
                        {notifications.length === 0 ? <div className="p-4 text-center text-gray-500 text-sm">لا توجد إشعارات</div> : notifications.map(n => (
                                <div key={n.id} onClick={() => { setSelectedNotif(n); setShowNotifDropdown(false); if(!n.isRead) update(ref(db, `notifications/${user.username}/${n.id}`), {isRead: true}); }} className={`p-3 border-b dark:border-gray-700 cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 transition flex gap-3 ${n.isRead ? 'opacity-60' : 'bg-blue-50 dark:bg-blue-900/20'}`}>
                                    <div className="mt-1"><MailOpen size={16} className={n.isRead ? 'text-gray-400' : 'text-blue-500'} /></div>
                                    <div className="flex-1 overflow-hidden">
                                        <div className="flex justify-between items-center mb-1">
                                            <span className="font-bold text-sm text-gray-800 dark:text-gray-200">{n.sender}</span>
                                            <span className="text-[10px] text-gray-500">{new Date(n.timestamp).toLocaleDateString('ar-EG')}</span>
                                        </div>
                                        <p className="text-xs text-gray-600 dark:text-gray-300 truncate">{n.message}</p>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>
                )}
            </div>
            <button onClick={() => setShowThemeSelector(true)} className="p-2 rounded-full hover:bg-black/10 transition-colors"><Palette size={20} /></button>
            <div className="text-sm hidden md:block">مرحباً، <span className="font-bold">{user.name}</span></div>
            <button onClick={handleLogout} className="text-red-500 hover:text-red-700 p-1"><LogOut size={20} /></button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        {isSidebarOpen && <div className="absolute inset-0 bg-black/50 z-20 md:hidden backdrop-blur-sm" onClick={() => setIsSidebarOpen(false)} />}
        <div className={`absolute top-0 bottom-0 right-0 z-30 h-full shadow-2xl transition-transform duration-300 ease-in-out md:relative md:transform-none md:shadow-none ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
            <Sidebar currentView={currentView} setView={(view) => { setCurrentView(view); setIsSidebarOpen(false); }} user={user} theme={theme} settings={settings} containerClass={`${theme === 'glass' ? 'bg-white/10 backdrop-blur-md' : theme === 'dark' ? 'bg-gray-800' : 'bg-gray-50 border-l border-gray-200'} h-full`} />
        </div>
        <main className="flex-1 p-2 md:p-4 overflow-y-auto w-full relative z-0">
            <div className={`p-3 md:p-6 min-h-full ${getContainerClasses()}`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorPrices' && <CompetitorPrices user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorReports' && <CompetitorReports user={user} markets={markets} theme={theme} />}
                {currentView === 'leaveBalance' && <LeaveBalanceComponent user={user} theme={theme} />}
                {currentView === 'settings' && <Settings user={user} settings={settings} markets={markets} theme={theme} setTheme={setTheme} />}
            </div>
        </main>
      </div>
      <footer className="p-2 text-center text-xs opacity-70 bg-black/5">مع تحيات المطور Amir Lamay</footer>
      <style>{`
        @keyframes marquee { 0% { transform: translateX(100%); } 100% { transform: translateX(-100%); } }
        .animate-marquee { animation: marquee 20s linear infinite; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue, remove } from "firebase/database";
import { User } from '../types';
import { 
    COMPANIES, 
    PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, 
    FINE_FACIAL, FINE_KITCHEN, FINE_TOILET,
    ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET,
    PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET,
    WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET
} from '../constants';
import { Save, Plus, Trash, Trash2, X } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [items, setItems] = useState<{category: string, name: string, price: number}[]>([]);

    useEffect(() => {
        onValue(ref(db, 'settings/companies'), s => {
            if(s.exists()) {
                const data = s.val();
                const allCompanies: any[] = Object.keys(data).map(key => {
                    if (typeof data[key] === 'string') return { name: data[key], createdBy: 'system' };
                    return data[key];
                });

                if (user.role === 'admin') {
                    setCompanies(allCompanies.map(c => c.name));
                } else {
                    const filtered = allCompanies.filter(c => c.createdBy === 'system' || c.createdBy === user.username);
                    setCompanies(filtered.map(c => c.name));
                }
            }
        });
    }, [user.username, user.role]);

    const getTemplatePath = () => {
        if (!selectedMarket || !selectedCompany || !user.username) return null;
        const safeUser = user.username.replace(/[.#$/[\]]/g, "_");
        const safeMarket = selectedMarket.replace(/[.#$/[\]]/g, "_");
        const safeCompany = selectedCompany.replace(/[.#$/[\]]/g, "_");
        return `competitor_templates/${safeUser}/${safeMarket}/${safeCompany}`;
    };

    const generateDefaultsFromList = (facial: string[], kitchen: string[], toilet: string[]) => {
        const defaultItems: {category: string, name: string, price: number}[] = [];
        facial.forEach(name => defaultItems.push({ category: 'مناديل سحب (Facial)', name, price: 0 }));
        kitchen.forEach(name => defaultItems.push({ category: 'مناديل مطبخ (Kitchen)', name, price: 0 }));
        toilet.forEach(name => defaultItems.push({ category: 'تواليت (Toilet)', name, price: 0 }));
        return defaultItems;
    };

    useEffect(() => {
        const path = getTemplatePath();
        if (path) {
            const templateRef = ref(db, path);
            const unsubscribe = onValue(templateRef, (snapshot) => {
                if (snapshot.exists()) {
                    setItems(snapshot.val());
                } else {
                    if (selectedCompany === 'Soft Rose') {
                        setItems(generateDefaultsFromList(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET));
                    } else if (selectedCompany === 'Fine') {
                        setItems(generateDefaultsFromList(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET));
                    } else if (selectedCompany === 'Zeina') {
                        setItems(generateDefaultsFromList(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET));
                    } else if (selectedCompany === 'Papia Familia') {
                        setItems(generateDefaultsFromList(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET));
                    } else if (selectedCompany === 'White') {
                        setItems(generateDefaultsFromList(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET));
                    } else {
                        setItems([]);
                    }
                }
            });
            return () => unsubscribe();
        } else {
            setItems([]);
        }
    }, [selectedMarket, selectedCompany, user.username]);

    const updateTemplate = async (newItems: any[]) => {
        const path = getTemplatePath();
        if (path) await set(ref(db, path), newItems);
    };

    const addItem = (category: string) => {
        if (!selectedMarket || !selectedCompany) return alert("يرجى اختيار الماركت والشركة أولاً");
        const newItems = [...items, { category, name: '', price: 0 }];
        setItems(newItems);
        updateTemplate(newItems);
    };

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...items];
        // @ts-ignore
        newItems[index][field] = value;
        setItems(newItems);
        updateTemplate(newItems);
    };

    const deleteItem = (index: number) => {
        if (confirm("هل تريد حذف هذا الصنف من القائمة المثبتة؟")) {
            const newItems = items.filter((_, i) => i !== index);
            setItems(newItems);
            updateTemplate(newItems);
        }
    };

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const validItems = items.filter(i => i.name && i.price > 0);
        if (validItems.length === 0) return alert("لا يوجد أصناف مسعرة للحفظ");
        const data = {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            employeeName: user.name,
            items: validItems
        };
        await push(ref(db, 'competitor_prices'), data);
        alert("تم حفظ تقرير أسعار المنافسين");
        const clearedItems = items.map(item => ({ ...item, price: 0 }));
        setItems(clearedItems);
        updateTemplate(clearedItems);
    };

    const addCompany = async () => {
        const name = prompt("اسم الشركة:");
        if(name) await push(ref(db, 'settings/companies'), { name, createdBy: user.username });
    };

    const handleAddMarket = async () => {
        const name = prompt("ادخل اسم الماركت الجديد:");
        if (name) await push(ref(db, 'settings/markets'), { name, createdBy: user.username });
    };

    const categories = ['مناديل سحب (Facial)', 'مناديل مطبخ (Kitchen)', 'تواليت (Toilet)'];
    const inputClass = "border p-2 rounded w-full text-black";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-white/5 p-4 rounded-lg text-black">
                <div>
                    <label className="block mb-1 font-bold text-gray-700 dark:text-gray-300">الماركت</label>
                    <div className="flex gap-2">
                        <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                            <option value="">اختر الماركت</option>
                            {markets.map(m => <option key={m} value={m}>{m}</option>)}
                        </select>
                        <button onClick={handleAddMarket} className="bg-blue-600 text-white p-2 rounded shrink-0" title="إضافة ماركت جديد">
                            <Plus size={18}/>
                        </button>
                    </div>
                </div>
                <div>
                    <label className="block mb-1 font-bold text-gray-700 dark:text-gray-300">الشركة</label>
                    <div className="flex gap-2">
                         <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                            <option value="">اختر الشركة</option>
                            {companies.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                         <button onClick={addCompany} className="bg-blue-500 text-white p-2 rounded shrink-0"><Plus size={18}/></button>
                    </div>
                </div>
            </div>

            {selectedMarket && selectedCompany && (
                <div className="text-sm text-blue-600 bg-blue-50 p-3 rounded-lg border border-blue-100">
                    ملاحظة: الأصناف المثبتة خاصة بحسابك فقط لهذا الماركت والشركة.
                </div>
            )}

            {categories.map(cat => (
                <div key={cat} className="border border-gray-200/20 p-4 rounded-xl bg-white/5">
                    <h3 className="font-bold mb-4 text-yellow-600 border-b border-gray-200/10 pb-2 text-lg">{cat}</h3>
                    <div className="flex gap-2 mb-2 px-1 text-[10px] md:text-xs font-bold opacity-60 uppercase">
                        <div className="flex-1">اسم الصنف</div>
                        <div className="w-24 md:w-32 text-center">السعر</div>
                        <div className="w-8"></div>
                    </div>
                    <div className="space-y-2">
                        {items.map((item, idx) => item.category === cat && (
                            <div key={idx} className="flex flex-row gap-2 items-center">
                                <div className="flex-1 min-w-0">
                                    <input placeholder="اسم الصنف" className={`${inputClass} text-xs md:text-sm h-10`} value={item.name} onChange={e => updateItem(idx, 'name', e.target.value)} />
                                </div>
                                <div className="w-24 md:w-32 flex-shrink-0">
                                    <input type="number" placeholder="السعر" className={`${inputClass} text-center text-xs md:text-sm h-10`} value={item.price || ''} onChange={e => updateItem(idx, 'price', e.target.value)} />
                                </div>
                                <button onClick={() => deleteItem(idx)} className="p-1.5 text-red-500 hover:bg-red-50 rounded transition shrink-0"><Trash2 size={16} /></button>
                            </div>
                        ))}
                    </div>
                    <button onClick={() => addItem(cat)} className="mt-4 text-xs bg-gray-100 hover:bg-white text-black px-4 py-2 rounded-lg shadow-sm border border-gray-200 transition w-full md:w-auto flex items-center justify-center gap-1">
                        <Plus size={14}/> اضف منتج جديد
                    </button>
                </div>
            ))}
            <button onClick={handleSaveReport} className="bg-green-600 hover:bg-green-700 w-full py-4 text-white rounded-2xl font-bold shadow-xl text-lg transition transform active:scale-[0.98] flex items-center justify-center gap-2">
                <Save size={24} /> حفظ التقرير وترحيله
            </button>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { ref, push, set } from "firebase/database";
import { db } from '../firebase';
import { User } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

interface InventoryItem {
    id: string;
    name: string;
    qty: number;
    category: string;
    isCustom: boolean;
}

const InventoryRegistration: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [items, setItems] = useState<InventoryItem[]>([]);

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial', allowAdd: true },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen', allowAdd: true },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet', allowAdd: false },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin', allowAdd: true },
    ];

    useEffect(() => {
        const initItems: InventoryItem[] = [];
        allCategories.forEach(cat => {
            cat.items.forEach(prod => {
                initItems.push({
                    id: prod,
                    name: prod,
                    qty: 0,
                    category: cat.key,
                    isCustom: false
                });
            });
        });
        setItems(initItems);
    }, []);

    const updateItem = (id: string, field: 'qty' | 'name', value: any) => {
        setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const handleAddCustomItem = (category: string) => {
        const newItem: InventoryItem = {
            id: `custom_${Date.now()}_${Math.random()}`,
            name: '',
            qty: 0,
            category,
            isCustom: true
        };
        setItems(prev => [...prev, newItem]);
    };

    const removeCustomItem = (id: string) => {
        setItems(prev => prev.filter(i => i.id !== id));
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const inventoryData = {
            market: selectedMarket,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: items.filter(i => i.qty > 0).map(i => ({ name: i.name, qty: i.qty, category: i.category }))
        };
        if (inventoryData.items.length === 0) return alert("الكميات كلها صفر");
        await push(ref(db, 'inventory'), inventoryData);
        alert("تم حفظ المخزون");
        setItems(prev => prev.map(i => ({...i, qty: 0})));
    };

    const handleAddMarket = async () => {
         const name = prompt("ادخل اسم الماركت الجديد:");
         if (name) await push(ref(db, 'settings/markets'), { name, createdBy: user.username });
    };

    const inputClass = theme === 'win10' || theme === 'light' 
        ? "border border-gray-300 p-2 rounded text-black" 
        : "bg-white/10 border border-white/20 p-2 rounded text-white";

    return (
        <div className="pb-20">
            <div className="flex justify-between mb-6">
                <h2 className="text-2xl font-bold">تسجيل المخزون</h2>
                <div className="flex gap-2">
                    <select className={`${inputClass} w-48`} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">اختر الماركت</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                    <button onClick={handleAddMarket} className="bg-blue-500 text-white p-2 rounded"><Plus /></button>
                </div>
            </div>

            {allCategories.map(cat => (
                <div key={cat.key} className="mb-6 bg-white/5 p-4 rounded-lg">
                    <div className="flex justify-between items-center mb-4 border-b border-gray-500/20 pb-2">
                        <h3 className="text-xl font-bold text-blue-500">{cat.name}</h3>
                        {cat.allowAdd && (
                             <button onClick={() => handleAddCustomItem(cat.key)} className="bg-green-600 hover:bg-green-700 text-white text-xs px-3 py-1.5 rounded flex items-center gap-1 shadow"><Plus size={14}/> اضف صنف</button>
                        )}
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {items.filter(i => i.category === cat.key).map((item) => (
                            <div key={item.id} className="flex justify-between items-center gap-2 p-2 border-b border-gray-500/10">
                                <div className="flex-1">
                                    {item.isCustom ? (
                                        <input type="text" value={item.name} onChange={e => updateItem(item.id, 'name', e.target.value)} className={`${inputClass} w-full text-sm`} placeholder="اسم الصنف الجديد..." />
                                    ) : (
                                        <span className="text-sm font-medium">{item.name}</span>
                                    )}
                                </div>
                                <div className="flex items-center gap-2">
                                    <input type="number" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} className={`${inputClass} w-20 text-center`} placeholder="الكمية" />
                                    {item.isCustom && <button onClick={() => removeCustomItem(item.id)} className="text-red-500 hover:bg-red-500/10 p-1 rounded transition"><Trash2 size={16} /></button>}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <div className="fixed bottom-4 left-4 right-4 md:left-auto md:right-8 md:w-auto flex justify-center z-10">
                <button onClick={handleSave} className="w-full md:w-64 bg-green-600 hover:bg-green-700 text-white py-3 rounded-full font-bold shadow-xl flex justify-center items-center gap-2 transform transition hover:scale-105">
                    <Save size={20} /> حفظ المخزون
                </button>
            </div>
        </div>
    );
};

export default InventoryRegistration;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update, get } from "firebase/database";
import { User, AppSettings } from '../types';
import { Save, Trash2, UserPlus, Shield, Edit2, Plus, X, Lock, Key, Download, UploadCloud, Database, Send, MessageSquare, UserCheck } from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<any[]>([]);
    const [newUser, setNewUser] = useState({ name: '', username: '', password: '', role: 'user', code: '', phone: '', canViewAllSales: false });
    const [selectedPermUser, setSelectedPermUser] = useState<string>('');
    const [marketList, setMarketList] = useState<{key: string, val: string, createdBy?: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, val: string, createdBy?: string}[]>([]);
    const [newItemVal, setNewItemVal] = useState('');
    const [editingItem, setEditingItem] = useState<{key: string, val: string, type: 'market'|'company'} | null>(null);
    const [passModal, setPassModal] = useState<{key: string, name: string} | null>(null);
    const [newPass, setNewPass] = useState('');
    const [msgTargetUser, setMsgTargetUser] = useState('');
    const [msgBody, setMsgBody] = useState('');
    const [showMsgModal, setShowMsgModal] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: any[] = []; snapshot.forEach(c => { u.push({ key: c.key, ...c.val() }); }); setUsers(u);
            }
        });

        onValue(ref(db, 'settings/markets'), snapshot => {
            if(snapshot.exists()){
                const m: any[] = [];
                snapshot.forEach(c => { 
                    const data = c.val();
                    m.push({
                        key: c.key, 
                        val: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'system' : data.createdBy
                    });
                });
                setMarketList(m);
            }
        });

        onValue(ref(db, 'settings/companies'), snapshot => {
            if(snapshot.exists()){
                const c: any[] = [];
                snapshot.forEach(k => { 
                    const data = k.val();
                    c.push({
                        key: k.key, 
                        val: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'system' : data.createdBy
                    });
                });
                setCompanyList(c);
            }
        });
    }, []);

    const saveSettings = async () => { await set(ref(db, 'settings/app'), localSettings); alert('تم حفظ الإعدادات'); };
    const updatePermission = (key: keyof AppSettings['permissions'], value: boolean) => setLocalSettings(prev => ({ ...prev, permissions: { ...prev.permissions, [key]: value } }));
    const handleAddUser = async () => { if (!newUser.username || !newUser.password || !newUser.name) return; await push(ref(db, 'users'), newUser); alert("تم اضافة المستخدم"); };
    const handleDeleteUser = async (key: string) => { if (confirm("حذف المستخدم؟")) await remove(ref(db, `users/${key}`)); };
    const handleUpdatePassword = async () => { if(!passModal || !newPass) return; await set(ref(db, `users/${passModal.key}/password`), newPass); setPassModal(null); };
    const handleAddListItem = async (type: 'market' | 'company') => {
        if(!newItemVal) return;
        const path = type === 'market' ? 'settings/markets' : 'settings/companies';
        await push(ref(db, path), { name: newItemVal, createdBy: user.username });
        setNewItemVal('');
    };

    const inputClass = "w-full p-2 rounded border border-gray-300 text-black";
    const sectionClass = `p-6 rounded-lg mb-6 ${theme === 'dark' ? 'bg-gray-800 border border-gray-700' : 'bg-white shadow'}`;

    return (
        <div className="max-w-4xl mx-auto space-y-6 pb-10">
            <h2 className="text-3xl font-bold mb-6">الإعدادات</h2>
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-4 border-b pb-2">إدارة الماركت والشركات (الكل)</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <h4 className="font-bold mb-2">الماركت</h4>
                        <ul className="max-h-60 overflow-y-auto space-y-1">
                            {marketList.map(m => (
                                <li key={m.key} className="flex justify-between items-center bg-black/5 p-2 rounded text-sm">
                                    <span>{m.val} <span className="text-[10px] opacity-50">({m.createdBy})</span></span>
                                    <button onClick={() => remove(ref(db, `settings/markets/${m.key}`))} className="text-red-500"><Trash2 size={14}/></button>
                                </li>
                            ))}
                        </ul>
                    </div>
                    <div>
                        <h4 className="font-bold mb-2">الشركات</h4>
                        <ul className="max-h-60 overflow-y-auto space-y-1">
                            {companyList.map(c => (
                                <li key={c.key} className="flex justify-between items-center bg-black/5 p-2 rounded text-sm">
                                    <span>{c.val} <span className="text-[10px] opacity-50">({c.createdBy})</span></span>
                                    <button onClick={() => remove(ref(db, `settings/companies/${c.key}`))} className="text-red-500"><Trash2 size={14}/></button>
                                </li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>

            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-4 border-b pb-2">إدارة المستخدمين</h3>
                <div className="bg-gray-100 p-4 rounded mb-4 text-black">
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                        <input placeholder="الاسم" className={inputClass} value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} />
                        <input placeholder="اسم المستخدم" className={inputClass} value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})} />
                        <input placeholder="كلمة المرور" type="password" className={inputClass} value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} />
                        <select className={inputClass} value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value})}>
                            <option value="user">مستخدم عادي</option>
                            <option value="admin">مسؤول</option>
                        </select>
                    </div>
                    <button onClick={handleAddUser} className="mt-2 bg-green-600 text-white px-4 py-1 rounded">إضافة</button>
                </div>
                <table className="w-full text-sm text-right">
                    <thead><tr className="bg-gray-200"><th>الاسم</th><th>المستخدم</th><th>الدور</th><th>إجراء</th></tr></thead>
                    <tbody>
                        {users.map(u => (
                            <tr key={u.key} className="border-b">
                                <td className="p-2">{u.name}</td><td className="p-2">{u.username}</td><td className="p-2">{u.role}</td>
                                <td className="p-2"><button onClick={() => handleDeleteUser(u.key)} className="text-red-500"><Trash2 size={16}/></button></td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { ref, push, set } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Plus, Trash2, Save } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [notification, setNotification] = useState('');

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
    ];

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        allCategories.forEach(cat => {
            cat.items.forEach(itemName => {
                initialItems.push({
                    id: itemName + Math.random(),
                    category: cat.key,
                    name: itemName,
                    price: 0,
                    qty: 0
                });
            });
        });
        setSalesItems(initialItems);
    }, []);

    const updateItem = (id: string, field: keyof ProductItem, value: any) => {
        setSalesItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const calculateTotal = () => salesItems.reduce((sum, item) => sum + ((Number(item.price) || 0) * (Number(item.qty) || 0)), 0);

    const handleSave = async () => {
        if (!selectedMarket) return alert("الرجاء اختيار الماركت");
        const soldItems = salesItems.filter(item => (Number(item.price) > 0 && Number(item.qty) > 0));
        if (soldItems.length === 0) return alert("لا يوجد مبيعات مكتملة للحفظ");

        const saleData = {
            market: selectedMarket,
            employeeName: user.name,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: soldItems,
            total: calculateTotal()
        };

        await push(ref(db, 'sales'), saleData);
        setNotification('تم حفظ المبيعات بنجاح!');
        setSalesItems(prev => prev.map(item => ({...item, price: 0, qty: 0})));
        setTimeout(() => setNotification(''), 3000);
    };

    const handleAddMarket = async () => {
        const name = prompt("ادخل اسم الماركت الجديد:");
        if (name) await push(ref(db, 'settings/markets'), { name, createdBy: user.username });
    };

    const inputClass = theme === 'win10' || theme === 'light' 
        ? "border border-gray-300 p-2 rounded w-full text-black" 
        : "bg-white/10 border border-white/20 p-2 rounded w-full text-white placeholder-gray-400";

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-2xl font-bold">المبيعات اليومية</h2>
                <div className="text-xl font-bold bg-green-500 text-white px-4 py-2 rounded shadow w-full md:w-auto text-center">
                    إجمالي الفاتورة: {calculateTotal().toLocaleString()} ج.م
                </div>
            </div>

            <div className="flex items-end gap-2">
                <div className="flex-1">
                    <label className="block mb-1 font-semibold">اسم الماركت</label>
                    <select value={selectedMarket} onChange={(e) => setSelectedMarket(e.target.value)} className={inputClass}>
                        <option value="">اختر الماركت...</option>
                        {markets.map((m, idx) => <option key={idx} value={m}>{m}</option>)}
                    </select>
                </div>
                <button onClick={handleAddMarket} className="bg-blue-500 hover:bg-blue-600 text-white p-2 rounded mb-[2px]"><Plus size={24} /></button>
            </div>

            {allCategories.map(cat => (
                <div key={cat.key}>
                    <div className="bg-gray-400 text-black font-bold p-2 rounded mt-4 mb-2 text-center shadow-sm">{cat.name}</div>
                    <div className="space-y-2">
                        {salesItems.filter(item => item.category === cat.key).map((item) => (
                            <div key={item.id} className="grid grid-cols-12 gap-1 items-center bg-black/5 p-1 rounded">
                                <div className="col-span-4 text-xs truncate pr-2">{item.name}</div>
                                <div className="col-span-3">
                                    <input type="number" value={item.price || ''} onChange={(e) => updateItem(item.id, 'price', parseFloat(e.target.value))} className={`${inputClass} text-center h-8 text-xs`} placeholder="السعر" />
                                </div>
                                <div className="col-span-2">
                                    <input type="number" value={item.qty || ''} onChange={(e) => updateItem(item.id, 'qty', parseFloat(e.target.value))} className={`${inputClass} text-center h-8 text-xs`} placeholder="0" />
                                </div>
                                <div className="col-span-3 text-center font-bold text-xs">{(Number(item.price) * Number(item.qty)) || '-'}</div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            <div className="mt-8 flex justify-center sticky bottom-4 z-10">
                <button onClick={handleSave} className="bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-8 rounded-full shadow-xl flex items-center gap-2 text-lg transform hover:scale-105 transition w-full md:w-auto justify-center">
                    <Save size={24} /> حفظ وترحيل
                </button>
            </div>

            {notification && <div className="fixed bottom-4 left-4 right-4 md:right-auto bg-green-600 text-white px-6 py-3 rounded-lg shadow-lg animate-bounce text-center z-50">{notification}</div>}
        </div>
    );
};

export default DailySales;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, CompetitorPrice } from '../types';
import { exportToCSV } from '../utils';
import { COMPANIES } from '../constants';
import { Trash2, Edit, Save, X, FileSpreadsheet, Columns2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorReports: React.FC<Props> = ({ user, markets, theme }) => {
    const [data, setData] = useState<CompetitorPrice[]>([]);
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [editingReport, setEditingReport] = useState<CompetitorPrice | null>(null);

    useEffect(() => {
        // جلب الشركات مع تطبيق منطق الخصوصية
        onValue(ref(db, 'settings/companies'), s => {
            if(s.exists()) {
                const data = s.val();
                const allCompanies: any[] = Object.keys(data).map(key => {
                    if (typeof data[key] === 'string') return { name: data[key], createdBy: 'system' };
                    return data[key];
                });

                if (user.role === 'admin') {
                    // المسؤول يرى كل الشركات
                    setCompanies(allCompanies.map(c => c.name));
                } else {
                    // المستخدم يرى فقط الشركات الافتراضية أو التي أضافها هو
                    const filtered = allCompanies.filter(c => c.createdBy === 'system' || c.createdBy === user.username);
                    setCompanies(filtered.map(c => c.name));
                }
            } else {
                setCompanies(COMPANIES);
            }
        });

        onValue(ref(db, 'competitor_prices'), s => {
            if(s.exists()) {
                let arr = Object.keys(s.val()).map(key => ({
                    id: key,
                    ...s.val()[key]
                })) as CompetitorPrice[];

                // خصوصية التقارير: المستخدم يرى تقاريره فقط، الـ Admin يرى الكل
                if (user.role !== 'admin') {
                    arr = arr.filter(d => d.employeeName === user.name);
                }

                setData(arr);
            } else {
                setData([]);
            }
        });
    }, [user.username, user.role, user.name]);

    const filtered = data.filter(d => 
        (!selectedMarket || d.market === selectedMarket) &&
        (!selectedCompany || d.company === selectedCompany)
    );

    const handleExport = () => {
        if (filtered.length === 0) return alert("لا توجد بيانات لتصديرها");
        const csv = filtered.flatMap(d => (d.items || []).map(i => ({
            "الماركت": d.market,
            "الشركة": d.company,
            "التاريخ": d.date,
            "بواسطة": d.employeeName || '-',
            "القسم": i.category,
            "المنتج": i.name,
            "السعر": i.price
        })));
        const fileName = selectedCompany ? `تقرير_منافسين_${selectedCompany}` : 'تقرير_المنافسين_العام';
        exportToCSV(csv, fileName);
    };

    const handleExportHorizontal = () => {
        if (!selectedMarket) return alert("يرجى اختيار الماركت أولاً للمقارنة");

        const marketData = data.filter(d => d.market === selectedMarket);
        const companyGroups: Record<string, {name: string, price: number}[]> = {};

        marketData.forEach(report => {
            if (!companyGroups[report.company]) companyGroups[report.company] = [];
            companyGroups[report.company].push(...report.items);
        });

        const activeCompanies = Object.keys(companyGroups);
        if (activeCompanies.length === 0) return alert("لا توجد بيانات لهذا الماركت");

        const maxRows = Math.max(...activeCompanies.map(c => companyGroups[c].length));
        const csvRows: any[] = [];

        for (let i = 0; i < maxRows; i++) {
            const row: Record<string, any> = {};
            activeCompanies.forEach(company => {
                const item = companyGroups[company][i];
                row[`${company} - الصنف`] = item ? item.name : "";
                row[`${company} - السعر`] = item ? item.price : "";
            });
            csvRows.push(row);
        }

        exportToCSV(csvRows, `مقارنة_عرضية_${selectedMarket}`);
    };

    const handleDelete = async (id: string) => {
        if(confirm("حذف هذا التقرير؟")) {
            await remove(ref(db, `competitor_prices/${id}`));
        }
    };

    const saveEdit = async () => {
        if(!editingReport || !editingReport.id) return;
        try {
            await update(ref(db, `competitor_prices/${editingReport.id}`), {
                items: editingReport.items
            });
            setEditingReport(null);
            alert("تم التعديل");
        } catch(e) { console.error(e); }
    };

    const updateEditItem = (index: number, price: number) => {
        if(!editingReport) return;
        const newItems = [...editingReport.items];
        newItems[index].price = price;
        setEditingReport({...editingReport, items: newItems});
    };

    const inputClass = "border p-2 rounded text-black w-full text-sm md:text-base";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">تقارير المنافسين</h2>

            <div className="bg-white/5 p-4 rounded-xl space-y-4">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                        <label className="block text-xs mb-1 opacity-70">فلترة بالماركت</label>
                        <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                            <option value="">كل الماركتات</option>
                            {markets.map(m => <option key={m} value={m}>{m}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-xs mb-1 opacity-70">فلترة بالشركة</label>
                        <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                            <option value="">كل الشركات</option>
                            {companies.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                    </div>
                </div>

                <div className="flex flex-col md:flex-row gap-3 pt-2">
                    <button 
                        onClick={handleExport} 
                        className="flex-1 bg-green-600 hover:bg-green-700 text-white px-4 py-2.5 rounded-lg flex items-center justify-center gap-2 font-bold transition shadow-lg"
                    >
                        <FileSpreadsheet size={20} /> تصدير إكسيل (طولي)
                    </button>

                    {selectedMarket && (
                        <button 
                            onClick={handleExportHorizontal} 
                            className="flex-1 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 rounded-lg flex items-center justify-center gap-2 font-bold transition shadow-lg border-2 border-blue-400/30"
                        >
                            <Columns2 size={20} /> تصدير مقارنة عرضية (ماركت {selectedMarket})
                        </button>
                    )}
                </div>
            </div>

            <div className="space-y-4">
                {filtered.length === 0 ? (
                    <div className="text-center py-10 opacity-50 italic">لا توجد تقارير مطابقة للبحث</div>
                ) : filtered.map((record, i) => (
                    <div key={record.id || i} className={`p-4 rounded-xl border transition-all hover:shadow-md ${theme === 'dark' ? 'bg-gray-800 border-gray-700' : 'bg-white border-gray-100 shadow'}`}>
                        <div className="font-bold text-lg mb-2 flex justify-between items-center">
                            <div className="flex flex-col">
                                <span className="text-blue-600">{record.company}</span>
                                <span className="text-xs font-normal opacity-70">{record.market} | {record.date}</span>
                                <span className="text-[10px] text-gray-400">بواسطة: {record.employeeName}</span>
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => setEditingReport(record)} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg transition"><Edit size={18}/></button>
                                {(user.role === 'admin' || user.name === record.employeeName) && (
                                     <button onClick={() => handleDelete(record.id!)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg transition"><Trash2 size={18}/></button>
                                )}
                            </div>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-center">
                                <thead className="bg-gray-500/5">
                                    <tr className="border-b border-gray-500/10">
                                        <th className="p-2 text-right">المنتج</th>
                                        <th className="p-2">السعر</th>
                                        <th className="p-2 hidden md:table-cell">القسم</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {(record.items || []).map((item, idx) => (
                                        <tr key={idx} className="border-b border-gray-500/5 hover:bg-black/5">
                                            <td className="p-2 text-right">{item.name}</td>
                                            <td className="p-2 font-bold text-green-600">{item.price}</td>
                                            <td className="p-2 opacity-70 text-xs hidden md:table-cell">{item.category}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                ))}
            </div>

            {/* Edit Modal */}
            {editingReport && (
                <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 overflow-y-auto p-4 backdrop-blur-sm">
                    <div className={`w-full max-w-xl rounded-2xl shadow-2xl p-6 ${theme === 'dark' ? 'bg-gray-800 text-white' : 'bg-white text-black'}`}>
                        <div className="flex justify-between items-center mb-4 border-b pb-2">
                            <h3 className="font-bold text-xl">تعديل أسعار {editingReport.company}</h3>
                            <button onClick={() => setEditingReport(null)} className="p-1 hover:bg-red-50 rounded-full transition"><X /></button>
                        </div>
                        <div className="max-h-[60vh] overflow-y-auto space-y-2 mb-4 pr-1 custom-scrollbar">
                            {editingReport.items.map((item, idx) => (
                                <div key={idx} className="flex justify-between items-center p-3 border border-gray-100/10 rounded-lg bg-black/5 gap-2">
                                    <span className="flex-1 text-sm font-medium">{item.name}</span>
                                    <div className="w-24">
                                        <input 
                                            type="number" 
                                            value={item.price} 
                                            onChange={e => updateEditItem(idx, Number(e.target.value))}
                                            className="w-full p-2 border rounded-lg text-center text-black font-bold focus:ring-2 focus:ring-blue-500 outline-none"
                                            placeholder="السعر"
                                        />
                                    </div>
                                </div>
                            ))}
                        </div>
                        <div className="flex justify-end gap-2 pt-4 border-t">
                            <button onClick={() => setEditingReport(null)} className="px-6 py-2 bg-gray-200 text-black rounded-xl font-bold hover:bg-gray-300 transition">إلغاء</button>
                            <button onClick={saveEdit} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 transition shadow-lg"><Save size={18}/> حفظ التعديل</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CompetitorReports;

