            "الماركت": d.market,
            "الشركة": d.company,
            "التاريخ": d.date,
            "بواسطة": d.employeeName || '-',
            "القسم": i.category,
            "المنتج": i.name,
            "السعر": i.price
        })));
        exportToCSV(csv, 'تقرير_المنافسين');
    };

