import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set, update, onDisconnect, serverTimestamp } from "firebase/database";
import { User, AppSettings, AppNotification } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, 
    showInventoryReg: false, 
    showCompetitorReports: false 
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'glass' | 'dark' | 'win10' | 'light'>('win10');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showThemeSelector, setShowThemeSelector] = useState(false);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);

  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    onValue(settingsRef, (snapshot) => {
      if (snapshot.exists()) setSettings({...DEFAULT_SETTINGS, ...snapshot.val()});
    });

    onValue(marketsRef, (snapshot) => {
      // 1. الماركتات الافتراضية للنظام
      const systemMarkets = INITIAL_MARKETS.map(name => ({ name, createdBy: 'system' }));

      // 2. الماركتات المضافة في قاعدة البيانات
      const dbMarkets = snapshot.exists() ? Object.values(snapshot.val()).map((m: any) => 
        typeof m === 'string' ? { name: m, createdBy: 'system' } : m
      ) : [];

      // 3. دمج الجميع
      const allCombined = [...systemMarkets, ...dbMarkets];

      if (user) {
        let filtered;
        if (user.role === 'admin') {
          // المسؤول يرى كل شيء
          filtered = allCombined;
        } else {
          // المستخدم يرى الافتراضي + ما أضافه هو فقط
          filtered = allCombined.filter(m => m.createdBy === 'system' || m.createdBy === user.username);
        }

        // إزالة التكرار بناءً على الاسم
        const uniqueNames = Array.from(new Set(filtered.map(m => m.name)));
        setMarkets(uniqueNames);
      }
    }, { onlyOnce: false });

    onValue(connectedRef, (snap) => setIsConnected(!!snap.val()));
  }, [user?.username, user?.role]);

  useEffect(() => {
    if (!user) return;
    const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
    const userStatusRef = ref(db, `status/${safeKey}`);
    set(userStatusRef, { online: true, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    onDisconnect(userStatusRef).set({ online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });

    onValue(ref(db, `notifications/${user.username}`), (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list = Object.keys(data).map(key => ({ id: key, ...data[key] })).sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        }
    });
  }, [user?.username]);

  const handleLogout = async () => {
    if (user) {
        const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `status/${safeKey}`), { online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    }
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  if (!user) return <Login onLogin={setUser} theme={theme} />;

  const getThemeClasses = () => {
    switch(theme) {
        case 'glass': return "bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500 min-h-screen text-white";
        case 'dark': return "bg-gray-900 text-white min-h-screen";
        case 'win10': return "bg-[#0078D7] min-h-screen font-sans";
        default: return "bg-gray-100 text-gray-800 min-h-screen";
    }
  };

  return (
    <div className={`${getThemeClasses()} flex flex-col overflow-hidden`}>
      {settings.tickerEnabled && (
        <div className="bg-black text-yellow-400 py-1 overflow-hidden whitespace-nowrap border-b border-yellow-600">
           <div className="animate-marquee inline-block px-4">{settings.tickerText}</div>
        </div>
      )}

      <header className={`p-4 flex justify-between items-center ${theme === 'glass' ? 'bg-white/10' : theme === 'dark' ? 'bg-gray-800' : 'bg-white text-black shadow-md'}`}>
        <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="md:hidden p-2 rounded hover:bg-black/10">
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="text-xl md:text-2xl font-bold truncate">{settings.appName}</h1>
        </div>
        <div className="flex items-center gap-4">
            <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className="relative p-2 rounded-full hover:bg-black/10">
                <Bell size={20} />
                {unreadCount > 0 && <span className="absolute top-1 right-1 bg-red-600 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-white">{unreadCount}</span>}
            </button>
            <div className="text-sm hidden md:block">مرحباً، <span className="font-bold">{user.name}</span></div>
            <button onClick={handleLogout} className="text-red-500 p-1"><LogOut size={20} /></button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <div className={`absolute top-0 bottom-0 right-0 z-30 h-full transition-transform duration-300 md:relative md:transform-none ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
            <Sidebar currentView={currentView} setView={(view) => { setCurrentView(view); setIsSidebarOpen(false); }} user={user} theme={theme} settings={settings} containerClass={`${theme === 'glass' ? 'bg-white/10 backdrop-blur-md' : theme === 'dark' ? 'bg-gray-800' : 'bg-gray-50 border-l border-gray-200'} h-full shadow-xl`} />
        </div>
        <main className="flex-1 p-2 md:p-4 overflow-y-auto w-full">
            <div className={`p-4 md:p-6 min-h-full ${theme === 'win10' ? 'bg-white text-black border-2 border-[#005a9e]' : 'bg-white/90 backdrop-blur-sm rounded-xl shadow-lg text-black'}`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorPrices' && <CompetitorPrices user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorReports' && <CompetitorReports user={user} markets={markets} theme={theme} />}
                {currentView === 'leaveBalance' && <LeaveBalanceComponent user={user} theme={theme} />}
                {currentView === 'settings' && <Settings user={user} settings={settings} markets={markets} theme={theme} setTheme={setTheme} />}
            </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue } from "firebase/database";
import { User } from '../types';
import { 
    COMPANIES, 
    PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, 
    FINE_FACIAL, FINE_KITCHEN, FINE_TOILET,
    ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET,
    PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET,
    WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET
} from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [items, setItems] = useState<{category: string, name: string, price: number}[]>([]);

    useEffect(() => {
        // فلترة الشركات بخصوصية
        onValue(ref(db, 'settings/companies'), s => {
            const systemCompanies = COMPANIES.map(name => ({ name, createdBy: 'system' }));
            const dbCompanies = s.exists() ? Object.values(s.val()).map((c: any) => 
                typeof c === 'string' ? { name: c, createdBy: 'system' } : c
            ) : [];

            const allCombined = [...systemCompanies, ...dbCompanies];

            let filtered;
            if (user.role === 'admin') {
                filtered = allCombined;
            } else {
                filtered = allCombined.filter(c => c.createdBy === 'system' || c.createdBy === user.username);
            }

            const uniqueNames = Array.from(new Set(filtered.map(c => c.name)));
            setCompanies(uniqueNames);
        });
    }, [user.username, user.role]);

    const getTemplatePath = () => {
        if (!selectedMarket || !selectedCompany || !user.username) return null;
        const safeUser = user.username.replace(/[.#$/[\]]/g, "_");
        const safeMarket = selectedMarket.replace(/[.#$/[\]]/g, "_");
        const safeCompany = selectedCompany.replace(/[.#$/[\]]/g, "_");
        return `competitor_templates/${safeUser}/${safeMarket}/${safeCompany}`;
    };

    const generateDefaultsFromList = (facial: string[], kitchen: string[], toilet: string[]) => {
        const defaultItems: {category: string, name: string, price: number}[] = [];
        facial.forEach(name => defaultItems.push({ category: 'مناديل سحب (Facial)', name, price: 0 }));
        kitchen.forEach(name => defaultItems.push({ category: 'مناديل مطبخ (Kitchen)', name, price: 0 }));
        toilet.forEach(name => defaultItems.push({ category: 'تواليت (Toilet)', name, price: 0 }));
        return defaultItems;
    };

    useEffect(() => {
        const path = getTemplatePath();
        if (path) {
            onValue(ref(db, path), (snapshot) => {
                if (snapshot.exists()) {
                    setItems(snapshot.val());
                } else {
                    if (selectedCompany === 'Soft Rose') setItems(generateDefaultsFromList(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET));
                    else if (selectedCompany === 'Fine') setItems(generateDefaultsFromList(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET));
                    else if (selectedCompany === 'Zeina') setItems(generateDefaultsFromList(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET));
                    else if (selectedCompany === 'Papia Familia') setItems(generateDefaultsFromList(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET));
                    else if (selectedCompany === 'White') setItems(generateDefaultsFromList(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET));
                    else setItems([]);
                }
            });
        }
    }, [selectedMarket, selectedCompany]);

    const updateTemplate = async (newItems: any[]) => {
        const path = getTemplatePath();
        if (path) await set(ref(db, path), newItems);
    };

    const addItem = (category: string) => {
        const newItems = [...items, { category, name: '', price: 0 }];
        setItems(newItems);
        updateTemplate(newItems);
    };

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...items];
        // @ts-ignore
        newItems[index][field] = value;
        setItems(newItems);
        updateTemplate(newItems);
    };

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const validItems = items.filter(i => i.name && i.price > 0);
        const data = {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            employeeName: user.name,
            items: validItems
        };
        await push(ref(db, 'competitor_prices'), data);
        alert("تم الحفظ");
        setItems(items.map(i => ({...i, price: 0})));
        updateTemplate(items.map(i => ({...i, price: 0})));
    };

    const handleAddMarket = async () => {
        const name = prompt("ادخل اسم الماركت الجديد:");
        if (name) await push(ref(db, 'settings/markets'), { name, createdBy: user.username });
    };

    const addCompany = async () => {
        const name = prompt("اسم الشركة الجديدة:");
        if(name) await push(ref(db, 'settings/companies'), { name, createdBy: user.username });
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-100 p-4 rounded-lg">
                <div>
                    <label className="block mb-1 font-bold">الماركت</label>
                    <div className="flex gap-2">
                        <select className="border p-2 rounded w-full" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                            <option value="">اختر الماركت</option>
                            {markets.map(m => <option key={m} value={m}>{m}</option>)}
                        </select>
                        <button onClick={handleAddMarket} className="bg-blue-600 text-white p-2 rounded"><Plus size={18}/></button>
                    </div>
                </div>
                <div>
                    <label className="block mb-1 font-bold">الشركة</label>
                    <div className="flex gap-2">
                         <select className="border p-2 rounded w-full" value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                            <option value="">اختر الشركة</option>
                            {companies.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                         <button onClick={addCompany} className="bg-blue-500 text-white p-2 rounded"><Plus size={18}/></button>
                    </div>
                </div>
            </div>

            {['مناديل سحب (Facial)', 'مناديل مطبخ (Kitchen)', 'تواليت (Toilet)'].map(cat => (
                <div key={cat} className="border p-4 rounded-xl">
                    <h3 className="font-bold mb-4 text-blue-600 border-b pb-2">{cat}</h3>
                    <div className="space-y-2">
                        {items.filter(i => i.category === cat).map((item, idx) => {
                            const actualIdx = items.indexOf(item);
                            return (
                                <div key={actualIdx} className="flex gap-2 items-center">
                                    <input className="flex-1 border p-2 rounded text-sm" value={item.name} onChange={e => updateItem(actualIdx, 'name', e.target.value)} placeholder="اسم المنتج" />
                                    <input type="number" className="w-24 border p-2 rounded text-center" value={item.price || ''} onChange={e => updateItem(actualIdx, 'price', e.target.value)} placeholder="السعر" />
                                    <button onClick={() => { const n = items.filter((_, i) => i !== actualIdx); setItems(n); updateTemplate(n); }} className="text-red-500"><Trash2 size={18}/></button>
                                </div>
                            );
                        })}
                    </div>
                    <button onClick={() => addItem(cat)} className="mt-2 text-xs bg-gray-200 p-2 rounded flex items-center gap-1"><Plus size={14}/> صنف جديد</button>
                </div>
            ))}
            <button onClick={handleSaveReport} className="bg-green-600 w-full py-4 text-white rounded-xl font-bold shadow-lg">حفظ وترحيل البيانات</button>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings } from '../types';
import { 
  Save, Trash2, UserPlus, Shield, Edit2, Plus, X, 
  Settings as SettingsIcon, Users, MapPin, Building2, 
  ToggleLeft, ToggleRight, Key, MessageSquare 
} from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<any[]>([]);
    const [newUser, setNewUser] = useState({ name: '', username: '', password: '', role: 'user' as const, canViewAllSales: false });
    const [marketList, setMarketList] = useState<{key: string, name: string, createdBy: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, name: string, createdBy: string}[]>([]);
    const [passModal, setPassModal] = useState<{key: string, name: string} | null>(null);
    const [newPass, setNewPass] = useState('');

    useEffect(() => {
        setLocalSettings(settings);
    }, [settings]);

    useEffect(() => {
        if (user.role !== 'admin') return;

        // جلب المستخدمين
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: any[] = [];
                snapshot.forEach(c => { u.push({ key: c.key, ...c.val() }); });
                setUsers(u);
            }
        });

        // جلب الماركتات مع تفاصيل المنشئ
        onValue(ref(db, 'settings/markets'), snapshot => {
            if(snapshot.exists()){
                const m: any[] = [];
                snapshot.forEach(c => { 
                    const data = c.val();
                    m.push({
                        key: c.key, 
                        name: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'System' : data.createdBy
                    });
                });
                setMarketList(m);
            }
        });

        // جلب الشركات مع تفاصيل المنشئ
        onValue(ref(db, 'settings/companies'), snapshot => {
            if(snapshot.exists()){
                const c: any[] = [];
                snapshot.forEach(k => { 
                    const data = k.val();
                    c.push({
                        key: k.key, 
                        name: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'System' : data.createdBy
                    });
                });
                setCompanyList(c);
            }
        });
    }, [user.role]);

    const saveAppSettings = async () => {
        try {
            await set(ref(db, 'settings/app'), localSettings);
            alert('تم حفظ إعدادات التطبيق بنجاح');
        } catch (e) { alert('خطأ في الحفظ'); }
    };

    const togglePermission = (key: keyof AppSettings['permissions']) => {
        setLocalSettings(prev => ({
            ...prev,
            permissions: {
                ...prev.permissions,
                [key]: !prev.permissions[key]
            }
        }));
    };

    const handleAddUser = async () => {
        if (!newUser.username || !newUser.password || !newUser.name) return alert("اكمل بيانات المستخدم");
        await push(ref(db, 'users'), newUser);
        alert("تمت إضافة المستخدم بنجاح");
        setNewUser({ name: '', username: '', password: '', role: 'user', canViewAllSales: false });
    };

    const handleDeleteUser = async (key: string) => {
        if (confirm("هل أنت متأكد من حذف هذا المستخدم؟")) {
            await remove(ref(db, `users/${key}`));
        }
    };

    const handleUpdatePassword = async () => {
        if(!passModal || !newPass) return;
        await update(ref(db, `users/${passModal.key}`), { password: newPass });
        alert("تم تحديث كلمة المرور");
        setPassModal(null);
        setNewPass('');
    };

    if (user.role !== 'admin') {
        return <div className="p-10 text-center opacity-50">عذراً، هذه الصفحة متاحة للمسؤولين فقط.</div>;
    }

    const inputClass = "w-full p-2.5 rounded-lg border border-gray-300 text-black focus:ring-2 focus:ring-blue-500 outline-none";
    const sectionClass = `p-6 rounded-2xl mb-6 ${theme === 'dark' ? 'bg-gray-800 border-gray-700 border' : 'bg-white shadow-xl'}`;

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-20">
            <div className="flex items-center gap-3 mb-2">
                <SettingsIcon className="text-blue-600" size={32} />
                <h2 className="text-3xl font-bold">لوحة تحكم المسؤول</h2>
            </div>

            {/* إعدادات التطبيق العامة */}
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-6 flex items-center gap-2 text-blue-600 border-b pb-3">
                    <Edit2 size={20} /> الإعدادات العامة للمنصة
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-bold mb-2 opacity-70">اسم التطبيق (AppName)</label>
                        <input className={inputClass} value={localSettings.appName} onChange={e => setLocalSettings({...localSettings, appName: e.target.value})} />
                    </div>
                    <div>
                        <label className="block text-sm font-bold mb-2 opacity-70">رقم واتساب الدعم</label>
                        <input className={inputClass} placeholder="مثال: 2010XXXXXXXX" value={localSettings.whatsappNumber} onChange={e => setLocalSettings({...localSettings, whatsappNumber: e.target.value})} />
                    </div>
                    <div className="md:col-span-2">
