import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue } from "firebase/database";
import { User, AppSettings } from '../types';
import { 
    ShoppingCart, FileText, PackagePlus, ClipboardList, 
    TrendingUp, BarChart2, Settings as SettingsIcon, CalendarOff,
    Users, Circle
} from 'lucide-react';

interface SidebarProps {
    currentView: string;
    setView: (view: string) => void;
    user: User;
    theme: string;
    containerClass: string;
    settings: AppSettings;
}

interface UserStatus {
    username: string;
    name: string;
    online: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, user, theme, containerClass, settings }) => {
    const [onlineUsers, setOnlineUsers] = useState<UserStatus[]>([]);

    useEffect(() => {
        if (user.role === 'admin') {
            const statusRef = ref(db, 'status');
            const unsubscribe = onValue(statusRef, (snapshot) => {
                if (snapshot.exists()) {
                    const data = snapshot.val();
                    const list: UserStatus[] = Object.keys(data).map(key => ({
                        username: data[key].username || key,
                        name: data[key].name || key,
                        online: data[key].online || false
                    }));

                    const sortedList = list.sort((a, b) => {
                        if (a.online === b.online) {
                            return a.name.localeCompare(b.name, 'ar');
                        }
                        return a.online ? -1 : 1;
                    });

                    setOnlineUsers(sortedList);
                } else {
                    setOnlineUsers([]);
                }
            });
            return () => unsubscribe();
        }
    }, [user.role]);

    const allItems = [
        { id: 'sales', label: 'المبيعات اليومية', icon: ShoppingCart, alwaysShow: true },
        { id: 'salesLog', label: 'سجل المبيعات', icon: FileText, permissionKey: 'showSalesLog' },
        { id: 'inventoryReg', label: 'تسجيل المخزون', icon: PackagePlus, permissionKey: 'showInventoryReg' },
        { id: 'inventoryLog', label: 'سجل المخزون', icon: ClipboardList, permissionKey: 'showInventoryLog' },
        { id: 'competitorPrices', label: 'أسعار المنافسين', icon: TrendingUp, alwaysShow: true },
        { id: 'competitorReports', label: 'تقارير المنافسين', icon: BarChart2, permissionKey: 'showCompetitorReports' },
        { id: 'leaveBalance', label: 'رصيد الإجازات', icon: CalendarOff, alwaysShow: true },
        { id: 'settings', label: 'الإعدادات', icon: SettingsIcon, adminOnly: true },
    ];

    const menuItems = allItems.filter(item => {
        if (user.role === 'admin') return true;
        if (item.adminOnly) return false;
        if (item.alwaysShow) return true;

        // Check per-user permissions with safety guards
        if (item.permissionKey) {
            const perms = user.permissions || {} as any;
            return perms[item.permissionKey] === true;
        }

        return false;
    });

    const getButtonClass = (isActive: boolean) => {
        let classes = "group w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-300 ease-out font-medium relative overflow-hidden ";

        if (theme === 'win10') {
            classes += isActive 
                ? "bg-[#0078D7] text-white shadow-lg translate-x-2 " 
                : "text-gray-700 hover:bg-gray-200 hover:translate-x-1 ";
        } else if (theme === 'dark') {
            classes += isActive 
                ? "bg-blue-600 text-white shadow-lg shadow-blue-500/20 translate-x-2 ring-1 ring-blue-400/30 " 
                : "text-gray-400 hover:bg-gray-800 hover:text-gray-100 hover:translate-x-1 ";
        } else if (theme === 'glass') {
            classes += isActive 
                ? "bg-gradient-to-r from-white/20 to-white/5 text-white shadow-lg border-r-4 border-white backdrop-blur-md translate-x-2 " 
                : "text-white/80 hover:bg-white/10 hover:text-white hover:translate-x-1 ";
        } else {
             classes += isActive 
                ? "bg-white text-blue-700 shadow-md translate-x-2 border-r-4 border-blue-500 " 
                : "text-gray-600 hover:bg-white hover:shadow-sm hover:text-blue-900 hover:translate-x-1 ";
        }

        return classes;
    };

    const headerClass = `text-xs font-bold uppercase tracking-wider mb-6 px-2 ${
        theme === 'glass' ? 'text-white/50' : theme === 'dark' ? 'text-gray-500' : 'text-gray-400'
    }`;

    return (
        <aside className={`w-64 md:w-72 p-6 flex flex-col ${containerClass} transition-all duration-300 overflow-hidden`}>
            <div className={headerClass}>القائمة الرئيسية</div>
            <nav className="flex-1 flex flex-col gap-3 overflow-y-auto custom-scrollbar">
                {menuItems.map(item => (
                    <button
                        key={item.id}
                        onClick={() => setView(item.id)}
                        className={getButtonClass(currentView === item.id)}
                    >
                        {currentView === item.id && theme !== 'win10' && theme !== 'glass' && (
                             <div className="absolute right-0 top-1/2 -translate-y-1/2 h-6 w-1 bg-current rounded-l-full opacity-60" />
                        )}
                        <item.icon size={22} strokeWidth={1.5} className="flex-shrink-0" />
                        <span className="text-base tracking-wide">{item.label}</span>
                    </button>
                ))}

                {user.role === 'admin' && (
                    <div className="mt-8 border-t pt-4 border-gray-500/20">
                        <div className="flex items-center gap-2 mb-4 px-2 text-xs font-bold uppercase text-gray-400">
                            <Users size={14} />
                            <span>المستخدمين الآن (Online)</span>
                        </div>
                        <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar px-1">
                            {onlineUsers.length === 0 ? (
                                <div className="text-[10px] text-gray-500 italic px-2">لا توجد سجلات حالية</div>
                            ) : onlineUsers.map((u) => (
                                <div key={u.username} className="flex items-center justify-between px-3 py-2 rounded-lg bg-black/5 hover:bg-black/10 transition">
                                    <span className={`text-xs font-medium truncate flex-1 ${theme === 'dark' ? 'text-gray-300' : 'text-gray-700'}`}>
                                        {u.name}
                                    </span>
                                    <div 
                                        className={`w-2.5 h-2.5 rounded-full transition-all duration-500 ${u.online ? 'bg-blue-500 lamp-glow-blue scale-110' : 'bg-red-500 opacity-40'}`} 
                                        title={u.online ? "متصل" : "غير متصل"} 
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </nav>

            <div className={`mt-auto text-xs px-2 pt-4 border-t ${theme === 'dark' ? 'border-gray-700 text-gray-500' : 'border-gray-200/20 text-gray-400'}`}>
                v1.2.1
            </div>
        </aside>
    );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings, UserPermissions } from '../types';
import { 
  Save, Trash2, UserPlus, Shield, Edit2, Plus, X, 
  Settings as SettingsIcon, Users, MapPin, Building2, 
  ToggleLeft, ToggleRight, Key, Eye, EyeOff
} from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<User[]>([]);
    const [newUser, setNewUser] = useState<User>({ 
        name: '', 
        username: '', 
        password: '', 
        role: 'user', 
        canViewAllSales: false,
        permissions: {
            showSalesLog: true,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false
        }
    });

    const [marketList, setMarketList] = useState<{key: string, name: string, createdBy: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, name: string, createdBy: string}[]>([]);

    // Modals
    const [passModal, setPassModal] = useState<{key: string, name: string} | null>(null);
    const [permModal, setPermModal] = useState<User | null>(null);
    const [newPass, setNewPass] = useState('');

    useEffect(() => {
        setLocalSettings(settings);
    }, [settings]);

    useEffect(() => {
        if (user.role !== 'admin') return;

        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: User[] = [];
                snapshot.forEach(c => { u.push({ key: c.key || '', ...c.val() }); });
                setUsers(u);
            }
        });

        onValue(ref(db, 'settings/markets'), snapshot => {
            if(snapshot.exists()){
                const m: any[] = [];
                snapshot.forEach(c => { 
                    const data = c.val();
                    m.push({
                        key: c.key, 
                        name: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'System' : data.createdBy
                    });
                });
                setMarketList(m);
            }
        });

        onValue(ref(db, 'settings/companies'), snapshot => {
            if(snapshot.exists()){
                const c: any[] = [];
                snapshot.forEach(k => { 
                    const data = k.val();
                    c.push({
                        key: k.key, 
                        name: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'System' : data.createdBy
                    });
                });
                setCompanyList(c);
            }
        });
    }, [user.role]);

    const saveAppSettings = async () => {
        try {
            await set(ref(db, 'settings/app'), localSettings);
            alert('تم حفظ إعدادات التطبيق بنجاح');
        } catch (e) { alert('خطأ في الحفظ'); }
    };

    const handleAddUser = async () => {
        if (!newUser.username || !newUser.password || !newUser.name) return alert("اكمل بيانات المستخدم");
        await push(ref(db, 'users'), newUser);
        alert("تمت إضافة المستخدم بنجاح");
        setNewUser({ 
            name: '', 
            username: '', 
            password: '', 
            role: 'user', 
            canViewAllSales: false,
            permissions: {
                showSalesLog: true,
                showInventoryLog: false,
                showInventoryReg: false,
                showCompetitorReports: false
            }
        });
    };

    const handleDeleteUser = async (key: string) => {
        if (confirm("هل أنت متأكد من حذف هذا المستخدم؟")) {
            await remove(ref(db, `users/${key}`));
        }
    };

    const handleUpdatePassword = async () => {
        if(!passModal || !newPass) return;
        await update(ref(db, `users/${passModal.key}`), { password: newPass });
        alert("تم تحديث كلمة المرور");
        setPassModal(null);
        setNewPass('');
    };

    const handleUpdatePermissions = async () => {
        if (!permModal || !permModal.key) return;
        // Ensure permissions object exists
        const permissions = permModal.permissions || {
            showSalesLog: false,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false
        };
        await update(ref(db, `users/${permModal.key}`), { 
            permissions: permissions,
            canViewAllSales: !!permModal.canViewAllSales
        });
        alert("تم تحديث الصلاحيات بنجاح");
        setPermModal(null);
    };

    const toggleUserPerm = (key: keyof UserPermissions) => {
        if (!permModal) return;

        // Provide defaults if permissions are missing (prevents undefined crash)
        const currentPermissions = permModal.permissions || {
            showSalesLog: false,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false
        };

        setPermModal({
            ...permModal,
            permissions: {
                ...currentPermissions,
                [key]: !currentPermissions[key]
            }
        });
    };

    if (user.role !== 'admin') {
        return <div className="p-10 text-center opacity-50">عذراً، هذه الصفحة متاحة للمسؤولين فقط.</div>;
    }

    const inputClass = "w-full p-2.5 rounded-lg border border-gray-300 text-black focus:ring-2 focus:ring-blue-500 outline-none";
    const sectionClass = `p-6 rounded-2xl mb-6 ${theme === 'dark' ? 'bg-gray-800 border-gray-700 border' : 'bg-white shadow-xl'}`;

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-20">
            <div className="flex items-center gap-3 mb-2">
                <SettingsIcon className="text-blue-600" size={32} />
                <h2 className="text-3xl font-bold">لوحة تحكم المسؤول</h2>
            </div>

            {/* إعدادات التطبيق العامة */}
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-6 flex items-center gap-2 text-blue-600 border-b pb-3">
                    <Edit2 size={20} /> الإعدادات العامة للمنصة
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-bold mb-2 opacity-70">اسم التطبيق (AppName)</label>
                        <input className={inputClass} value={localSettings.appName} onChange={e => setLocalSettings({...localSettings, appName: e.target.value})} />
                    </div>
                    <div>
                        <label className="block text-sm font-bold mb-2 opacity-70">رقم واتساب الدعم</label>
                        <input className={inputClass} placeholder="مثال: 2010XXXXXXXX" value={localSettings.whatsappNumber} onChange={e => setLocalSettings({...localSettings, whatsappNumber: e.target.value})} />
                    </div>
                    <div className="md:col-span-2">
                        <label className="block text-sm font-bold mb-2 opacity-70">نص الشريط المتحرك (Ticker Text)</label>
                        <div className="flex gap-2">
                            <input className={inputClass} value={localSettings.tickerText} onChange={e => setLocalSettings({...localSettings, tickerText: e.target.value})} />
                            <button 
                                onClick={() => setLocalSettings({...localSettings, tickerEnabled: !localSettings.tickerEnabled})}
                                className={`px-4 rounded-lg flex items-center gap-2 font-bold ${localSettings.tickerEnabled ? 'bg-green-600 text-white' : 'bg-gray-300 text-gray-700'}`}
                            >
                                {localSettings.tickerEnabled ? <ToggleRight /> : <ToggleLeft />} {localSettings.tickerEnabled ? 'مفعل' : 'معطل'}
                            </button>
                        </div>
                    </div>
                </div>
                <button onClick={saveAppSettings} className="mt-6 w-full bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-xl font-bold flex items-center justify-center gap-2 shadow-lg transition transform active:scale-95">
                    <Save size={20} /> حفظ الإعدادات العامة
                </button>
            </div>

            {/* إدارة المستخدمين */}
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-6 flex items-center gap-2 text-purple-600 border-b pb-3">
                    <Users size={20} /> إدارة حسابات وصلاحيات الموظفين
                </h3>

                {/* إضافة مستخدم جديد */}
                <div className="bg-gray-50 dark:bg-black/20 p-6 rounded-2xl mb-6 border border-gray-200 dark:border-gray-700">
                    <h4 className="font-bold mb-4 flex items-center gap-2 text-sm"><UserPlus size={16}/> إضافة موظف جديد</h4>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                        <input className={inputClass} placeholder="الاسم الكامل" value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} />
                        <input className={inputClass} placeholder="اسم المستخدم" value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})} />
                        <input className={inputClass} type="password" placeholder="كلمة المرور" value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} />
                        <select className={inputClass} value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as any})}>
                            <option value="user">موظف (User)</option>
                            <option value="admin">مسؤول (Admin)</option>
                        </select>
                    </div>
                    <button onClick={handleAddUser} className="mt-4 w-full bg-green-600 text-white font-bold py-2 rounded-lg hover:bg-green-700 transition">إضافة الموظف</button>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-right">
                        <thead className="bg-gray-100 dark:bg-gray-700">
                            <tr>
                                <th className="p-3">الاسم</th>
                                <th className="p-3">المستخدم</th>
                                <th className="p-3">الدور</th>
                                <th className="p-3 text-center">الإجراءات</th>
                            </tr>
                        </thead>
                        <tbody>
                            {users.map(u => (
                                <tr key={u.key} className="border-b border-gray-100 dark:border-gray-700 hover:bg-black/5">
                                    <td className="p-3 font-bold">{u.name}</td>
                                    <td className="p-3 opacity-70">{u.username}</td>
                                    <td className="p-3">
                                        <span className={`px-2 py-1 rounded text-[10px] font-bold ${u.role === 'admin' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>
                                            {u.role === 'admin' ? 'مسؤول' : 'موظف'}
                                        </span>
