import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set, update, onDisconnect, serverTimestamp, remove } from "firebase/database";
import { User, AppSettings, AppNotification } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen, Check, Trash2, Clock, Copy, ExternalLink } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, 
    showInventoryReg: false, 
    showCompetitorReports: false 
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'blue' | 'green' | 'purple' | 'gold'>('blue');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showThemeSelector, setShowThemeSelector] = useState(false);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [selectedNotif, setSelectedNotif] = useState<AppNotification | null>(null);

  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    onValue(settingsRef, (snapshot) => {
      if (snapshot.exists()) setSettings({...DEFAULT_SETTINGS, ...snapshot.val()});
    });

    onValue(marketsRef, (snapshot) => {
      const systemMarkets = INITIAL_MARKETS.map(name => ({ name, createdBy: 'system' }));
      const dbMarkets = snapshot.exists() ? Object.values(snapshot.val()).map((m: any) => 
        typeof m === 'string' ? { name: m, createdBy: 'system' } : m
      ) : [];
      const allCombined = [...systemMarkets, ...dbMarkets];

      if (user) {
        let filtered;
        if (user.role === 'admin') {
          filtered = allCombined;
        } else {
          filtered = allCombined.filter(m => m.createdBy === 'system' || m.createdBy === user.username);
        }
        const uniqueNames = Array.from(new Set(filtered.map(m => m.name)));
        setMarkets(uniqueNames);
      }
    }, { onlyOnce: false });

    onValue(connectedRef, (snap) => setIsConnected(!!snap.val()));
  }, [user?.username, user?.role]);

  useEffect(() => {
    if (!user) return;
    const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
    const userStatusRef = ref(db, `status/${safeKey}`);
    set(userStatusRef, { online: true, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    onDisconnect(userStatusRef).set({ online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });

    onValue(ref(db, `notifications/${user.username}`), (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list = Object.keys(data).map(key => ({ id: key, ...data[key] })).sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        } else {
            setNotifications([]);
            setUnreadCount(0);
        }
    });
  }, [user?.username]);

  const handleLogout = async () => {
    if (user) {
        const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `status/${safeKey}`), { online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    }
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  const markAsRead = (id: string) => {
    if (!user) return;
    update(ref(db, `notifications/${user.username}/${id}`), { isRead: true });
  };

  const deleteNotif = (id: string) => {
    if (!user) return;
    remove(ref(db, `notifications/${user.username}/${id}`));
  };

  const copyNotifText = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("تم نسخ نص الرسالة");
  };

  if (!user) return <Login onLogin={setUser} theme={'dark'} />;

  // القوة الضاربة: خلفية سوداء دائمة وخط أبيض دائم
  const getThemeClasses = () => "bg-black text-white min-h-screen font-sans selection:bg-blue-500 selection:text-white";

  const themesList = [
      { id: 'blue', name: 'الاستايل الأزرق', color: 'bg-blue-600' },
      { id: 'green', name: 'الاستايل الأخضر', color: 'bg-green-600' },
      { id: 'purple', name: 'الاستايل البنفسجي', color: 'bg-purple-600' },
      { id: 'gold', name: 'الاستايل الذهبي', color: 'bg-yellow-600' },
  ];

  const getAccentColor = () => {
      switch(theme) {
          case 'green': return 'text-green-500';
          case 'purple': return 'text-purple-500';
          case 'gold': return 'text-yellow-500';
          default: return 'text-blue-500';
      }
  };

  return (
    <div className={`${getThemeClasses()} flex flex-col overflow-hidden`}>
      {settings.tickerEnabled && (
        <div className="bg-black text-yellow-400 py-1 overflow-hidden whitespace-nowrap border-b border-white/10">
           <div className="animate-marquee inline-block px-4 font-bold">{settings.tickerText}</div>
        </div>
      )}

      <header className="p-4 flex justify-between items-center z-50 bg-black border-b border-white/20 text-white shadow-2xl">
        <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="md:hidden p-2 rounded-lg hover:bg-white/10 border border-white/5 transition-all">
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="text-lg md:text-2xl font-bold truncate flex items-center gap-3">
                <span className={getAccentColor()}>{settings.appName}</span>
                <span className="text-sm font-normal opacity-70 hidden sm:inline-block border-r border-white/30 pr-3">
                   المستخدم: <span className="font-bold text-white">{user.name}</span>
                </span>
            </h1>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
            {settings.whatsappNumber && (
                <a 
                    href={`https://wa.me/${settings.whatsappNumber}`} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="p-2 rounded-full hover:bg-green-500/20 text-green-500 transition-all border border-transparent hover:border-green-500/30"
                    title="الدعم الفني"
                >
                    <Phone size={20} />
                </a>
            )}

            <div className="relative">
                <button 
                    onClick={() => setShowThemeSelector(!showThemeSelector)} 
                    className={`p-2 rounded-full hover:bg-white/10 transition-all border ${showThemeSelector ? 'border-white/40 bg-white/10' : 'border-transparent'}`}
                    title="تغيير الاستايل"
                >
                    <Palette size={20} className={getAccentColor()} />
                </button>
                {showThemeSelector && (
                    <div className="absolute left-0 mt-3 w-56 bg-gray-900 rounded-2xl shadow-[0_10px_40px_rgba(0,0,0,0.8)] border border-white/20 p-2 animate-in fade-in zoom-in duration-200 z-[60]">
                        <div className="text-[10px] font-bold text-gray-500 px-3 py-2 uppercase tracking-widest border-b border-white/5 mb-2">تخصيص المظهر</div>
                        {themesList.map((t) => (
                            <button 
                                key={t.id}
                                onClick={() => { setTheme(t.id as any); setShowThemeSelector(false); }}
                                className={`w-full flex items-center justify-between px-3 py-2.5 rounded-xl text-sm transition-all mb-1 ${theme === t.id ? 'bg-white/10 text-white ring-1 ring-white/20' : 'text-gray-400 hover:bg-white/5 hover:text-gray-200'}`}
                            >
                                <div className="flex items-center gap-3">
                                    <div className={`w-4 h-4 rounded-full shadow-inner ${t.color}`} />
                                    <span className="font-medium">{t.name}</span>
                                </div>
                                {theme === t.id && <Check size={16} className={getAccentColor()} />}
                            </button>
                        ))}
                    </div>
                )}
            </div>

            <div className="relative">
                <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className={`relative p-2 rounded-full hover:bg-white/10 transition-all ${showNotifDropdown ? 'bg-white/10 border border-white/20' : ''}`}>
                    <Bell size={20} />
                    {unreadCount > 0 && <span className="absolute top-1.5 right-1.5 bg-red-600 text-white text-[9px] w-4 h-4 flex items-center justify-center rounded-full border border-black font-bold ring-2 ring-red-600/20">{unreadCount}</span>}
                </button>
                {showNotifDropdown && (
                    <div className="absolute left-0 mt-3 w-80 bg-gray-900 rounded-2xl shadow-[0_10px_50px_rgba(0,0,0,0.9)] border border-white/20 overflow-hidden animate-in fade-in slide-in-from-top-3 duration-200 z-[60] text-white">
                        <div className="p-4 bg-black/50 border-b border-white/10 flex justify-between items-center">
                            <h3 className="font-bold text-sm flex items-center gap-2"><Bell size={16} className={getAccentColor()}/> الإشعارات</h3>
                            <span className="text-[10px] bg-white/10 text-gray-300 px-2 py-1 rounded-full font-bold">{unreadCount} جديدة</span>
                        </div>
                        <div className="max-h-96 overflow-y-auto custom-scrollbar">
                            {notifications.length === 0 ? (
                                <div className="p-12 text-center opacity-40 italic text-sm">لا توجد إشعارات حالياً</div>
                            ) : (
                                notifications.map(n => (
                                    <div 
                                      key={n.id} 
                                      onClick={() => { setSelectedNotif(n); markAsRead(n.id!); setShowNotifDropdown(false); }}
                                      className={`p-4 border-b border-white/5 last:border-0 hover:bg-white/5 transition-all relative group cursor-pointer ${!n.isRead ? 'bg-blue-600/5' : ''}`}
                                    >
                                        <div className="flex justify-between items-start mb-2">
                                            <span className="text-[10px] font-bold text-gray-400 flex items-center gap-1.5"><Clock size={12}/> {new Date(n.timestamp).toLocaleTimeString('ar-EG', {hour:'2-digit', minute:'2-digit'})}</span>
                                            <div className="flex gap-1" onClick={e => e.stopPropagation()}>
                                                {!n.isRead && <button onClick={() => markAsRead(n.id!)} className="p-1.5 text-green-400 hover:bg-green-600/20 rounded-lg transition-colors" title="تعليم كمقروء"><Check size={14}/></button>}
                                                <button onClick={() => deleteNotif(n.id!)} className="p-1.5 text-red-400 hover:bg-red-600/20 rounded-lg transition-colors" title="حذف"><Trash2 size={14}/></button>
                                            </div>
                                        </div>
                                        <div className="text-xs font-bold mb-1 flex items-center gap-2 text-white">
                                            <div className={`w-1.5 h-1.5 rounded-full ${!n.isRead ? 'bg-blue-500' : 'bg-transparent'}`} />
                                            {n.sender}
                                        </div>
                                        <div className="text-[11px] leading-relaxed opacity-60 line-clamp-2 pr-3">{n.message}</div>
                                    </div>
                                ))
                            )}
                        </div>
                        {notifications.length > 0 && (
                            <button onClick={() => setShowNotifDropdown(false)} className="w-full p-3 text-center text-[10px] font-bold text-gray-500 hover:bg-white/5 border-t border-white/10 transition-colors uppercase tracking-widest">إغلاق القائمة</button>
                        )}
                    </div>
                )}
            </div>

            <button onClick={handleLogout} className="text-red-500 p-2.5 rounded-full hover:bg-red-500/10 transition-all border border-transparent hover:border-red-500/20" title="تسجيل الخروج">
                <LogOut size={20} />
            </button>
        </div>
      </header>

      {selectedNotif && (
          <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-[100] p-4 backdrop-blur-md animate-in fade-in duration-300" onClick={() => setSelectedNotif(null)}>
              <div className="w-full max-w-lg bg-gray-900 rounded-[2.5rem] shadow-[0_0_100px_rgba(0,0,0,1)] overflow-hidden text-white animate-in zoom-in duration-300 border border-white/10" onClick={e => e.stopPropagation()}>
                  <div className="p-8 border-b border-white/10 bg-black/50 flex justify-between items-center">
                      <div className="flex items-center gap-4">
                          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center text-white shadow-2xl bg-gradient-to-br from-gray-700 to-gray-900 border border-white/10`}>
                              <Bell size={28} className={getAccentColor()}/>
                          </div>
                          <div>
                              <h3 className="font-bold text-xl">رسالة من: {selectedNotif.sender}</h3>
                              <p className="text-xs text-gray-500 font-bold tracking-wide mt-1 uppercase">{new Date(selectedNotif.timestamp).toLocaleString('ar-EG')}</p>
                          </div>
                      </div>
                      <button onClick={() => setSelectedNotif(null)} className="p-3 hover:bg-white/10 rounded-full transition-all group">
                        <X className="group-hover:rotate-90 transition-transform duration-300" />
                      </button>
                  </div>
                  <div className="p-10 bg-gray-900">
                      <div className="text-base leading-loose whitespace-pre-wrap select-all bg-white/5 p-8 rounded-3xl border border-white/10 text-gray-200 font-medium">
                          {selectedNotif.message}
                      </div>
                  </div>
                  <div className="p-6 bg-black/50 border-t border-white/10 flex gap-4">
                      <button 
                          onClick={() => copyNotifText(selectedNotif.message)} 
                          className="flex-1 bg-white/10 hover:bg-white/20 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-3 transition-all border border-white/10 active:scale-95"
                      >
                          <Copy size={20}/> نسخ النص
                      </button>
                      <button 
                          onClick={() => setSelectedNotif(null)} 
                          className="px-10 bg-black hover:bg-gray-800 text-gray-300 font-bold py-4 rounded-2xl transition-all border border-white/5"
                      >
                          إغلاق
                      </button>
                  </div>
              </div>
          </div>
      )}

      <div className="flex flex-1 overflow-hidden relative">
        {isSidebarOpen && (
            <div 
                className="fixed inset-0 bg-black/80 backdrop-blur-md z-40 md:hidden animate-in fade-in duration-300"
                onClick={() => setIsSidebarOpen(false)}
            />
        )}

        <div className={`fixed md:relative top-0 bottom-0 right-0 z-50 h-full transition-transform duration-500 ease-in-out md:transform-none ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
            <Sidebar 
                currentView={currentView} 
                setView={(view) => { setCurrentView(view); setIsSidebarOpen(false); }} 
                user={user} 
                theme={theme} 
                settings={settings} 
                containerClass="bg-black border-l border-white/10 h-full shadow-[20px_0_50px_rgba(0,0,0,1)]" 
            />
        </div>

        <main 
            className="flex-1 p-3 md:p-6 overflow-y-auto w-full bg-black scroll-smooth" 
            onClick={() => isSidebarOpen && setIsSidebarOpen(false)}
        >
            <div className="p-5 md:p-8 min-h-full bg-gray-900/40 rounded-3xl border border-white/5 shadow-inner text-white backdrop-blur-sm">
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorPrices' && <CompetitorPrices user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorReports' && <CompetitorReports user={user} markets={markets} theme={theme} />}
                {currentView === 'leaveBalance' && <LeaveBalanceComponent user={user} theme={theme} />}
                {currentView === 'settings' && <Settings user={user} settings={settings} markets={markets} theme={theme} setTheme={setTheme} />}
            </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue } from "firebase/database";
import { User, AppSettings } from '../types';
import { 
    ShoppingCart, FileText, PackagePlus, ClipboardList, 
    TrendingUp, BarChart2, Settings as SettingsIcon, CalendarOff,
    Users, Circle
} from 'lucide-react';

interface SidebarProps {
    currentView: string;
    setView: (view: string) => void;
    user: User;
    theme: string;
    containerClass: string;
    settings: AppSettings;
}

interface UserStatus {
    username: string;
    name: string;
    online: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, user, theme, containerClass, settings }) => {
    const [onlineUsers, setOnlineUsers] = useState<UserStatus[]>([]);

    useEffect(() => {
        if (user.role === 'admin') {
            const statusRef = ref(db, 'status');
            const unsubscribe = onValue(statusRef, (snapshot) => {
                if (snapshot.exists()) {
                    const data = snapshot.val();
                    const list: UserStatus[] = Object.keys(data).map(key => ({
                        username: data[key].username || key,
                        name: data[key].name || key,
                        online: data[key].online || false
                    }));

                    const sortedList = list.sort((a, b) => {
                        if (a.online === b.online) {
                            return a.name.localeCompare(b.name, 'ar');
                        }
                        return a.online ? -1 : 1;
                    });

                    setOnlineUsers(sortedList);
                } else {
                    setOnlineUsers([]);
                }
            });
            return () => unsubscribe();
        }
    }, [user.role]);

    const allItems = [
        { id: 'sales', label: 'المبيعات اليومية', icon: ShoppingCart, alwaysShow: true },
        { id: 'salesLog', label: 'سجل المبيعات', icon: FileText, permissionKey: 'showSalesLog' },
        { id: 'inventoryReg', label: 'تسجيل المخزون', icon: PackagePlus, permissionKey: 'showInventoryReg' },
        { id: 'inventoryLog', label: 'سجل المخزون', icon: ClipboardList, permissionKey: 'showInventoryLog' },
        { id: 'competitorPrices', label: 'أسعار المنافسين', icon: TrendingUp, alwaysShow: true },
        { id: 'competitorReports', label: 'تقارير المنافسين', icon: BarChart2, permissionKey: 'showCompetitorReports' },
        { id: 'leaveBalance', label: 'رصيد الإجازات', icon: CalendarOff, alwaysShow: true },
        { id: 'settings', label: 'الإعدادات', icon: SettingsIcon, adminOnly: true },
    ];

    const menuItems = allItems.filter(item => {
        if (user.role === 'admin') return true;
        if (item.adminOnly) return false;
        if (item.alwaysShow) return true;
        if (item.permissionKey) {
            const perms = user.permissions || {} as any;
            return perms[item.permissionKey] === true;
        }
        return false;
    });

    const getButtonClass = (isActive: boolean) => {
        let classes = "group w-full flex items-center gap-4 px-4 py-4 rounded-2xl transition-all duration-300 ease-out font-bold relative overflow-hidden mb-1 ";

        const accentColors: Record<string, string> = {
            blue: "bg-blue-600 shadow-blue-600/30 ring-blue-400/50",
            green: "bg-green-600 shadow-green-600/30 ring-green-400/50",
            purple: "bg-purple-600 shadow-purple-600/30 ring-purple-400/50",
            gold: "bg-yellow-600 shadow-yellow-600/30 ring-yellow-400/50"
        };

        const hoverColors: Record<string, string> = {
            blue: "hover:text-blue-400",
            green: "hover:text-green-400",
            purple: "hover:text-purple-400",
            gold: "hover:text-yellow-400"
        };

        const accent = accentColors[theme] || accentColors.blue;
        const hover = hoverColors[theme] || hoverColors.blue;

        if (isActive) {
            classes += `${accent} text-white shadow-lg translate-x-2 ring-1 scale-[1.02] `;
        } else {
            classes += `text-gray-400 hover:bg-white/5 ${hover} hover:translate-x-1 `;
        }

        return classes;
    };

    const headerClass = "text-[10px] font-bold uppercase tracking-[0.2em] mb-8 px-4 text-gray-600 border-b border-white/5 pb-4";

    return (
        <aside className={`w-64 md:w-72 p-6 flex flex-col ${containerClass} transition-all duration-500 overflow-hidden`}>
            <div className={headerClass}>التجارة الحديثة</div>
            <nav className="flex-1 flex flex-col gap-1 overflow-y-auto custom-scrollbar pr-1">
                {menuItems.map(item => (
                    <button
                        key={item.id}
                        onClick={() => setView(item.id)}
                        className={getButtonClass(currentView === item.id)}
                    >
                        <item.icon size={20} strokeWidth={2.5} className="flex-shrink-0" />
                        <span className="text-sm tracking-wide">{item.label}</span>
                        {currentView === item.id && (
                             <div className="absolute right-0 top-0 bottom-0 w-1.5 bg-white/20 rounded-l-full" />
                        )}
                    </button>
                ))}

                {user.role === 'admin' && (
                    <div className="mt-10 border-t pt-6 border-white/10">
                        <div className="flex items-center gap-2 mb-5 px-3 text-[10px] font-bold uppercase tracking-widest text-gray-500">
                            <Users size={14} />
                            <span>المتواجدون حالياً</span>
                        </div>
                        <div className="space-y-2 max-h-64 overflow-y-auto custom-scrollbar px-1">
                            {onlineUsers.length === 0 ? (
                                <div className="text-[10px] text-gray-600 italic px-3">لا يوجد مستخدمون نشطون</div>
                            ) : onlineUsers.map((u) => (
                                <div key={u.username} className="flex items-center justify-between px-4 py-3 rounded-xl bg-white/5 hover:bg-white/10 transition-all border border-white/5 group">
                                    <span className="text-xs font-bold truncate flex-1 text-gray-400 group-hover:text-white transition-colors">
                                        {u.name}
                                    </span>
                                    <div 
                                        className={`w-2.5 h-2.5 rounded-full transition-all duration-700 ${u.online ? 'bg-green-500 shadow-[0_0_10px_rgba(34,197,94,0.6)] scale-110' : 'bg-red-900 opacity-20'}`} 
                                        title={u.online ? "متصل" : "غير متصل"} 
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </nav>

            <div className="mt-auto text-[9px] px-4 pt-6 border-t border-white/10 text-gray-700 font-bold uppercase tracking-tighter flex justify-between items-center">
                <span>Soft Rose System</span>
                <span>v1.3.0</span>
            </div>
        </aside>
    );
};

export default Sidebar;

body {
  font-family: 'Cairo', sans-serif;
  margin: 0;
  padding: 0;
  background-color: #000000 !important;
  color: #ffffff !important;
  overflow-x: hidden;
}

/* Force global color and background for consistency */
* {
  border-color: rgba(255, 255, 255, 0.15);
}

#root {
  background-color: #000000 !important;
}

/* Custom Scrollbar for modern look */
::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::-webkit-scrollbar-track {
  background: rgba(0, 0, 0, 0.1);
}
::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.1); 
  border-radius: 10px;
}
::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.3); 
}

/* Base text clarity */
h1, h2, h3, h4, h5, h6, p, span, label, div, td, th {
  color: #ffffff !important;
  text-shadow: 0 1px 2px rgba(0,0,0,0.5);
}

/* Interactive elements visibility */
input, select, textarea {
  background-color: rgba(255, 255, 255, 0.07) !important;
  color: #ffffff !important;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
  border-radius: 12px !important;
  transition: all 0.3s ease !important;
}

input:focus, select:focus, textarea:focus {
  background-color: rgba(255, 255, 255, 0.12) !important;
  border-color: rgba(255, 255, 255, 0.4) !important;
  outline: none !important;
  box-shadow: 0 0 15px rgba(255, 255, 255, 0.1) !important;
}

input::placeholder, textarea::placeholder {
  color: rgba(255, 255, 255, 0.3) !important;
}

/* Table Clarity */
table {
  border-collapse: separate;
  border-spacing: 0 4px;
}

tr td {
  background-color: rgba(255, 255, 255, 0.03);
  transition: transform 0.2s ease;
}

tr:hover td {
  background-color: rgba(255, 255, 255, 0.07) !important;
  transform: translateY(-1px);
}

/* Selection */
::selection {
  background: rgba(255, 255, 255, 0.2);
  color: #fff;
}

/* Animations */
@keyframes marquee {
  0% { transform: translateX(100%); }
  100% { transform: translateX(-100%); }
}

.animate-marquee {
  animation: marquee 25s linear infinite;
  display: inline-block;
  padding-left: 100%;
}

/* Custom Scrollbar for modals */
.custom-scrollbar::-webkit-scrollbar {
  width: 4px;
}
.custom-scrollbar::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.15);
  border-radius: 10px;
}

/* Modern Glows */
.lamp-glow-blue {
  box-shadow: 0 0 15px rgba(59, 130, 246, 0.5);
}

/* Responsive adjustments */
@media (max-width: 768px) {
    .animate-marquee {
        animation-duration: 15s;
    }
}

import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set, update, onDisconnect, serverTimestamp, remove } from "firebase/database";
import { User, AppSettings, AppNotification } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen, Check, Trash2, Clock, Copy, ExternalLink } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, 
    showInventoryReg: false, 
    showCompetitorReports: false 
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'glass' | 'dark' | 'win10' | 'light'>('dark');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showThemeSelector, setShowThemeSelector] = useState(false);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [selectedNotif, setSelectedNotif] = useState<AppNotification | null>(null);

  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    onValue(settingsRef, (snapshot) => {
      if (snapshot.exists()) setSettings({...DEFAULT_SETTINGS, ...snapshot.val()});
    });

    onValue(marketsRef, (snapshot) => {
      const systemMarkets = INITIAL_MARKETS.map(name => ({ name, createdBy: 'system' }));
      const dbMarkets = snapshot.exists() ? Object.values(snapshot.val()).map((m: any) => 
        typeof m === 'string' ? { name: m, createdBy: 'system' } : m
      ) : [];
      const allCombined = [...systemMarkets, ...dbMarkets];

      if (user) {
        let filtered;
        if (user.role === 'admin') {
          filtered = allCombined;
        } else {
          filtered = allCombined.filter(m => m.createdBy === 'system' || m.createdBy === user.username);
        }
        const uniqueNames = Array.from(new Set(filtered.map(m => m.name)));
        setMarkets(uniqueNames);
      }
    }, { onlyOnce: false });

    onValue(connectedRef, (snap) => setIsConnected(!!snap.val()));
  }, [user?.username, user?.role]);

  useEffect(() => {
    if (!user) return;
    const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
    const userStatusRef = ref(db, `status/${safeKey}`);
    set(userStatusRef, { online: true, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    onDisconnect(userStatusRef).set({ online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });

    onValue(ref(db, `notifications/${user.username}`), (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list = Object.keys(data).map(key => ({ id: key, ...data[key] })).sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        } else {
            setNotifications([]);
            setUnreadCount(0);
        }
    });
  }, [user?.username]);

  const handleLogout = async () => {
    if (user) {
        const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `status/${safeKey}`), { online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    }
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  const markAsRead = (id: string) => {
    if (!user) return;
    update(ref(db, `notifications/${user.username}/${id}`), { isRead: true });
  };

  const deleteNotif = (id: string) => {
    if (!user) return;
    remove(ref(db, `notifications/${user.username}/${id}`));
  };

  const copyNotifText = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("تم نسخ نص الرسالة");
  };

  if (!user) return <Login onLogin={setUser} theme={theme} />;

  const getThemeClasses = () => {
    switch (theme) {
      case 'dark': return "bg-black text-white min-h-screen";
      case 'glass': return "bg-gray-950 text-white min-h-screen bg-[url('https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?q=80&w=2564&auto=format&fit=crop')] bg-cover bg-fixed";
      case 'win10': return "bg-[#00182b] text-white min-h-screen";
      case 'light': return "bg-gray-100 text-gray-900 min-h-screen";
      default: return "bg-black text-white min-h-screen";
    }
  };

  const themesList = [
      { id: 'win10', name: 'ويندوز 10', color: 'bg-blue-600' },
      { id: 'dark', name: 'الوضع الليلي', color: 'bg-gray-900' },
      { id: 'glass', name: 'زجاجي مودرن', color: 'bg-purple-500' },
      { id: 'light', name: 'فاتح كلاسيك', color: 'bg-white border' },
  ];

  return (
    <div className={`${getThemeClasses()} flex flex-col overflow-hidden`}>
      {settings.tickerEnabled && (
        <div className="bg-black/80 backdrop-blur-md text-yellow-400 py-1 overflow-hidden whitespace-nowrap border-b border-white/10">
           <div className="animate-marquee inline-block px-4 font-bold">{settings.tickerText}</div>
        </div>
      )}

      <header className="p-4 flex justify-between items-center z-50 bg-black/40 backdrop-blur-lg border-b border-white/10 text-white shadow-2xl">
        <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="md:hidden p-2 rounded-lg hover:bg-white/10 transition-all">
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="text-lg md:text-2xl font-bold truncate flex items-center gap-2">
                {settings.appName}
                <span className="text-sm font-normal opacity-60 hidden sm:inline-block border-r border-white/20 pr-2 mr-2">
                  المستخدم: <span className="font-bold">{user.name}</span>
                </span>
            </h1>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
            {settings.whatsappNumber && (
                <a 
                    href={`https://wa.me/${settings.whatsappNumber}`} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="p-2 rounded-full hover:bg-green-500/10 text-green-500 transition-colors"
                    title="الدعم الفني"
                >
                    <Phone size={20} />
                </a>
            )}

            <div className="relative">
                <button 
                    onClick={() => setShowThemeSelector(!showThemeSelector)} 
                    className={`p-2 rounded-full hover:bg-white/10 transition-colors ${showThemeSelector ? 'bg-white/10' : ''}`}
                    title="تغيير المظهر"
                >
                    <Palette size={20} />
                </button>
                {showThemeSelector && (
                    <div className="absolute left-0 mt-2 w-48 bg-gray-900 rounded-xl shadow-2xl border border-white/10 p-2 animate-in fade-in zoom-in duration-200 z-[60]">
                        <div className="text-[10px] font-bold text-gray-400 px-3 py-1 uppercase mb-1">اختر المظهر</div>
                        {themesList.map((t) => (
                            <button 
                                key={t.id}
                                onClick={() => { setTheme(t.id as any); setShowThemeSelector(false); }}
                                className={`w-full flex items-center justify-between px-3 py-2 rounded-lg text-sm transition ${theme === t.id ? 'bg-blue-600/20 text-blue-400' : 'text-gray-300 hover:bg-white/5'}`}
                            >
                                <div className="flex items-center gap-2">
                                    <div className={`w-3 h-3 rounded-full ${t.color}`} />
                                    <span>{t.name}</span>
                                </div>
                                {theme === t.id && <Check size={14} />}
                            </button>
                        ))}
                    </div>
                )}
            </div>

            <div className="relative">
                <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className={`relative p-2 rounded-full hover:bg-white/10 ${showNotifDropdown ? 'bg-white/10' : ''}`}>
                    <Bell size={20} />
                    {unreadCount > 0 && <span className="absolute top-1 right-1 bg-red-600 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full border border-black">{unreadCount}</span>}
                </button>
                {showNotifDropdown && (
                    <div className="absolute left-0 mt-2 w-72 md:w-80 bg-gray-900 rounded-2xl shadow-2xl border border-white/10 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200 z-[60] text-white">
                        <div className="p-4 bg-black border-b border-white/10 flex justify-between items-center">
                            <h3 className="font-bold text-sm flex items-center gap-2"><Bell size={16} className="text-blue-500"/> الإشعارات</h3>
                            <span className="text-[10px] bg-blue-600/20 text-blue-400 px-2 py-0.5 rounded-full font-bold">{unreadCount} جديدة</span>
                        </div>
                        <div className="max-h-80 overflow-y-auto custom-scrollbar">
                            {notifications.length === 0 ? (
                                <div className="p-10 text-center opacity-30 italic text-sm">لا توجد إشعارات حالياً</div>
                            ) : (
                                notifications.map(n => (
                                    <div 
                                      key={n.id} 
                                      onClick={() => { setSelectedNotif(n); markAsRead(n.id!); setShowNotifDropdown(false); }}
                                      className={`p-4 border-b border-white/5 last:border-0 hover:bg-white/5 transition relative group cursor-pointer ${!n.isRead ? 'bg-blue-600/10' : ''}`}
                                    >
                                        <div className="flex justify-between items-start mb-1">
                                            <span className="text-[10px] font-bold text-blue-400 flex items-center gap-1"><Clock size={10}/> {new Date(n.timestamp).toLocaleTimeString('ar-EG', {hour:'2-digit', minute:'2-digit'})}</span>
                                            <div className="flex gap-1" onClick={e => e.stopPropagation()}>
                                                {!n.isRead && <button onClick={() => markAsRead(n.id!)} className="p-1 text-green-400 hover:bg-green-600/10 rounded" title="تعليم كمقروء"><Check size={12}/></button>}
                                                <button onClick={() => deleteNotif(n.id!)} className="p-1 text-red-400 hover:bg-red-600/10 rounded" title="حذف"><Trash2 size={12}/></button>
                                            </div>
                                        </div>
                                        <div className="text-xs font-bold mb-0.5 flex items-center gap-1">{n.sender} <ExternalLink size={10} className="opacity-30"/></div>
                                        <div className="text-[11px] leading-relaxed opacity-70 line-clamp-2">{n.message}</div>
                                    </div>
                                ))
                            )}
                        </div>
                        {notifications.length > 0 && (
                            <button onClick={() => setShowNotifDropdown(false)} className="w-full p-2 text-center text-[10px] font-bold text-gray-500 hover:bg-white/5 border-t border-white/10">إغلاق القائمة</button>
                        )}
                    </div>
                )}
            </div>

            <button onClick={handleLogout} className="text-red-500 p-2 rounded-full hover:bg-red-500/10 transition-colors" title="تسجيل الخروج">
                <LogOut size={20} />
            </button>
        </div>
      </header>

      {selectedNotif && (
          <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[100] p-4 backdrop-blur-sm animate-in fade-in duration-200" onClick={() => setSelectedNotif(null)}>
              <div className="w-full max-w-md bg-gray-900 rounded-3xl shadow-2xl overflow-hidden text-white animate-in zoom-in duration-300 border border-white/10" onClick={e => e.stopPropagation()}>
                  <div className="p-6 border-b border-white/10 bg-black flex justify-between items-center">
                      <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-blue-600 rounded-full flex items-center justify-center text-white shadow-xl">
                              <Bell size={20}/>
                          </div>
                          <div>
                              <h3 className="font-bold text-lg">رسالة من: {selectedNotif.sender}</h3>
                              <p className="text-[10px] text-gray-500 font-bold">{new Date(selectedNotif.timestamp).toLocaleString('ar-EG')}</p>
                          </div>
                      </div>
                      <button onClick={() => setSelectedNotif(null)} className="p-2 hover:bg-white/10 rounded-full transition"><X/></button>
                  </div>
                  <div className="p-8 bg-gray-900 min-h-[150px]">
                      <div className="text-sm leading-relaxed whitespace-pre-wrap select-all bg-white/5 p-4 rounded-2xl border border-white/10">
                          {selectedNotif.message}
                      </div>
                  </div>
                  <div className="p-4 bg-black border-t border-white/10 flex gap-3">
                      <button 
                          onClick={() => copyNotifText(selectedNotif.message)} 
                          className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-xl flex items-center justify-center gap-2 transition"
                      >
                          <Copy size={18}/> نسخ النص
                      </button>
                      <button 
                          onClick={() => setSelectedNotif(null)} 
                          className="px-6 bg-white/5 hover:bg-white/10 text-gray-300 font-bold py-3 rounded-xl transition border border-white/10"
                      >
                          إغلاق
                      </button>
                  </div>
              </div>
          </div>
      )}

      <div className="flex flex-1 overflow-hidden relative">
        {/* Overlay for mobile sidebar closure */}
        {isSidebarOpen && (
            <div 
                className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 md:hidden"
                onClick={() => setIsSidebarOpen(false)}
            />
        )}

        <div className={`fixed md:relative top-0 bottom-0 right-0 z-50 h-full transition-transform duration-300 ease-in-out md:transform-none ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
            <Sidebar currentView={currentView} setView={(view) => { setCurrentView(view); setIsSidebarOpen(false); }} user={user} theme={theme} settings={settings} containerClass="bg-black/20 backdrop-blur-md border-l border-white/10 h-full shadow-2xl" />
        </div>

        <main className="flex-1 p-2 md:p-4 overflow-y-auto w-full" onClick={() => isSidebarOpen && setIsSidebarOpen(false)}>
            <div className={`p-4 md:p-6 min-h-full rounded-2xl border border-white/10 shadow-lg ${theme === 'dark' ? 'bg-black/40' : theme === 'glass' ? 'bg-white/5 backdrop-blur-md' : theme === 'win10' ? 'bg-[#002b4a]/60' : 'bg-white'}`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorPrices' && <CompetitorPrices user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorReports' && <CompetitorReports user={user} markets={markets} theme={theme} />}
                {currentView === 'leaveBalance' && <LeaveBalanceComponent user={user} theme={theme} />}
                {currentView === 'settings' && <Settings user={user} settings={settings} markets={markets} theme={theme} setTheme={setTheme} />}
            </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue } from "firebase/database";
import { User, AppSettings } from '../types';
import { 
    ShoppingCart, FileText, PackagePlus, ClipboardList, 
    TrendingUp, BarChart2, Settings as SettingsIcon, CalendarOff,
    Users, Circle
} from 'lucide-react';

interface SidebarProps {
    currentView: string;
    setView: (view: string) => void;
    user: User;
    theme: string;
    containerClass: string;
    settings: AppSettings;
}

interface UserStatus {
    username: string;
    name: string;
    online: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, user, theme, containerClass, settings }) => {
    const [onlineUsers, setOnlineUsers] = useState<UserStatus[]>([]);

    useEffect(() => {
        if (user.role === 'admin') {
            const statusRef = ref(db, 'status');
            const unsubscribe = onValue(statusRef, (snapshot) => {
                if (snapshot.exists()) {
                    const data = snapshot.val();
                    const list: UserStatus[] = Object.keys(data).map(key => ({
                        username: data[key].username || key,
                        name: data[key].name || key,
                        online: data[key].online || false
                    }));

                    const sortedList = list.sort((a, b) => {
                        if (a.online === b.online) {
                            return a.name.localeCompare(b.name, 'ar');
                        }
                        return a.online ? -1 : 1;
                    });

                    setOnlineUsers(sortedList);
                } else {
                    setOnlineUsers([]);
                }
            });
            return () => unsubscribe();
        }
    }, [user.role]);

    const allItems = [
        { id: 'sales', label: 'المبيعات اليومية', icon: ShoppingCart, alwaysShow: true },
        { id: 'salesLog', label: 'سجل المبيعات', icon: FileText, permissionKey: 'showSalesLog' },
        { id: 'inventoryReg', label: 'تسجيل المخزون', icon: PackagePlus, permissionKey: 'showInventoryReg' },
        { id: 'inventoryLog', label: 'سجل المخزون', icon: ClipboardList, permissionKey: 'showInventoryLog' },
        { id: 'competitorPrices', label: 'أسعار المنافسين', icon: TrendingUp, alwaysShow: true },
        { id: 'competitorReports', label: 'تقارير المنافسين', icon: BarChart2, permissionKey: 'showCompetitorReports' },
        { id: 'leaveBalance', label: 'رصيد الإجازات', icon: CalendarOff, alwaysShow: true },
        { id: 'settings', label: 'الإعدادات', icon: SettingsIcon, adminOnly: true },
    ];

    const menuItems = allItems.filter(item => {
        if (user.role === 'admin') return true;
        if (item.adminOnly) return false;
        if (item.alwaysShow) return true;
        if (item.permissionKey) {
            const perms = user.permissions || {} as any;
            return perms[item.permissionKey] === true;
        }
        return false;
    });

    const getButtonClass = (isActive: boolean) => {
        let classes = "group w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-200 font-bold mb-1 ";

        if (isActive) {
            switch (theme) {
                case 'win10': classes += "bg-blue-600 text-white shadow-lg"; break;
                case 'glass': classes += "bg-white/20 text-white backdrop-blur-md border border-white/20"; break;
                case 'light': classes += "bg-blue-600 text-white shadow-md"; break;
                default: classes += "bg-blue-600 text-white shadow-lg shadow-blue-600/20"; break;
            }
        } else {
            classes += theme === 'light' ? "text-gray-600 hover:bg-gray-100" : "text-gray-400 hover:bg-white/5";
        }

        return classes;
    };

    const headerClass = "text-[10px] font-bold uppercase tracking-[0.2em] mb-8 px-4 opacity-50 border-b border-white/5 pb-4";

    return (
        <aside className={`w-64 md:w-72 p-6 flex flex-col ${containerClass} transition-all duration-300`}>
            <div className={headerClass}>نظام سوفت روز</div>
            <nav className="flex-1 flex flex-col gap-1 overflow-y-auto custom-scrollbar">
                {menuItems.map(item => (
                    <button
                        key={item.id}
                        onClick={() => setView(item.id)}
                        className={getButtonClass(currentView === item.id)}
                    >
                        <item.icon size={20} strokeWidth={2.5} />
                        <span className="text-sm">{item.label}</span>
                    </button>
                ))}

                {user.role === 'admin' && (
                    <div className="mt-10 border-t pt-6 border-white/10">
                        <div className="flex items-center gap-2 mb-4 px-2 text-[10px] font-bold uppercase opacity-50">
                            <Users size={14} />
                            <span>المتواجدون حالياً</span>
                        </div>
                        <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar">
                            {onlineUsers.length === 0 ? (
                                <div className="text-[10px] opacity-40 italic px-2">لا يوجد مستخدمون نشطون</div>
                            ) : onlineUsers.map((u) => (
                                <div key={u.username} className="flex items-center justify-between px-3 py-2 rounded-lg bg-white/5 border border-white/5">
                                    <span className="text-xs font-bold truncate flex-1 opacity-80">
                                        {u.name}
                                    </span>
                                    <div 
                                        className={`w-2.5 h-2.5 rounded-full ${u.online ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]' : 'bg-gray-600'}`} 
                                        title={u.online ? "متصل" : "غير متصل"} 
                                    />
                                </div>
