            <div className="relative">
                <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className={`relative p-2 rounded-full hover:bg-black/5 dark:hover:bg-white/10 ${showNotifDropdown ? 'bg-black/10 dark:bg-white/10' : ''}`}>
