import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue } from "firebase/database";
import { User, AppSettings } from '../types';
import { 
    ShoppingCart, FileText, PackagePlus, ClipboardList, 
    TrendingUp, BarChart2, Settings as SettingsIcon, CalendarOff,
    Users, Circle
} from 'lucide-react';

interface SidebarProps {
    currentView: string;
    setView: (view: string) => void;
    user: User;
    theme: string;
    containerClass: string;
    settings: AppSettings;
}

interface UserStatus {
    username: string;
    name: string;
    online: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentView, setView, user, theme, containerClass, settings }) => {
    const [onlineUsers, setOnlineUsers] = useState<UserStatus[]>([]);

    useEffect(() => {
        if (user.role === 'admin') {
            const statusRef = ref(db, 'status');
            const unsubscribe = onValue(statusRef, (snapshot) => {
                if (snapshot.exists()) {
                    const data = snapshot.val();
                    const list: UserStatus[] = Object.keys(data).map(key => ({
                        username: data[key].username || key,
                        name: data[key].name || key,
                        online: data[key].online || false
                    }));

                    const sortedList = list.sort((a, b) => {
                        if (a.online === b.online) {
                            return a.name.localeCompare(b.name, 'ar');
                        }
                        return a.online ? -1 : 1;
                    });

                    setOnlineUsers(sortedList);
                } else {
                    setOnlineUsers([]);
                }
            });
            return () => unsubscribe();
        }
    }, [user.role]);

    const allItems = [
        { id: 'sales', label: 'المبيعات اليومية', icon: ShoppingCart, permissionKey: 'showDailySales' },
        { id: 'salesLog', label: 'سجل المبيعات', icon: FileText, permissionKey: 'showSalesLog' },
        { id: 'inventoryReg', label: 'تسجيل المخزون', icon: PackagePlus, permissionKey: 'showInventoryReg' },
        { id: 'inventoryLog', label: 'سجل المخزون', icon: ClipboardList, permissionKey: 'showInventoryLog' },
        { id: 'competitorPrices', label: 'أسعار المنافسين', icon: TrendingUp, permissionKey: 'showCompetitorPrices' },
        { id: 'competitorReports', label: 'تقارير المنافسين', icon: BarChart2, permissionKey: 'showCompetitorReports' },
        { id: 'leaveBalance', label: 'رصيد الإجازات', icon: CalendarOff, alwaysShow: true },
        { id: 'settings', label: 'الإعدادات', icon: SettingsIcon, adminOnly: true },
    ];

    const menuItems = allItems.filter(item => {
        if (user.role === 'admin') return true;
        if (item.adminOnly) return false;
        if (item.alwaysShow) return true;
        if (item.permissionKey) {
            const perms = user.permissions || {} as any;
            return perms[item.permissionKey] === true;
        }
        return false;
    });

    const getButtonClass = (isActive: boolean) => {
        let classes = "group w-full flex items-center gap-4 px-4 py-3.5 rounded-xl transition-all duration-200 font-bold mb-1 ";

        if (isActive) {
            switch (theme) {
                case 'win10': classes += "bg-blue-600 text-white shadow-lg"; break;
                case 'glass': classes += "bg-white/20 text-white backdrop-blur-md border border-white/20"; break;
                case 'light': classes += "bg-blue-600 text-white shadow-md"; break;
                default: classes += "bg-blue-600 text-white shadow-lg shadow-blue-600/20"; break;
            }
        } else {
            classes += theme === 'light' ? "text-gray-600 hover:bg-gray-100" : "text-gray-400 hover:bg-white/5";
        }

        return classes;
    };

    const headerClass = "text-[10px] font-bold uppercase tracking-[0.2em] mb-8 px-4 opacity-50 border-b border-white/5 pb-4";

    return (
        <aside className={`w-64 md:w-72 p-6 flex flex-col ${containerClass} transition-all duration-300`}>
            <div className={headerClass}>نظام سوفت روز</div>
            <nav className="flex-1 flex flex-col gap-1 overflow-y-auto custom-scrollbar">
                {menuItems.map(item => (
                    <button
                        key={item.id}
                        onClick={() => setView(item.id)}
                        className={getButtonClass(currentView === item.id)}
                    >
                        <item.icon size={20} strokeWidth={2.5} />
                        <span className="text-sm">{item.label}</span>
                    </button>
                ))}

                {user.role === 'admin' && (
                    <div className="mt-10 border-t pt-6 border-white/10">
                        <div className="flex items-center gap-2 mb-4 px-2 text-[10px] font-bold uppercase opacity-50">
                            <Users size={14} />
                            <span>المتواجدون حالياً</span>
                        </div>
                        <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar">
                            {onlineUsers.length === 0 ? (
                                <div className="text-[10px] opacity-40 italic px-2">لا يوجد مستخدمون نشطون</div>
                            ) : onlineUsers.map((u) => (
                                <div key={u.username} className="flex items-center justify-between px-3 py-2 rounded-lg bg-white/5 border border-white/5">
                                    <span className="text-xs font-bold truncate flex-1 opacity-80">
                                        {u.name}
                                    </span>
                                    <div 
                                        className={`w-2.5 h-2.5 rounded-full ${u.online ? 'bg-green-500 shadow-[0_0_8px_rgba(34,197,94,0.5)]' : 'bg-gray-600'}`} 
                                        title={u.online ? "متصل" : "غير متصل"} 
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </nav>

            <div className="mt-auto text-[9px] px-4 pt-4 border-t border-white/10 opacity-30 font-bold uppercase tracking-widest flex justify-between items-center">
                <span>Soft Rose System</span>
                <span>v1.5.0</span>
            </div>
        </aside>
    );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings, UserPermissions, AppNotification } from '../types';
import { 
  Save, Trash2, UserPlus, Shield, Edit2, Plus, X, 
  Settings as SettingsIcon, Users, MapPin, Building2, 
  ToggleLeft, ToggleRight, Key, Eye, EyeOff, Send
} from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<User[]>([]);
    const [newUser, setNewUser] = useState<User>({ 
        name: '', 
        username: '', 
        password: '', 
        role: 'user', 
        canViewAllSales: false,
        permissions: {
            showSalesLog: true,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        }
    });

    const [marketList, setMarketList] = useState<{key: string, name: string, createdBy: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, name: string, createdBy: string}[]>([]);

    // Modals
    const [passModal, setPassModal] = useState<{key: string, name: string} | null>(null);
    const [permModal, setPermModal] = useState<User | null>(null);
    const [notifModal, setNotifModal] = useState<{username: string, name: string} | null>(null);
    const [newPass, setNewPass] = useState('');
    const [notifMsg, setNotifMsg] = useState('');

    useEffect(() => {
        setLocalSettings(settings);
    }, [settings]);

    useEffect(() => {
        if (user.role !== 'admin') return;

        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: User[] = [];
                snapshot.forEach(c => { u.push({ key: c.key || '', ...c.val() }); });
                setUsers(u);
            }
        });

        onValue(ref(db, 'settings/markets'), snapshot => {
            if(snapshot.exists()){
                const m: any[] = [];
                snapshot.forEach(c => { 
                    const data = c.val();
                    m.push({
                        key: c.key, 
                        name: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'System' : data.createdBy
                    });
                });
                setMarketList(m);
            }
        });

        onValue(ref(db, 'settings/companies'), snapshot => {
            if(snapshot.exists()){
                const c: any[] = [];
                snapshot.forEach(k => { 
                    const data = k.val();
                    c.push({
                        key: k.key, 
                        name: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'System' : data.createdBy
                    });
                });
                setCompanyList(c);
            }
        });
    }, [user.role]);

    const saveAppSettings = async () => {
        try {
            await set(ref(db, 'settings/app'), localSettings);
            alert('تم حفظ إعدادات التطبيق بنجاح');
        } catch (e) { alert('خطأ في الحفظ'); }
    };

    const handleAddUser = async () => {
        if (!newUser.username || !newUser.password || !newUser.name) return alert("اكمل بيانات المستخدم");
        await push(ref(db, 'users'), newUser);
        alert("تمت إضافة المستخدم بنجاح");
        setNewUser({ 
            name: '', 
            username: '', 
            password: '', 
            role: 'user', 
            canViewAllSales: false,
            permissions: {
                showSalesLog: true,
                showInventoryLog: false,
                showInventoryReg: false,
                showCompetitorReports: false,
                showDailySales: true,
                showCompetitorPrices: true
            }
        });
    };

    const handleDeleteUser = async (key: string) => {
        if (confirm("هل أنت متأكد من حذف هذا المستخدم؟")) {
            await remove(ref(db, `users/${key}`));
        }
    };

    const handleUpdatePassword = async () => {
        if(!passModal || !newPass) return;
        await update(ref(db, `users/${passModal.key}`), { password: newPass });
        alert("تم تحديث كلمة المرور");
        setPassModal(null);
        setNewPass('');
    };

    const handleUpdatePermissions = async () => {
        if (!permModal || !permModal.key) return;
        const permissions = permModal.permissions || {
            showSalesLog: false,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        };
        await update(ref(db, `users/${permModal.key}`), { 
            permissions: permissions,
            canViewAllSales: !!permModal.canViewAllSales
        });
        alert("تم تحديث الصلاحيات بنجاح");
        setPermModal(null);
    };

    const handleSendNotif = async () => {
        if (!notifModal || !notifMsg) return;
        const notification: AppNotification = {
            message: notifMsg,
            sender: user.name,
            timestamp: Date.now(),
            isRead: false
        };
        await push(ref(db, `notifications/${notifModal.username}`), notification);
        alert(`تم إرسال الرسالة بنجاح إلى ${notifModal.name}`);
        setNotifModal(null);
        setNotifMsg('');
    };

    const toggleUserPerm = (key: keyof UserPermissions) => {
        if (!permModal) return;
        const currentPermissions = permModal.permissions || {
            showSalesLog: false,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        };
        setPermModal({
            ...permModal,
            permissions: {
                ...currentPermissions,
                [key]: !currentPermissions[key]
            }
        });
    };

    if (user.role !== 'admin') {
        return <div className="p-10 text-center opacity-50">عذراً، هذه الصفحة متاحة للمسؤولين فقط.</div>;
    }

    const inputClass = "w-full p-2.5 rounded-lg border border-gray-300 text-black focus:ring-2 focus:ring-blue-500 outline-none";
    const sectionClass = `p-6 rounded-2xl mb-6 ${theme === 'dark' ? 'bg-gray-800 border-gray-700 border' : 'bg-white shadow-xl'}`;

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-20">
            <div className="flex items-center gap-3 mb-2">
                <SettingsIcon className="text-blue-600" size={32} />
                <h2 className="text-3xl font-bold">لوحة تحكم المسؤول</h2>
            </div>

            {/* إعدادات التطبيق العامة */}
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-6 flex items-center gap-2 text-blue-600 border-b pb-3">
                    <Edit2 size={20} /> الإعدادات العامة للمنصة
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-bold mb-2 opacity-70">اسم التطبيق (AppName)</label>
                        <input className={inputClass} value={localSettings.appName} onChange={e => setLocalSettings({...localSettings, appName: e.target.value})} />
                    </div>
                    <div>
                        <label className="block text-sm font-bold mb-2 opacity-70">رقم واتساب الدعم</label>
                        <input className={inputClass} placeholder="مثال: 2010XXXXXXXX" value={localSettings.whatsappNumber} onChange={e => setLocalSettings({...localSettings, whatsappNumber: e.target.value})} />
