import React, { useEffect, useState } from 'react';
import { Route, Routes } from 'react-router-dom';
import Login from './Login';
import Register from './Register';
import Home from './Home';
import Profile from './Profile';
import { useAuth } from './AuthContext';
import { ThemeProvider } from './ThemeContext';
import Ticker from './components/Ticker';
import { darkCoffee } from './themes/darkCoffee';
import { dark } from './themes/dark';
import { light } from './themes/light';
import { coffee } from './themes/coffee';

const App = () => {
  const { loggedIn, logout } = useAuth();
  const [theme, setTheme] = useState('light');
  const [tickerData, setTickerData] = useState([]);

  useEffect(() => {
    // Fetch and set the theme from local storage
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme) {
      setTheme(savedTheme);
    } else {
      setTheme('light');
    }
  }, []);

  const toggleTheme = (newTheme: string) => {
    setTheme(newTheme);
    localStorage.setItem('theme', newTheme); // Save the theme to local storage
  };

  useEffect(() => {
    const fetchTickerData = async () => {
      try {
        const response = await fetch('https://api.coingecko.com/api/v3/coins/markets?vs_currency=usd&order=market_cap_desc&per_page=10&page=1&sparkline=false');
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        setTickerData(data);
      } catch (error) {
        console.error("Could not fetch ticker data:", error);
      }
    };
    fetchTickerData();
  }, []);

  const getThemeObject = (theme: string) => {
    switch (theme) {
      case 'dark':
        return dark;
      case 'darkCoffee':
        return darkCoffee;
      case 'light':
        return light;
      case 'coffee':
        return coffee;
      default:
        return light;
    }
  };

  return (
    <div className={`flex flex-col overflow-hidden h-screen bg-gray-100 dark:bg-gray-800 ${getThemeObject(theme).backgroundColor}`}>
      <Ticker tickerData={tickerData} />
      <header className="bg-white dark:bg-gray-900 shadow-md py-4 px-6">
        <div className="flex justify-between items-center max-w-7xl mx-auto">
          <h1 className="text-2xl font-bold dark:text-white">Soft Rose Trading</h1>
          <div className="flex items-center space-x-4">
            {loggedIn && (
              <>
                <button
                  onClick={logout}
                  className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded"
                >
                  Logout
                </button>
                <ThemeProvider>
                  <button onClick={() => toggleTheme(theme === 'dark' ? 'light' : 'dark')} className="text-gray-700 dark:text-white">
                    {theme === 'dark' ? 'Light Mode' : 'Dark Mode'}
                  </button>
                </ThemeProvider>
              </>
            )}
          </div>
        </div>
      </header>
      <div className="flex-1 overflow-hidden flex">
        <aside className="w-1/4 bg-gray-200 dark:bg-gray-700 p-4">
          <ul className="space-y-2">
            <li><a href="/" className="block py-2 px-4 text-gray-700 dark:text-white hover:bg-gray-300

**Refining Signature Integration**

I'm now zeroing in on the final touches. Considering the user's specific directive to avoid functional changes, I've decided the best approach is to insert the signature directly after the copyright line within the application's footer, in a small new `<p>` tag, without changing the existing formatting. I'm verifying this doesn't impact any other app elements.

