import React, { useState, useEffect } from 'react';
import { ref, push, set, onValue } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Plus, Trash2, Save } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [globalProducts, setGlobalProducts] = useState<ProductItem[]>([]);
    const [notification, setNotification] = useState('');

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
    ];

    useEffect(() => {
        // جلب الأصناف العالمية المضافة من قبل المسؤول
        onValue(ref(db, 'settings/global_products'), (snapshot) => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                setGlobalProducts(Object.keys(data).map(k => ({ id: k, ...data[k] })));
            } else {
                setGlobalProducts([]);
            }
        });
    }, []);

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        allCategories.forEach(cat => {
            // إضافة الأصناف الأساسية من الثوابت
            cat.items.forEach(itemName => {
                initialItems.push({
                    id: itemName + "_base",
                    category: cat.key,
                    name: itemName,
                    price: 0,
                    qty: 0,
                    isCustom: false
                });
            });
            // إضافة الأصناف العالمية من قاعدة البيانات
            globalProducts.filter(gp => gp.category === cat.key).forEach(gp => {
                initialItems.push({
                    ...gp,
                    price: 0,
                    qty: 0
                });
            });
        });
        setSalesItems(initialItems);
    }, [globalProducts]);

    const updateItem = (id: string, field: keyof ProductItem, value: any) => {
        setSalesItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const handleAddCustomItem = async (category: string) => {
        const name = prompt("ادخل اسم الصنف الجديد:");
        if (!name) return;

        const newItem = {
            category,
            name,
            isCustom: true
        };

        if (user.role === 'admin') {
            // إذا كان مسؤول، يتم الحفظ في الأصناف العالمية لجميع الماركتات
            await push(ref(db, 'settings/global_products'), newItem);
        } else {
            // إذا كان مستخدم عادي، يضاف كصنف مؤقت لهذه الفاتورة فقط
            const tempItem: ProductItem = {
                id: `temp_${Date.now()}`,
                ...newItem,
                price: 0,
                qty: 0
            };
            setSalesItems(prev => [...prev, tempItem]);
        }
    };

    const removeCustomItem = (id: string) => {
        setSalesItems(prev => prev.filter(i => i.id !== id));
    };

    const calculateTotal = () => salesItems.reduce((sum, item) => sum + ((Number(item.price) || 0) * (Number(item.qty) || 0)), 0);

    const handleSave = async () => {
        if (!selectedMarket) return alert("الرجاء اختيار الماركت");
        const soldItems = salesItems.filter(item => (item.name && Number(item.price) > 0 && Number(item.qty) > 0));
        if (soldItems.length === 0) return alert("لا يوجد مبيعات مكتملة للحفظ");

        const saleData = {
            market: selectedMarket,
            employeeName: user.name,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: soldItems,
            total: calculateTotal()
        };

        await push(ref(db, 'sales'), saleData);
        setNotification('تم حفظ المبيعات بنجاح!');
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
        setTimeout(() => setNotification(''), 3000);
    };

    const handleAddMarket = async () => {
        const name = prompt("ادخل اسم الماركت الجديد:");
        if (name) await push(ref(db, 'settings/markets'), { name, createdBy: user.username });
    };

    const inputClass = theme === 'win10' || theme === 'light' 
        ? "border border-gray-300 p-2 rounded w-full text-black" 
        : "bg-white/10 border border-white/20 p-2 rounded w-full text-white placeholder-gray-400";

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-2xl font-bold">المبيعات اليومية</h2>
                <div className="text-xl font-bold bg-green-500 text-white px-4 py-2 rounded shadow w-full md:w-auto text-center">
                    إجمالي الفاتورة: {calculateTotal().toLocaleString()} ج.م
                </div>
            </div>

            <div className="flex items-end gap-2">
                <div className="flex-1">
                    <label className="block mb-1 font-semibold">اسم الماركت</label>
                    <select value={selectedMarket} onChange={(e) => setSelectedMarket(e.target.value)} className={inputClass}>
                        <option value="">اختر الماركت...</option>
                        {markets.map((m, idx) => <option key={idx} value={m}>{m}</option>)}
                    </select>
                </div>
                <button onClick={handleAddMarket} className="bg-blue-500 hover:bg-blue-600 text-white p-2 rounded mb-[2px] transition active:scale-95"><Plus size={24} /></button>
            </div>

            {allCategories.map(cat => (
                <div key={cat.key} className="bg-white/5 p-4 rounded-xl border border-gray-500/10">
                    <div className="flex justify-between items-center mb-4 border-b border-gray-500/20 pb-2">
                        <h3 className="text-xl font-bold text-blue-500">{cat.name}</h3>
                        <button 
                            onClick={() => handleAddCustomItem(cat.key)} 
                            className="bg-green-600 hover:bg-green-700 text-white text-xs px-3 py-1.5 rounded flex items-center gap-1 shadow transition active:scale-95"
                        >
                            <Plus size={14}/> {user.role === 'admin' ? 'إضافة صنف دائم' : 'إضافة صنف مؤقت'}
                        </button>
                    </div>

                    <div className="grid grid-cols-12 gap-1 items-center bg-gray-500/10 p-2 rounded mb-2 text-[10px] md:text-xs font-bold opacity-70">
                        <div className="col-span-4 pr-2">الصنف</div>
                        <div className="col-span-3 text-center">سعر القطعة</div>
                        <div className="col-span-2 text-center">العدد</div>
                        <div className="col-span-2 text-center">الإجمالي</div>
                        <div className="col-span-1"></div>
                    </div>

                    <div className="space-y-2">
                        {salesItems.filter(item => item.category === cat.key).map((item) => (
                            <div key={item.id} className="grid grid-cols-12 gap-1 items-center bg-black/5 p-1 rounded hover:bg-white/5 transition">
                                <div className="col-span-4 text-xs pr-2 truncate">
                                    {item.name}
                                </div>
                                <div className="col-span-3">
                                    <input type="number" value={item.price || ''} onChange={(e) => updateItem(item.id, 'price', parseFloat(e.target.value))} className={`${inputClass} text-center h-8 text-xs`} placeholder="السعر" />
                                </div>
                                <div className="col-span-2">
                                    <input type="number" value={item.qty || ''} onChange={(e) => updateItem(item.id, 'qty', parseFloat(e.target.value))} className={`${inputClass} text-center h-8 text-xs`} placeholder="0" />
                                </div>
                                <div className="col-span-2 text-center font-bold text-xs">{(Number(item.price) * Number(item.qty)) || '-'}</div>
                                <div className="col-span-1 flex justify-center">
                                    {(item.id.includes('temp_') || (user.role === 'admin' && item.id.includes('_global'))) && (
                                        <button onClick={() => removeCustomItem(item.id)} className="text-red-500 hover:bg-red-50 p-1 rounded transition">
                                            <Trash2 size={14} />
                                        </button>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            <div className="mt-8 flex justify-center sticky bottom-4 z-10">
                <button onClick={handleSave} className="bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-8 rounded-full shadow-xl flex items-center gap-2 text-lg transform hover:scale-105 transition w-full md:w-auto justify-center">
                    <Save size={24} /> حفظ وترحيل المبيعات
                </button>
            </div>

            {notification && <div className="fixed bottom-4 left-4 right-4 md:right-auto bg-green-600 text-white px-6 py-3 rounded-lg shadow-lg animate-bounce text-center z-50">{notification}</div>}
        </div>
    );
};

export default DailySales;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { 
    Trash2, Edit, CalendarPlus, X, Save, History, 
    ChevronRight, ChevronLeft, Calendar, 
    CheckCircle2, AlertCircle, Clock, Filter
} from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<LeaveBalance[]>([]);
    const [usersList, setUsersList] = useState<{key: string, name: string}[]>([]);
    const [allHistory, setAllHistory] = useState<({id: string} & LeaveRecord)[]>([]);

    // Modal States
    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showEditBalanceModal, setShowEditBalanceModal] = useState(false);
    const [showHistoryDetailsModal, setShowHistoryDetailsModal] = useState(false);
    const [showEditRecordModal, setShowEditRecordModal] = useState(false);

    // Period Control State (21 to 20)
    const [currentPeriodStart, setCurrentPeriodStart] = useState<Date>(() => {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        return now.getDate() >= 21 ? new Date(year, month, 21) : new Date(year, month - 1, 21);
    });

    // Form States
    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams' | 'unpaid'>('annual');
    const [editingBalance, setEditingBalance] = useState<LeaveBalance | null>(null);
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);
    const [editingRecord, setEditingRecord] = useState<{id: string} & LeaveRecord | null>(null);

    // Load Data
    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: any[] = [];
                snapshot.forEach(c => { u.push({ key: c.key, name: c.val().name }); });
                setUsersList(u);
            }
        });

        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const b: LeaveBalance[] = Object.values(snapshot.val());
                setBalances(user.role === 'admin' ? b : b.filter(x => x.employeeName === user.name));
            } else { setBalances([]); }
        });

        onValue(ref(db, 'leave_history'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                const h: any = Object.keys(data).map(key => ({
                    id: key,
                    ...data[key]
                }));
                setAllHistory(h);
            } else { setAllHistory([]); }
        });
    }, [user]);

    // Period Logic
    const getPeriodEnd = (start: Date) => {
        const end = new Date(start);
        end.setMonth(end.getMonth() + 1);
        end.setDate(20);
        return end;
    };

    const changePeriod = (direction: number) => {
        const newStart = new Date(currentPeriodStart);
        newStart.setMonth(newStart.getMonth() + direction);
        setCurrentPeriodStart(newStart);
    };

    const filterHistoryByPeriodAndUser = (userId: string) => {
        const pStart = new Date(currentPeriodStart);
        pStart.setHours(0,0,0,0);
        const pEnd = getPeriodEnd(currentPeriodStart);
        pEnd.setHours(23,59,59,999);

        return allHistory.filter((record) => {
            const recordDate = new Date(record.date);
            return record.userId === userId && recordDate >= pStart && recordDate <= pEnd;
        });
    };

    // حساب الغياب بإذن للفترة الحالية فقط
    const getUnpaidForPeriod = (userId: string) => {
        return filterHistoryByPeriodAndUser(userId)
            .filter(r => r.type === 'unpaid')
            .reduce((sum, r) => sum + r.days, 0);
    };

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate || leaveDays <= 0) return alert("يرجى اكمال البيانات");

        // منع تسجيل نفس اليوم مرتين لنفس الموظف
        const isAlreadyRecorded = allHistory.some(r => r.userId === selectedUser && r.date === leaveDate);
        if (isAlreadyRecorded) {
            return alert("تم تسجيل اليوم من قبل لهذا الموظف!");
        }

        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;

        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        let currentBalance: LeaveBalance = balances.find(b => b.userId === selectedUser) || {
            userId: selectedUser, employeeName: targetUser.name,
            annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0
        };

        // تحديث الرصيد (تجاهل خصم unpaid إذا كان الموظف يريد تصفيره شهرياً)
        const newBalance = { ...currentBalance, [leaveType]: Number(currentBalance[leaveType] || 0) - (leaveType === 'unpaid' ? 0 : Number(leaveDays)) };
        await set(balanceRef, newBalance);

        const historyData: LeaveRecord = {
            userId: selectedUser, employeeName: targetUser.name,
            date: leaveDate, days: Number(leaveDays), type: leaveType, timestamp: Date.now()
        };
        await push(ref(db, 'leave_history'), historyData);

        alert("تم تسجيل الاجازة بنجاح");
        setShowAddLeaveModal(false);
        setLeaveDate('');
    };

    const handleEditBalance = async () => {
        if (user.role !== 'admin') return;
        if (!editingBalance) return;
        await set(ref(db, `leave_balances/${editingBalance.userId}`), editingBalance);
        setShowEditBalanceModal(false);
        setEditingBalance(null);
    };

    const openHistory = (userId: string, name: string) => {
        setHistoryUserView({ userId, name });
        setShowHistoryDetailsModal(true);
    };

    const inputClass = "border p-2.5 rounded-lg text-black w-full focus:ring-2 focus:ring-blue-500 outline-none transition";
    const modalClass = `fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/70 backdrop-blur-md`;
    const modalContentClass = `w-full max-w-2xl p-6 rounded-2xl shadow-2xl border ${theme === 'dark' ? 'bg-gray-900 text-white border-gray-800' : 'bg-white text-black border-gray-100'}`;

    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات', unpaid: 'غياب بإذن' };
    const typeColors = { 
        annual: 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400',
        casual: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400',
        sick: 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
        exams: 'bg-purple-100 text-purple-700 dark:bg-purple-900/30 dark:text-purple-400',
        unpaid: 'bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400'
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <h2 className="text-2xl font-bold flex items-center gap-2">
                    <History className="text-blue-500" /> رصيد الإجازات
                </h2>
                <button 
                    onClick={() => setShowAddLeaveModal(true)}
                    className="bg-red-600 hover:bg-red-700 text-white px-6 py-2.5 rounded-xl font-bold shadow-lg flex items-center gap-2 transition transform active:scale-95"
                >
                    <CalendarPlus size={20} /> تسجيل إجازة
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {balances.map((balance) => (
                    <div key={balance.userId} className={`p-5 rounded-2xl border ${theme === 'dark' ? 'bg-gray-800 border-gray-700' : 'bg-white border-gray-100 shadow-md hover:shadow-xl transition-all duration-300'}`}>
                        <div className="flex justify-between items-start mb-4">
                            <div className="font-bold text-lg text-blue-600 truncate">{balance.employeeName}</div>
                            {user.role === 'admin' && (
                                <button onClick={() => { setEditingBalance(balance); setShowEditBalanceModal(true); }} className="p-2 text-indigo-500 hover:bg-indigo-50 rounded-lg"><Edit size={16} /></button>
                            )}
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                            {Object.entries(typeLabels).map(([key, label]) => (
                                <button 
                                    key={key}
                                    onClick={() => openHistory(balance.userId, balance.employeeName)}
                                    className={`p-3 rounded-xl flex flex-col items-center transition-transform active:scale-95 ${typeColors[key as keyof typeof typeColors]}`}
                                >
                                    <span className="text-[10px] opacity-70 uppercase font-bold text-center">{label}</span>
                                    <span className="text-xl font-black">
                                        {key === 'unpaid' ? getUnpaidForPeriod(balance.userId) : (balance as any)[key] || 0}
                                    </span>
                                </button>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            {/* Modal: History */}
            {showHistoryDetailsModal && historyUserView && (
                <div className={modalClass}>
                    <div className={`${modalContentClass} max-w-3xl overflow-hidden flex flex-col max-h-[90vh]`}>
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold text-blue-600 flex items-center gap-2">
