import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, CompetitorPrice } from '../types';
import { exportToCSV } from '../utils';
import { COMPANIES } from '../constants';
import { Trash2, Edit, Save, X, FileSpreadsheet, User as UserIcon, Calendar, Building } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorReports: React.FC<Props> = ({ user, markets, theme }) => {
    const [data, setData] = useState<CompetitorPrice[]>([]);
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [editingReport, setEditingReport] = useState<CompetitorPrice | null>(null);

    useEffect(() => {
        onValue(ref(db, 'settings/companies'), s => {
            if(s.exists()) {
                const rawData = s.val();
                const allCompanies: any[] = Object.keys(rawData).map(key => {
                    const item = rawData[key];
                    return typeof item === 'string' ? { name: item, createdBy: 'system' } : item;
                });
                setCompanies(allCompanies.map(c => c.name));
            } else {
                setCompanies(COMPANIES);
            }
        });

        onValue(ref(db, 'competitor_prices'), s => {
            if(s.exists()) {
                let arr = Object.keys(s.val()).map(key => ({
                    id: key,
                    ...s.val()[key]
                })) as CompetitorPrice[];
                if (user.role !== 'admin' && !user.canViewAllSales) {
                    arr = arr.filter(d => d.employeeName === user.name);
                }
                setData(arr.sort((a, b) => b.date.localeCompare(a.date)));
            } else {
                setData([]);
            }
        });
    }, [user]);

    const filtered = data.filter(d => 
        (!selectedMarket || d.market === selectedMarket) &&
        (!selectedCompany || d.company === selectedCompany)
    );

    const handleExport = () => {
        if (filtered.length === 0) return alert("لا توجد بيانات لتصديرها");

        // تحسين تنسيق البيانات للإكسيل - فصل كل يوم وشركة
        const csv = filtered.flatMap(d => (d.items || []).map(i => ({
            "التاريخ": d.date,
            "الماركت": d.market,
            "اسم المستخدم": d.employeeName || '-',
            "الشركة": d.company,
            "القسم": i.category,
            "المنتج": i.name,
            "السعر (ج.م)": i.price
        })));

        exportToCSV(csv, `تقرير_المنافسين_الشامل_${new Date().toLocaleDateString('ar-EG')}`);
    };

    const inputClass = "border p-2 rounded text-black w-full text-sm";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold flex items-center gap-2">
                <Building className="text-blue-500" /> تقارير أسعار المنافسين
            </h2>

            <div className="bg-white/5 p-4 rounded-xl space-y-4 border border-white/10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">كل الماركتات</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                    <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                        <option value="">كل الشركات</option>
                        {companies.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
                <button onClick={handleExport} className="w-full bg-green-600 hover:bg-green-700 text-white py-3 rounded-lg flex items-center justify-center gap-2 font-bold shadow-lg transition active:scale-95">
                    <FileSpreadsheet size={20} /> تصدير تقرير احترافي (Excel)
                </button>
            </div>

            <div className="space-y-4">
                {filtered.map((record, i) => (
                    <div key={record.id || i} className="p-5 rounded-2xl border bg-gray-800/50 border-white/10 hover:border-blue-500/30 transition shadow-sm">
                        <div className="flex flex-col md:flex-row justify-between items-start md:items-center mb-4 gap-2">
                            <div>
                                <h3 className="text-lg font-bold text-blue-400">{record.market}</h3>
                                <div className="flex flex-wrap gap-3 mt-1 text-[10px] opacity-60">
                                    <span className="flex items-center gap-1"><Calendar size={12}/> {record.date}</span>
                                    <span className="flex items-center gap-1"><UserIcon size={12}/> {record.employeeName}</span>
                                    <span className="flex items-center gap-1 text-green-400 font-bold"><Building size={12}/> {record.company}</span>
                                </div>
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => setEditingReport(record)} className="p-2 text-indigo-400 hover:bg-indigo-500/10 rounded-lg"><Edit size={16}/></button>
                                {(user.role === 'admin' || user.name === record.employeeName) && (
                                     <button onClick={() => remove(ref(db, `competitor_prices/${record.id!}`))} className="p-2 text-red-400 hover:bg-red-500/10 rounded-lg"><Trash2 size={16}/></button>
                                )}
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                            {(record.items || []).map((item, idx) => (
                                <div key={idx} className="flex justify-between p-2.5 bg-black/30 rounded-xl text-xs border border-white/5">
                                    <span className="opacity-80">{item.name}</span>
                                    <span className="font-bold text-green-500">{item.price} ج.م</span>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default CompetitorReports;

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { db } from '../firebase';
import { ref, get } from "firebase/database";
import { Bot, Send, X, Loader2, Sparkles, MessageSquare } from 'lucide-react';

interface Props {
    user: any;
    theme: string;
}

const AISearch: React.FC<Props> = ({ user, theme }) => {
    const [isOpen, setIsOpen] = useState(false);
    const [query, setQuery] = useState('');
    const [messages, setMessages] = useState<{role: 'user' | 'bot', text: string}[]>([]);
    const [loading, setLoading] = useState(false);
    const chatRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (chatRef.current) {
            chatRef.current.scrollTop = chatRef.current.scrollHeight;
        }
    }, [messages]);

    const getSystemContext = async () => {
        // جلب عينة من البيانات لتقديمها كـ Context للذكاء الاصطناعي
        const salesSnap = await get(ref(db, 'sales'));
        const leaveSnap = await get(ref(db, 'leave_balances'));
        const historySnap = await get(ref(db, 'leave_history'));

        const salesData = salesSnap.exists() ? Object.values(salesSnap.val()).slice(-20) : [];
        const leaveData = leaveSnap.exists() ? Object.values(leaveSnap.val()) : [];
        const historyData = historySnap.exists() ? Object.values(historySnap.val()).slice(-20) : [];

        return `
            أنت المساعد الذكي لنظام "Soft Rose Modern Trade".
            بيانات النظام الحالية:
            - الموظف الحالي: ${user.name} (الدور: ${user.role})
            - آخر 20 عملية مبيعات: ${JSON.stringify(salesData)}
            - أرصدة الإجازات للموظفين: ${JSON.stringify(leaveData)}
            - آخر 20 إجازة مسجلة: ${JSON.stringify(historyData)}

            تعليمات:
            1. أجب باحترافية وباللغة العربية.
            2. استخرج البيانات المطلوبة (مثلاً مبيعات فترة، أرصدة إجازات، تارجت مقترح).
            3. إذا سئلت عن تارجت، اقترح تارجت بناءً على متوسط المبيعات الأخير للموظف.
            4. كن مختصراً وواضحاً.
        `;
    };

    const handleAskAI = async () => {
        if (!query.trim()) return;
        setLoading(true);
        const userMsg = query;
        setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
        setQuery('');

        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
            const context = await getSystemContext();

            const response = await ai.models.generateContent({
                model: 'gemini-3-pro-preview',
                contents: userMsg,
                config: {
                    systemInstruction: context,
                    thinkingConfig: { thinkingBudget: 0 }
                }
            });

            const botText = response.text || "عذراً، لم أستطع معالجة طلبك حالياً.";
            setMessages(prev => [...prev, { role: 'bot', text: botText }]);
        } catch (err) {
            setMessages(prev => [...prev, { role: 'bot', text: "حدث خطأ في الاتصال بخادم الذكاء الاصطناعي." }]);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="fixed bottom-6 left-6 z-[100]">
            {/* Floating Button */}
            <button 
                onClick={() => setIsOpen(!isOpen)}
                className="w-14 h-14 bg-gradient-to-tr from-blue-600 to-indigo-600 rounded-full shadow-2xl flex items-center justify-center text-white transition transform hover:scale-110 active:scale-95 border-2 border-white/20 animate-pulse"
            >
                {isOpen ? <X size={24}/> : <Sparkles size={24}/>}
            </button>

            {/* Chat Window */}
            {isOpen && (
                <div className="absolute bottom-16 left-0 w-[90vw] md:w-96 h-[70vh] max-h-[600px] bg-gray-900 border border-white/10 rounded-3xl shadow-2xl flex flex-col overflow-hidden animate-in fade-in slide-in-from-bottom-5 duration-300">
                    <div className="p-4 bg-gradient-to-r from-blue-600 to-indigo-600 text-white flex justify-between items-center">
                        <div className="flex items-center gap-2">
                            <Bot size={20}/>
                            <span className="font-bold text-sm">مساعد سوفت روز الذكي</span>
                        </div>
                        <Sparkles size={16} className="opacity-50"/>
                    </div>

                    <div ref={chatRef} className="flex-1 p-4 overflow-y-auto space-y-4 custom-scrollbar bg-black/40">
                        {messages.length === 0 && (
                            <div className="h-full flex flex-col items-center justify-center opacity-30 text-center space-y-2">
                                <MessageSquare size={48}/>
                                <p className="text-xs font-bold">اسألني عن المبيعات، الإجازات، أو التارجت المقترح</p>
                            </div>
                        )}
                        {messages.map((m, i) => (
                            <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                <div className={`max-w-[85%] p-3 rounded-2xl text-xs leading-relaxed ${m.role === 'user' ? 'bg-blue-600 text-white rounded-tr-none' : 'bg-gray-800 text-gray-200 rounded-tl-none border border-white/5'}`}>
                                    {m.text}
                                </div>
                            </div>
                        ))}
                        {loading && (
                            <div className="flex justify-start">
                                <div className="bg-gray-800 p-3 rounded-2xl flex items-center gap-2">
                                    <Loader2 className="animate-spin text-blue-500" size={16}/>
                                    <span className="text-[10px] opacity-60">جاري التفكير...</span>
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="p-3 border-t border-white/5 bg-gray-900">
                        <div className="flex gap-2">
                            <input 
                                className="flex-1 bg-black/40 border border-white/10 rounded-xl px-4 py-2 text-xs text-white outline-none focus:border-blue-500 transition"
                                placeholder="اكتب سؤالك هنا..."
                                value={query}
                                onChange={e => setQuery(e.target.value)}
                                onKeyPress={e => e.key === 'Enter' && handleAskAI()}
                            />
                            <button 
                                onClick={handleAskAI}
                                disabled={loading || !query.trim()}
                                className="bg-blue-600 text-white p-2 rounded-xl hover:bg-blue-700 transition disabled:opacity-50"
                            >
                                <Send size={18}/>
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AISearch;

import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set, update, onDisconnect, serverTimestamp, remove } from "firebase/database";
import { User, AppSettings, AppNotification } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import AISearch from './components/AISearch';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen, Check, Trash2, Clock, Copy, ExternalLink } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, 
    showInventoryReg: false, 
    showCompetitorReports: false,
    showDailySales: true,
    showCompetitorPrices: true
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'dark'>('dark');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showThemeSelector, setShowThemeSelector] = useState(false);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [selectedNotif, setSelectedNotif] = useState<AppNotification | null>(null);

  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    onValue(settingsRef, (snapshot) => {
      if (snapshot.exists()) setSettings({...DEFAULT_SETTINGS, ...snapshot.val()});
    });

    onValue(marketsRef, (snapshot) => {
      const systemMarkets = INITIAL_MARKETS.map(name => ({ name, createdBy: 'system' }));
      const dbMarkets = snapshot.exists() ? Object.values(snapshot.val()).map((m: any) => 
        typeof m === 'string' ? { name: m, createdBy: 'system' } : m
      ) : [];
      const allCombined = [...systemMarkets, ...dbMarkets];

      if (user) {
        let filtered;
        if (user.role === 'admin') {
          filtered = allCombined;
        } else {
          filtered = allCombined.filter(m => m.createdBy === 'system' || m.createdBy === user.username);
        }
        const uniqueNames = Array.from(new Set(filtered.map(m => m.name)));
        setMarkets(uniqueNames);
      }
    }, { onlyOnce: false });

    onValue(connectedRef, (snap) => setIsConnected(!!snap.val()));
  }, [user?.username, user?.role]);

  useEffect(() => {
    if (!user || !user.key || user.key === 'admin_root') return;

    const userRef = ref(db, `users/${user.key}`);
    const unsubscribe = onValue(userRef, (snapshot) => {
      if (snapshot.exists()) {
        const updatedData = { ...snapshot.val(), key: user.key };
        setUser(updatedData);
        localStorage.setItem('soft_rose_user', JSON.stringify(updatedData));
      }
    });

    return () => unsubscribe();
  }, [user?.key]);

  useEffect(() => {
    if (!user) return;
    const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
    const userStatusRef = ref(db, `status/${safeKey}`);
    set(userStatusRef, { online: true, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    onDisconnect(userStatusRef).set({ online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });

    onValue(ref(db, `notifications/${user.username}`), (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list = Object.keys(data).map(key => ({ id: key, ...data[key] })).sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        } else {
            setNotifications([]);
            setUnreadCount(0);
        }
    });
  }, [user?.username]);

  const handleLogout = async () => {
    if (user) {
        const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `status/${safeKey}`), { online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    }
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  const markAsRead = (id: string) => {
    if (!user) return;
    update(ref(db, `notifications/${user.username}/${id}`), { isRead: true });
  };

  const deleteNotif = (id: string) => {
    if (!user) return;
    remove(ref(db, `notifications/${user.username}/${id}`));
  };

  const copyNotifText = (text: string) => {
    navigator.clipboard.writeText(text);
    alert("تم نسخ نص الرسالة بنجاح");
  };

  if (!user) return <Login onLogin={setUser} theme={theme} />;

  const getThemeClasses = () => "bg-black text-white min-h-screen";

  const themesList = [
      { id: 'dark', name: 'الوضع الليلي (الأساسي)', color: 'bg-black border border-white/20' }
  ];

  const headerBg = () => 'bg-black/80 backdrop-blur-md border-b border-white/10 text-white shadow-lg';
  const mainContentBg = () => 'bg-gray-900/60 border border-white/5 backdrop-blur-md';

  return (
    <div className={`${getThemeClasses()} flex flex-col overflow-hidden transition-all duration-700`}>
      {settings.tickerEnabled && (
        <div className="bg-black/90 text-yellow-400 py-1.5 overflow-hidden whitespace-nowrap border-b border-white/10 z-50 backdrop-blur-xl">
           <div className="animate-marquee inline-block px-4 font-bold">{settings.tickerText}</div>
        </div>
      )}

      <header className={`p-4 flex justify-between items-center z-50 ${headerBg()} transition-all duration-500`}>
        <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="md:hidden p-2 rounded-lg hover:bg-white/10 transition-all">
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="text-lg md:text-2xl font-bold truncate flex items-center gap-2">
                {settings.appName}
                <span className={`text-sm font-normal opacity-60 hidden sm:inline-block border-r border-current pr-2 mr-2`}>
                  | <span className="font-bold">{user.name}</span>
                </span>
            </h1>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
            {settings.whatsappNumber && (
                <a 
                    href={`https://wa.me/${settings.whatsappNumber}`} 
                    target="_blank" 
                    rel="noopener noreferrer" 
                    className="p-2 rounded-full hover:bg-green-500/10 text-green-500 transition-colors"
                    title="الدعم الفني"
                >
                    <Phone size={20} />
                </a>
            )}

            {/* --- Simplified Theme Selector --- */}
            <div className="relative">
                <button 
                    onClick={() => setShowThemeSelector(!showThemeSelector)} 
                    className={`p-2.5 rounded-full hover:bg-white/20 transition-all shadow-inner ${showThemeSelector ? 'bg-blue-600 text-white scale-110' : ''}`}
                    title="المظهر"
                >
