import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue } from "firebase/database";
import { User } from '../types';
import { 
    COMPANIES, 
    PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, 
    FINE_FACIAL, FINE_KITCHEN, FINE_TOILET,
    ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET,
    PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET,
    WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET
} from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [items, setItems] = useState<{category: string, name: string, price: number}[]>([]);

    useEffect(() => {
        onValue(ref(db, 'settings/companies'), s => {
            const systemCompanies = COMPANIES.map(name => ({ name, createdBy: 'system' }));
            const dbCompanies = s.exists() ? Object.values(s.val()).map((c: any) => 
                typeof c === 'string' ? { name: c, createdBy: 'system' } : c
            ) : [];
            const allCombined = [...systemCompanies, ...dbCompanies];
            let filtered = user.role === 'admin' ? allCombined : allCombined.filter(c => c.createdBy === 'system' || c.createdBy === user.username);
            setCompanies(Array.from(new Set(filtered.map(c => c.name))));
        });
    }, [user.username, user.role]);

    const getTemplatePath = () => {
        if (!selectedMarket || !selectedCompany || !user.username) return null;
        const safeUser = user.username.replace(/[.#$/[\]]/g, "_");
        const safeMarket = selectedMarket.replace(/[.#$/[\]]/g, "_");
        const safeCompany = selectedCompany.replace(/[.#$/[\]]/g, "_");
        return `competitor_templates/${safeUser}/${safeMarket}/${safeCompany}`;
    };

    const generateDefaultsFromList = (facial: string[], kitchen: string[], toilet: string[]) => {
        const defaultItems: {category: string, name: string, price: number}[] = [];
        facial.forEach(name => defaultItems.push({ category: 'مناديل سحب (Facial)', name, price: 0 }));
        kitchen.forEach(name => defaultItems.push({ category: 'مناديل مطبخ (Kitchen)', name, price: 0 }));
        toilet.forEach(name => defaultItems.push({ category: 'تواليت (Toilet)', name, price: 0 }));
        return defaultItems;
    };

    useEffect(() => {
        const path = getTemplatePath();
        if (path) {
            onValue(ref(db, path), (snapshot) => {
                if (snapshot.exists()) {
                    setItems(snapshot.val());
                } else {
                    if (selectedCompany === 'Soft Rose') setItems(generateDefaultsFromList(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET));
                    else if (selectedCompany === 'Fine') setItems(generateDefaultsFromList(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET));
                    else if (selectedCompany === 'Zeina') setItems(generateDefaultsFromList(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET));
                    else if (selectedCompany === 'Papia Familia') setItems(generateDefaultsFromList(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET));
                    else if (selectedCompany === 'White') setItems(generateDefaultsFromList(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET));
                    else setItems([]);
                }
            });
        }
    }, [selectedMarket, selectedCompany]);

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...items];
        // @ts-ignore
        newItems[index][field] = value;
        setItems(newItems);
        const path = getTemplatePath();
        if (path) set(ref(db, path), newItems);
    };

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const validItems = items.filter(i => i.name && i.price > 0);
        await push(ref(db, 'competitor_prices'), {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            employeeName: user.name,
            items: validItems
        });
        alert("تم الحفظ");
        const resetItems = items.map(i => ({...i, price: 0}));
        setItems(resetItems);
        const path = getTemplatePath();
        if (path) set(ref(db, path), resetItems);
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-900/40 p-5 rounded-2xl border border-white/5">
                <div>
                    <label className="block mb-1.5 text-xs font-bold opacity-60">الماركت</label>
                    <select className="w-full p-2.5 rounded-xl text-white" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">اختر الماركت</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block mb-1.5 text-xs font-bold opacity-60">الشركة</label>
                    <select className="w-full p-2.5 rounded-xl text-white" value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                        <option value="">اختر الشركة</option>
                        {companies.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            {['مناديل سحب (Facial)', 'مناديل مطبخ (Kitchen)', 'تواليت (Toilet)'].map(cat => (
                <div key={cat} className="bg-white/5 p-4 rounded-2xl border border-white/5">
                    <h3 className="font-bold mb-4 text-blue-400 border-b border-white/10 pb-2 flex items-center gap-2">{cat}</h3>
                    <div className="space-y-2">
                        {items.filter(i => i.category === cat).map((item, idx) => {
                            const actualIdx = items.indexOf(item);
                            return (
                                <div key={actualIdx} className="flex gap-2 items-center">
                                    <input 
                                        className="flex-1 bg-gray-600 text-white border border-white/10 p-2.5 rounded-xl text-xs font-bold" 
                                        value={item.name} 
                                        onChange={e => updateItem(actualIdx, 'name', e.target.value)} 
                                        placeholder="اسم المنتج" 
                                    />
                                    <input 
                                        type="number" 
                                        className="w-24 bg-white/10 border border-white/10 p-2.5 rounded-xl text-center text-xs font-bold" 
                                        value={item.price || ''} 
                                        onChange={e => updateItem(actualIdx, 'price', e.target.value)} 
                                        placeholder="0" 
                                    />
                                </div>
                            );
                        })}
                    </div>
                </div>
            ))}
            <button onClick={handleSaveReport} className="bg-green-600 w-full py-4 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 hover:bg-green-700 transition active:scale-95">
                <Save size={20}/> حفظ وترحيل البيانات
            </button>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, SaleRecord, ProductItem } from '../types';
import { 
    Trash2, Edit, FileSpreadsheet, Save, X, Calculator, 
    TrendingUp, Calendar, Search, Download, Trophy, Star, User as UserIcon
} from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [editingSale, setEditingSale] = useState<SaleRecord | null>(null);
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    useEffect(() => {
        onValue(ref(db, 'sales'), (snapshot) => {
            const data = snapshot.val();
            if (data) {
                let loadedSales: SaleRecord[] = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                if (user.role !== 'admin' && !user.canViewAllSales) {
                    loadedSales = loadedSales.filter(s => s.employeeName === user.name);
                }
                setSales(loadedSales.sort((a, b) => b.timestamp - a.timestamp));
            } else { setSales([]); }
        });
    }, [user]);

    useEffect(() => {
        let result = sales;
        if (filterDate) result = result.filter(s => s.date.includes(filterDate));
        if (filterEmployee) result = result.filter(s => s.employeeName.includes(filterEmployee));
        if (filterMarket) result = result.filter(s => s.market === filterMarket);
        setFilteredSales(result);
    }, [sales, filterDate, filterEmployee, filterMarket]);

    const handleDelete = async (id: string) => {
        if (user.role === 'admin' && window.confirm("هل أنت متأكد من حذف هذا السجل؟")) {
            await remove(ref(db, `sales/${id}`));
        }
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold flex items-center gap-2"><FileSpreadsheet className="text-blue-500" /> سجل المبيعات</h2>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <input type="date" className="p-2.5 rounded-xl text-white" value={filterDate} onChange={e => setFilterDate(e.target.value)} />
                <input type="text" placeholder="بحث بالمشاركين..." className="p-2.5 rounded-xl text-white" value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} />
                <select className="p-2.5 rounded-xl text-white" value={filterMarket} onChange={e => setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {filteredSales.map(sale => (
                    <div key={sale.id} className="p-5 rounded-2xl border border-white/10 bg-gray-600 text-white shadow-lg transition-all">
                        <div className="flex justify-between items-start mb-4 border-b border-white/10 pb-3">
                            <div>
                                <div className="font-bold text-lg text-white mb-0.5">{sale.market}</div>
                                <div className="flex items-center gap-3 text-[10px] opacity-80 text-white font-bold">
                                    <span className="flex items-center gap-1"><Calendar size={10}/> {sale.date}</span>
                                    <span>•</span>
                                    <span className="flex items-center gap-1"><UserIcon size={10}/> {sale.employeeName}</span>
                                </div>
                            </div>
                            {user.role === 'admin' && (
                                <button onClick={() => handleDelete(sale.id!)} className="p-2 text-red-200 hover:bg-red-500/20 rounded-lg transition"><Trash2 size={16} /></button>
                            )}
                        </div>
                        <div className="space-y-1.5">
                            {(sale.items || []).map((item, idx) => (
                                <div key={idx} className="flex justify-between text-xs py-1 border-b border-white/5 last:border-0">
                                    <span className="font-bold">{item.name}</span>
                                    <span className="opacity-80 font-bold">{item.qty} × {item.price} = {item.qty * item.price} ج.م</span>
                                </div>
                            ))}
                        </div>
                        <div className="mt-4 pt-3 border-t border-white/20 flex justify-between items-center">
                            <span className="text-sm font-bold">المجموع الكلي:</span>
                            <span className="text-lg font-black text-white">{sale.total.toLocaleString()} ج.م</span>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

