import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, SaleRecord, ProductItem } from '../types';
import { 
    Trash2, Edit, FileSpreadsheet, Save, X, Calculator, 
    TrendingUp, Calendar, Search, Download, Trophy, Star, User as UserIcon, Clock
} from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [editingSale, setEditingSale] = useState<SaleRecord | null>(null);

    // Filters
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    useEffect(() => {
        const salesRef = ref(db, 'sales');
        onValue(salesRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                let loadedSales: SaleRecord[] = Object.keys(data).map(key => ({
                    id: key,
                    ...data[key]
                }));

                if (user.role !== 'admin' && !user.canViewAllSales) {
                    loadedSales = loadedSales.filter(s => s.employeeName === user.name);
                }

                setSales(loadedSales.sort((a, b) => b.timestamp - a.timestamp));
            } else {
                setSales([]);
            }
        });
    }, [user]);

    useEffect(() => {
        let result = sales;
        if (filterDate) {
            result = result.filter(s => s.date.includes(filterDate) || new Date(s.timestamp).toISOString().slice(0,10) === filterDate);
        }
        if (filterEmployee) {
            result = result.filter(s => s.employeeName.includes(filterEmployee));
        }
        if (filterMarket) {
            result = result.filter(s => s.market === filterMarket);
        }
        setFilteredSales(result);
    }, [sales, filterDate, filterEmployee, filterMarket]);

    const calculateAggregatedStats = (records: SaleRecord[]) => {
        const aggregation: Record<string, { name: string, price: number, qty: number, total: number, employee: string }> = {};

        records.forEach(sale => {
            (sale.items || []).forEach(item => {
                const key = `${item.name}`;
                if (!aggregation[key]) {
                    aggregation[key] = { name: item.name, price: Number(item.price), qty: 0, total: 0, employee: sale.employeeName };
                }
                aggregation[key].qty += Number(item.qty);
                aggregation[key].total += (Number(item.qty) * Number(item.price));
            });
        });

        return Object.values(aggregation);
    };

    const monthlyData = calculateAggregatedStats(sales);
    const topItems = monthlyData.sort((a, b) => b.total - a.total).slice(0, 5);

    const handleDelete = async (id: string) => {
        if (user.role !== 'admin' && user.name !== sales.find(s => s.id === id)?.employeeName) {
            return alert("لا تملك صلاحية الحذف");
        }
        if (window.confirm("هل أنت متأكد من حذف هذا السجل؟")) {
            await remove(ref(db, `sales/${id}`));
        }
    };

    const startEdit = (sale: SaleRecord) => {
        setEditingSale(JSON.parse(JSON.stringify(sale)));
    };

    const saveEdit = async () => {
        if (!editingSale || !editingSale.id) return;
        try {
            await update(ref(db, `sales/${editingSale.id}`), {
                items: editingSale.items,
                total: editingSale.items.reduce((sum, i) => sum + (i.price * i.qty), 0),
                market: editingSale.market 
            });
            setEditingSale(null);
            alert("تم تعديل الفاتورة بنجاح");
        } catch (e) { alert("حدث خطأ"); }
    };

    const updateEditItem = (index: number, field: string, value: any) => {
        if (!editingSale) return;
        const newItems = [...editingSale.items];
        // @ts-ignore
        newItems[index][field] = value;
        setEditingSale({ ...editingSale, items: newItems });
    };

    const inputClass = "border p-2.5 rounded-lg w-full bg-gray-600 text-white focus:ring-2 focus:ring-blue-500 outline-none transition";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold flex items-center gap-2">
                <FileSpreadsheet className="text-blue-500" /> سجل المبيعات
            </h2>

            {/* Top Items Summary */}
            <div className="bg-gray-800 p-5 rounded-2xl border border-white/10">
                <h3 className="text-sm font-bold text-blue-400 mb-4 flex items-center gap-2">
                    <TrendingUp size={16} /> الأصناف الأكثر مبيعاً (شاملة)
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                    {topItems.map((item, idx) => (
                        <div key={idx} className="bg-gray-700 p-4 rounded-xl border border-white/5 flex flex-col gap-1">
                            <div className="font-bold text-white text-xs truncate">{item.name}</div>
                            <div className="flex justify-between items-center text-[10px] opacity-80 text-white">
                                <span>الكمية: {item.qty}</span>
                                <span className="text-green-400 font-bold">{item.total.toLocaleString()} ج.م</span>
                            </div>
                            <div className="text-[9px] opacity-60 text-white italic">أهم بائع: {item.employee}</div>
                        </div>
                    ))}
                </div>
            </div>

            {/* Filters */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3 bg-gray-800 p-4 rounded-2xl">
                <input type="date" className={inputClass} value={filterDate} onChange={e => setFilterDate(e.target.value)} />
                <input type="text" placeholder="بحث بالمشاركين..." className={inputClass} value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} />
                <select className={inputClass} value={filterMarket} onChange={e => setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            {/* Sales Feed */}
            <div className="space-y-4">
                {filteredSales.map(sale => (
                    <div key={sale.id} className="p-5 rounded-2xl border bg-gray-800 border-white/10 text-white shadow-lg">
                        <div className="flex justify-between items-start mb-4">
                            <div className="flex gap-3">
                                <div className="w-10 h-10 rounded-full bg-blue-900/30 flex items-center justify-center text-blue-400">
                                    <UserIcon size={20} />
                                </div>
                                <div>
                                    <div className="font-bold text-lg text-blue-400">{sale.market}</div>
                                    <div className="flex items-center gap-3 text-[10px] opacity-70">
                                        <span className="flex items-center gap-1"><Calendar size={10}/> {sale.date}</span>
                                        <span>بواسطة: {sale.employeeName}</span>
                                    </div>
                                </div>
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => startEdit(sale)} className="p-2 text-indigo-400 hover:bg-indigo-500/20 rounded-lg"><Edit size={16} /></button>
                                <button onClick={() => handleDelete(sale.id!)} className="p-2 text-red-400 hover:bg-red-500/20 rounded-lg"><Trash2 size={16} /></button>
                            </div>
                        </div>

                        <div className="overflow-x-auto bg-black/20 rounded-xl">
                            <table className="w-full text-xs text-center border-collapse">
                                <thead className="bg-gray-700/50 opacity-80 text-white">
                                    <tr>
                                        <th className="py-2 px-3 text-right">الصنف</th>
                                        <th className="py-2 px-2">السعر</th>
                                        <th className="py-2 px-2">الكمية</th>
                                        <th className="py-2 px-3">المجموع</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {(sale.items || []).map((item, idx) => (
                                        <tr key={idx} className="border-b border-white/5 last:border-0">
                                            <td className="py-2 px-3 text-right font-medium">{item.name}</td>
                                            <td className="py-2 px-2">{item.price}</td>
                                            <td className="py-2 px-2 font-bold">{item.qty}</td>
                                            <td className="py-2 px-3 font-black text-green-400">{(item.price * item.qty).toLocaleString()}</td>
                                        </tr>
                                    ))}
                                </tbody>
                                <tfoot className="bg-gray-700/30">
                                    <tr>
                                        <td colSpan={3} className="py-2 px-3 text-left font-bold opacity-70 uppercase tracking-tighter">الإجمالي الكلي للفاتورة:</td>
                                        <td className="py-2 px-3 font-black text-blue-400 text-sm border-r border-white/10">{sale.total.toLocaleString()} ج.م</td>
                                    </tr>
                                </tfoot>
                            </table>
                        </div>
                    </div>
                ))}
            </div>

            {/* Edit Modal */}
            {editingSale && (
                <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[100] p-4 backdrop-blur-md">
                    <div className="w-full max-w-2xl bg-gray-900 border border-white/10 rounded-3xl p-6 overflow-hidden flex flex-col max-h-[90vh]">
                        <div className="flex justify-between items-center mb-6 border-b border-white/10 pb-4">
                            <h3 className="text-xl font-bold flex items-center gap-2 text-blue-400"><Edit /> تعديل فاتورة</h3>
                            <button onClick={() => setEditingSale(null)} className="p-2 hover:bg-white/10 rounded-full"><X/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
                            {editingSale.items.map((item, idx) => (
                                <div key={idx} className="grid grid-cols-12 gap-2 bg-white/5 p-3 rounded-xl border border-white/5 items-center">
                                    <div className="col-span-6 font-bold text-xs truncate">{item.name}</div>
                                    <div className="col-span-3">
                                        <input type="number" value={item.price} onChange={e => updateEditItem(idx, 'price', Number(e.target.value))} className="w-full p-1.5 rounded bg-gray-800 text-white text-center border border-white/10" placeholder="السعر"/>
                                    </div>
                                    <div className="col-span-3">
                                        <input type="number" value={item.qty} onChange={e => updateEditItem(idx, 'qty', Number(e.target.value))} className="w-full p-1.5 rounded bg-gray-800 text-white text-center border border-white/10" placeholder="الكمية"/>
                                    </div>
                                </div>
                            ))}
                        </div>
                        <button onClick={saveEdit} className="mt-6 w-full bg-blue-600 hover:bg-blue-700 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 shadow-xl active:scale-95 transition">
                            <Save /> حفظ التعديلات
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

