import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue } from "firebase/database";
import { User } from '../types';
import { 
    COMPANIES, 
    PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, 
    FINE_FACIAL, FINE_KITCHEN, FINE_TOILET,
    ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET,
    PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET,
    WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET
} from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [items, setItems] = useState<{category: string, name: string, price: number}[]>([]);

    useEffect(() => {
        onValue(ref(db, 'settings/companies'), s => {
            const systemCompanies = COMPANIES.map(name => ({ name, createdBy: 'system' }));
            const dbCompanies = s.exists() ? Object.values(s.val()).map((c: any) => 
                typeof c === 'string' ? { name: c, createdBy: 'system' } : c
            ) : [];
            const allCombined = [...systemCompanies, ...dbCompanies];
            let filtered = user.role === 'admin' ? allCombined : allCombined.filter(c => c.createdBy === 'system' || c.createdBy === user.username);
            setCompanies(Array.from(new Set(filtered.map(c => c.name))));
        });
    }, [user.username, user.role]);

    const getTemplatePath = () => {
        if (!selectedMarket || !selectedCompany || !user.username) return null;
        const safeUser = user.username.replace(/[.#$/[\]]/g, "_");
        const safeMarket = selectedMarket.replace(/[.#$/[\]]/g, "_");
        const safeCompany = selectedCompany.replace(/[.#$/[\]]/g, "_");
        return `competitor_templates/${safeUser}/${safeMarket}/${safeCompany}`;
    };

    const generateDefaultsFromList = (facial: string[], kitchen: string[], toilet: string[]) => {
        const defaultItems: {category: string, name: string, price: number}[] = [];
        facial.forEach(name => defaultItems.push({ category: 'مناديل سحب (Facial)', name, price: 0 }));
        kitchen.forEach(name => defaultItems.push({ category: 'مناديل مطبخ (Kitchen)', name, price: 0 }));
        toilet.forEach(name => defaultItems.push({ category: 'تواليت (Toilet)', name, price: 0 }));
        return defaultItems;
    };

    useEffect(() => {
        const path = getTemplatePath();
        if (path) {
            onValue(ref(db, path), (snapshot) => {
                if (snapshot.exists()) {
                    setItems(snapshot.val());
                } else {
                    if (selectedCompany === 'Soft Rose') setItems(generateDefaultsFromList(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET));
                    else if (selectedCompany === 'Fine') setItems(generateDefaultsFromList(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET));
                    else if (selectedCompany === 'Zeina') setItems(generateDefaultsFromList(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET));
                    else if (selectedCompany === 'Papia Familia') setItems(generateDefaultsFromList(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET));
                    else if (selectedCompany === 'White') setItems(generateDefaultsFromList(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET));
                    else setItems([]);
                }
            });
        }
    }, [selectedMarket, selectedCompany]);

    const updateItem = (index: number, field: string, value: any) => {
        const newItems = [...items];
        // @ts-ignore
        newItems[index][field] = value;
        setItems(newItems);
        const path = getTemplatePath();
        if (path) set(ref(db, path), newItems);
    };

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const validItems = items.filter(i => i.name && i.price > 0);
        await push(ref(db, 'competitor_prices'), {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            employeeName: user.name,
            items: validItems
        });
        alert("تم الحفظ");
        const resetItems = items.map(i => ({...i, price: 0}));
        setItems(resetItems);
        const path = getTemplatePath();
        if (path) set(ref(db, path), resetItems);
    };

    const inputClass = "w-full p-2.5 rounded-xl bg-gray-700 text-white border border-white/10 focus:ring-2 focus:ring-blue-500 outline-none";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-800 p-5 rounded-2xl border border-white/10">
                <div>
                    <label className="block mb-1.5 text-xs font-bold opacity-60">الماركت</label>
                    <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">اختر الماركت</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block mb-1.5 text-xs font-bold opacity-60">الشركة</label>
                    <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                        <option value="">اختر الشركة</option>
                        {companies.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            {['مناديل سحب (Facial)', 'مناديل مطبخ (Kitchen)', 'تواليت (Toilet)'].map(cat => (
                <div key={cat} className="bg-gray-800 p-4 rounded-2xl border border-white/5">
                    <h3 className="font-bold mb-4 text-blue-400 border-b border-white/10 pb-2 flex items-center gap-2">{cat}</h3>
                    <div className="space-y-2">
                        {items.filter(i => i.category === cat).map((item, idx) => {
                            const actualIdx = items.indexOf(item);
                            return (
                                <div key={actualIdx} className="grid grid-cols-12 gap-2 items-center bg-black/20 p-2 rounded-xl">
                                    <div className="col-span-8">
                                        <input 
                                            className="w-full bg-gray-700 text-white border border-white/5 p-2 rounded-lg text-xs font-bold" 
                                            value={item.name} 
                                            onChange={e => updateItem(actualIdx, 'name', e.target.value)} 
                                            placeholder="اسم المنتج" 
                                        />
                                    </div>
                                    <div className="col-span-4">
                                        <input 
                                            type="number" 
                                            className="w-full bg-gray-700 text-white border border-white/5 p-2 rounded-lg text-center text-xs font-black" 
                                            value={item.price || ''} 
                                            onChange={e => updateItem(actualIdx, 'price', e.target.value)} 
                                            placeholder="السعر" 
                                        />
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                </div>
            ))}
            <button onClick={handleSaveReport} className="bg-green-600 w-full py-4 text-white rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 hover:bg-green-700 active:scale-95 transition">
                <Save size={20}/> حفظ وترحيل البيانات
            </button>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, CompetitorPrice } from '../types';
import { exportToCSV } from '../utils';
import { COMPANIES } from '../constants';
import { Trash2, Edit, Save, X, FileSpreadsheet, User as UserIcon, Calendar, Building } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorReports: React.FC<Props> = ({ user, markets, theme }) => {
    const [data, setData] = useState<CompetitorPrice[]>([]);
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [editingReport, setEditingReport] = useState<CompetitorPrice | null>(null);

    useEffect(() => {
        onValue(ref(db, 'settings/companies'), s => {
            if(s.exists()) {
                const rawData = s.val();
                const allCompanies: any[] = Object.keys(rawData).map(key => {
                    const item = rawData[key];
                    return typeof item === 'string' ? { name: item, createdBy: 'system' } : item;
                });
                setCompanies(allCompanies.map(c => c.name));
            } else {
                setCompanies(COMPANIES);
            }
        });

        onValue(ref(db, 'competitor_prices'), s => {
            if(s.exists()) {
                let arr = Object.keys(s.val()).map(key => ({
                    id: key,
                    ...s.val()[key]
                })) as CompetitorPrice[];
                if (user.role !== 'admin' && !user.canViewAllSales) {
                    arr = arr.filter(d => d.employeeName === user.name);
                }
                setData(arr.sort((a, b) => b.date.localeCompare(a.date)));
            } else {
                setData([]);
            }
        });
    }, [user]);

    const filtered = data.filter(d => 
        (!selectedMarket || d.market === selectedMarket) &&
        (!selectedCompany || d.company === selectedCompany)
    );

    const handleUpdate = async () => {
        if(!editingReport || !editingReport.id) return;
        await update(ref(db, `competitor_prices/${editingReport.id}`), { items: editingReport.items });
        setEditingReport(null);
        alert("تم التعديل بنجاح");
    };

    const inputClass = "w-full p-2.5 rounded-xl bg-gray-700 text-white border border-white/10 text-xs";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold flex items-center gap-2">
                <Building className="text-blue-500" /> تقارير أسعار المنافسين
            </h2>

            <div className="bg-gray-800 p-5 rounded-2xl space-y-4 border border-white/10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">كل الماركتات</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                    <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                        <option value="">كل الشركات</option>
                        {companies.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
                <button onClick={() => exportToCSV(filtered.flatMap(d => (d.items || []).map(i => ({ التاريخ: d.date, الماركت: d.market, الشركة: d.company, الصنف: i.name, السعر: i.price }))), 'Competitor_Report')} className="w-full bg-green-600 hover:bg-green-700 text-white py-3 rounded-xl flex items-center justify-center gap-2 font-bold shadow-lg transition active:scale-95">
                    <FileSpreadsheet size={20} /> تصدير التقرير (Excel)
                </button>
            </div>

            <div className="space-y-4">
                {filtered.map((record) => (
                    <div key={record.id} className="p-5 rounded-2xl border bg-gray-800 border-white/10 text-white shadow-lg">
                        <div className="flex justify-between items-start mb-4 border-b border-white/5 pb-3">
                            <div>
                                <h3 className="text-lg font-bold text-blue-400">{record.market}</h3>
                                <div className="flex flex-wrap gap-3 mt-1 text-[10px] opacity-70">
                                    <span className="flex items-center gap-1"><Calendar size={12}/> {record.date}</span>
                                    <span className="flex items-center gap-1"><UserIcon size={12}/> {record.employeeName}</span>
                                    <span className="font-bold text-green-400">{record.company}</span>
                                </div>
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => setEditingReport(record)} className="p-2 text-indigo-400 hover:bg-indigo-500/20 rounded-lg transition"><Edit size={16}/></button>
                                {(user.role === 'admin' || user.name === record.employeeName) && (
                                     <button onClick={() => remove(ref(db, `competitor_prices/${record.id!}`))} className="p-2 text-red-400 hover:bg-red-500/20 rounded-lg transition"><Trash2 size={16}/></button>
                                )}
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
                            {(record.items || []).map((item, idx) => (
                                <div key={idx} className="flex justify-between p-2 px-3 bg-black/30 rounded-xl text-xs border border-white/5">
                                    <span className="opacity-80 truncate pr-2">{item.name}</span>
                                    <span className="font-black text-green-400">{item.price} ج.م</span>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            {editingReport && (
                <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[100] p-4 backdrop-blur-md">
                    <div className="w-full max-w-2xl bg-gray-900 border border-white/10 rounded-3xl p-6 flex flex-col max-h-[85vh]">
                        <div className="flex justify-between items-center mb-6 border-b border-white/10 pb-4">
                            <h3 className="font-bold text-xl text-blue-400">تعديل التقرير</h3>
                            <button onClick={() => setEditingReport(null)} className="p-2 hover:bg-white/10 rounded-full"><X/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                            {editingReport.items.map((item, idx) => (
                                <div key={idx} className="flex gap-2 items-center p-2 bg-white/5 rounded-xl">
                                    <span className="flex-1 text-xs font-bold">{item.name}</span>
                                    <input type="number" value={item.price} onChange={e => {
                                        const n = [...editingReport.items];
                                        n[idx].price = Number(e.target.value);
                                        setEditingReport({...editingReport, items: n});
                                    }} className="w-24 p-1.5 rounded bg-gray-700 text-white text-center border border-white/10 text-xs"/>
                                </div>
                            ))}
                        </div>
                        <button onClick={handleUpdate} className="mt-6 w-full bg-blue-600 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 active:scale-95 transition">
                            <Save size={20}/> حفظ التعديلات
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CompetitorReports;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { 
    Trash2, Edit, CalendarPlus, X, Save, History, 
    ChevronRight, ChevronLeft, Calendar, 
    CheckCircle2, AlertCircle, Clock, Filter
} from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<LeaveBalance[]>([]);
    const [usersList, setUsersList] = useState<{key: string, name: string}[]>([]);
    const [allHistory, setAllHistory] = useState<({id: string} & LeaveRecord)[]>([]);

    // Modal States
    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showEditBalanceModal, setShowEditBalanceModal] = useState(false);
    const [showHistoryDetailsModal, setShowHistoryDetailsModal] = useState(false);

    // Period Control State (21 to 20)
    const [currentPeriodStart, setCurrentPeriodStart] = useState<Date>(() => {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        return now.getDate() >= 21 ? new Date(year, month, 21) : new Date(year, month - 1, 21);
    });

    // Form States
    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams' | 'unpaid'>('annual');
    const [editingBalance, setEditingBalance] = useState<LeaveBalance | null>(null);
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);

    // Load Data
    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: any[] = [];
                snapshot.forEach(c => { u.push({ key: c.key, name: c.val().name }); });
                setUsersList(u);
            }
        });

        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const b: LeaveBalance[] = Object.values(snapshot.val());
                setBalances(user.role === 'admin' ? b : b.filter(x => x.employeeName === user.name));
            } else { setBalances([]); }
        });

        onValue(ref(db, 'leave_history'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                const h: any = Object.keys(data).map(key => ({
                    id: key,
                    ...data[key]
                }));
                setAllHistory(h);
            } else { setAllHistory([]); }
        });
    }, [user]);

    // Period Logic
    const getPeriodEnd = (start: Date) => {
        const end = new Date(start);
        end.setMonth(end.getMonth() + 1);
        end.setDate(20);
        return end;
    };

    const changePeriod = (direction: number) => {
        const newStart = new Date(currentPeriodStart);
        newStart.setMonth(newStart.getMonth() + direction);
        setCurrentPeriodStart(newStart);
    };

    const filterHistoryByPeriodAndUser = (userId: string) => {
        const pStart = new Date(currentPeriodStart);
        pStart.setHours(0,0,0,0);
        const pEnd = getPeriodEnd(currentPeriodStart);
        pEnd.setHours(23,59,59,999);

        return allHistory.filter((record) => {
            const recordDate = new Date(record.date);
            return record.userId === userId && recordDate >= pStart && recordDate <= pEnd;
        });
    };

    const getUnpaidForPeriod = (userId: string) => {
        return filterHistoryByPeriodAndUser(userId)
            .filter(r => r.type === 'unpaid')
            .reduce((sum, r) => sum + r.days, 0);
    };

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate || leaveDays <= 0) return alert("يرجى اكمال البيانات");
        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;

        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        let currentBalance: LeaveBalance = balances.find(b => b.userId === selectedUser) || {
            userId: selectedUser, employeeName: targetUser.name,
            annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0
        };

        const newBalance = { ...currentBalance, [leaveType]: Number(currentBalance[leaveType] || 0) - (leaveType === 'unpaid' ? 0 : Number(leaveDays)) };
        await set(balanceRef, newBalance);

        await push(ref(db, 'leave_history'), {
            userId: selectedUser, employeeName: targetUser.name,
            date: leaveDate, days: Number(leaveDays), type: leaveType, timestamp: Date.now()
        });

        alert("تم تسجيل الاجازة بنجاح");
        setShowAddLeaveModal(false);
    };

    const handleDeleteRecord = async (id: string, record: LeaveRecord) => {
        if(!confirm("هل أنت متأكد من حذف هذا السجل؟")) return;

        // إعادة الرصيد إذا لم يكن غياب بإذن
        if(record.type !== 'unpaid') {
            const balanceRef = ref(db, `leave_balances/${record.userId}`);
            const balanceSnap = await get(balanceRef);
            if(balanceSnap.exists()) {
                const bal = balanceSnap.val();
                await update(balanceRef, { [record.type]: (Number(bal[record.type]) || 0) + Number(record.days) });
            }
        }

        await remove(ref(db, `leave_history/${id}`));
        alert("تم الحذف وإعادة الرصيد");
    };

    const handleEditBalance = async () => {
        if (!editingBalance) return;
        await set(ref(db, `leave_balances/${editingBalance.userId}`), editingBalance);
        setShowEditBalanceModal(false);
        setEditingBalance(null);
    };

    const openHistory = (userId: string, name: string) => {
        setHistoryUserView({ userId, name });
        setShowHistoryDetailsModal(true);
    };

    const inputClass = "border p-2.5 rounded-xl bg-gray-700 text-white border-white/10 w-full outline-none focus:ring-2 focus:ring-blue-500";
    const modalClass = `fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200`;
    const modalContentClass = `w-full max-w-2xl p-6 rounded-3xl shadow-2xl border border-white/10 bg-gray-900 text-white flex flex-col max-h-[90vh]`;

    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات', unpaid: 'غياب بإذن' };
    const typeColors = { 
        annual: 'bg-green-100 text-green-700 dark:bg-green-900/40 dark:text-green-300',
        casual: 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/40 dark:text-yellow-300',
        sick: 'bg-red-100 text-red-700 dark:bg-red-900/40 dark:text-red-300',
        exams: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300',
        unpaid: 'bg-orange-100 text-orange-700 dark:bg-orange-900/40 dark:text-orange-300'
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <h2 className="text-2xl font-bold flex items-center gap-2">
                    <History className="text-blue-500" /> رصيد الإجازات
                </h2>
                <button 
                    onClick={() => setShowAddLeaveModal(true)}
                    className="bg-red-600 hover:bg-red-700 text-white px-8 py-3 rounded-2xl font-bold shadow-xl flex items-center gap-2 transition transform active:scale-95"
                >
                    <CalendarPlus size={20} /> تسجيل إجازة
                </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {balances.map((balance) => (
                    <div key={balance.userId} className="p-5 rounded-3xl border bg-gray-800 border-white/10 text-white shadow-lg hover:border-blue-500/30 transition-all">
                        <div className="flex justify-between items-start mb-4">
                            <div className="font-bold text-lg text-blue-400 truncate">{balance.employeeName}</div>
                            {user.role === 'admin' && (
                                <button onClick={() => { setEditingBalance(balance); setShowEditBalanceModal(true); }} className="p-2 text-indigo-400 hover:bg-white/5 rounded-xl"><Edit size={16} /></button>
                            )}
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                            {Object.entries(typeLabels).map(([key, label]) => (
                                <button 
                                    key={key}
                                    onClick={() => openHistory(balance.userId, balance.employeeName)}
                                    className={`p-3 rounded-2xl flex flex-col items-center transition-transform active:scale-95 ${typeColors[key as keyof typeof typeColors]}`}
                                >
                                    <span className="text-[10px] opacity-70 uppercase font-black text-center">{label}</span>
                                    <span className="text-xl font-black">
                                        {key === 'unpaid' ? getUnpaidForPeriod(balance.userId) : (balance as any)[key] || 0}
                                    </span>
                                </button>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            {/* Modal: History */}
            {showHistoryDetailsModal && historyUserView && (
                <div className={modalClass}>
                    <div className={modalContentClass}>
                        <div className="flex justify-between items-center mb-6 border-b border-white/10 pb-4">
                            <h3 className="text-xl font-bold text-blue-400 flex items-center gap-2">
                                <History size={24} /> سجل: {historyUserView.name}
                            </h3>
                            <button onClick={() => setShowHistoryDetailsModal(false)} className="p-2 hover:bg-white/10 rounded-full"><X/></button>
                        </div>

                        <div className="bg-blue-600 text-white p-4 rounded-2xl mb-6 flex justify-between items-center shadow-lg">
                            <button onClick={() => changePeriod(-1)} className="p-2 hover:bg-white/20 rounded-xl"><ChevronRight size={20}/></button>
                            <div className="text-center">
                                <div className="text-[10px] opacity-80 font-bold uppercase tracking-widest">الدورة الحالية</div>
                                <div className="font-bold text-xs">{currentPeriodStart.toLocaleDateString('ar-EG')} - {getPeriodEnd(currentPeriodStart).toLocaleDateString('ar-EG')}</div>
                            </div>
                            <button onClick={() => changePeriod(1)} className="p-2 hover:bg-white/20 rounded-xl"><ChevronLeft size={20}/></button>
                        </div>

                        <div className="flex-1 overflow-y-auto custom-scrollbar space-y-3 pr-1">
                            {filterHistoryByPeriodAndUser(historyUserView.userId).map((rec) => (
                                <div key={rec.id} className="p-4 rounded-2xl border bg-black/20 border-white/5 flex justify-between items-center">
                                    <div className="flex items-center gap-4">
                                        <div className={`p-2.5 rounded-xl ${typeColors[rec.type as keyof typeof typeColors]}`}><CheckCircle2 size={18} /></div>
                                        <div>
                                            <div className="font-bold text-sm">{typeLabels[rec.type as keyof typeof typeLabels]}</div>
                                            <div className="text-[10px] opacity-60">{rec.date}</div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        <div className="text-right pr-4 border-r border-white/10">
                                            <div className="font-black text-lg">{rec.days}</div>
                                            <div className="text-[8px] opacity-50 uppercase tracking-tighter">أيام</div>
                                        </div>
                                        {user.role === 'admin' && (
                                            <button onClick={() => handleDeleteRecord(rec.id, rec)} className="p-2 text-red-400 hover:bg-red-500/20 rounded-lg transition">
                                                <Trash2 size={16}/>
                                            </button>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {/* Modal: Edit Balance */}
            {showEditBalanceModal && editingBalance && (
                <div className={modalClass}>
                    <div className={modalContentClass}>
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="font-bold text-xl text-blue-400">تعديل أرصدة: {editingBalance.employeeName}</h3>
                            <button onClick={() => setShowEditBalanceModal(false)}><X/></button>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                            {Object.entries(typeLabels).map(([key, label]) => (
                                <div key={key}>
                                    <label className="block text-xs font-bold opacity-60 mb-1">{label}</label>
                                    <input type="number" className={inputClass} value={(editingBalance as any)[key]} onChange={e => setEditingBalance({...editingBalance, [key]: Number(e.target.value)})} />
                                </div>
                            ))}
                        </div>
                        <button onClick={handleEditBalance} className="mt-6 w-full bg-blue-600 text-white py-4 rounded-2xl font-bold active:scale-95 transition">حفظ التعديلات</button>
                    </div>
                </div>
            )}

            {/* Modal: Add Leave */}
            {showAddLeaveModal && (
                <div className={modalClass}>
                    <div className={modalContentClass}>
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold flex items-center gap-2"><CalendarPlus /> تسجيل إجازة</h3>
                            <button onClick={() => setShowAddLeaveModal(false)}><X/></button>
                        </div>
                        <div className="space-y-4">
                            <select className={inputClass} value={selectedUser} onChange={e => setSelectedUser(e.target.value)}>
                                <option value="">-- اختر الموظف --</option>
                                {usersList.filter(u => user.role === 'admin' || u.name === user.name).map(u => <option key={u.key} value={u.key}>{u.name}</option>)}
                            </select>
                            <input type="date" className={inputClass} value={leaveDate} onChange={e => setLeaveDate(e.target.value)} />
                            <div className="grid grid-cols-2 gap-4">
                                <input type="number" min="0.5" step="0.5" className={inputClass} value={leaveDays} onChange={e => setLeaveDays(parseFloat(e.target.value))} placeholder="الأيام" />
                                <select className={inputClass} value={leaveType} onChange={e => setLeaveType(e.target.value as any)}>
                                    {Object.entries(typeLabels).map(([k,v]) => <option key={k} value={k}>{v}</option>)}
                                </select>
                            </div>
                            <button onClick={handleAddLeave} className="w-full bg-red-600 text-white font-bold py-4 rounded-2xl shadow-xl transition active:scale-95">تسجيل الإجازة</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

