import React, { useState, useEffect } from 'react';
import { ref, push, set, onValue } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Plus, Trash2, Save } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [globalProducts, setGlobalProducts] = useState<ProductItem[]>([]);
    const [notification, setNotification] = useState('');

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
    ];

    useEffect(() => {
        onValue(ref(db, 'settings/global_products'), (snapshot) => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                setGlobalProducts(Object.keys(data).map(k => ({ id: k, ...data[k] })));
            } else {
                setGlobalProducts([]);
            }
        });
    }, []);

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        allCategories.forEach(cat => {
            cat.items.forEach(itemName => {
                initialItems.push({
                    id: itemName + "_base",
                    category: cat.key,
                    name: itemName,
                    price: 0,
                    qty: 0,
                    isCustom: false
                });
            });
            globalProducts.filter(gp => gp.category === cat.key).forEach(gp => {
                initialItems.push({ ...gp, price: 0, qty: 0 });
            });
        });
        setSalesItems(initialItems);
    }, [globalProducts]);

    const updateItem = (id: string, field: keyof ProductItem, value: any) => {
        setSalesItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("الرجاء اختيار الماركت");
        const soldItems = salesItems.filter(item => (item.name && Number(item.price) > 0 && Number(item.qty) > 0));
        if (soldItems.length === 0) return alert("لا يوجد مبيعات مكتملة للحفظ");

        const saleData = {
            market: selectedMarket,
            employeeName: user.name,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: soldItems,
            total: soldItems.reduce((sum, item) => sum + (item.price * item.qty), 0)
        };

        await push(ref(db, 'sales'), saleData);
        setNotification('تم حفظ المبيعات بنجاح!');
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
        setTimeout(() => setNotification(''), 3000);
    };

    const inputClass = "bg-gray-700 border border-white/10 p-2 rounded-xl w-full text-white placeholder-gray-400 text-xs text-center font-bold";

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row justify-between items-center mb-6 gap-4">
                <h2 className="text-2xl font-bold">المبيعات اليومية</h2>
                <div className="text-xl font-black bg-blue-600 text-white px-6 py-3 rounded-2xl shadow-2xl w-full md:w-auto text-center border border-white/20">
                    الإجمالي: {salesItems.reduce((sum, item) => sum + (item.price * item.qty), 0).toLocaleString()} ج.م
                </div>
            </div>

            <div className="flex items-end gap-2 bg-gray-800 p-4 rounded-2xl border border-white/10">
                <div className="flex-1">
                    <label className="block mb-1 text-xs font-bold opacity-60">الماركت المستهدف</label>
                    <select value={selectedMarket} onChange={(e) => setSelectedMarket(e.target.value)} className="w-full bg-gray-700 border border-white/10 p-3 rounded-xl text-white outline-none">
                        <option value="">اختر الماركت...</option>
                        {markets.map((m, idx) => <option key={idx} value={m}>{m}</option>)}
                    </select>
                </div>
            </div>

            {allCategories.map(cat => (
                <div key={cat.key} className="bg-gray-800 p-4 rounded-3xl border border-white/5 shadow-lg">
                    <h3 className="text-lg font-bold text-blue-400 mb-4 border-b border-white/5 pb-2">{cat.name}</h3>

                    <div className="grid grid-cols-12 gap-2 mb-2 px-2 text-[10px] font-black opacity-50 uppercase tracking-widest text-white">
                        <div className="col-span-5 pr-2">الصنف</div>
                        <div className="col-span-2 text-center">السعر</div>
                        <div className="col-span-2 text-center">الكمية</div>
                        <div className="col-span-3 text-center">المجموع</div>
                    </div>

                    <div className="space-y-1.5">
                        {salesItems.filter(item => item.category === cat.key).map((item) => (
                            <div key={item.id} className="grid grid-cols-12 gap-2 items-center bg-black/20 p-2 rounded-2xl hover:bg-white/5 transition border border-transparent hover:border-white/10">
                                <div className="col-span-5 text-[11px] pr-2 font-bold text-white truncate">
                                    {item.name}
                                </div>
                                <div className="col-span-2">
                                    <input type="number" value={item.price || ''} onChange={(e) => updateItem(item.id, 'price', parseFloat(e.target.value))} className={inputClass} placeholder="0" />
                                </div>
                                <div className="col-span-2">
                                    <input type="number" value={item.qty || ''} onChange={(e) => updateItem(item.id, 'qty', parseFloat(e.target.value))} className={inputClass} placeholder="0" />
                                </div>
                                <div className="col-span-3 text-center font-black text-xs text-green-400">
                                    {((item.price || 0) * (item.qty || 0)).toLocaleString()}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            <div className="mt-8 flex justify-center sticky bottom-4 z-10">
                <button onClick={handleSave} className="bg-green-600 hover:bg-green-700 text-white font-black py-4 px-12 rounded-3xl shadow-2xl flex items-center gap-3 text-lg transform hover:scale-105 active:scale-95 transition w-full md:w-auto justify-center border-t border-white/20">
                    <Save size={24} /> حفظ وترحيل المبيعات
                </button>
            </div>

            {notification && <div className="fixed bottom-24 left-1/2 -translate-x-1/2 bg-green-600 text-white px-8 py-4 rounded-3xl shadow-2xl font-bold z-[100] animate-bounce">{notification}</div>}
        </div>
    );
};

export default DailySales;

import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set, update, onDisconnect, serverTimestamp, remove } from "firebase/database";
import { User, AppSettings, AppNotification } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import AISearch from './components/AISearch';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen, Check, Trash2, Clock, Copy, ExternalLink } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, 
    showInventoryReg: false, 
    showCompetitorReports: false,
    showDailySales: true,
    showCompetitorPrices: true
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'dark'>('dark');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [showThemeSelector, setShowThemeSelector] = useState(false);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [selectedNotif, setSelectedNotif] = useState<AppNotification | null>(null);

  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    onValue(settingsRef, (snapshot) => {
      if (snapshot.exists()) setSettings({...DEFAULT_SETTINGS, ...snapshot.val()});
    });

    onValue(marketsRef, (snapshot) => {
      const systemMarkets = INITIAL_MARKETS.map(name => ({ name, createdBy: 'system' }));
      const dbMarkets = snapshot.exists() ? Object.values(snapshot.val()).map((m: any) => 
        typeof m === 'string' ? { name: m, createdBy: 'system' } : m
      ) : [];
      const allCombined = [...systemMarkets, ...dbMarkets];

      if (user) {
        let filtered;
        if (user.role === 'admin') {
          filtered = allCombined;
        } else {
          filtered = allCombined.filter(m => m.createdBy === 'system' || m.createdBy === user.username);
        }
        const uniqueNames = Array.from(new Set(filtered.map(m => m.name)));
        setMarkets(uniqueNames);
      }
    }, { onlyOnce: false });

    onValue(connectedRef, (snap) => setIsConnected(!!snap.val()));
  }, [user?.username, user?.role]);

  useEffect(() => {
    if (!user || !user.key || user.key === 'admin_root') return;

    const userRef = ref(db, `users/${user.key}`);
    const unsubscribe = onValue(userRef, (snapshot) => {
      if (snapshot.exists()) {
        const updatedData = { ...snapshot.val(), key: user.key };
        setUser(updatedData);
        localStorage.setItem('soft_rose_user', JSON.stringify(updatedData));
      }
    });

    return () => unsubscribe();
  }, [user?.key]);

  useEffect(() => {
    if (!user) return;
    const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
    const userStatusRef = ref(db, `status/${safeKey}`);
    set(userStatusRef, { online: true, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    onDisconnect(userStatusRef).set({ online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });

    onValue(ref(db, `notifications/${user.username}`), (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list = Object.keys(data).map(key => ({ id: key, ...data[key] })).sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        } else {
            setNotifications([]);
            setUnreadCount(0);
        }
    });
  }, [user?.username]);

  const handleLogout = async () => {
    if (user) {
        const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `status/${safeKey}`), { online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    }
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  const markAsRead = (id: string) => {
    if (!user) return;
    update(ref(db, `notifications/${user.username}/${id}`), { isRead: true });
  };

  const deleteNotif = (id: string) => {
    if (!user) return;
    remove(ref(db, `notifications/${user.username}/${id}`));
  };

  if (!user) return <Login onLogin={setUser} theme={theme} />;

  const mainContentBg = () => 'bg-gray-900/60 border border-white/5 backdrop-blur-md';

  return (
    <div className="bg-black text-white min-h-screen flex flex-col overflow-hidden">
      {settings.tickerEnabled && (
        <div className="bg-black/90 text-yellow-400 py-1.5 overflow-hidden whitespace-nowrap border-b border-white/10 z-50">
           <div className="animate-marquee inline-block px-4 font-bold">{settings.tickerText}</div>
        </div>
      )}

      <header className="p-4 flex justify-between items-center z-50 bg-black/80 backdrop-blur-md border-b border-white/10 text-white shadow-lg">
        <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="md:hidden p-2 rounded-lg hover:bg-white/10">
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="text-lg md:text-2xl font-bold truncate">
                {settings.appName}
            </h1>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
            <div className="relative">
                <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className="relative p-2 rounded-full hover:bg-white/10">
                    <Bell size={20} />
                    {unreadCount > 0 && <span className="absolute top-1 right-1 bg-red-600 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full">{unreadCount}</span>}
                </button>
                {showNotifDropdown && (
                    <div className="absolute left-0 mt-2 w-72 md:w-80 bg-gray-900 text-white rounded-2xl shadow-2xl border border-white/10 overflow-hidden z-[60]">
                        <div className="p-4 bg-black border-b border-white/10 flex justify-between items-center">
                            <h3 className="font-bold text-sm">الإشعارات</h3>
                        </div>
                        <div className="max-h-80 overflow-y-auto custom-scrollbar">
                            {notifications.length === 0 ? (
                                <div className="p-10 text-center opacity-30 italic text-sm">لا توجد إشعارات</div>
                            ) : (
                                notifications.map(n => (
                                    <div 
                                      key={n.id} 
                                      onClick={() => { setSelectedNotif(n); markAsRead(n.id!); setShowNotifDropdown(false); }}
                                      className={`p-4 border-b border-white/5 last:border-0 hover:bg-white/5 cursor-pointer ${!n.isRead ? 'bg-blue-600/10' : ''}`}
                                    >
                                        <div className="text-xs font-bold mb-0.5">{n.sender}</div>
                                        <div className="text-[11px] opacity-70 line-clamp-2">{n.message}</div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                )}
            </div>

            <button onClick={handleLogout} className="text-red-500 p-2 rounded-full hover:bg-red-500/10">
                <LogOut size={20} />
            </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <div className={`fixed md:relative top-0 bottom-0 right-0 z-50 h-full transition-transform duration-300 md:transform-none ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
            <Sidebar 
                currentView={currentView} 
                setView={(view) => { setCurrentView(view); setIsSidebarOpen(false); }} 
                user={user} 
                theme={theme} 
                settings={settings} 
                containerClass="bg-black/60 backdrop-blur-2xl border-l border-white/10 h-full shadow-2xl" 
            />
        </div>

        <main className="flex-1 p-2 md:p-4 overflow-y-auto w-full">
            <div className={`p-4 md:p-6 min-h-full rounded-2xl shadow-xl ${mainContentBg()}`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorPrices' && <CompetitorPrices user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorReports' && <CompetitorReports user={user} markets={markets} theme={theme} />}
                {currentView === 'leaveBalance' && <LeaveBalanceComponent user={user} theme={theme} />}
                {currentView === 'settings' && <Settings user={user} settings={settings} markets={markets} theme={theme} setTheme={setTheme as any} />}
            </div>
        </main>
      </div>

      <AISearch user={user} theme={theme} />
      <footer className="py-2 px-4 text-center text-[10px] font-bold opacity-50 text-white border-t border-white/5">
          مع تحيات المطور Amir Lamay
      </footer>
    </div>
  );
};

export default App;

