import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, SaleRecord, ProductItem } from '../types';
import { 
    Trash2, Edit, FileSpreadsheet, Save, X, Calendar, User as UserIcon
} from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    useEffect(() => {
        const salesRef = ref(db, 'sales');
        onValue(salesRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                let loadedSales: SaleRecord[] = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                if (user.role !== 'admin' && !user.canViewAllSales) {
                    loadedSales = loadedSales.filter(s => s.employeeName === user.name);
                }
                setSales(loadedSales.sort((a, b) => b.timestamp - a.timestamp));
            } else { setSales([]); }
        });
    }, [user]);

    useEffect(() => {
        let result = sales;
        if (filterDate) result = result.filter(s => s.date.includes(filterDate));
        if (filterEmployee) result = result.filter(s => s.employeeName.includes(filterEmployee));
        if (filterMarket) result = result.filter(s => s.market === filterMarket);
        setFilteredSales(result);
    }, [sales, filterDate, filterEmployee, filterMarket]);

    const handleDelete = async (id: string) => {
        if (user.role === 'admin' && window.confirm("هل أنت متأكد من الحذف؟")) {
            await remove(ref(db, `sales/${id}`));
        }
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold flex items-center gap-2"><FileSpreadsheet /> سجل المبيعات</h2>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <input type="date" className="p-2.5 rounded-xl" value={filterDate} onChange={e => setFilterDate(e.target.value)} />
                <input type="text" placeholder="الموظف..." className="p-2.5 rounded-xl" value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} />
                <select className="p-2.5 rounded-xl" value={filterMarket} onChange={e => setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {filteredSales.map(sale => (
                    <div key={sale.id} className="p-5 rounded-2xl border border-white/10 bg-white/5 shadow-lg">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <div className="font-bold text-lg text-blue-400">{sale.market}</div>
                                <div className="text-[10px] opacity-60">
                                    {sale.date} • {sale.employeeName}
                                </div>
                            </div>
                            {user.role === 'admin' && (
                                <button onClick={() => handleDelete(sale.id!)} className="text-red-500 p-2 hover:bg-red-500/10 rounded-lg"><Trash2 size={16} /></button>
                            )}
                        </div>
                        <div className="space-y-2">
                            {(sale.items || []).map((item, idx) => (
                                <div key={idx} className="flex justify-between text-xs py-1 border-b border-white/5 last:border-0">
                                    <span>{item.name}</span>
                                    <span>{item.qty} × {item.price} = {item.qty * item.price} ج.م</span>
                                </div>
                            ))}
                        </div>
                        <div className="mt-4 pt-3 border-t border-white/10 flex justify-between font-bold">
                            <span>المجموع:</span>
                            <span className="text-blue-400">{sale.total.toLocaleString()} ج.م</span>
                        </div>
                    </div>
                ))}
