import React, { useState, useEffect } from 'react';
import { ref, push, onValue } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        [PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN].forEach((list, idx) => {
            const cat = ['Facial', 'Kitchen', 'Toilet', 'Dolphin'][idx];
            list.forEach(name => {
                initialItems.push({ id: name + Date.now(), name, price: 0, qty: 0, category: cat });
            });
        });
        setSalesItems(initialItems);
    }, []);

    const updateItem = (id: string, field: string, value: any) => {
        setSalesItems(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const sold = salesItems.filter(i => i.qty > 0 && i.price > 0);
        if (!sold.length) return alert("أدخل بيانات صحيحة");

        await push(ref(db, 'sales'), {
            market: selectedMarket,
            employeeName: user.name,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: sold,
            total: sold.reduce((sum, i) => sum + (i.price * i.qty), 0)
        });
        alert("تم الحفظ");
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold">المبيعات اليومية</h2>
            <select className="w-full p-3 rounded-xl" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                <option value="">اختر الماركت...</option>
                {markets.map(m => <option key={m} value={m}>{m}</option>)}
            </select>

            {['Facial', 'Kitchen', 'Toilet', 'Dolphin'].map(cat => (
                <div key={cat} className="bg-white/5 p-4 rounded-2xl border border-white/5">
                    <h3 className="font-bold text-blue-400 mb-4">{cat}</h3>
                    <div className="space-y-3">
                        {salesItems.filter(i => i.category === cat).map(item => (
                            <div key={item.id} className="flex gap-2 items-center">
                                <span className="flex-1 text-sm">{item.name}</span>
                                <input type="number" placeholder="سعر" className="w-20 p-2 rounded-lg text-center" value={item.price || ''} onChange={e => updateItem(item.id, 'price', parseFloat(e.target.value))} />
                                <input type="number" placeholder="كمية" className="w-20 p-2 rounded-lg text-center" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} />
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <button onClick={handleSave} className="w-full bg-green-600 py-4 rounded-2xl font-bold flex justify-center items-center gap-2">
                <Save /> حفظ المبيعات
            </button>
        </div>
    );
};

