import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { 
    Trash2, Edit, CalendarPlus, X, Save, History, 
    ChevronRight, ChevronLeft, CheckCircle2
} from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<LeaveBalance[]>([]);
    const [usersList, setUsersList] = useState<{key: string, name: string}[]>([]);
    const [allHistory, setAllHistory] = useState<({id: string} & LeaveRecord)[]>([]);

    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showEditBalanceModal, setShowEditBalanceModal] = useState(false);
    const [showHistoryDetailsModal, setShowHistoryDetailsModal] = useState(false);

    const [currentPeriodStart, setCurrentPeriodStart] = useState<Date>(() => {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        return now.getDate() >= 21 ? new Date(year, month, 21) : new Date(year, month - 1, 21);
    });

    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams' | 'unpaid'>('annual');
    const [editingBalance, setEditingBalance] = useState<LeaveBalance | null>(null);
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);

    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: any[] = [];
                snapshot.forEach(c => { u.push({ key: c.key, name: c.val().name }); });
                setUsersList(u);
            }
        });
        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const b: LeaveBalance[] = Object.values(snapshot.val());
                setBalances(user.role === 'admin' ? b : b.filter(x => x.employeeName === user.name));
            } else { setBalances([]); }
        });
        onValue(ref(db, 'leave_history'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                const h: any = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                setAllHistory(h);
            } else { setAllHistory([]); }
        });
    }, [user]);

    const getPeriodEnd = (start: Date) => {
        const end = new Date(start);
        end.setMonth(end.getMonth() + 1);
        end.setDate(20);
        return end;
    };

    const changePeriod = (direction: number) => {
        const newStart = new Date(currentPeriodStart);
        newStart.setMonth(newStart.getMonth() + direction);
        setCurrentPeriodStart(newStart);
    };

    const filterHistoryByPeriodAndUser = (userId: string) => {
        const pStart = new Date(currentPeriodStart);
        pStart.setHours(0,0,0,0);
        const pEnd = getPeriodEnd(currentPeriodStart);
        pEnd.setHours(23,59,59,999);
        return allHistory.filter(r => r.userId === userId && new Date(r.date) >= pStart && new Date(r.date) <= pEnd);
    };

    const handleDeleteRecord = async (id: string, record: LeaveRecord) => {
        if(!confirm("حذف السجل وإعادة الرصيد؟")) return;
        if(record.type !== 'unpaid') {
            const balanceRef = ref(db, `leave_balances/${record.userId}`);
            const balanceSnap = await get(balanceRef);
            if(balanceSnap.exists()) {
                const bal = balanceSnap.val();
                await update(balanceRef, { [record.type]: (Number(bal[record.type]) || 0) + Number(record.days) });
            }
        }
        await remove(ref(db, `leave_history/${id}`));
    };

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate) return alert("اكمل البيانات");
        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;
        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        const snap = await get(balanceRef);
        let cur = snap.exists() ? snap.val() : { userId: selectedUser, employeeName: targetUser.name, annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };
        const newVal = { ...cur, [leaveType]: Number(cur[leaveType] || 0) - (leaveType === 'unpaid' ? 0 : Number(leaveDays)) };
        await set(balanceRef, newVal);
        await push(ref(db, 'leave_history'), { userId: selectedUser, employeeName: targetUser.name, date: leaveDate, days: Number(leaveDays), type: leaveType, timestamp: Date.now() });
        setShowAddLeaveModal(false);
    };

    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات', unpaid: 'غياب بإذن' };
    const typeColors = { annual: 'text-green-400', casual: 'text-yellow-400', sick: 'text-red-400', exams: 'text-purple-400', unpaid: 'text-orange-400' };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2"><History className="text-blue-500" /> رصيد الإجازات</h2>
                <button onClick={() => setShowAddLeaveModal(true)} className="bg-red-600 text-white px-6 py-3 rounded-2xl font-bold shadow-xl flex items-center gap-2"><CalendarPlus size={20} /> تسجيل إجازة</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {balances.map(balance => (
                    <div key={balance.userId} className="p-5 rounded-3xl border bg-gray-800 border-white/10 text-white shadow-xl">
                        <div className="flex justify-between items-start mb-4">
                            <div className="font-bold text-lg text-blue-400">{balance.employeeName}</div>
                            {user.role === 'admin' && (
                                <button onClick={() => { setEditingBalance(balance); setShowEditBalanceModal(true); }} className="p-2 text-indigo-400 hover:bg-white/5 rounded-xl transition"><Edit size={16}/></button>
                            )}
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                            {Object.entries(typeLabels).map(([key, label]) => (
                                <button key={key} onClick={() => { setHistoryUserView({userId: balance.userId, name: balance.employeeName}); setShowHistoryDetailsModal(true); }} className="p-3 bg-black/20 rounded-2xl border border-white/5 flex flex-col items-center">
                                    <span className="text-[10px] opacity-50 font-black uppercase">{label}</span>
                                    <span className={`text-xl font-black ${typeColors[key as keyof typeof typeColors]}`}>{(balance as any)[key] || 0}</span>
                                </button>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            {/* مودال التاريخ مع زر الحذف */}
            {showHistoryDetailsModal && historyUserView && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
                    <div className="w-full max-w-2xl p-6 rounded-3xl border border-white/10 bg-gray-900 text-white flex flex-col max-h-[90vh]">
                        <div className="flex justify-between items-center mb-6 border-b border-white/10 pb-4">
                            <h3 className="text-xl font-bold text-blue-400 flex items-center gap-2">سجل: {historyUserView.name}</h3>
                            <button onClick={() => setShowHistoryDetailsModal(false)} className="p-2 hover:bg-white/10 rounded-full"><X/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-3 pr-1 custom-scrollbar">
                            {filterHistoryByPeriodAndUser(historyUserView.userId).map(rec => (
                                <div key={rec.id} className="p-4 rounded-2xl border bg-black/20 border-white/5 flex justify-between items-center">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-xl bg-white/5 ${typeColors[rec.type]}`}><CheckCircle2 size={18} /></div>
                                        <div>
                                            <div className="font-bold text-sm">{typeLabels[rec.type]}</div>
                                            <div className="text-[10px] opacity-50">{rec.date}</div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        <div className="font-black text-lg">{rec.days} يوم</div>
                                        {user.role === 'admin' && (
                                            <button onClick={() => handleDeleteRecord(rec.id, rec)} className="p-2 text-red-400 hover:bg-red-500/20 rounded-lg transition"><Trash2 size={16}/></button>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default LeaveBalanceComponent;

