import React, { useState, useEffect } from 'react';
import { db } from './firebase';
import { ref, onValue, set, update, onDisconnect, serverTimestamp, remove } from "firebase/database";
import { User, AppSettings, AppNotification } from './types';
import Login from './components/Login';
import Sidebar from './components/Sidebar';
import DailySales from './components/DailySales';
import SalesLog from './components/SalesLog';
import InventoryRegistration from './components/InventoryRegistration';
import InventoryLog from './components/InventoryLog';
import CompetitorPrices from './components/CompetitorPrices';
import CompetitorReports from './components/CompetitorReports';
import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import AISearch from './components/AISearch';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen, Check, Trash2, Clock, Copy, ExternalLink, Sparkles } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, 
    showInventoryReg: false, 
    showCompetitorReports: false,
    showDailySales: true,
    showCompetitorPrices: true
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'dark'>('dark');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [welcomeToast, setWelcomeToast] = useState<string | null>(null);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [selectedNotif, setSelectedNotif] = useState<AppNotification | null>(null);

  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    onValue(settingsRef, (snapshot) => {
      if (snapshot.exists()) setSettings({...DEFAULT_SETTINGS, ...snapshot.val()});
    });

    onValue(marketsRef, (snapshot) => {
      const systemMarkets = INITIAL_MARKETS.map(name => ({ name, createdBy: 'system' }));
      const dbMarkets = snapshot.exists() ? Object.values(snapshot.val()).map((m: any) => 
        typeof m === 'string' ? { name: m, createdBy: 'system' } : m
      ) : [];
      const allCombined = [...systemMarkets, ...dbMarkets];

      if (user) {
        let filtered;
        if (user.role === 'admin') {
          filtered = allCombined;
        } else {
          filtered = allCombined.filter(m => m.createdBy === 'system' || m.createdBy === user.username);
        }
        const uniqueNames = Array.from(new Set(filtered.map(m => m.name)));
        setMarkets(uniqueNames);
      }
    }, { onlyOnce: false });

    onValue(connectedRef, (snap) => setIsConnected(!!snap.val()));
  }, [user?.username, user?.role]);

  useEffect(() => {
    if (!user || !user.key || user.key === 'admin_root') return;
    const userRef = ref(db, `users/${user.key}`);
    const unsubscribe = onValue(userRef, (snapshot) => {
      if (snapshot.exists()) {
        const updatedData = { ...snapshot.val(), key: user.key };
        setUser(updatedData);
      }
    });
    return () => unsubscribe();
  }, [user?.key]);

  useEffect(() => {
    if (!user) return;

    // Welcome Toast
    setWelcomeToast(`مرحباً ${user.name}`);
    const timer = setTimeout(() => setWelcomeToast(null), 3000);

    const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
    const userStatusRef = ref(db, `status/${safeKey}`);
    set(userStatusRef, { online: true, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    onDisconnect(userStatusRef).set({ online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });

    onValue(ref(db, `notifications/${user.username}`), (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list = Object.keys(data).map(key => ({ id: key, ...data[key] })).sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        } else {
            setNotifications([]);
            setUnreadCount(0);
        }
    });

    return () => clearTimeout(timer);
  }, [user?.username]);

  const handleLogout = async () => {
    if (user) {
        const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `status/${safeKey}`), { online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    }
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  const markAsRead = (id: string) => {
    if (!user) return;
    update(ref(db, `notifications/${user.username}/${id}`), { isRead: true });
  };

  const deleteNotif = (id: string) => {
    if (!user) return;
    remove(ref(db, `notifications/${user.username}/${id}`));
  };

  if (!user) return <Login onLogin={setUser} theme={theme} />;

  return (
    <div className="bg-black text-white min-h-screen flex flex-col overflow-hidden relative">
      {welcomeToast && (
        <div className="fixed top-5 left-1/2 -translate-x-1/2 z-[200] bg-blue-600 px-6 py-3 rounded-2xl shadow-2xl font-bold flex items-center gap-2 toast-in border border-white/20">
            <Sparkles size={18} />
            {welcomeToast}
        </div>
      )}

      {settings.tickerEnabled && (
        <div className="bg-black/90 text-yellow-400 py-1.5 overflow-hidden whitespace-nowrap border-b border-white/10 z-50">
           <div className="animate-marquee inline-block px-4 font-bold">{settings.tickerText}</div>
        </div>
      )}

      <header className="p-4 flex justify-between items-center z-50 bg-black/80 backdrop-blur-md border-b border-white/10 text-white shadow-lg">
        <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="md:hidden p-2 rounded-lg hover:bg-white/10">
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="text-lg md:text-2xl font-bold truncate">
                {settings.appName}
            </h1>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
            <div className="relative">
                <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className="relative p-2 rounded-full hover:bg-white/10">
                    <Bell size={20} />
                    {unreadCount > 0 && <span className="absolute top-1 right-1 bg-red-600 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full">{unreadCount}</span>}
                </button>
                {showNotifDropdown && (
                    <div className="absolute left-0 mt-2 w-72 md:w-80 bg-gray-900 text-white rounded-2xl shadow-2xl border border-white/10 overflow-hidden z-[60]">
                        <div className="p-4 bg-black border-b border-white/10 flex justify-between items-center">
                            <h3 className="font-bold text-sm text-white">الإشعارات</h3>
                        </div>
                        <div className="max-h-80 overflow-y-auto custom-scrollbar">
                            {notifications.length === 0 ? (
                                <div className="p-10 text-center opacity-30 italic text-sm text-white">لا توجد إشعارات</div>
                            ) : (
                                notifications.map(n => (
                                    <div 
                                      key={n.id} 
                                      onClick={() => { setSelectedNotif(n); markAsRead(n.id!); setShowNotifDropdown(false); }}
                                      className={`p-4 border-b border-white/5 last:border-0 hover:bg-white/5 cursor-pointer ${!n.isRead ? 'bg-blue-600/10' : ''}`}
                                    >
                                        <div className="text-xs font-bold mb-0.5 text-white">{n.sender}</div>
                                        <div className="text-[11px] opacity-70 line-clamp-2 text-white">{n.message}</div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                )}
            </div>

            <button onClick={handleLogout} className="text-red-500 p-2 rounded-full hover:bg-red-500/10 transition-colors">
                <LogOut size={20} />
            </button>
        </div>
      </header>

      <div className="flex flex-1 overflow-hidden relative">
        <div className={`fixed md:relative top-0 bottom-0 right-0 z-50 h-full transition-transform duration-300 md:transform-none ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
            <Sidebar 
                currentView={currentView} 
                setView={(view) => { setCurrentView(view); setIsSidebarOpen(false); }} 
                user={user} 
                theme={theme} 
                settings={settings} 
                containerClass="bg-black/60 backdrop-blur-2xl border-l border-white/10 h-full shadow-2xl" 
            />
        </div>

        <main className="flex-1 p-2 md:p-4 overflow-y-auto w-full">
            <div className={`p-4 md:p-6 min-h-full rounded-2xl shadow-xl bg-gray-900/60 border border-white/5 backdrop-blur-md`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorPrices' && <CompetitorPrices user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorReports' && <CompetitorReports user={user} markets={markets} theme={theme} />}
                {currentView === 'leaveBalance' && <LeaveBalanceComponent user={user} theme={theme} />}
                {currentView === 'settings' && <Settings user={user} settings={settings} markets={markets} theme={theme} setTheme={setTheme as any} />}
            </div>
        </main>
      </div>

      <AISearch user={user} theme={theme} />
      <footer className="py-2 px-4 text-center text-[10px] font-bold opacity-50 text-white border-t border-white/5">
          مع تحيات المطور Amir Lamay
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { 
    Trash2, Edit, CalendarPlus, X, Save, History, 
    ChevronRight, ChevronLeft, CheckCircle2, AlertCircle
} from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<LeaveBalance[]>([]);
    const [usersList, setUsersList] = useState<{key: string, name: string}[]>([]);
    const [allHistory, setAllHistory] = useState<({id: string} & LeaveRecord)[]>([]);

    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showEditBalanceModal, setShowEditBalanceModal] = useState(false);
    const [showHistoryDetailsModal, setShowHistoryDetailsModal] = useState(false);

    const [currentPeriodStart, setCurrentPeriodStart] = useState<Date>(() => {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        // دورة الإجازات من 21 الشهر السابق إلى 20 الشهر الحالي
        return now.getDate() >= 21 ? new Date(year, month, 21) : new Date(year, month - 1, 21);
    });

    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams' | 'unpaid'>('annual');
    const [editingBalance, setEditingBalance] = useState<LeaveBalance | null>(null);
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);

    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: any[] = [];
                snapshot.forEach(c => { u.push({ key: c.key, name: c.val().name }); });
                setUsersList(u);
            }
        });
        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const b: LeaveBalance[] = Object.values(snapshot.val());
                setBalances(user.role === 'admin' ? b : b.filter(x => x.employeeName === user.name));
            } else { setBalances([]); }
        });
        onValue(ref(db, 'leave_history'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                const h: any = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                setAllHistory(h);
            } else { setAllHistory([]); }
        });
    }, [user]);

    const getPeriodEnd = (start: Date) => {
        const end = new Date(start);
        end.setMonth(end.getMonth() + 1);
        end.setDate(20);
        return end;
    };

    // حساب عداد غياب بإذن بناءً على الفترة الحالية (من 21 لـ 20)
    const getUnpaidForCurrentPeriod = (userId: string) => {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        const start = now.getDate() >= 21 ? new Date(year, month, 21) : new Date(year, month - 1, 21);
        const end = new Date(start);
        end.setMonth(end.getMonth() + 1);
        end.setDate(20);

        return allHistory.filter(r => 
            r.userId === userId && 
            r.type === 'unpaid' && 
            new Date(r.date) >= start && 
            new Date(r.date) <= end
        ).reduce((sum, r) => sum + r.days, 0);
    };

    const changePeriod = (direction: number) => {
        const newStart = new Date(currentPeriodStart);
        newStart.setMonth(newStart.getMonth() + direction);
        setCurrentPeriodStart(newStart);
    };

    const filterHistoryByPeriodAndUser = (userId: string) => {
        const pStart = new Date(currentPeriodStart);
        pStart.setHours(0,0,0,0);
        const pEnd = getPeriodEnd(currentPeriodStart);
        pEnd.setHours(23,59,59,999);
        return allHistory.filter(r => r.userId === userId && new Date(r.date) >= pStart && new Date(r.date) <= pEnd);
    };

    const handleDeleteRecord = async (id: string, record: LeaveRecord) => {
        if(!confirm("حذف السجل وإعادة الرصيد؟")) return;
        if(record.type !== 'unpaid') {
            const balanceRef = ref(db, `leave_balances/${record.userId}`);
            const balanceSnap = await get(balanceRef);
            if(balanceSnap.exists()) {
                const bal = balanceSnap.val();
                await update(balanceRef, { [record.type]: (Number(bal[record.type]) || 0) + Number(record.days) });
            }
        }
        await remove(ref(db, `leave_history/${id}`));
    };

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate) return alert("اكمل البيانات");

        // منع التكرار: التحقق من وجود التاريخ مسبقاً لهذا المستخدم
        const isDuplicate = allHistory.some(r => r.userId === selectedUser && r.date === leaveDate);
        if (isDuplicate) {
            alert("تم تسجيل اليوم من قبل");
            return;
        }

        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;
        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        const snap = await get(balanceRef);
        let cur = snap.exists() ? snap.val() : { userId: selectedUser, employeeName: targetUser.name, annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };

        // غياب بإذن (unpaid) لا يخصم من الرصيد السنوي
        const newVal = { ...cur, [leaveType]: Number(cur[leaveType] || 0) - (leaveType === 'unpaid' ? 0 : Number(leaveDays)) };
        await set(balanceRef, newVal);
        await push(ref(db, 'leave_history'), { userId: selectedUser, employeeName: targetUser.name, date: leaveDate, days: Number(leaveDays), type: leaveType, timestamp: Date.now() });
        setShowAddLeaveModal(false);
    };

    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات', unpaid: 'غياب بإذن' };
    const typeColors = { annual: 'text-green-400', casual: 'text-yellow-400', sick: 'text-red-400', exams: 'text-purple-400', unpaid: 'text-orange-400' };

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2 text-white"><History className="text-blue-500" /> رصيد الإجازات</h2>
                <button onClick={() => setShowAddLeaveModal(true)} className="bg-red-600 text-white px-6 py-3 rounded-2xl font-bold shadow-xl flex items-center gap-2"><CalendarPlus size={20} /> تسجيل إجازة</button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {balances.map(balance => (
                    <div key={balance.userId} className="p-5 rounded-3xl border border-white/10 bg-gray-800 text-white shadow-xl">
                        <div className="flex justify-between items-start mb-4">
                            <div className="font-bold text-lg text-blue-400">{balance.employeeName}</div>
                            {user.role === 'admin' && (
                                <button onClick={() => { setEditingBalance(balance); setShowEditBalanceModal(true); }} className="p-2 text-indigo-400 hover:bg-white/5 rounded-xl transition"><Edit size={16}/></button>
                            )}
                        </div>
                        <div className="grid grid-cols-2 gap-2">
                            {Object.entries(typeLabels).map(([key, label]) => {
                                const val = key === 'unpaid' ? getUnpaidForCurrentPeriod(balance.userId) : (balance as any)[key] || 0;
                                return (
                                    <button key={key} onClick={() => { setHistoryUserView({userId: balance.userId, name: balance.employeeName}); setShowHistoryDetailsModal(true); }} className="p-3 bg-black/20 rounded-2xl border border-white/5 flex flex-col items-center">
                                        <span className="text-[10px] opacity-50 font-black uppercase text-white">{label}</span>
                                        <span className={`text-xl font-black ${typeColors[key as keyof typeof typeColors]}`}>{val}</span>
                                    </button>
                                );
                            })}
                        </div>
                    </div>
                ))}
            </div>

            {/* مودال التاريخ */}
            {showHistoryDetailsModal && historyUserView && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
                    <div className="w-full max-w-2xl p-6 rounded-3xl border border-white/10 bg-gray-900 text-white flex flex-col max-h-[90vh]">
                        <div className="flex justify-between items-center mb-6 border-b border-white/10 pb-4">
                            <h3 className="text-xl font-bold text-blue-400 flex items-center gap-2">سجل: {historyUserView.name}</h3>
                            <button onClick={() => setShowHistoryDetailsModal(false)} className="p-2 hover:bg-white/10 rounded-full text-white"><X/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-3 pr-1 custom-scrollbar">
                            {filterHistoryByPeriodAndUser(historyUserView.userId).map(rec => (
                                <div key={rec.id} className="p-4 rounded-2xl border bg-black/20 border-white/5 flex justify-between items-center">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-xl bg-white/5 ${typeColors[rec.type]}`}><CheckCircle2 size={18} /></div>
                                        <div>
                                            <div className="font-bold text-sm text-white">{typeLabels[rec.type]}</div>
                                            <div className="text-[10px] opacity-50 text-white">{rec.date}</div>
                                        </div>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        <div className="font-black text-lg text-white">{rec.days} يوم</div>
