import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue } from "firebase/database";
import { User } from '../types';
import { COMPANIES, PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, FINE_FACIAL, FINE_KITCHEN, FINE_TOILET, ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET, PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET, WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET } from '../constants';
import { Save, Building2, User as UserIcon } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [items, setItems] = useState<{category: string, name: string, price: number}[]>([]);

    useEffect(() => {
        if (!selectedCompany) return;

        const generateItems = (facial: string[], kitchen: string[], toilet: string[]) => {
            return [
                ...facial.map(n => ({ category: 'Facial', name: n, price: 0 })),
                ...kitchen.map(n => ({ category: 'Kitchen', name: n, price: 0 })),
                ...toilet.map(n => ({ category: 'Toilet', name: n, price: 0 })),
            ];
        };

        switch(selectedCompany) {
            case 'Soft Rose': setItems(generateItems(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET)); break;
            case 'Fine': setItems(generateItems(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET)); break;
            case 'Zeina': setItems(generateItems(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET)); break;
            case 'Papia Familia': setItems(generateItems(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET)); break;
            case 'White': setItems(generateItems(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET)); break;
            default: setItems([]); break;
        }
    }, [selectedCompany]);

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const validItems = items.filter(i => i.price > 0);
        if (validItems.length === 0) return alert("يرجى إدخال الأسعار");

        await push(ref(db, 'competitor_prices'), {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: validItems
        });
        alert("تم الحفظ بنجاح");
        setItems(prev => prev.map(i => ({...i, price: 0})));
    };

    const inputClass = "w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10 font-bold";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold text-white">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-800 p-6 rounded-3xl border border-white/10 shadow-2xl">
                <div>
                    <label className="block text-xs font-bold mb-1 opacity-60 text-white">الماركت / الفرع</label>
                    <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">اختر الماركت...</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-xs font-bold mb-1 opacity-60 text-white">الشركة المنافسة</label>
                    <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                        <option value="">اختر الشركة...</option>
                        {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            <div className="space-y-4">
                {items.length > 0 && ['Facial', 'Kitchen', 'Toilet'].map(cat => (
                    <div key={cat} className="bg-gray-800 p-4 rounded-3xl border border-white/5">
                        <h3 className="font-bold text-blue-400 mb-3 border-b border-white/10 pb-2">{cat}</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                            {items.filter(i => i.category === cat).map((item, idx) => (
                                <div key={idx} className="flex items-center gap-2 bg-black/20 p-2 rounded-xl">
                                    <span className="flex-1 text-xs text-white truncate font-bold">{item.name}</span>
                                    <input 
                                        type="number" 
                                        placeholder="السعر" 
                                        className="w-24 p-2 bg-gray-700 rounded-lg text-white text-center text-xs font-black"
                                        value={item.price || ''}
                                        onChange={e => {
                                            const newItems = [...items];
                                            const actualIdx = items.indexOf(item);
                                            newItems[actualIdx].price = parseFloat(e.target.value);
                                            setItems(newItems);
                                        }}
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            <button onClick={handleSaveReport} className="bg-green-600 hover:bg-green-700 w-full py-5 text-white rounded-3xl font-black shadow-2xl flex items-center justify-center gap-2 transform active:scale-95 transition mt-8">
                <Save size={24}/> حفظ وترحيل أسعار المنافسين
            </button>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, CompetitorPrice } from '../types';
import { exportToCSV } from '../utils';
import { COMPANIES } from '../constants';
import { Trash2, Edit, Save, X, FileSpreadsheet, User as UserIcon, Calendar, Building } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorReports: React.FC<Props> = ({ user, markets, theme }) => {
    const [data, setData] = useState<CompetitorPrice[]>([]);
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [companies, setCompanies] = useState<string[]>(COMPANIES);
    const [editingReport, setEditingReport] = useState<CompetitorPrice | null>(null);

    useEffect(() => {
        onValue(ref(db, 'competitor_prices'), s => {
            if(s.exists()) {
                let arr = Object.keys(s.val()).map(key => ({
                    id: key,
                    ...s.val()[key]
                })) as CompetitorPrice[];

                // عزل البيانات: كل مستخدم يرى بيانات الماركتات الخاصة به فقط (إلا الآدمن)
                if (user.role !== 'admin') {
                    arr = arr.filter(d => markets.includes(d.market));
                }

                setData(arr.sort((a, b) => b.timestamp - a.timestamp));
            } else {
                setData([]);
            }
        });
    }, [user, markets]);

    const filtered = data.filter(d => 
        (!selectedMarket || d.market === selectedMarket) &&
        (!selectedCompany || d.company === selectedCompany)
    );

    const handleExport = () => {
        // تنظيم البيانات حسب اليوم ليكون التقرير احترافي
        const exportData = filtered.flatMap(d => (d.items || []).map(i => ({
            "التاريخ": d.date,
            "اليوم": new Date(d.timestamp).toLocaleDateString('ar-EG', { weekday: 'long' }),
            "اسم الفرع": d.market,
            "الموظف": d.employeeName || "غير معروف",
            "الشركة": d.company,
            "الصنف": i.name,
            "الفئة": i.category,
            "السعر": i.price
        })));

        exportToCSV(exportData, 'Competitor_Report_Professional');
    };

    const handleUpdate = async () => {
        if(!editingReport || !editingReport.id) return;
        await update(ref(db, `competitor_prices/${editingReport.id}`), { items: editingReport.items });
        setEditingReport(null);
        alert("تم التعديل بنجاح");
    };

    const inputClass = "w-full p-2.5 rounded-xl bg-gray-700 text-white border border-white/10 text-xs font-bold";

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold flex items-center gap-2 text-white">
                <Building className="text-blue-500" /> تقارير أسعار المنافسين
            </h2>

            <div className="bg-gray-800 p-5 rounded-2xl space-y-4 border border-white/10">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">كل الماركتات المتاحة لك</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                    <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                        <option value="">كل الشركات</option>
                        {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
                <button onClick={handleExport} className="w-full bg-green-600 hover:bg-green-700 text-white py-3 rounded-xl flex items-center justify-center gap-2 font-bold shadow-lg transition active:scale-95">
                    <FileSpreadsheet size={20} /> تصدير التقرير الاحترافي (منظم حسب اليوم)
                </button>
            </div>

            <div className="space-y-4">
                {filtered.map((record) => (
                    <div key={record.id} className="p-5 rounded-2xl border bg-gray-800 border-white/10 text-white shadow-lg">
                        <div className="flex justify-between items-start mb-4 border-b border-white/5 pb-3">
                            <div>
                                <h3 className="text-lg font-bold text-blue-400">{record.market}</h3>
                                <div className="flex flex-wrap gap-3 mt-1 text-[10px] opacity-70 text-white">
                                    <span className="flex items-center gap-1 font-bold"><Calendar size={12}/> {record.date}</span>
                                    <span className="flex items-center gap-1 font-bold"><UserIcon size={12}/> {record.employeeName}</span>
                                    <span className="font-black text-green-400">{record.company}</span>
                                </div>
                            </div>
                            <div className="flex gap-1">
                                <button onClick={() => setEditingReport(record)} className="p-2 text-indigo-400 hover:bg-indigo-500/20 rounded-lg transition"><Edit size={16}/></button>
                                {(user.role === 'admin' || user.name === record.employeeName) && (
                                     <button onClick={() => remove(ref(db, `competitor_prices/${record.id!}`))} className="p-2 text-red-400 hover:bg-red-500/20 rounded-lg transition"><Trash2 size={16}/></button>
                                )}
                            </div>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-2">
                            {(record.items || []).map((item, idx) => (
                                <div key={idx} className="flex justify-between p-2 px-3 bg-black/30 rounded-xl text-xs border border-white/5">
                                    <span className="opacity-80 truncate pr-2 font-bold text-white">{item.name}</span>
                                    <span className="font-black text-green-400">{item.price} ج.م</span>
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            {editingReport && (
                <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-[100] p-4 backdrop-blur-md">
                    <div className="w-full max-w-2xl bg-gray-900 border border-white/10 rounded-3xl p-6 flex flex-col max-h-[85vh]">
                        <div className="flex justify-between items-center mb-6 border-b border-white/10 pb-4">
                            <h3 className="font-bold text-xl text-blue-400">تعديل التقرير</h3>
                            <button onClick={() => setEditingReport(null)} className="p-2 hover:bg-white/10 rounded-full text-white"><X/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-2 pr-2 custom-scrollbar">
                            {editingReport.items.map((item, idx) => (
                                <div key={idx} className="flex gap-2 items-center p-2 bg-white/5 rounded-xl">
                                    <span className="flex-1 text-xs font-bold text-white">{item.name}</span>
                                    <input type="number" value={item.price} onChange={e => {
                                        const n = [...editingReport.items];
                                        n[idx].price = Number(e.target.value);
                                        setEditingReport({...editingReport, items: n});
                                    }} className="w-24 p-1.5 rounded bg-gray-700 text-white text-center border border-white/10 text-xs font-bold"/>
                                </div>
                            ))}
                        </div>
                        <button onClick={handleUpdate} className="mt-6 w-full bg-blue-600 text-white py-4 rounded-2xl font-bold flex items-center justify-center gap-2 active:scale-95 transition">
                            <Save size={20}/> حفظ التعديلات
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CompetitorReports;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings, UserPermissions, AppNotification } from '../types';
import { 
  Save, Trash2, UserPlus, Shield, Edit2, Plus, X, 
  Settings as SettingsIcon, Users, MapPin, Building2, 
  ToggleLeft, ToggleRight, Key, Send
} from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<User[]>([]);
    const [newUser, setNewUser] = useState<User>({ 
        name: '', 
        username: '', 
        password: '', 
        role: 'user', 
        canViewAllSales: false,
        permissions: {
            showSalesLog: true,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        }
    });

    const [marketList, setMarketList] = useState<{key: string, name: string, createdBy: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, name: string, createdBy: string}[]>([]);

    // Modals
    const [passModal, setPassModal] = useState<{key: string, name: string} | null>(null);
    const [permModal, setPermModal] = useState<User | null>(null);
    const [notifModal, setNotifModal] = useState<{username: string, name: string} | null>(null);
    const [newPass, setNewPass] = useState('');
    const [notifMsg, setNotifMsg] = useState('');

    useEffect(() => {
        setLocalSettings(settings);
    }, [settings]);

    useEffect(() => {
        if (user.role !== 'admin') return;

        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: User[] = [];
                snapshot.forEach(c => { u.push({ key: c.key || '', ...c.val() }); });
                setUsers(u);
            }
        });

        onValue(ref(db, 'settings/markets'), snapshot => {
            if(snapshot.exists()){
                const m: any[] = [];
                snapshot.forEach(c => { 
                    const data = c.val();
                    m.push({
                        key: c.key, 
                        name: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'System' : data.createdBy
                    });
                });
                setMarketList(m);
            }
        });

        onValue(ref(db, 'settings/companies'), snapshot => {
            if(snapshot.exists()){
                const c: any[] = [];
                snapshot.forEach(k => { 
                    const data = k.val();
                    c.push({
                        key: k.key, 
                        name: typeof data === 'string' ? data : data.name,
                        createdBy: typeof data === 'string' ? 'System' : data.createdBy
                    });
                });
                setCompanyList(c);
            }
        });
    }, [user.role]);

    const saveAppSettings = async () => {
        try {
            await set(ref(db, 'settings/app'), localSettings);
            alert('تم حفظ إعدادات التطبيق بنجاح');
        } catch (e) { alert('خطأ في الحفظ'); }
    };

    const handleAddUser = async () => {
        if (!newUser.username || !newUser.password || !newUser.name) return alert("اكمل بيانات المستخدم");
        await push(ref(db, 'users'), newUser);
        alert("تمت إضافة المستخدم بنجاح");
        setNewUser({ 
            name: '', 
            username: '', 
            password: '', 
            role: 'user', 
            canViewAllSales: false,
            permissions: {
                showSalesLog: true,
                showInventoryLog: false,
                showInventoryReg: false,
                showCompetitorReports: false,
                showDailySales: true,
                showCompetitorPrices: true
            }
        });
    };

    const handleDeleteUser = async (key: string) => {
        if (confirm("هل أنت متأكد من حذف هذا المستخدم؟")) {
            await remove(ref(db, `users/${key}`));
        }
    };

    const handleUpdatePassword = async () => {
        if(!passModal || !newPass) return;
        await update(ref(db, `users/${passModal.key}`), { password: newPass });
        alert("تم تحديث كلمة المرور");
        setPassModal(null);
        setNewPass('');
    };

    const handleUpdatePermissions = async () => {
        if (!permModal || !permModal.key) return;
        const permissions = permModal.permissions || {
            showSalesLog: false,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        };
        await update(ref(db, `users/${permModal.key}`), { 
            permissions: permissions,
            canViewAllSales: !!permModal.canViewAllSales
        });
        alert("تم تحديث الصلاحيات بنجاح");
        setPermModal(null);
    };

    const handleSendNotif = async () => {
        if (!notifModal || !notifMsg) return;
        const notification: AppNotification = {
            message: notifMsg,
            sender: user.name,
            timestamp: Date.now(),
            isRead: false
        };
        await push(ref(db, `notifications/${notifModal.username}`), notification);
        alert(`تم إرسال الرسالة بنجاح إلى ${notifModal.name}`);
        setNotifModal(null);
        setNotifMsg('');
    };

    const toggleUserPerm = (key: keyof UserPermissions) => {
        if (!permModal) return;
        const currentPermissions = permModal.permissions || {
            showSalesLog: false,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        };
        setPermModal({
            ...permModal,
            permissions: {
                ...currentPermissions,
                [key]: !currentPermissions[key]
            }
        });
    };

    if (user.role !== 'admin') {
        return <div className="p-10 text-center opacity-50">عذراً، هذه الصفحة متاحة للمسؤولين فقط.</div>;
    }

    const inputClass = "w-full p-2.5 rounded-lg border border-gray-300 bg-gray-600 text-white focus:ring-2 focus:ring-blue-500 outline-none font-bold";
    const sectionClass = `p-6 rounded-2xl mb-6 bg-gray-800 border-gray-700 border text-white`;

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-20">
            <div className="flex items-center gap-3 mb-2 text-white">
                <SettingsIcon className="text-blue-600" size={32} />
                <h2 className="text-3xl font-bold">لوحة تحكم المسؤول</h2>
            </div>

            {/* إعدادات التطبيق العامة */}
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-6 flex items-center gap-2 text-blue-600 border-b pb-3">
                    <Edit2 size={20} /> الإعدادات العامة للمنصة
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    <div>
                        <label className="block text-sm font-bold mb-2 opacity-70 text-white">اسم التطبيق (AppName)</label>
                        <input className={inputClass} value={localSettings.appName} onChange={e => setLocalSettings({...localSettings, appName: e.target.value})} />
                    </div>
                    <div>
                        <label className="block text-sm font-bold mb-2 opacity-70 text-white">رقم واتساب الدعم</label>
                        <input className={inputClass} placeholder="مثال: 2010XXXXXXXX" value={localSettings.whatsappNumber} onChange={e => setLocalSettings({...localSettings, whatsappNumber: e.target.value})} />
                    </div>
                    <div className="md:col-span-2 text-white">
                        <label className="block text-sm font-bold mb-2 opacity-70">نص الشريط المتحرك (Ticker Text)</label>
                        <div className="flex gap-2">
                            <input className={inputClass} value={localSettings.tickerText} onChange={e => setLocalSettings({...localSettings, tickerText: e.target.value})} />
                            <button 
                                onClick={() => setLocalSettings({...localSettings, tickerEnabled: !localSettings.tickerEnabled})}
                                className={`px-4 rounded-lg flex items-center gap-2 font-bold ${localSettings.tickerEnabled ? 'bg-green-600 text-white' : 'bg-gray-300 text-gray-700'}`}
                            >
                                {localSettings.tickerEnabled ? <ToggleRight /> : <ToggleLeft />} {localSettings.tickerEnabled ? 'مفعل' : 'معطل'}
                            </button>
                        </div>
                    </div>
                </div>
                <button onClick={saveAppSettings} className="mt-6 w-full bg-blue-600 hover:bg-blue-700 text-white py-3 rounded-xl font-bold flex items-center justify-center gap-2 shadow-lg transition transform active:scale-95">
                    <Save size={20} /> حفظ الإعدادات العامة
                </button>
            </div>

            {/* إدارة المستخدمين */}
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-6 flex items-center gap-2 text-purple-600 border-b pb-3">
                    <Users size={20} /> إدارة حسابات وصلاحيات الموظفين
                </h3>

                {/* إضافة مستخدم جديد */}
                <div className="bg-gray-700/50 p-6 rounded-2xl mb-6 border border-gray-600">
                    <h4 className="font-bold mb-4 flex items-center gap-2 text-sm text-white"><UserPlus size={16}/> إضافة موظف جديد</h4>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                        <input className={inputClass} placeholder="الاسم الكامل" value={newUser.name} onChange={e => setNewUser({...newUser, name: e.target.value})} />
                        <input className={inputClass} placeholder="اسم المستخدم" value={newUser.username} onChange={e => setNewUser({...newUser, username: e.target.value})} />
                        <input className={inputClass} type="password" placeholder="كلمة المرور" value={newUser.password} onChange={e => setNewUser({...newUser, password: e.target.value})} />
                        <select className={inputClass} value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as any})}>
                            <option value="user">موظف (User)</option>
                            <option value="admin">مسؤول (Admin)</option>
                        </select>
                    </div>
                    <button onClick={handleAddUser} className="mt-4 w-full bg-green-600 text-white font-bold py-2 rounded-lg hover:bg-green-700 transition shadow-lg">إضافة الموظف</button>
                </div>

                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-right">
                        <thead className="bg-gray-700">
                            <tr>
                                <th className="p-3 text-white">الاسم</th>
                                <th className="p-3 text-white">المستخدم</th>
                                <th className="p-3 text-white">الدور</th>
                                <th className="p-3 text-center text-white">الإجراءات</th>
                            </tr>
                        </thead>
                        <tbody>
                            {users.map(u => (
                                <tr key={u.key} className="border-b border-gray-700 hover:bg-black/10">
                                    <td className="p-3 font-bold text-white">{u.name}</td>
                                    <td className="p-3 opacity-70 text-white">{u.username}</td>
                                    <td className="p-3">
                                        <span className={`px-2 py-1 rounded text-[10px] font-bold ${u.role === 'admin' ? 'bg-red-100 text-red-700' : 'bg-blue-100 text-blue-700'}`}>
                                            {u.role === 'admin' ? 'مسؤول' : 'موظف'}
                                        </span>
                                    </td>
                                    <td className="p-3 flex justify-center gap-1 md:gap-2">
                                        <button onClick={() => setNotifModal({username: u.username, name: u.name})} className="p-2 text-green-400 hover:bg-green-400/10 rounded" title="إرسال رسالة تنبيه"><Send size={16}/></button>
                                        <button onClick={() => setPermModal(u)} className="p-2 text-blue-400 hover:bg-blue-400/10 rounded permission-btn" title="تعديل صلاحيات الأقسام"><Shield size={16}/></button>
                                        <button onClick={() => setPassModal({key: u.key!, name: u.name})} className="p-2 text-orange-400 hover:bg-orange-400/10 rounded" title="تغيير كلمة المرور"><Key size={16}/></button>
                                        <button onClick={() => handleDeleteUser(u.key!)} className="p-2 text-red-400 hover:bg-red-400/10 rounded" title="حذف الحساب"><Trash2 size={16}/></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

             {/* إدارة الماركت والشركات */}
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6 text-white">
                <div className={sectionClass}>
                    <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-blue-400 border-b pb-2">
                        <MapPin size={18} /> إدارة الماركتات
                    </h3>
                    <div className="max-h-64 overflow-y-auto space-y-2 custom-scrollbar pr-2">
                        {marketList.map(m => (
                            <div key={m.key} className="flex justify-between items-center p-3 bg-gray-700 rounded-xl text-sm border border-transparent hover:border-blue-500/20 market-item">
                                <div>
                                    <div className="font-bold text-white">{m.name}</div>
                                    <div className="text-[10px] opacity-50 italic text-white">بواسطة: {m.createdBy}</div>
                                </div>
                                <button onClick={() => remove(ref(db, `settings/markets/${m.key}`))} className="p-1.5 text-red-400 hover:bg-red-400/10 rounded"><Trash2 size={14}/></button>
                            </div>
                        ))}
                    </div>
                </div>

                <div className={sectionClass}>
                    <h3 className="text-lg font-bold mb-4 flex items-center gap-2 text-green-400 border-b pb-2">
                        <Building2 size={18} /> إدارة الشركات
                    </h3>
                    <div className="max-h-64 overflow-y-auto space-y-2 custom-scrollbar pr-2">
                        {companyList.map(c => (
                            <div key={c.key} className="flex justify-between items-center p-3 bg-gray-700 rounded-xl text-sm border border-transparent hover:border-green-500/20 company-item">
                                <div>
                                    <div className="font-bold text-white">{c.name}</div>
                                    <div className="text-[10px] opacity-50 italic text-white">بواسطة: {c.createdBy}</div>
                                </div>
                                <button onClick={() => remove(ref(db, `settings/companies/${c.key}`))} className="p-1.5 text-red-400 hover:bg-red-400/10 rounded"><Trash2 size={14}/></button>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* Modals for Notifications, Permissions, Passwords remain in Settings... */}
            {/* [Existing modals are retained and already included in original source logic] */}
        </div>
    );
};

