import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update } from "firebase/database";
import { User, SaleRecord, ProductItem } from '../types';
import { 
    Trash2, Edit, FileSpreadsheet, Save, X, Calendar, User as UserIcon, TrendingUp, Star, Trophy, Download, Filter
} from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');
    const [editingSale, setEditingSale] = useState<SaleRecord | null>(null);

    // Export state
    const [showExportModal, setShowExportModal] = useState(false);
    const [exportStart, setExportStart] = useState('');
    const [exportEnd, setExportEnd] = useState('');
    const [exportMarket, setExportMarket] = useState('');

    useEffect(() => {
        const salesRef = ref(db, 'sales');
        onValue(salesRef, (snapshot) => {
            const data = snapshot.val();
            if (data) {
                let loadedSales: SaleRecord[] = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                if (user.role !== 'admin' && !user.canViewAllSales) {
                    loadedSales = loadedSales.filter(s => s.employeeName === user.name);
                }
                setSales(loadedSales.sort((a, b) => b.timestamp - a.timestamp));
            } else { setSales([]); }
        });
    }, [user]);

    useEffect(() => {
        let result = sales;
        if (filterDate) result = result.filter(s => s.date.includes(filterDate));
        if (filterEmployee) result = result.filter(s => s.employeeName.includes(filterEmployee));
        if (filterMarket) result = result.filter(s => s.market === filterMarket);
        setFilteredSales(result);
    }, [sales, filterDate, filterEmployee, filterMarket]);

    const getStarOfMonth = () => {
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        const start = new Date(year, month, 1);
        const end = new Date(year, month, 30);

        const currentMonthSales = sales.filter(s => {
            const d = new Date(s.timestamp);
            return d >= start && d <= end;
        });

        const totals: Record<string, number> = {};
        currentMonthSales.forEach(s => {
            totals[s.employeeName] = (totals[s.employeeName] || 0) + s.total;
        });

        const sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);
        return sorted.length > 0 ? { name: sorted[0][0], total: sorted[0][1] } : null;
    };

    const star = getStarOfMonth();

    const calculateTopItemsForStar = () => {
        if (!star) return [];
        const now = new Date();
        const year = now.getFullYear();
        const month = now.getMonth();
        const start = new Date(year, month, 1);
        const end = new Date(year, month, 30);

        const starSales = sales.filter(s => {
            const d = new Date(s.timestamp);
            return s.employeeName === star.name && d >= start && d <= end;
        });

        const counts: Record<string, { qty: number, total: number }> = {};
        starSales.forEach(s => {
            (s.items || []).forEach(item => {
                if (!counts[item.name]) counts[item.name] = { qty: 0, total: 0 };
                counts[item.name].qty += item.qty;
                counts[item.name].total += (item.qty * item.price);
            });
        });

        return Object.entries(counts)
            .sort((a, b) => b[1].total - a[1].total)
            .slice(0, 5);
    };

    const handleExportPeriod = () => {
        if (!exportStart || !exportEnd) return alert("اختر الفترة الزمنية");

        const startTS = new Date(exportStart).getTime();
        const endTS = new Date(exportEnd).getTime() + 86400000; // نهاية اليوم

        const periodSales = sales.filter(s => {
            const ts = s.timestamp;
            const matchesPeriod = ts >= startTS && ts <= endTS;
            const matchesMarket = !exportMarket || s.market === exportMarket;
            return matchesPeriod && matchesMarket;
        });

        if (periodSales.length === 0) return alert("لا توجد مبيعات في هذه الفترة");

        const exportData = periodSales.flatMap(s => (s.items || []).map(i => ({
            "الموظف": s.employeeName,
            "اليوم": new Date(s.timestamp).toLocaleDateString('ar-EG', { weekday: 'long' }),
            "التاريخ": s.date,
            "الماركت": s.market,
            "الحساب": (s as any).username || "غير معروف",
            "الصنف": i.name,
            "السعر": i.price,
            "الكمية": i.qty,
            "الإجمالي": i.price * i.qty
        })));

        exportToCSV(exportData, `Sales_Report_${exportStart}_to_${exportEnd}`);
        setShowExportModal(false);
    };

    const handleExportCurrent = () => {
        if (filteredSales.length === 0) return alert("لا توجد بيانات للتصدير");

        const exportData = filteredSales.map(s => ({
            "اسم الموظف": s.employeeName,
            "اليوم": new Date(s.timestamp).toLocaleDateString('ar-EG', { weekday: 'long' }),
            "التاريخ": s.date,
            "اسم الفرع": s.market,
            "الحساب": (s as any).username || "غير معروف",
            "إجمالي مبيعات اليوم": s.total.toLocaleString() + " ج.م"
        }));

        exportToCSV(exportData, "Current_Sales_Log");
    };

    const handleDelete = async (id: string) => {
        if (window.confirm("هل أنت متأكد من حذف هذا السجل نهائياً؟")) {
            await remove(ref(db, `sales/${id}`));
        }
    };

    const saveEdit = async () => {
        if (!editingSale || !editingSale.id) return;
        await update(ref(db, `sales/${editingSale.id}`), {
            items: editingSale.items,
            total: editingSale.items.reduce((sum, i) => sum + (i.price * i.qty), 0)
        });
        setEditingSale(null);
        alert("تم التحديث بنجاح");
    };

    return (
        <div className="space-y-6">
            <h2 className="text-2xl font-bold flex items-center gap-2 text-white"><FileSpreadsheet /> سجل المبيعات</h2>

            {/* أزرار التصدير */}
            <div className="flex flex-col md:flex-row gap-3">
                <button 
                  onClick={() => setShowExportModal(true)}
                  className="flex-1 bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 rounded-2xl shadow-lg flex items-center justify-center gap-2 transition active:scale-95"
                >
                  <Filter size={18}/> تصدير فترة معينة
                </button>
                <button 
                  onClick={handleExportCurrent}
                  className="flex-1 bg-green-600 hover:bg-green-700 text-white font-bold py-3 rounded-2xl shadow-lg flex items-center justify-center gap-2 transition active:scale-95"
                >
                  <Download size={18}/> تصدير السجل الحالي
                </button>
            </div>

            {/* نجم الشهر - خلفية رمادية */}
            {star && (
                <div className="bg-[#808080] p-6 rounded-3xl border border-white/20 shadow-2xl flex flex-col items-center justify-center space-y-2 relative overflow-hidden group">
                    <div className="absolute -right-4 -top-4 opacity-10 group-hover:rotate-12 transition-transform duration-700">
                        <Trophy size={120} />
                    </div>
                    <Star className="text-yellow-400 animate-pulse" size={32} fill="currentColor" />
                    <h3 className="text-xl font-black text-white uppercase tracking-widest">نجم الشهر الحالي</h3>
                    <div className="text-3xl font-black text-white">{star.name}</div>
                    <div className="text-sm font-bold opacity-80 text-white">إجمالي مبيعات الشهر: <span className="text-green-300 font-black">{star.total.toLocaleString()} ج.م</span></div>
                </div>
            )}

            {/* الأكثر مبيعاً للنجم */}
            {star && (
                <div className="bg-gray-800 p-5 rounded-3xl border border-white/10 shadow-xl">
                    <h3 className="text-xs font-black text-blue-400 mb-4 flex items-center gap-2 uppercase tracking-widest text-white"><TrendingUp size={14}/> الأكثر مبيعاً لنجم الشهر</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
                        {calculateTopItemsForStar().map(([name, data], idx) => (
                            <div key={idx} className="bg-black/30 p-4 rounded-2xl border border-white/5">
                                <div className="font-bold text-xs text-white truncate mb-1">{name}</div>
                                <div className="flex justify-between text-[10px] text-green-400 font-black">
                                    <span>{data.qty} قطعة</span>
                                    <span>{data.total.toLocaleString()} ج.م</span>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                {user.role === 'admin' && (
                    <input type="date" className="p-3 rounded-xl bg-gray-700 text-white" value={filterDate} onChange={e => setFilterDate(e.target.value)} />
                )}
                <input type="text" placeholder="بحث باسم الموظف..." className="p-3 rounded-xl bg-gray-700 text-white" value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} />
                <select className="p-3 rounded-xl bg-gray-700 text-white" value={filterMarket} onChange={e => setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {filteredSales.map(sale => (
                    <div key={sale.id} className="p-5 rounded-3xl border border-white/10 bg-gray-800 shadow-2xl">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <div className="font-bold text-xl text-blue-400">{sale.market}</div>
                                <div className="flex flex-wrap items-center gap-3 text-[10px] opacity-60 font-bold mt-1 text-white">
                                    <span className="flex items-center gap-1"><Calendar size={12}/> {new Date(sale.timestamp).toLocaleDateString('ar-EG', { weekday: 'long' })} - {sale.date}</span>
                                    <span className="flex items-center gap-1"><UserIcon size={12}/> {sale.employeeName}</span>
                                    <span className="bg-white/10 px-2 py-0.5 rounded text-[9px] uppercase">{(sale as any).username || "System"}</span>
                                </div>
                            </div>
                            <div className="flex gap-2">
                                <button onClick={() => setEditingSale(sale)} className="p-2 text-indigo-400 hover:bg-white/5 rounded-xl transition"><Edit size={18} /></button>
                                {(user.role === 'admin' || user.name === sale.employeeName) && (
                                    <button onClick={() => handleDelete(sale.id!)} className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition"><Trash2 size={18} /></button>
                                )}
                            </div>
                        </div>

                        <div className="overflow-hidden rounded-2xl bg-black/20 border border-white/5">
                            <table className="w-full text-[11px] text-center">
                                <thead className="bg-white/5 text-white/50">
                                    <tr>
                                        <th className="py-2 px-3 text-right text-white">الصنف</th>
                                        <th className="py-2 text-white">السعر</th>
                                        <th className="py-2 text-white">الكمية</th>
                                        <th className="py-2 px-3 text-white">المجموع</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {(sale.items || []).map((item, idx) => (
                                        <tr key={idx} className="border-t border-white/5 text-white">
                                            <td className="py-2 px-3 text-right font-bold">{item.name}</td>
                                            <td className="py-2">{item.price}</td>
                                            <td className="py-2 font-black">{item.qty}</td>
                                            <td className="py-2 px-3 text-green-400 font-black">{(item.qty * item.price).toLocaleString()}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>

                        <div className="mt-4 pt-4 border-t border-white/10 flex justify-between items-center text-white">
                            <span className="text-xs font-bold opacity-60 uppercase tracking-tighter">إجمالي الفاتورة:</span>
                            <span className="text-xl font-black text-blue-400">{sale.total.toLocaleString()} ج.م</span>
                        </div>
                    </div>
                ))}
            </div>

            {/* مودال تصدير فترة */}
            {showExportModal && (
              <div className="fixed inset-0 z-[200] bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
                <div className="bg-gray-900 border border-white/10 w-full max-w-md rounded-3xl p-6 shadow-2xl">
                  <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold text-lg text-white">تصدير مبيعات فترة زمنية</h3>
                    <button onClick={() => setShowExportModal(false)} className="text-white/50 hover:text-white"><X size={20}/></button>
                  </div>
                  <div className="space-y-4">
                    <div>
                      <label className="block text-xs font-bold mb-1 opacity-60 text-white">تاريخ البداية</label>
                      <input type="date" className="w-full p-3 rounded-xl bg-gray-800 text-white border border-white/10" value={exportStart} onChange={e => setExportStart(e.target.value)} />
                    </div>
                    <div>
                      <label className="block text-xs font-bold mb-1 opacity-60 text-white">تاريخ النهاية</label>
                      <input type="date" className="w-full p-3 rounded-xl bg-gray-800 text-white border border-white/10" value={exportEnd} onChange={e => setExportEnd(e.target.value)} />
                    </div>
                    <div>
                      <label className="block text-xs font-bold mb-1 opacity-60 text-white">الماركت (اختياري)</label>
                      <select className="w-full p-3 rounded-xl bg-gray-800 text-white border border-white/10" value={exportMarket} onChange={e => setExportMarket(e.target.value)}>
                        <option value="">كل الماركتات</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                      </select>
                    </div>
                    <button onClick={handleExportPeriod} className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-xl transition active:scale-95">بدء التحميل (Excel)</button>
                  </div>
                </div>
              </div>
            )}

            {/* مودال التعديل */}
            {editingSale && (
                <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-[100] p-4 backdrop-blur-xl">
                    <div className="w-full max-w-2xl bg-gray-900 border border-white/10 rounded-3xl p-6 flex flex-col max-h-[90vh]">
                        <div className="flex justify-between items-center mb-6 border-b border-white/10 pb-4">
                            <h3 className="text-xl font-bold flex items-center gap-2 text-blue-400"><Edit /> تعديل السجل</h3>
                            <button onClick={() => setEditingSale(null)} className="p-2 hover:bg-white/10 rounded-full text-white"><X/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
                            {editingSale.items.map((item, idx) => (
                                <div key={idx} className="grid grid-cols-12 gap-2 bg-white/5 p-3 rounded-2xl items-center border border-white/5">
                                    <div className="col-span-6 text-xs font-bold text-white">{item.name}</div>
                                    <div className="col-span-3">
                                        <input type="number" value={item.price} onChange={e => {
                                            const n = [...editingSale.items];
                                            n[idx].price = Number(e.target.value);
                                            setEditingSale({...editingSale, items: n});
                                        }} className="w-full p-2 rounded-lg bg-gray-800 text-white text-center text-xs" />
                                    </div>
                                    <div className="col-span-3">
                                        <input type="number" value={item.qty} onChange={e => {
                                            const n = [...editingSale.items];
                                            n[idx].qty = Number(e.target.value);
                                            setEditingSale({...editingSale, items: n});
                                        }} className="w-full p-2 rounded-lg bg-gray-800 text-white text-center text-xs" />
                                    </div>
                                </div>
                            ))}
                        </div>
                        <button onClick={saveEdit} className="mt-6 w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-2xl font-black shadow-2xl flex justify-center items-center gap-2 active:scale-95 transition">
                            <Save /> حفظ التعديلات الجديدة
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

