}

/* High Visibility Data Rules - Custom Gray #808080 */
.bg-custom-gray {
  background-color: #808080 !important;
}

select, 
.bg-gray-700,
.bg-gray-800,
input,
.permission-btn,
.market-item,
.company-item {
