import React, { useState, useEffect } from 'react';
import { ref, push, set } from "firebase/database";
import { db } from '../firebase';
import { User } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

interface InventoryItem {
    id: string;
    name: string;
    qty: number;
    category: string;
    isCustom: boolean;
}

const InventoryRegistration: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [items, setItems] = useState<InventoryItem[]>([]);

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial', allowAdd: true },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen', allowAdd: true },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet', allowAdd: false },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin', allowAdd: true },
    ];

    useEffect(() => {
        const initItems: InventoryItem[] = [];
        allCategories.forEach(cat => {
            cat.items.forEach(prod => {
                initItems.push({
                    id: prod,
                    name: prod,
                    qty: 0,
                    category: cat.key,
                    isCustom: false
                });
            });
        });
        setItems(initItems);
    }, []);

    const updateItem = (id: string, field: 'qty' | 'name', value: any) => {
        // إذا كان تعديل الاسم لصنف مخصص، نتحقق من اللغة
        if (field === 'name') {
            const containsArabic = /[\u0600-\u06FF]/.test(value);
            if (containsArabic) {
                alert("يرجى كتابة اسم الصنف باللغة الإنجليزية فقط");
                return;
            }
        }
        setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const handleAddCustomItem = (category: string) => {
        const newItem: InventoryItem = {
            id: `custom_${Date.now()}_${Math.random()}`,
            name: '',
            qty: 0,
            category,
            isCustom: true
        };
        setItems(prev => [...prev, newItem]);
    };

    const removeCustomItem = (id: string) => {
        setItems(prev => prev.filter(i => i.id !== id));
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");

        // التحقق من أن جميع الأصناف المخصصة مكتوبة بالإنجليزية
        const arabicItems = items.filter(i => i.qty > 0 && /[\u0600-\u06FF]/.test(i.name));
        if (arabicItems.length > 0) return alert("يرجى التأكد من كتابة أسماء الأصناف الجديدة بالإنجليزية فقط");

        const inventoryData = {
            market: selectedMarket,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: items.filter(i => i.qty > 0).map(i => ({ name: i.name, qty: i.qty, category: i.category }))
        };
        if (inventoryData.items.length === 0) return alert("الكميات كلها صفر");
        await push(ref(db, 'inventory'), inventoryData);
        alert("تم حفظ المخزون");
        setItems(prev => prev.map(i => ({...i, qty: 0})));
    };

    const dropdownClass = "w-48 bg-[#808080] text-white border border-white/20 p-2.5 rounded-xl font-bold outline-none";
    const inputClass = "bg-white/10 border border-white/20 p-2 rounded text-white";

    return (
        <div className="pb-20">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold">تسجيل المخزون</h2>
                <div className="flex gap-2">
                    <select className={dropdownClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">اختر الماركت</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                </div>
            </div>

            {allCategories.map(cat => (
                <div key={cat.key} className="mb-6 bg-white/5 p-4 rounded-lg">
                    <div className="flex justify-between items-center mb-4 border-b border-gray-500/20 pb-2">
                        <h3 className="text-xl font-bold text-blue-500">{cat.name}</h3>
                        {cat.allowAdd && (
                             <button onClick={() => handleAddCustomItem(cat.key)} className="bg-green-600 hover:bg-green-700 text-white text-xs px-3 py-1.5 rounded flex items-center gap-1 shadow"><Plus size={14}/> أضف صنف</button>
                        )}
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {items.filter(i => i.category === cat.key).map((item) => (
                            <div key={item.id} className="flex justify-between items-center gap-2 p-2 border-b border-gray-500/10">
                                <div className="flex-1">
                                    {item.isCustom ? (
                                        <input type="text" value={item.name} onChange={e => updateItem(item.id, 'name', e.target.value)} className={`${inputClass} w-full text-sm`} placeholder="اسم الصنف (English Only)..." />
                                    ) : (
                                        <span className="text-sm font-medium">{item.name}</span>
                                    )}
                                </div>
                                <div className="flex items-center gap-2">
                                    <input type="number" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} className={`${inputClass} w-20 text-center`} placeholder="الكمية" />
                                    {item.isCustom && <button onClick={() => removeCustomItem(item.id)} className="text-red-500 hover:bg-red-500/10 p-1 rounded transition"><Trash2 size={16} /></button>}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <div className="fixed bottom-4 left-4 right-4 md:left-auto md:right-8 md:w-auto flex justify-center z-10">
                <button 
                    onClick={handleSave} 
                    className="w-full md:w-64 bg-green-600 hover:bg-green-700 text-white py-3 rounded-full font-bold shadow-xl flex justify-center items-center gap-2 transform transition hover:scale-105"
                >
                    <Save size={20} /> حفظ المخزون
                </button>
            </div>
        </div>
    );
};

export default InventoryRegistration;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue } from "firebase/database";
import { User } from '../types';
import { COMPANIES, PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, FINE_FACIAL, FINE_KITCHEN, FINE_TOILET, ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET, PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET, WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET } from '../constants';
import { Save, Building2, User as UserIcon, Plus } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [items, setItems] = useState<{category: string, name: string, price: number, isCustom?: boolean}[]>([]);

    useEffect(() => {
        if (!selectedCompany) return;

        const generateItems = (facial: string[], kitchen: string[], toilet: string[]) => {
            return [
                ...facial.map(n => ({ category: 'Facial', name: n, price: 0 })),
                ...kitchen.map(n => ({ category: 'Kitchen', name: n, price: 0 })),
                ...toilet.map(n => ({ category: 'Toilet', name: n, price: 0 })),
            ];
        };

        switch(selectedCompany) {
            case 'Soft Rose': setItems(generateItems(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET)); break;
            case 'Fine': setItems(generateItems(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET)); break;
            case 'Zeina': setItems(generateItems(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET)); break;
            case 'Papia Familia': setItems(generateItems(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET)); break;
            case 'White': setItems(generateItems(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET)); break;
            default: setItems([]); break;
        }
    }, [selectedCompany]);

    const addCustomItem = (category: string) => {
        const name = prompt("ادخل اسم الصنف المنافس (English Only):");
        if (name) {
            // التحقق من اللغة (منع العربية)
            const containsArabic = /[\u0600-\u06FF]/.test(name);
            if (containsArabic) {
                alert("يرجى كتابة اسم الصنف باللغة الإنجليزية فقط");
                return;
            }
            setItems(prev => [...prev, { category, name, price: 0, isCustom: true }]);
        }
    };

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const validItems = items.filter(i => i.price > 0);
        if (validItems.length === 0) return alert("يرجى إدخال الأسعار");

        await push(ref(db, 'competitor_prices'), {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: validItems
        });
        alert("تم الحفظ بنجاح");
        setItems(prev => prev.map(i => ({...i, price: 0})));
    };

    const inputClass = "w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10 font-bold";

    return (
        <div className="space-y-6 pb-20">
            <h2 className="text-2xl font-bold text-white">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-800 p-6 rounded-3xl border border-white/10 shadow-2xl">
                <div>
                    <label className="block text-xs font-bold mb-1 opacity-60 text-white">الماركت / الفرع</label>
                    <select className={inputClass} value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                        <option value="">اختر الماركت...</option>
                        {markets.map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-xs font-bold mb-1 opacity-60 text-white">الشركة المنافسة</label>
                    <select className={inputClass} value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                        <option value="">اختر الشركة...</option>
                        {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
            </div>

            <div className="space-y-4">
                {items.length > 0 && ['Facial', 'Kitchen', 'Toilet'].map(cat => (
                    <div key={cat} className="bg-gray-800 p-4 rounded-3xl border border-white/5">
                        <div className="flex justify-between items-center mb-3 border-b border-white/10 pb-2">
                            <h3 className="font-bold text-blue-400">{cat}</h3>
                            <button 
                                onClick={() => addCustomItem(cat)}
                                className="bg-green-600 text-white px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-1 active:scale-95 transition"
                            >
                                <Plus size={14}/> أضف صنف
                            </button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                            {items.filter(i => i.category === cat).map((item, idx) => (
                                <div key={idx} className="flex items-center gap-2 bg-black/20 p-2 rounded-xl">
                                    <span className="flex-1 text-xs text-white truncate font-bold">{item.name}</span>
                                    <input 
                                        type="number" 
                                        placeholder="السعر" 
                                        className="w-24 p-2 bg-gray-700 rounded-lg text-white text-center text-xs font-black"
                                        value={item.price || ''}
                                        onChange={e => {
                                            const newItems = [...items];
                                            const actualIdx = items.indexOf(item);
                                            newItems[actualIdx].price = parseFloat(e.target.value);
                                            setItems(newItems);
                                        }}
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSaveReport} className="bg-green-600 hover:bg-green-700 w-full py-5 text-white rounded-3xl font-black shadow-2xl flex items-center justify-center gap-2 transform active:scale-95 transition">
                    <Save size={20}/> حفظ وترحيل أسعار المنافسين
                </button>
            </div>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { ref, push, onValue, set, get, update } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem, UserTarget } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Calculator, Target, TrendingUp, AlertCircle, Edit, Trash2, Check, X } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [userTarget, setUserTarget] = useState<UserTarget | null>(null);

    // حالات التعديل الجديدة
    const [editingItemId, setEditingItemId] = useState<string | null>(null);
    const [tempName, setTempName] = useState('');

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        const categories = [
            { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
            { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
            { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
            { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
        ];

        categories.forEach(cat => {
            cat.items.forEach(name => {
                initialItems.push({ 
                    id: name + "_base_" + Math.random().toString(36).substr(2, 9), 
                    name, 
                    price: 0, 
                    qty: 0, 
                    category: cat.key 
                });
            });
        });
        setSalesItems(initialItems);

        if (user.key) {
            const targetRef = ref(db, `targets/${user.key}`);
            onValue(targetRef, (snapshot) => {
                if (snapshot.exists()) {
                    const data = snapshot.val() as UserTarget;
                    const now = new Date();
                    const currentMonth = `${now.getFullYear()}-${now.getMonth() + 1}`;

                    if (data.lastResetMonth !== currentMonth) {
                        const historyRef = ref(db, `target_history/${user.key}`);
                        push(historyRef, {
                            userId: data.userId,
                            employeeName: data.employeeName,
                            month: data.lastResetMonth,
                            targetAmount: data.finalTarget,
                            achievedAmount: data.achieved
                        });

                        update(targetRef, {
                            achieved: 0,
                            lastResetMonth: currentMonth
                        });
                    } else {
                        setUserTarget(data);
                    }
                } else {
                    setUserTarget(null);
                }
            });
        }
    }, [user.key, user.name]);

    const updateItem = (id: string, field: string, value: any) => {
        setSalesItems(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    const deleteItem = (id: string) => {
        if (confirm("هل تريد حذف هذا الصنف من القائمة الحالية؟")) {
            setSalesItems(prev => prev.filter(i => i.id !== id));
        }
    };

    const startEditingName = (id: string, currentName: string) => {
        setEditingItemId(id);
        setTempName(currentName);
    };

    const saveName = (id: string) => {
        const containsArabic = /[\u0600-\u06FF]/.test(tempName);
        if (containsArabic) {
            alert("يرجى كتابة اسم الصنف باللغة الإنجليزية فقط");
            return;
        }
        setSalesItems(prev => prev.map(i => i.id === id ? { ...i, name: tempName } : i));
        setEditingItemId(null);
    };

    const addCustomItem = (category: string) => {
        const newItemName = prompt("ادخل اسم الصنف الجديد (English Only):");
        if (newItemName) {
            const containsArabic = /[\u0600-\u06FF]/.test(newItemName);
            if (containsArabic) {
                alert("يرجى كتابة اسم الصنف باللغة الإنجليزية فقط");
                return;
            }

            setSalesItems(prev => [
                ...prev,
                {
                    id: newItemName + "_" + Date.now(),
                    name: newItemName,
                    price: 0,
                    qty: 0,
                    category,
                    isCustom: true
                }
            ]);
        }
    };

    const currentTotal = salesItems.reduce((sum, item) => sum + ((item.price || 0) * (item.qty || 0)), 0);

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const sold = salesItems.filter(i => i.qty > 0 && i.price > 0);
        if (!sold.length) return alert("أدخل بيانات صحيحة");

        await push(ref(db, 'sales'), {
            market: selectedMarket,
            employeeName: user.name,
            username: user.username,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: sold,
            total: currentTotal
        });

        if (user.key && userTarget) {
            const targetRef = ref(db, `targets/${user.key}`);
            const newAchieved = (userTarget.achieved || 0) + currentTotal;
            await update(targetRef, { achieved: newAchieved });
        }

        alert("تم الحفظ بنجاح");
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
    };

    const remaining = userTarget ? Math.max(0, userTarget.finalTarget - userTarget.achieved) : 0;
    const progressPercent = userTarget ? Math.min(100, Math.round((userTarget.achieved / userTarget.finalTarget) * 100)) : 0;

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h2 className="text-2xl font-bold text-white">المبيعات اليومية</h2>

                <div className="flex flex-wrap gap-4">
                    <div className="bg-blue-600/20 border border-blue-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[200px]">
                        <div className="bg-blue-600 p-2 rounded-2xl text-white">
                            <Calculator size={24} />
                        </div>
                        <div>
                            <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">إجمالي المبيعات الحالية</div>
                            <div className="text-2xl font-black text-blue-400">
                                {currentTotal.toLocaleString()} <span className="text-xs">ج.م</span>
                            </div>
                        </div>
                    </div>

                    {userTarget && (
                        <div className="bg-purple-600/20 border border-purple-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[280px]">
                            <div className="bg-purple-600 p-2 rounded-2xl text-white">
                                <Target size={24} />
                            </div>
                            <div className="flex-1">
                                <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">متابعة التارجت ( {userTarget.finalTarget.toLocaleString()} ج.م )</div>
                                <div className="flex justify-between items-end">
                                    <div className="text-lg font-black text-purple-400">
                                        المتبقي: {remaining.toLocaleString()}
                                    </div>
                                    <div className="text-sm font-bold text-green-400">
                                        {progressPercent}%
                                    </div>
                                </div>
                                <div className="w-full bg-black/40 h-1.5 rounded-full mt-1 overflow-hidden">
                                    <div className="bg-green-500 h-full transition-all duration-1000" style={{ width: `${progressPercent}%` }}></div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            <select className="w-full p-4 rounded-2xl bg-gray-800 text-white border border-white/10" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                <option value="">اختر الماركت من القائمة...</option>
                {markets.map(m => <option key={m} value={m}>{m}</option>)}
            </select>

            {[
                { label: 'مناديل السحب (Facial)', key: 'Facial' },
                { label: 'مناديل المطبخ (Kitchen)', key: 'Kitchen' },
                { label: 'تواليت (Toilet)', key: 'Toilet' },
                { label: 'دولفن (Dolphin)', key: 'Dolphin' }
            ].map(cat => (
                <div key={cat.key} className="bg-gray-800 p-4 rounded-3xl border border-white/5 shadow-xl">
                    <div className="flex justify-between items-center mb-4 border-b border-white/10 pb-2">
                        <h3 className="font-bold text-blue-400">{cat.label}</h3>
                        <button 
                            onClick={() => addCustomItem(cat.key)}
                            className="bg-green-600 text-white px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-1 shadow-lg active:scale-95 transition"
                        >
                            <Plus size={14}/> أضف صنف
                        </button>
                    </div>

                    <div className="grid grid-cols-12 gap-2 mb-2 px-2 text-[10px] font-black opacity-60 uppercase text-white">
                        <div className="col-span-4 pr-2">الصنف</div>
                        <div className="col-span-2 text-center">السعر</div>
                        <div className="col-span-2 text-center">الكمية</div>
                        <div className="col-span-2 text-center">المجموع</div>
                        <div className="col-span-2 text-center">إجراء</div>
                    </div>

                    <div className="space-y-2">
                        {salesItems.filter(i => i.category === cat.key).map(item => (
                            <div key={item.id} className="grid grid-cols-12 gap-2 items-center bg-black/20 p-2 rounded-2xl border border-transparent hover:border-white/10 transition">
                                <div className="col-span-4 pr-2 font-bold text-white">
                                    {editingItemId === item.id ? (
                                        <div className="flex gap-1">
                                            <input 
                                                type="text" 
                                                className="w-full bg-gray-700 border border-blue-500/50 p-1.5 rounded-lg text-white text-[10px] font-bold"
                                                value={tempName}
                                                onChange={e => setTempName(e.target.value)}
                                                autoFocus
                                            />
                                            <button onClick={() => saveName(item.id)} className="text-green-400 p-1 hover:bg-green-400/10 rounded"><Check size={14}/></button>
                                            <button onClick={() => setEditingItemId(null)} className="text-red-400 p-1 hover:bg-red-400/10 rounded"><X size={14}/></button>
                                        </div>
                                    ) : (
                                        <span className="text-[11px] truncate block" title={item.name}>{item.name}</span>
                                    )}
                                </div>
                                <div className="col-span-2">
                                    <input type="number" placeholder="0" className="w-full bg-gray-700 border border-white/10 p-2 rounded-xl text-white text-center text-xs font-bold" value={item.price || ''} onChange={e => updateItem(item.id, 'price', parseFloat(e.target.value))} />
                                </div>
                                <div className="col-span-2">
                                    <input type="number" placeholder="0" className="w-full bg-gray-700 border border-white/10 p-2 rounded-xl text-white text-center text-xs font-bold" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} />
                                </div>
                                <div className="col-span-2 text-center font-black text-xs text-green-400">
                                    {((item.price || 0) * (item.qty || 0)).toLocaleString()}
                                </div>
                                <div className="col-span-2 flex justify-center gap-1">
                                    {user.role === 'admin' && editingItemId !== item.id && (
                                        <button onClick={() => startEditingName(item.id, item.name)} className="p-2 text-blue-400 hover:bg-blue-400/10 rounded-xl transition" title="تعديل المسمى">
                                            <Edit size={14} />
                                        </button>
                                    )}
                                    <button onClick={() => deleteItem(item.id)} className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition" title="حذف">
                                        <Trash2 size={14} />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 hover:bg-green-700 text-white py-4 rounded-3xl font-black shadow-2xl flex justify-center items-center gap-2 transform active:scale-95 transition">
                    <Save size={20} /> حفظ وترحيل المبيعات
                </button>
            </div>
        </div>
    );
};

export default DailySales;

