        if(filtered.length === 0) return alert("لا توجد بيانات تطابق الاختيارات المختارة");

        const exportData = filtered.map(h => ({
            "اسم الموظف": h.employeeName,
            "تاريخ العملية": h.date,
            "النوع": typeLabels[h.type],
            "عدد الأيام": h.days
