                            <CalendarPlus size={18} /> تسجيل إجازة/غياب
                        </button>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {displayedUsers.map(u => {
                    const balance = balances[u.key!] || {
