import React, { useState, useEffect } from 'react';
import { ref, push, set, onValue } from "firebase/database";
import { db } from '../firebase';
import { User } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

interface InventoryItem {
    id: string;
    name: string;
    qty: number;
    category: string;
    isCustom: boolean;
}

const InventoryRegistration: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [items, setItems] = useState<InventoryItem[]>([]);

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial', allowAdd: true },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen', allowAdd: true },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet', allowAdd: false },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin', allowAdd: true },
    ];

    useEffect(() => {
        const baseItems: InventoryItem[] = [];
        allCategories.forEach(cat => {
            cat.items.forEach(prod => {
                baseItems.push({
                    id: prod,
                    name: prod,
                    qty: 0,
                    category: cat.key,
                    isCustom: false
                });
            });
        });

        // مزامنة الأصناف المخصصة من قاعدة البيانات
        onValue(ref(db, 'settings/global_products'), (snapshot) => {
            const extra: InventoryItem[] = [];
            if (snapshot.exists()) {
                const data = snapshot.val();
                Object.keys(data).forEach(cat => {
                    Object.values(data[cat]).forEach((p: any) => {
                        extra.push({ ...p, qty: 0 });
                    });
                });
            }
            const combined = [...baseItems];
            extra.forEach(ex => {
                const idx = combined.findIndex(c => c.id === ex.id || c.name === ex.name);
                if (idx > -1) combined[idx] = ex;
                else combined.push(ex);
            });
            setItems(combined);
        });
    }, []);

    const updateItem = (id: string, field: 'qty' | 'name', value: any) => {
        setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const handleAddCustomItem = async (category: string) => {
        if (user.role !== 'admin') return alert("إضافة الأصناف للمسؤول فقط");
        const name = prompt("ادخل اسم الصنف الجديد للمخزون (English Only):");
        if (name) {
            const containsArabic = /[\u0600-\u06FF]/.test(name);
            if (containsArabic) return alert("الإنجليزية فقط");

            const id = `custom_${Date.now()}`;
            await set(ref(db, `settings/global_products/${category}/${id}`), { id, name, category, isCustom: true });
            alert("تمت الإضافة والمزامنة");
        }
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const inventoryData = {
            market: selectedMarket,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: items.filter(i => i.qty > 0).map(i => ({ name: i.name, qty: i.qty, category: i.category }))
        };
        if (inventoryData.items.length === 0) return alert("الكميات كلها صفر");
        await push(ref(db, 'inventory'), inventoryData);
        alert("تم حفظ المخزون");
        setItems(prev => prev.map(i => ({...i, qty: 0})));
    };

    return (
        <div className="pb-20">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold">تسجيل المخزون</h2>
                <select className="w-48 bg-gray-700 text-white border border-white/20 p-2.5 rounded-xl font-bold" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                    <option value="">اختر الماركت</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            {allCategories.map(cat => (
                <div key={cat.key} className="mb-6 bg-white/5 p-4 rounded-lg">
                    <div className="flex justify-between items-center mb-4 border-b border-gray-500/20 pb-2">
                        <h3 className="text-xl font-bold text-blue-500">{cat.name}</h3>
                        {user.role === 'admin' && cat.allowAdd && (
                             <button onClick={() => handleAddCustomItem(cat.key)} className="bg-green-600 hover:bg-green-700 text-white text-xs px-3 py-1.5 rounded flex items-center gap-1 shadow"><Plus size={14}/> أضف صنف</button>
                        )}
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {items.filter(i => i.category === cat.key).map((item) => (
                            <div key={item.id} className="flex justify-between items-center gap-2 p-2 border-b border-gray-500/10">
                                <span className="text-sm font-medium text-white">{item.name}</span>
                                <input type="number" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} className="bg-white/10 border border-white/20 p-2 rounded text-white w-20 text-center" placeholder="الكمية" />
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 hover:bg-green-700 text-white py-4 rounded-3xl font-bold shadow-2xl flex justify-center items-center gap-2 active:scale-95 transition">
                    <Save size={20} /> حفظ المخزون
                </button>
            </div>
        </div>
    );
};

export default InventoryRegistration;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue } from "firebase/database";
import { User } from '../types';
import { COMPANIES, PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, FINE_FACIAL, FINE_KITCHEN, FINE_TOILET, ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET, PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET, WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET } from '../constants';
import { Save, Plus } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [items, setItems] = useState<{category: string, name: string, price: number, isCustom?: boolean, id?: string}[]>([]);

    useEffect(() => {
        if (!selectedCompany) return;

        const generateBase = (facial: string[], kitchen: string[], toilet: string[]) => {
            return [
                ...facial.map(n => ({ category: 'Facial', name: n, price: 0, id: n })),
                ...kitchen.map(n => ({ category: 'Kitchen', name: n, price: 0, id: n })),
                ...toilet.map(n => ({ category: 'Toilet', name: n, price: 0, id: n })),
            ];
        };

        let base: any[] = [];
        switch(selectedCompany) {
            case 'Soft Rose': base = generateBase(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET); break;
            case 'Fine': base = generateBase(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET); break;
            case 'Zeina': base = generateBase(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET); break;
            case 'Papia Familia': base = generateBase(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET); break;
            case 'White': base = generateBase(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET); break;
            default: base = []; break;
        }

        // إذا كانت الشركة سوفت روز، نقوم بمزامنة الأصناف المخصصة
        if (selectedCompany === 'Soft Rose') {
            onValue(ref(db, 'settings/global_products'), (snap) => {
                if (snap.exists()) {
                    const extra: any[] = [];
                    const data = snap.val();
                    Object.keys(data).forEach(cat => {
                        Object.values(data[cat]).forEach((p: any) => extra.push({...p, price: 0}));
                    });
                    const combined = [...base];
                    extra.forEach(ex => {
                        const idx = combined.findIndex(c => c.id === ex.id || c.name === ex.name);
                        if (idx > -1) combined[idx] = ex;
                        else combined.push(ex);
                    });
                    setItems(combined);
                } else {
                    setItems(base);
                }
            });
        } else {
            setItems(base);
        }
    }, [selectedCompany]);

    const addCustomItem = async (category: string) => {
        if (user.role !== 'admin') return alert("إضافة الأصناف للمسؤول فقط");
        const name = prompt("ادخل اسم صنف المنافس الجديد (English Only):");
        if (name) {
            if (/[\u0600-\u06FF]/.test(name)) return alert("الإنجليزية فقط");

            if (selectedCompany === 'Soft Rose') {
                const id = `custom_${Date.now()}`;
                await set(ref(db, `settings/global_products/${category}/${id}`), { id, name, category, isCustom: true });
                alert("تمت الإضافة والمزامنة");
            } else {
                setItems(prev => [...prev, { category, name, price: 0, isCustom: true }]);
            }
        }
    };

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const validItems = items.filter(i => i.price > 0);
        if (validItems.length === 0) return alert("يرجى إدخال الأسعار");

        await push(ref(db, 'competitor_prices'), {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: validItems
        });
        alert("تم الحفظ بنجاح");
        setItems(prev => prev.map(i => ({...i, price: 0})));
    };

    return (
        <div className="space-y-6 pb-20">
            <h2 className="text-2xl font-bold text-white">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-800 p-6 rounded-3xl border border-white/10">
                <select className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                    <option value="">اختر الماركت...</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <select className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10" value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                    <option value="">اختر الشركة...</option>
                    {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {items.length > 0 && ['Facial', 'Kitchen', 'Toilet'].map(cat => (
                    <div key={cat} className="bg-gray-800 p-4 rounded-3xl border border-white/5">
                        <div className="flex justify-between items-center mb-3 border-b border-white/10 pb-2">
                            <h3 className="font-bold text-blue-400">{cat}</h3>
                            {user.role === 'admin' && (
                                <button onClick={() => addCustomItem(cat)} className="bg-green-600 text-white px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-1 active:scale-95 transition">
                                    <Plus size={14}/> أضف صنف
                                </button>
                            )}
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                            {items.filter(i => i.category === cat).map((item, idx) => (
                                <div key={idx} className="flex items-center gap-2 bg-black/20 p-2 rounded-xl">
                                    <span className="flex-1 text-xs text-white font-bold truncate">{item.name}</span>
                                    <input type="number" placeholder="السعر" className="w-24 p-2 bg-gray-700 rounded-lg text-white text-center text-xs font-black" value={item.price || ''} onChange={e => {
                                        const newItems = [...items];
                                        const actualIdx = items.findIndex(it => it.name === item.name);
                                        newItems[actualIdx].price = parseFloat(e.target.value) || 0;
                                        setItems(newItems);
                                    }} />
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSaveReport} className="bg-green-600 hover:bg-green-700 w-full py-5 text-white rounded-3xl font-black shadow-2xl flex items-center justify-center gap-2 transform active:scale-95 transition">
                    <Save size={20}/> حفظ وترحيل أسعار المنافسين
                </button>
            </div>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { 
    Trash2, Edit, CalendarPlus, X, Save, History, 
    ChevronRight, ChevronLeft, CheckCircle2, AlertCircle, Calendar as CalendarIcon,
    User as UserIcon, FileSpreadsheet, Printer
} from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<Record<string, LeaveBalance>>({});
    const [usersList, setUsersList] = useState<User[]>([]);
    const [allHistory, setAllHistory] = useState<({id: string} & LeaveRecord)[]>([]);

    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showHistoryDetailsModal, setShowHistoryDetailsModal] = useState(false);
    const [showExportModal, setShowExportModal] = useState(false);
    const [showEditBalanceModal, setShowEditBalanceModal] = useState<LeaveBalance | null>(null);
    const [editingLeaveRecord, setEditingLeaveRecord] = useState<({id: string} & LeaveRecord) | null>(null);

    const [selectedEmployeeForExport, setSelectedEmployeeForExport] = useState<string>('all');
    const [exportStartDate, setExportStartDate] = useState<string>('');
    const [exportEndDate, setExportEndDate] = useState<string>('');

    // دورة الإجازات
    const [periodDate, setPeriodDate] = useState<Date>(() => {
        const now = new Date();
        return now.getDate() >= 21 ? new Date(now.getFullYear(), now.getMonth(), 21) : new Date(now.getFullYear(), now.getMonth() - 1, 21);
    });

    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams' | 'unpaid'>('annual');
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);

    const typeLogic = { annual: 'remaining', casual: 'remaining', sick: 'accrued', exams: 'accrued', unpaid: 'accrued' };
    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات', unpaid: 'غياب بدون إذن' };
    const typeColors = { annual: 'text-green-400', casual: 'text-yellow-400', sick: 'text-red-400', exams: 'text-purple-400', unpaid: 'text-orange-400' };

    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: User[] = [];
                snapshot.forEach(c => { u.push({ key: c.key!, ...c.val() }); });
                setUsersList(u);
            }
        });

        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val() as Record<string, LeaveBalance>;
                setBalances(data);

                const now = new Date();
                const currentMonthKey = `${now.getFullYear()}-${now.getMonth() + 1}`;
                if (now.getDate() >= 21) {
                    Object.keys(data).forEach(async (uKey) => {
                        const balance = data[uKey];
                        if (balance.lastUnpaidReset !== currentMonthKey) {
                            await update(ref(db, `leave_balances/${uKey}`), { unpaid: 0, lastUnpaidReset: currentMonthKey });
                        }
                    });
                }
            } else { setBalances({}); }
        });

        onValue(ref(db, 'leave_history'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                const h: any = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                setAllHistory(h);
            } else { setAllHistory([]); }
        });
    }, []);

    const getPeriodEnd = (start: Date) => {
        const end = new Date(start);
        end.setMonth(end.getMonth() + 1);
        end.setDate(20);
        return end;
    };

    const formatDateFull = (date: Date) => {
        const d = date.getDate();
        const m = date.getMonth() + 1;
        const y = date.getFullYear();
        return `${d}/${m}/${y}`;
    };

    const changePeriod = (direction: number) => {
        const next = new Date(periodDate);
        next.setMonth(next.getMonth() + direction);
        setPeriodDate(next);
    };

    const filterHistoryByPeriodAndUser = (userId: string) => {
        const pStart = new Date(periodDate); pStart.setHours(0,0,0,0);
        const pEnd = getPeriodEnd(periodDate); pEnd.setHours(23,59,59,999);
        return allHistory.filter(r => r.userId === userId && new Date(r.date) >= pStart && new Date(r.date) <= pEnd);
    };

    const handleDeleteRecord = async (id: string, record: LeaveRecord) => {
        if(!confirm("حذف السجل وإعادة الرصيد للموظف؟")) return;
        const balanceRef = ref(db, `leave_balances/${record.userId}`);
        const snap = await get(balanceRef);
        if(snap.exists()) {
            const bal = snap.val();
            const multiplier = typeLogic[record.type] === 'remaining' ? 1 : -1;
            await update(balanceRef, { [record.type]: (Number(bal[record.type]) || 0) + (multiplier * Number(record.days)) });
        }
        await remove(ref(db, `leave_history/${id}`));
        alert("تم الحذف بنجاح");
    };

    const handleUpdateRecord = async () => {
        if(!editingLeaveRecord) return;
        // هنا نحتاج منطق عكس التأثير القديم وإضافة التأثير الجديد
        const old = allHistory.find(h => h.id === editingLeaveRecord.id);
        if(!old) return;

        const balanceRef = ref(db, `leave_balances/${editingLeaveRecord.userId}`);
        const snap = await get(balanceRef);
        if(snap.exists()) {
            const bal = snap.val();
            // عكس القديم
            let midVal = bal[old.type];
            if(typeLogic[old.type] === 'remaining') midVal += old.days; else midVal -= old.days;
            // تطبيق الجديد
            if(typeLogic[editingLeaveRecord.type] === 'remaining') midVal -= editingLeaveRecord.days; else midVal += editingLeaveRecord.days;

            await update(balanceRef, { [editingLeaveRecord.type]: midVal });
            await update(ref(db, `leave_history/${editingLeaveRecord.id}`), {
                days: editingLeaveRecord.days,
                type: editingLeaveRecord.type,
                date: editingLeaveRecord.date,
                timestamp: new Date(editingLeaveRecord.date).getTime()
            });
            alert("تم التعديل بنجاح");
            setEditingLeaveRecord(null);
        }
    };

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate) return alert("اكمل البيانات");
        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;
        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        const snap = await get(balanceRef);
        let cur = snap.exists() ? snap.val() : { userId: selectedUser, employeeName: targetUser.name, annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };
        let newValue = (typeLogic[leaveType] === 'remaining') ? (Number(cur[leaveType] || 0) - Number(leaveDays)) : (Number(cur[leaveType] || 0) + Number(leaveDays));
        await update(balanceRef, { ...cur, [leaveType]: newValue });
        await push(ref(db, 'leave_history'), { userId: selectedUser, employeeName: targetUser.name, date: leaveDate, days: Number(leaveDays), type: leaveType, timestamp: new Date(leaveDate).getTime() });
        setShowAddLeaveModal(false); alert("تم التسجيل بنجاح");
    };

    return (
        <div className="space-y-6">
            <div className="flex flex-col md:flex-row justify-between items-center gap-4">
                <h2 className="text-2xl font-bold flex items-center gap-2 text-white"><History className="text-blue-500" /> رصيد الإجازات والغياب</h2>
                {user.role === 'admin' && (
                    <div className="flex gap-2">
                        <button onClick={() => setShowExportModal(true)} className="bg-green-600 text-white px-5 py-2.5 rounded-2xl font-bold flex items-center gap-2 transition"><FileSpreadsheet size={18} /> تصدير</button>
                        <button onClick={() => setShowAddLeaveModal(true)} className="bg-red-600 text-white px-5 py-2.5 rounded-2xl font-bold flex items-center gap-2 transition"><CalendarPlus size={18} /> تسجيل</button>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {displayedUsers.map(u => {
                    const balance = balances[u.key!] || { userId: u.key!, employeeName: u.name, annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };
                    return (
                        <div key={u.key} className="p-5 rounded-3xl border border-white/10 bg-gray-800 text-white shadow-xl relative overflow-hidden">
                            <div className="flex justify-between items-start mb-4">
                                <div><div className="font-bold text-lg text-blue-400">{u.name}</div><div className="text-[10px] opacity-40">@{u.username}</div></div>
                                <div className="flex gap-1">
                                    {user.role === 'admin' && (
                                        <button onClick={() => setShowEditBalanceModal(balance)} className="p-1.5 bg-white/5 text-blue-400 rounded-lg"><Edit size={14}/></button>
                                    )}
                                    <button onClick={() => { setHistoryUserView({userId: u.key!, name: u.name}); setShowHistoryDetailsModal(true); }} className="text-[10px] font-bold bg-white/5 px-3 py-1.5 rounded-xl">السجل</button>
                                </div>
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                {Object.entries(typeLabels).map(([key, label]) => (
                                    <div key={key} className="p-3 bg-black/20 rounded-2xl border border-white/5 flex flex-col items-center">
                                        <span className="text-[10px] opacity-50 font-black text-white text-center h-6">{label}</span>
                                        <span className={`text-xl font-black ${typeColors[key as keyof typeof typeColors]}`}>{(balance as any)[key] || 0}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>

            {showHistoryDetailsModal && historyUserView && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
                    <div className="w-full max-w-2xl p-6 rounded-3xl border border-white/10 bg-gray-900 text-white flex flex-col max-h-[90vh]">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold text-white">{historyUserView.name}</h3>
                            <button onClick={() => setShowHistoryDetailsModal(false)} className="text-white"><X/></button>
                        </div>
                        <div className="flex items-center justify-between bg-black/30 p-4 rounded-2xl border border-white/5 mb-6">
                            <button onClick={() => changePeriod(-1)}><ChevronRight/></button>
                            <div className="text-center">
                                <div className="text-[10px] font-black opacity-40 uppercase tracking-widest mb-1">دورة الشهر</div>
                                <div className="text-sm font-bold flex items-center gap-2">
                                    {formatDateFull(periodDate)} <span className="opacity-40">إلى</span> {formatDateFull(getPeriodEnd(periodDate))}
                                </div>
                            </div>
                            <button onClick={() => changePeriod(1)}><ChevronLeft/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-3 pr-1 custom-scrollbar">
                            {filterHistoryByPeriodAndUser(historyUserView.userId).map(rec => (
                                <div key={rec.id} className="p-4 rounded-2xl border bg-black/20 border-white/5 flex justify-between items-center group">
                                    <div className="flex items-center gap-3">
                                        <div><div className="font-bold text-sm text-white">{typeLabels[rec.type]}</div><div className="text-[10px] opacity-50">{rec.date}</div></div>
                                    </div>
                                    <div className="flex items-center gap-4">
                                        <div className="font-black text-lg text-white">{rec.days} يوم</div>
                                        {user.role === 'admin' && (
                                            <div className="flex gap-2">
                                                <button onClick={() => setEditingLeaveRecord({...rec})} className="p-2 text-blue-400 hover:bg-blue-400/10 rounded-lg transition"><Edit size={16}/></button>
                                                <button onClick={() => handleDeleteRecord(rec.id, rec)} className="p-2 text-red-400 hover:bg-red-400/20 rounded-lg transition"><Trash2 size={16}/></button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {editingLeaveRecord && (
                <div className="fixed inset-0 z-[200] bg-black/90 flex items-center justify-center p-4 backdrop-blur-md">
                    <div className="bg-gray-900 p-6 rounded-3xl border border-white/20 w-full max-w-sm">
                        <h4 className="font-bold text-lg text-white mb-6">تعديل سجل الإجازة</h4>
                        <div className="space-y-4">
                            <input type="date" className="w-full p-3 rounded-xl bg-gray-800 text-white border border-white/10" value={editingLeaveRecord.date} onChange={e => setEditingLeaveRecord({...editingLeaveRecord, date: e.target.value})} />
                            <input type="number" step="0.5" className="w-full p-3 rounded-xl bg-gray-700 text-white border border-white/10 text-center font-black" value={editingLeaveRecord.days} onChange={e => setEditingLeaveRecord({...editingLeaveRecord, days: parseFloat(e.target.value)})} />
                            <select className="w-full p-3 rounded-xl bg-gray-700 text-white" value={editingLeaveRecord.type} onChange={e => setEditingLeaveRecord({...editingLeaveRecord, type: e.target.value as any})}>
                                {Object.entries(typeLabels).map(([k,v]) => <option key={k} value={k}>{v}</option>)}
                            </select>
                            <div className="flex gap-2 pt-4">
                                <button onClick={handleUpdateRecord} className="flex-1 bg-blue-600 py-3 rounded-xl font-bold flex justify-center items-center gap-2"><Save size={18}/> حفظ</button>
                                <button onClick={() => setEditingLeaveRecord(null)} className="flex-1 bg-white/5 py-3 rounded-xl font-bold">إلغاء</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* بقية المودالات (تصدير، رصيد، إضافة) تبقى كما هي مع التعديلات البرمجية الضرورية */}
        </div>
    );
};

export default LeaveBalanceComponent;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings, UserPermissions, AppNotification } from '../types';
import { 
  Save, Trash2, UserPlus, Shield, Edit2, Plus, X, 
  Settings as SettingsIcon, Users, MapPin, Building2, 
  ToggleLeft, ToggleRight, Key, Send, LayoutGrid
} from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<User[]>([]);
    const [newUser, setNewUser] = useState<User>({ 
        name: '', username: '', password: '', role: 'user', canViewAllSales: false,
        permissions: { showSalesLog: true, showInventoryLog: false, showInventoryReg: false, showCompetitorReports: false, showDailySales: true, showCompetitorPrices: true }
    });

    const [marketList, setMarketList] = useState<{key: string, name: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, name: string}[]>([]);
    const [newMarketName, setNewMarketName] = useState('');
    const [newCompanyName, setNewCompanyName] = useState('');

    const [passModal, setPassModal] = useState<{key: string, name: string} | null>(null);
    const [permModal, setPermModal] = useState<User | null>(null);
    const [notifModal, setNotifModal] = useState<{username: string, name: string} | null>(null);
    const [newPass, setNewPass] = useState('');
    const [notifMsg, setNotifMsg] = useState('');

    useEffect(() => {
        if (user.role !== 'admin') return;
        onValue(ref(db, 'users'), s => {
            if (s.exists()) {
                const u: User[] = []; s.forEach(c => { u.push({ key: c.key || '', ...c.val() }); });
                setUsers(u);
            }
        });
        onValue(ref(db, 'settings/markets'), s => {
            const m: any[] = []; if(s.exists()){ s.forEach(c => { m.push({ key: c.key, name: c.val() }); }); }
            setMarketList(m);
        });
        onValue(ref(db, 'settings/companies'), s => {
            const c: any[] = []; if(s.exists()){ s.forEach(k => { c.push({ key: k.key, name: k.val() }); }); }
            setCompanyList(c);
        });
    }, [user.role]);

    const addMarket = async () => {
        if(!newMarketName) return;
        await push(ref(db, 'settings/markets'), newMarketName);
        setNewMarketName(''); alert("تمت إضافة الماركت");
    };

    const deleteMarket = async (key: string) => {
        if(confirm("حذف الماركت من القوائم؟ (لن يحذف مبيعاته القديمة)")) {
            await remove(ref(db, `settings/markets/${key}`));
        }
    };

    const addCompany = async () => {
        if(!newCompanyName) return;
        await push(ref(db, 'settings/companies'), newCompanyName);
        setNewCompanyName(''); alert("تمت إضافة الشركة");
    };

    const deleteCompany = async (key: string) => {
        if(confirm("حذف الشركة؟")) await remove(ref(db, `settings/companies/${key}`));
    };

    const toggleUserPerm = (key: keyof UserPermissions) => {
        if (!permModal) return;
        const current = permModal.permissions || { showSalesLog: false, showInventoryLog: false, showInventoryReg: false, showCompetitorReports: false, showDailySales: true, showCompetitorPrices: true };
        setPermModal({ ...permModal, permissions: { ...current, [key]: !current[key] } });
    };

    const sectionClass = "p-6 rounded-2xl mb-6 bg-gray-800 border-gray-700 border text-white";
    const inputClass = "w-full p-2.5 rounded-lg bg-gray-700 text-white border border-white/10 outline-none";

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-20">
            <h2 className="text-3xl font-bold text-white flex items-center gap-3"><SettingsIcon className="text-blue-600"/> لوحة تحكم المسؤول</h2>

            {/* إدارة الماركتات والشركات */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className={sectionClass}>
                    <h3 className="font-bold mb-4 flex items-center gap-2 text-blue-400 border-b border-white/10 pb-2"><MapPin size={18}/> إدارة الماركتات</h3>
                    <div className="flex gap-2 mb-4">
                        <input className={inputClass} placeholder="اسم ماركت جديد..." value={newMarketName} onChange={e => setNewMarketName(e.target.value)} />
                        <button onClick={addMarket} className="bg-blue-600 px-4 rounded-xl transition active:scale-95"><Plus/></button>
                    </div>
                    <div className="space-y-2 max-h-48 overflow-y-auto custom-scrollbar">
                        {marketList.map(m => (
                            <div key={m.key} className="flex justify-between items-center bg-white/5 p-2 rounded-xl px-4 border border-white/5">
                                <span className="text-sm font-bold truncate">{m.name}</span>
                                <button onClick={() => deleteMarket(m.key)} className="text-red-400 hover:text-red-500"><Trash2 size={16}/></button>
                            </div>
                        ))}
                    </div>
                </div>

                <div className={sectionClass}>
                    <h3 className="font-bold mb-4 flex items-center gap-2 text-purple-400 border-b border-white/10 pb-2"><Building2 size={18}/> إدارة الشركات</h3>
                    <div className="flex gap-2 mb-4">
                        <input className={inputClass} placeholder="اسم شركة منافسة..." value={newCompanyName} onChange={e => setNewCompanyName(e.target.value)} />
                        <button onClick={addCompany} className="bg-purple-600 px-4 rounded-xl transition active:scale-95"><Plus/></button>
                    </div>
                    <div className="space-y-2 max-h-48 overflow-y-auto custom-scrollbar">
                        {companyList.map(c => (
                            <div key={c.key} className="flex justify-between items-center bg-white/5 p-2 rounded-xl px-4 border border-white/5">
                                <span className="text-sm font-bold truncate">{c.name}</span>
                                <button onClick={() => deleteCompany(c.key)} className="text-red-400 hover:text-red-500"><Trash2 size={16}/></button>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

            {/* بقية الإعدادات (المستخدمين، التطبيق) */}
            <div className={sectionClass}>
                <h3 className="text-xl font-bold mb-6 flex items-center gap-2 text-green-500 border-b pb-3"><Users size={20} /> إدارة الموظفين</h3>
                {/* ... عرض المستخدمين كما كان مع مراعاة الحفاظ على الكود ... */}
                <div className="overflow-x-auto">
                    <table className="w-full text-sm text-right">
                        <thead className="bg-gray-700">
                            <tr><th className="p-3 text-white">الاسم</th><th className="p-3 text-white">المستخدم</th><th className="p-3 text-center text-white">الإجراءات</th></tr>
                        </thead>
                        <tbody>
                            {users.map(u => (
                                <tr key={u.key} className="border-b border-gray-700 hover:bg-black/10">
                                    <td className="p-3 font-bold text-white">{u.name}</td>
                                    <td className="p-3 opacity-70 text-white">{u.username}</td>
                                    <td className="p-3 flex justify-center gap-2">
                                        <button onClick={() => setPermModal(u)} className="p-2 text-blue-400"><Shield size={16}/></button>
                                        <button onClick={() => setPassModal({key: u.key!, name: u.name})} className="p-2 text-orange-400"><Key size={16}/></button>
                                        <button onClick={() => remove(ref(db, `users/${u.key!}`))} className="p-2 text-red-400"><Trash2 size={16}/></button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>

            {permModal && (
                <div className="fixed inset-0 z-[110] bg-black/80 flex items-center justify-center p-4">
                    <div className="bg-gray-900 p-6 rounded-2xl border border-white/10 w-full max-w-lg">
                        <h4 className="font-bold mb-6 text-white border-b pb-2">تعديل صلاحيات: {permModal.name}</h4>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-6">
                            {[
                                { key: 'showDailySales', label: 'المبيعات اليومية' },
                                { key: 'showSalesLog', label: 'سجل المبيعات' },
                                { key: 'showInventoryReg', label: 'تسجيل المخزون' },
                                { key: 'showInventoryLog', label: 'سجل المخزون' },
                                { key: 'showCompetitorPrices', label: 'أسعار المنافسين' },
                                { key: 'showCompetitorReports', label: 'تقارير المنافسين' }
                            ].map(item => (
                                <button key={item.key} onClick={() => toggleUserPerm(item.key as any)} className={`p-3 rounded-xl border text-sm font-bold flex justify-between items-center transition ${ (permModal.permissions as any)?.[item.key] ? 'bg-blue-600 border-blue-500 text-white' : 'bg-white/5 border-white/5 text-white/40'}`}>
                                    {item.label}
                                    {(permModal.permissions as any)?.[item.key] ? <ToggleRight/> : <ToggleLeft/>}
                                </button>
                            ))}
                        </div>
                        <button onClick={async () => { await update(ref(db, `users/${permModal.key}`), { permissions: permModal.permissions }); setPermModal(null); alert("تم الحفظ"); }} className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold">حفظ الصلاحيات</button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Settings;

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove, update, get, set, push } from "firebase/database";
import { User, SaleRecord, ProductItem, UserTarget, TargetHistory } from '../types';
import { 
    Trash2, Edit, FileSpreadsheet, Save, X, Calendar, User as UserIcon, TrendingUp, Star, Trophy, Download, Filter, Target, History, Copy, Search, Package, ShoppingBag, Calculator, LayoutGrid
} from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [usersList, setUsersList] = useState<User[]>([]);
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    const [editingSale, setEditingSale] = useState<SaleRecord | null>(null);
    const [showExportModal, setShowExportModal] = useState(false);
    const [exportStart, setExportStart] = useState('');
    const [exportEnd, setExportEnd] = useState('');
    const [exportMarket, setExportMarket] = useState('all');

    useEffect(() => {
        onValue(ref(db, 'sales'), (snapshot) => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                let list: SaleRecord[] = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                if (user.role !== 'admin' && !user.canViewAllSales) list = list.filter(s => s.employeeName === user.name);
                setSales(list.sort((a, b) => b.timestamp - a.timestamp));
            } else setSales([]);
        });
        if (user.role === 'admin') {
            onValue(ref(db, 'users'), (snap) => {
                if (snap.exists()) {
                    const list: User[] = []; snap.forEach(child => { list.push({ key: child.key!, ...child.val() }); });
                    setUsersList(list);
                }
            });
        }
    }, [user]);

    useEffect(() => {
        let res = sales;
        if (filterDate) res = res.filter(s => s.date.includes(filterDate));
        if (filterEmployee) res = res.filter(s => s.employeeName.includes(filterEmployee));
        if (filterMarket) res = res.filter(s => s.market === filterMarket);
        setFilteredSales(res);
    }, [sales, filterDate, filterEmployee, filterMarket]);

    // إحصائيات الأكثر مبيعاً (Admin Only) - مجمعة من يوم 1 إلى 30
    const topSellingProducts = useMemo(() => {
        if (user.role !== 'admin') return [];
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
        const end = new Date(now.getFullYear(), now.getMonth(), 31).getTime();

        const monthSales = sales.filter(s => s.timestamp >= start && s.timestamp <= end);
        const stats: Record<string, { name: string, price: number, qty: number, total: number }> = {};

        monthSales.forEach(s => {
            s.items.forEach(i => {
                if (!stats[i.name]) stats[i.name] = { name: i.name, price: i.price, qty: 0, total: 0 };
                stats[i.name].qty += i.qty;
                stats[i.name].total += (i.qty * i.price);
            });
        });

        return Object.values(stats).sort((a, b) => b.qty - a.qty).slice(0, 5);
    }, [sales, user.role]);

    // تصدير Excel المتطور
    const handleSmartExport = () => {
        if (!exportStart || !exportEnd) return alert("اختر الفترة");
        const startTS = new Date(exportStart).getTime();
        const endTS = new Date(exportEnd).getTime() + 86400000;

        let periodSales = sales.filter(s => s.timestamp >= startTS && s.timestamp <= endTS);
        if (exportMarket !== 'all') periodSales = periodSales.filter(s => s.market === exportMarket);

        if (periodSales.length === 0) return alert("لا توجد مبيعات");

        const finalData: any[] = [];
        const marketsInvolved = exportMarket === 'all' ? Array.from(new Set(periodSales.map(s => s.market))) : [exportMarket];

        let grandTotal = 0;

        marketsInvolved.forEach(mName => {
            const mSales = periodSales.filter(s => s.market === mName);
            if (mSales.length === 0) return;

            finalData.push({ "اسم الموظف": `--- ماركت: ${mName} ---`, "اسم الصنف": "", "سعر القطعة": "", "إجمالي الكمية": "", "إجمالي مبيعات الصنف": "" });

            const productGroups: Record<string, { employee: string, name: string, price: number, qty: number, total: number }> = {};
            let marketSubtotal = 0;

            mSales.forEach(s => {
                s.items.forEach(i => {
                    const key = `${s.employeeName}_${i.name}`;
                    if (!productGroups[key]) {
                        productGroups[key] = { employee: s.employeeName, name: i.name, price: i.price, qty: 0, total: 0 };
                    }
                    productGroups[key].qty += i.qty;
                    productGroups[key].total += (i.qty * i.price);
                });
            });

            Object.values(productGroups).forEach(pg => {
                finalData.push({
                    "اسم الموظف": pg.employee,
                    "اسم الصنف": pg.name,
                    "سعر القطعة": pg.price,
                    "إجمالي الكمية": pg.qty,
                    "إجمالي مبيعات الصنف": pg.total
                });
                marketSubtotal += pg.total;
            });

            finalData.push({ "اسم الموظف": `إجمالي ماركت ${mName}`, "اسم الصنف": "", "سعر القطعة": "", "إجمالي الكمية": "", "إجمالي مبيعات الصنف": marketSubtotal });
            finalData.push({}); // صف فارغ للفصل
            grandTotal += marketSubtotal;
        });

        finalData.push({ "اسم الموظف": "الإجمالي الكلي للتقرير", "اسم الصنف": "", "سعر القطعة": "", "إجمالي الكمية": "", "إجمالي مبيعات الصنف": grandTotal });

        exportToCSV(finalData, `Sales_Report_${exportStart}_to_${exportEnd}`);
        setShowExportModal(false);
    };

    const getStarOfMonth = () => {
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
        const totals: Record<string, number> = {};
        sales.filter(s => s.timestamp >= start).forEach(s => totals[s.employeeName] = (totals[s.employeeName] || 0) + s.total);
        const sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);
        return sorted.length > 0 ? { name: sorted[0][0], total: sorted[0][1] } : null;
    };
    const star = getStarOfMonth();

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2 text-white"><FileSpreadsheet /> سجل المبيعات</h2>
                {user.role === 'admin' && (
                    <button onClick={() => setShowExportModal(true)} className="bg-blue-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 font-bold shadow-lg transition active:scale-95"><Filter size={18}/> تصدير تقرير ذكي</button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {star && (
                    <div className="bg-[#808080] p-6 rounded-3xl border border-white/20 shadow-2xl flex flex-col items-center justify-center space-y-2 relative overflow-hidden group">
                        <Star className="text-yellow-400 animate-pulse" size={32} fill="currentColor" />
                        <h3 className="text-xl font-black text-white uppercase tracking-widest">نجم الشهر</h3>
                        <div className="text-3xl font-black text-white">{star.name}</div>
                        <div className="text-sm font-bold opacity-80 text-white">إجمالي المبيعات: <span className="text-green-300 font-black">{star.total.toLocaleString()}</span></div>
                    </div>
                )}

                {user.role === 'admin' && topSellingProducts.length > 0 && (
                    <div className="bg-gray-800 p-6 rounded-3xl border border-white/10 shadow-2xl">
                        <h3 className="text-lg font-black text-blue-400 mb-4 flex items-center gap-2"><LayoutGrid size={20}/> الأكثر مبيعاً (هذا الشهر)</h3>
                        <div className="space-y-3">
                            {topSellingProducts.map((p, idx) => (
                                <div key={idx} className="flex justify-between items-center bg-black/20 p-2 rounded-xl border border-white/5">
                                    <div className="text-xs">
                                        <div className="font-bold text-white">{p.name}</div>
                                        <div className="opacity-40 text-[10px]">{p.price} ج.م / قطعة</div>
                                    </div>
                                    <div className="text-left">
                                        <div className="text-xs font-black text-green-400">{p.total.toLocaleString()} ج.م</div>
                                        <div className="text-[10px] font-bold opacity-40">المباع: {p.qty}</div>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                {user.role === 'admin' && <input type="date" className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterDate} onChange={e => setFilterDate(e.target.value)} />}
                <input type="text" placeholder="بحث باسم الموظف..." className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} />
                <select className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterMarket} onChange={e => setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {filteredSales.map(sale => (
                    <div key={sale.id} className="p-5 rounded-3xl border border-white/10 bg-gray-800 shadow-2xl">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <div className="font-bold text-xl text-blue-400">{sale.market}</div>
                                <div className="flex items-center gap-3 text-[10px] opacity-60 font-bold mt-1 text-white">
                                    <span className="flex items-center gap-1"><Calendar size={12}/> {sale.date}</span>
                                    <span className="flex items-center gap-1"><UserIcon size={12}/> {sale.employeeName}</span>
                                </div>
                            </div>
                            {user.role === 'admin' && (
                                <div className="flex gap-2">
                                    <button onClick={() => remove(ref(db, `sales/${sale.id!}`))} className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition"><Trash2 size={18}/></button>
                                </div>
                            )}
                        </div>
                        <div className="overflow-hidden rounded-2xl bg-black/20 border border-white/5">
                            <table className="w-full text-[11px] text-center">
                                <thead className="bg-white/5 text-white/50">
                                    <tr><th className="py-2 px-3 text-right">الصنف</th><th className="py-2">السعر</th><th className="py-2">الكمية</th><th className="py-2 px-3">المجموع</th></tr>
                                </thead>
                                <tbody>
                                    {sale.items.map((item, idx) => (
                                        <tr key={idx} className="border-t border-white/5 text-white"><td className="py-2 px-3 text-right font-bold">{item.name}</td><td className="py-2">{item.price}</td><td className="py-2 font-black">{item.qty}</td><td className="py-2 px-3 text-green-400 font-black">{(item.qty * item.price).toLocaleString()}</td></tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                ))}
            </div>

            {showExportModal && (
                <div className="fixed inset-0 z-[200] bg-black/90 flex items-center justify-center p-4 backdrop-blur-md">
                    <div className="bg-gray-900 border border-white/20 w-full max-w-md rounded-3xl p-6 shadow-2xl">
                        <div className="flex justify-between items-center mb-6"><h3 className="font-bold text-lg text-white">تصدير التقرير الذكي</h3><button onClick={() => setShowExportModal(false)} className="text-white"><X size={20}/></button></div>
                        <div className="space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div><label className="text-xs opacity-60 text-white">البداية</label><input type="date" className="w-full p-3 rounded-xl bg-gray-700 text-white" value={exportStart} onChange={e => setExportStart(e.target.value)} /></div>
                                <div><label className="text-xs opacity-60 text-white">النهاية</label><input type="date" className="w-full p-3 rounded-xl bg-gray-700 text-white" value={exportEnd} onChange={e => setExportEnd(e.target.value)} /></div>
                            </div>
                            <div><label className="text-xs opacity-60 text-white">الماركت</label><select className="w-full p-3 rounded-xl bg-gray-700 text-white" value={exportMarket} onChange={e => setExportMarket(e.target.value)}><option value="all">كل الماركتات</option>{markets.map(m => <option key={m} value={m}>{m}</option>)}</select></div>
                            <button onClick={handleSmartExport} className="w-full bg-blue-600 text-white font-bold py-4 rounded-xl shadow-xl active:scale-95 transition">تحميل التقرير (Excel)</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default SalesLog;

import React, { useState, useEffect } from 'react';
import { ref, push, onValue, set, get, update, remove } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem, UserTarget } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Calculator, Target, TrendingUp, AlertCircle, Edit, Trash2, Check, X, ChevronDown } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [targetUserKey, setTargetUserKey] = useState(user.key || '');
    const [targetData, setTargetData] = useState<UserTarget | null>(null);
    const [usersList, setUsersList] = useState<User[]>([]);

    // حالات التعديل
    const [editingItemId, setEditingItemId] = useState<string | null>(null);
    const [tempName, setTempName] = useState('');

    useEffect(() => {
        // تحميل قائمة الموظفين للآدمن
        if (user.role === 'admin') {
            onValue(ref(db, 'users'), (snap) => {
                if (snap.exists()) {
                    const list: User[] = [];
                    snap.forEach(child => { list.push({ key: child.key!, ...child.val() }); });
                    setUsersList(list);
                }
            });
        }
    }, [user.role]);

    useEffect(() => {
        // تحميل الأصناف الأساسية والمزامنة مع الأصناف المخصصة من قاعدة البيانات
        const initialItems: ProductItem[] = [];
        const categories = [
            { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
            { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
            { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
            { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
        ];

        categories.forEach(cat => {
            cat.items.forEach(name => {
                initialItems.push({ 
                    id: name, 
                    name, 
                    price: 0, 
                    qty: 0, 
                    category: cat.key 
                });
            });
        });

        // جلب الأصناف المخصصة من قاعدة البيانات لضمان المزامنة
        onValue(ref(db, 'settings/global_products'), (snapshot) => {
            const extraItems: ProductItem[] = [];
            if (snapshot.exists()) {
                const data = snapshot.val();
                Object.keys(data).forEach(catKey => {
                    Object.keys(data[catKey]).forEach(prodId => {
                        const prod = data[catKey][prodId];
                        // إذا كان الصنف مخصصاً أو تم تعديله، نقوم بإضافته أو تحديثه في القائمة
                        extraItems.push({ ...prod, price: 0, qty: 0 });
                    });
                });
            }

            // دمج القوائم: الأصناف المخصصة تلغي الأصناف الأساسية بنفس الاسم
            const combined = [...initialItems];
            extraItems.forEach(extra => {
                const idx = combined.findIndex(c => c.id === extra.id || c.name === extra.name);
                if (idx > -1) combined[idx] = extra;
                else combined.push(extra);
            });
            setSalesItems(combined);
        });

        // مراقبة التارجت
        if (targetUserKey) {
            const targetRef = ref(db, `targets/${targetUserKey}`);
            const unsubscribe = onValue(targetRef, (snapshot) => {
                if (snapshot.exists()) {
                    setTargetData(snapshot.val());
                } else {
                    setTargetData(null);
                }
            });
            return () => unsubscribe();
        }
    }, [targetUserKey]);

    const updateItem = (id: string, field: string, value: any) => {
        setSalesItems(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    // Fix: Added 'remove' to firebase/database imports above and using it here
    const deleteItem = async (id: string, category: string) => {
        if (user.role !== 'admin') return alert("عذراً، هذه الصلاحية للمسؤول فقط");
        if (confirm("هل تريد حذف هذا الصنف نهائياً من النظام؟")) {
            // حذف من القائمة المحلية
            setSalesItems(prev => prev.filter(i => i.id !== id));
            // حذف من قاعدة البيانات العالمية للمزامنة
            await remove(ref(db, `settings/global_products/${category}/${id.replace(/[.#$/[\]]/g, "_")}`));
        }
    };

    const startEditingName = (id: string, currentName: string) => {
        setEditingItemId(id);
        setTempName(currentName);
    };

    const saveName = async (item: ProductItem) => {
        const containsArabic = /[\u0600-\u06FF]/.test(tempName);
        if (containsArabic) {
            alert("يرجى كتابة اسم الصنف باللغة الإنجليزية فقط");
            return;
        }

        const updatedItem = { ...item, name: tempName };
        setSalesItems(prev => prev.map(i => i.id === item.id ? updatedItem : i));

        // حفظ التعديل في قاعدة البيانات العالمية للمزامنة مع باقي الأقسام
        const safeId = item.id.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `settings/global_products/${item.category}/${safeId}`), {
            id: item.id,
            name: tempName,
            category: item.category,
            isCustom: item.isCustom || false
        });

        setEditingItemId(null);
    };

    const addCustomItem = async (category: string) => {
        if (user.role !== 'admin') return alert("إضافة الأصناف مقتصرة على المسؤول فقط");
        const newItemName = prompt("ادخل اسم الصنف الجديد (English Only):");
        if (newItemName) {
            const containsArabic = /[\u0600-\u06FF]/.test(newItemName);
            if (containsArabic) {
                alert("يرجى كتابة اسم الصنف باللغة الإنجليزية فقط");
                return;
            }

            const newItemId = newItemName + "_" + Date.now();
            const newItem = {
                id: newItemId,
                name: newItemName,
                price: 0,
                qty: 0,
                category,
                isCustom: true
            };

            // حفظ في قاعدة البيانات العالمية للمزامنة
            const safeId = newItemId.replace(/[.#$/[\]]/g, "_");
            await set(ref(db, `settings/global_products/${category}/${safeId}`), {
                id: newItemId,
                name: newItemName,
                category,
                isCustom: true
            });

            alert("تمت إضافة الصنف بنجاح ومزامنته");
        }
    };

    const currentTotal = salesItems.reduce((sum, item) => sum + ((item.price || 0) * (item.qty || 0)), 0);

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const sold = salesItems.filter(i => i.qty > 0 && i.price > 0);
        if (!sold.length) return alert("أدخل بيانات صحيحة");

        await push(ref(db, 'sales'), {
            market: selectedMarket,
            employeeName: user.name,
            username: user.username,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: sold,
            total: currentTotal
        });

        // تحديث المحقق في التارجت الخاص بالموظف الحالي (دائماً الموظف المسجل)
        if (user.key) {
            const myTargetRef = ref(db, `targets/${user.key}`);
            const snap = await get(myTargetRef);
            if (snap.exists()) {
                const currentAchieved = snap.val().achieved || 0;
                await update(myTargetRef, { achieved: currentAchieved + currentTotal });
            }
        }

        alert("تم الحفظ بنجاح");
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
    };

    // حسابات التارجت للعرض
    const achieved = targetData?.achieved || 0;
    const finalTarget = targetData?.finalTarget || 1;
    const excess = Math.max(0, achieved - finalTarget);
    const progressPercent = Math.round((achieved / finalTarget) * 100);
    const remaining = Math.max(0, finalTarget - achieved);

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h2 className="text-2xl font-bold text-white">المبيعات اليومية</h2>

                <div className="flex flex-wrap gap-4">
                    <div className="bg-blue-600/20 border border-blue-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[180px]">
                        <div className="bg-blue-600 p-2 rounded-2xl text-white">
                            <Calculator size={24} />
                        </div>
                        <div>
                            <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">إجمالي الحالية</div>
                            <div className="text-xl font-black text-blue-400">
                                {currentTotal.toLocaleString()} <span className="text-xs">ج.م</span>
                            </div>
                        </div>
                    </div>

                    <div className="bg-purple-600/20 border border-purple-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[280px]">
                        <div className="bg-purple-600 p-2 rounded-2xl text-white">
                            <Target size={24} />
                        </div>
                        <div className="flex-1">
                            <div className="flex justify-between items-center mb-1">
                                <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">
                                    {user.role === 'admin' ? (
                                        <select 
                                            className="bg-transparent border-none p-0 text-purple-300 font-black cursor-pointer focus:ring-0"
                                            value={targetUserKey}
                                            onChange={(e) => setTargetUserKey(e.target.value)}
                                        >
                                            {usersList.map(u => <option key={u.key} value={u.key!} className="bg-gray-900">{u.name}</option>)}
                                        </select>
                                    ) : `التارجت ( ${finalTarget.toLocaleString()} )`}
                                </div>
                                <div className={`text-sm font-black ${progressPercent >= 100 ? 'text-green-400' : 'text-purple-400'}`}>
                                    {progressPercent}%
                                </div>
                            </div>

                            <div className="flex justify-between items-end mb-1">
                                <div className="text-sm font-bold text-white">
                                    {excess > 0 ? (
                                        <span className="text-green-400">تجاوز: +{excess.toLocaleString()}</span>
                                    ) : (
                                        <span className="opacity-60">المتبقي: {remaining.toLocaleString()}</span>
                                    )}
                                </div>
                                <div className="text-[10px] opacity-40 text-white font-bold">
                                    المحقق: {achieved.toLocaleString()}
                                </div>
                            </div>
                            <div className="w-full bg-black/40 h-1.5 rounded-full overflow-hidden">
                                <div className={`h-full transition-all duration-1000 ${progressPercent >= 100 ? 'bg-green-500' : 'bg-purple-500'}`} style={{ width: `${Math.min(100, progressPercent)}%` }}></div>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

