import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings, UserPermissions, AppNotification } from '../types';
import { 
  Save, Trash2, UserPlus, Shield, Edit2, Plus, X, 
  Settings as SettingsIcon, Users, MapPin, Building2, 
  ToggleLeft, ToggleRight, Key, Send, LayoutGrid
} from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<User[]>([]);
    const [newUser, setNewUser] = useState<User>({ 
        name: '', username: '', password: '', role: 'user', canViewAllSales: false,
        permissions: { showSalesLog: true, showInventoryLog: false, showInventoryReg: false, showCompetitorReports: false, showDailySales: true, showCompetitorPrices: true }
    });

    const [marketList, setMarketList] = useState<{key: string, name: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, name: string}[]>([]);
    const [newMarketName, setNewMarketName] = useState('');
    const [newCompanyName, setNewCompanyName] = useState('');

    const [passModal, setPassModal] = useState<{key: string, name: string} | null>(null);
    const [permModal, setPermModal] = useState<User | null>(null);
    const [notifModal, setNotifModal] = useState<{username: string, name: string} | null>(null);
    const [newPass, setNewPass] = useState('');
    const [notifMsg, setNotifMsg] = useState('');

    useEffect(() => {
        if (user.role !== 'admin') return;

        // جلب المستخدمين
        onValue(ref(db, 'users'), s => {
            if (s.exists()) {
                const u: User[] = []; s.forEach(c => { u.push({ key: c.key || '', ...c.val() }); });
                setUsers(u);
            }
        });

        // جلب الماركتات مع معالجة الأخطاء (التأكد من أن الاسم نص وليس كائن)
        onValue(ref(db, 'settings/markets'), s => {
            const m: {key: string, name: string}[] = []; 
            if(s.exists()){ 
                s.forEach(c => { 
                    const val = c.val();
                    const name = typeof val === 'string' ? val : (val?.name || 'Unnamed Market');
                    m.push({ key: c.key!, name }); 
                }); 
            }
            setMarketList(m);
        });

        // جلب الشركات مع معالجة الأخطاء
        onValue(ref(db, 'settings/companies'), s => {
            const c: {key: string, name: string}[] = []; 
            if(s.exists()){ 
                s.forEach(k => { 
                    const val = k.val();
                    const name = typeof val === 'string' ? val : (val?.name || 'Unnamed Company');
                    c.push({ key: k.key!, name }); 
                }); 
            }
            setCompanyList(c);
        });
    }, [user.role]);

    const addMarket = async () => {
        if(!newMarketName.trim()) return;
        await push(ref(db, 'settings/markets'), {
            name: newMarketName.trim(),
            createdBy: user.username
        });
        setNewMarketName(''); 
        alert("تمت إضافة الماركت");
    };

    const deleteMarket = async (key: string) => {
        if(confirm("حذف الماركت من القوائم؟ (لن يحذف مبيعاته القديمة)")) {
            await remove(ref(db, `settings/markets/${key}`));
        }
    };

    const addCompany = async () => {
        if(!newCompanyName.trim()) return;
        await push(ref(db, 'settings/companies'), newCompanyName.trim());
        setNewCompanyName(''); 
        alert("تمت إضافة الشركة");
    };

    const deleteCompany = async (key: string) => {
        if(confirm("حذف الشركة؟")) await remove(ref(db, `settings/companies/${key}`));
    };

    const toggleUserPerm = (key: keyof UserPermissions) => {
        if (!permModal) return;
        const current = permModal.permissions || { showSalesLog: false, showInventoryLog: false, showInventoryReg: false, showCompetitorReports: false, showDailySales: true, showCompetitorPrices: true };
        setPermModal({ ...permModal, permissions: { ...current, [key]: !current[key] } });
    };

    const sectionClass = "p-6 rounded-2xl mb-6 bg-gray-800 border-gray-700 border text-white shadow-lg";
    const inputClass = "w-full p-2.5 rounded-lg bg-gray-700 text-white border border-white/10 outline-none focus:border-blue-500 transition-colors";

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-20">
            <h2 className="text-3xl font-bold text-white flex items-center gap-3"><SettingsIcon className="text-blue-600"/> لوحة تحكم المسؤول</h2>

            {/* إدارة الماركتات والشركات */}
