                            <button onClick={() => setPermModal(null)} className="text-white/50 hover:text-white"><X/></button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-3 mb-8">
                            {[
                                { key: 'showDailySales', label: 'المبيعات اليومية' },
                                { key: 'showSalesLog', label: 'سجل المبيعات' },
                                { key: 'showInventoryReg', label: 'تسجيل المخزون' },
                                { key: 'showInventoryLog', label: 'سجل المخزون' },
                                { key: 'showCompetitorPrices', label: 'أسعار المنافسين' },
                                { key: 'showCompetitorReports', label: 'تقارير المنافسين' }
                            ].map(item => (
                                <button key={item.key} onClick={() => toggleUserPerm(item.key as any)} className={`p-4 rounded-2xl border text-xs font-black flex justify-between items-center transition-all ${ (permModal.permissions as any)?.[item.key] ? 'bg-blue-600 border-blue-500 text-white shadow-lg' : 'bg-white/5 border-white/5 text-white/40 opacity-60 hover:opacity-100'}`}>
                                    {item.label}
                                    {(permModal.permissions as any)?.[item.key] ? <ToggleRight size={20}/> : <ToggleLeft size={20}/>}
                                </button>
                            ))}
                        </div>
                        <button onClick={async () => { await update(ref(db, `users/${permModal.key}`), { permissions: permModal.permissions }); setPermModal(null); alert("تم الحفظ بنجاح"); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white py-4 rounded-2xl font-black shadow-xl transition-all active:scale-95">حفظ التغييرات</button>
                    </div>
                </div>
            )}

            {/* مودال تغيير كلمة المرور */}
            {passModal && (
                <div className="fixed inset-0 z-[110] bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
                    <div className="bg-gray-900 p-6 rounded-3xl border border-white/20 w-full max-w-sm shadow-2xl animate-in zoom-in-95">
                         <div className="flex justify-between items-center mb-6">
