import React, { useState, useEffect } from 'react';
import { ref, push, onValue, set, get, update } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem, UserTarget } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Calculator, Target, TrendingUp, AlertCircle } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [targetData, setTargetData] = useState<UserTarget | null>(null);

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        const categories = [
            { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
            { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
            { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
            { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
        ];

        categories.forEach(cat => {
            cat.items.forEach(name => {
                initialItems.push({ id: name, name, price: 0, qty: 0, category: cat.key });
            });
        });
        setSalesItems(initialItems);

        if (user.key) {
            onValue(ref(db, `targets/${user.key}`), (snapshot) => {
                if (snapshot.exists()) setTargetData(snapshot.val());
            });
        }
    }, [user.key]);

    const updateItem = (id: string, field: string, value: any) => {
        setSalesItems(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    const currentTotal = salesItems.reduce((sum, item) => sum + ((item.price || 0) * (item.qty || 0)), 0);

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const sold = salesItems.filter(i => i.qty > 0 && i.price > 0);
        if (!sold.length) return alert("أدخل بيانات صحيحة");

        await push(ref(db, 'sales'), {
            market: selectedMarket,
            employeeName: user.name,
            username: user.username,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: sold,
            total: currentTotal
        });

        if (user.key && targetData) {
            await update(ref(db, `targets/${user.key}`), { achieved: (targetData.achieved || 0) + currentTotal });
        }

        alert("تم الحفظ بنجاح");
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
    };

    const progressPercent = targetData ? Math.round((targetData.achieved / targetData.finalTarget) * 100) : 0;

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h2 className="text-2xl font-bold text-white">المبيعات اليومية</h2>

                <div className="flex flex-wrap gap-4">
                    <div className="bg-blue-600/20 border border-blue-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[180px]">
                        <div className="bg-blue-600 p-2 rounded-2xl text-white"><Calculator size={24} /></div>
                        <div>
                            <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">إجمالي الحالية</div>
                            <div className="text-xl font-black text-blue-400">{currentTotal.toLocaleString()} <span className="text-xs">ج.م</span></div>
                        </div>
                    </div>

                    {targetData && (
                        <div className="bg-purple-600/20 border border-purple-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[200px]">
                            <div className="bg-purple-600 p-2 rounded-2xl text-white"><Target size={24} /></div>
                            <div className="flex-1">
                                <div className="flex justify-between items-center mb-1">
                                    <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">تقدم التارجت</div>
                                    <div className="text-sm font-black text-purple-400">{progressPercent}%</div>
                                </div>
                                <div className="w-full bg-black/40 h-1.5 rounded-full overflow-hidden">
                                    <div className="bg-purple-500 h-full transition-all duration-1000" style={{ width: `${Math.min(100, progressPercent)}%` }}></div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            <select className="w-full p-4 rounded-2xl bg-gray-800 text-white border border-white/10" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                <option value="">اختر الماركت...</option>
                {markets.map(m => <option key={m} value={m}>{m}</option>)}
            </select>

            {['Facial', 'Kitchen', 'Toilet', 'Dolphin'].map(cat => (
                <div key={cat} className="bg-gray-800 p-4 rounded-3xl border border-white/5 shadow-xl">
                    <h3 className="font-bold text-blue-400 mb-4 border-b border-white/10 pb-2">{cat}</h3>
                    <div className="space-y-3">
                        {salesItems.filter(i => i.category === cat).map(item => (
                            <div key={item.id} className="grid grid-cols-12 gap-2 items-center bg-black/20 p-2 rounded-2xl">
                                <div className="col-span-5 text-xs font-bold text-white truncate">{item.name}</div>
                                <div className="col-span-3">
                                    <input type="number" placeholder="السعر" className="w-full bg-gray-700 p-2 rounded-xl text-white text-center text-xs" value={item.price || ''} onChange={e => updateItem(item.id, 'price', parseFloat(e.target.value))} />
                                </div>
                                <div className="col-span-2">
                                    <input type="number" placeholder="الكمية" className="w-full bg-gray-700 p-2 rounded-xl text-white text-center text-xs" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} />
                                </div>
                                <div className="col-span-2 text-center font-black text-xs text-green-400">{(item.price * item.qty).toLocaleString()}</div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 hover:bg-green-700 text-white py-4 rounded-3xl font-black shadow-2xl flex justify-center items-center gap-2 transform active:scale-95 transition">
                    <Save size={20} /> حفظ وترحيل المبيعات
                </button>
            </div>
        </div>
    );
};

export default DailySales;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove } from "firebase/database";
import { User, SaleRecord } from '../types';
import { Trash2, FileSpreadsheet, Calendar, User as UserIcon, Star, Download, Filter } from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    useEffect(() => {
        onValue(ref(db, 'sales'), (snapshot) => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                let list: SaleRecord[] = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                if (user.role !== 'admin' && !user.canViewAllSales) list = list.filter(s => s.employeeName === user.name);
                setSales(list.sort((a, b) => b.timestamp - a.timestamp));
            } else setSales([]);
        });
    }, [user]);

    useEffect(() => {
        let res = sales;
        if (filterDate) res = res.filter(s => s.date.includes(filterDate));
        if (filterEmployee) res = res.filter(s => s.employeeName.includes(filterEmployee));
        if (filterMarket) res = res.filter(s => s.market === filterMarket);
        setFilteredSales(res);
    }, [sales, filterDate, filterEmployee, filterMarket]);

    const handleExport = () => {
        if (filteredSales.length === 0) return alert("لا توجد بيانات");
        const exportData = filteredSales.map(s => ({
            "الموظف": s.employeeName,
            "التاريخ": s.date,
            "الماركت": s.market,
            "الإجمالي": s.total
        }));
        exportToCSV(exportData, "Sales_Log");
    };

    const getStarOfMonth = () => {
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
        const totals: Record<string, number> = {};
        sales.filter(s => s.timestamp >= start).forEach(s => totals[s.employeeName] = (totals[s.employeeName] || 0) + s.total);
        const sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);
        return sorted.length > 0 ? { name: sorted[0][0], total: sorted[0][1] } : null;
    };
    const star = getStarOfMonth();

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2 text-white"><FileSpreadsheet /> سجل المبيعات</h2>
                {user.role === 'admin' && (
                    <button onClick={handleExport} className="bg-green-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 font-bold shadow-lg"><Download size={18}/> تصدير Excel</button>
                )}
            </div>

            {star && (
                <div className="bg-[#808080] p-6 rounded-3xl border border-white/20 shadow-2xl flex flex-col items-center justify-center space-y-2 relative overflow-hidden group text-white">
                    <Star className="text-yellow-400 animate-pulse" size={32} fill="currentColor" />
                    <h3 className="text-xl font-black uppercase tracking-widest">نجم الشهر</h3>
                    <div className="text-3xl font-black">{star.name}</div>
                    <div className="text-sm font-bold opacity-80">إجمالي المبيعات: <span className="text-green-300 font-black">{star.total.toLocaleString()} ج.م</span></div>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                {user.role === 'admin' && <input type="date" className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterDate} onChange={e => setFilterDate(e.target.value)} />}
                <input type="text" placeholder="بحث باسم الموظف..." className="p-3 rounded-xl bg-gray-700 text-white border border-white/20 text-xs" value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} />
                <select className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterMarket} onChange={e => setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {filteredSales.map(sale => (
                    <div key={sale.id} className="p-5 rounded-3xl border border-white/10 bg-gray-800 shadow-2xl text-white">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <div className="font-bold text-xl text-blue-400">{sale.market}</div>
                                <div className="flex items-center gap-3 text-[10px] opacity-60 font-bold mt-1">
                                    <span className="flex items-center gap-1"><Calendar size={12}/> {sale.date}</span>
                                    <span className="flex items-center gap-1"><UserIcon size={12}/> {sale.employeeName}</span>
                                </div>
                            </div>
                            {user.role === 'admin' && (
                                <button onClick={() => remove(ref(db, `sales/${sale.id!}`))} className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition"><Trash2 size={18}/></button>
                            )}
                        </div>
                        <div className="overflow-hidden rounded-2xl bg-black/20 border border-white/5">
                            <table className="w-full text-[11px] text-center">
                                <thead className="bg-white/5 text-white/50">
                                    <tr><th className="py-2 px-3 text-right">الصنف</th><th className="py-2">السعر</th><th className="py-2">الكمية</th><th className="py-2 px-3">المجموع</th></tr>
                                </thead>
                                <tbody>
                                    {(sale.items || []).map((item, idx) => (
                                        <tr key={idx} className="border-t border-white/5">
                                            <td className="py-2 px-3 text-right font-bold">{item.name}</td>
                                            <td className="py-2">{item.price}</td>
                                            <td className="py-2 font-black">{item.qty}</td>
                                            <td className="py-2 px-3 text-green-400 font-black">{(item.qty * item.price).toLocaleString()}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="mt-4 text-left font-black text-lg text-blue-400">إجمالي: {sale.total.toLocaleString()} ج.م</div>
                    </div>
                ))}
            </div>
        </div>
    );
};

