import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { Trash2, CalendarPlus, X, Save, History, ChevronRight, ChevronLeft, CheckCircle2, Calendar as CalendarIcon, User as UserIcon } from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<Record<string, LeaveBalance>>({});
    const [usersList, setUsersList] = useState<User[]>([]);
    const [allHistory, setAllHistory] = useState<({id: string} & LeaveRecord)[]>([]);
    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showHistoryDetailsModal, setShowHistoryDetailsModal] = useState(false);
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);

    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams' | 'unpaid'>('annual');

    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات', unpaid: 'غياب بدون إذن' };
    const typeColors = { annual: 'text-green-400', casual: 'text-yellow-400', sick: 'text-red-400', exams: 'text-purple-400', unpaid: 'text-orange-400' };

    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: User[] = []; snapshot.forEach(c => { u.push({ key: c.key!, ...c.val() }); });
                setUsersList(u);
            }
        });

        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val() as Record<string, LeaveBalance>;
                setBalances(data);

                const now = new Date();
                const currentMonthKey = `${now.getFullYear()}-${now.getMonth() + 1}`;
                if (now.getDate() >= 21) {
                    Object.keys(data).forEach(async (uKey) => {
                        const balance = data[uKey];
                        if (balance.lastUnpaidReset !== currentMonthKey) {
                            await update(ref(db, `leave_balances/${uKey}`), { unpaid: 0, lastUnpaidReset: currentMonthKey });
                        }
                    });
                }
            } else setBalances({});
        });

        onValue(ref(db, 'leave_history'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                const h: any = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                setAllHistory(h.sort((a,b) => b.timestamp - a.timestamp));
            } else setAllHistory([]);
        });
    }, []);

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate) return alert("اكمل البيانات");
        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;

        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        const snap = await get(balanceRef);
        let cur = snap.exists() ? snap.val() : { userId: selectedUser, employeeName: targetUser.name, annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };

        const typeLogic = { annual: 'remaining', casual: 'remaining', sick: 'accrued', exams: 'accrued', unpaid: 'accrued' };
        let newValue = (typeLogic[leaveType] === 'remaining') ? (Number(cur[leaveType]) - Number(leaveDays)) : (Number(cur[leaveType]) + Number(leaveDays));

        await update(balanceRef, { ...cur, [leaveType]: newValue });
        await push(ref(db, 'leave_history'), { userId: selectedUser, employeeName: targetUser.name, date: leaveDate, days: Number(leaveDays), type: leaveType, timestamp: new Date(leaveDate).getTime() });
        setShowAddLeaveModal(false); alert("تم الحفظ بنجاح");
    };

    const displayedUsers = (user.role === 'admin' || user.canViewAllSales) ? usersList : usersList.filter(u => u.username === user.username);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2 text-white"><History className="text-blue-500" /> رصيد الإجازات والغياب</h2>
                {user.role === 'admin' && (
                    <button onClick={() => setShowAddLeaveModal(true)} className="bg-red-600 text-white px-5 py-2.5 rounded-2xl font-bold shadow-xl flex items-center gap-2 transition active:scale-95"><CalendarPlus size={18} /> تسجيل إجازة/غياب</button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {displayedUsers.map(u => {
                    const balance = balances[u.key!] || { userId: u.key!, employeeName: u.name, annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };
                    return (
                        <div key={u.key} className="p-5 rounded-3xl border border-white/10 bg-gray-800 text-white shadow-xl relative overflow-hidden">
                            <div className="flex justify-between items-start mb-4">
                                <div><div className="font-bold text-lg text-blue-400">{u.name}</div><div className="text-[10px] opacity-40">@{u.username}</div></div>
                                <button onClick={() => { setHistoryUserView({userId: u.key!, name: u.name}); setShowHistoryDetailsModal(true); }} className="text-[10px] font-bold bg-white/5 px-3 py-1.5 rounded-xl hover:bg-white/10 transition">عرض السجل</button>
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                {Object.entries(typeLabels).map(([key, label]) => (
                                    <div key={key} className="p-3 bg-black/20 rounded-2xl border border-white/5 flex flex-col items-center">
                                        <span className="text-[10px] opacity-50 font-black text-center h-6 leading-3">{label}</span>
                                        <span className={`text-xl font-black ${typeColors[key as keyof typeof typeColors]}`}>{(balance as any)[key] || 0}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>

            {showHistoryDetailsModal && historyUserView && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
                    <div className="w-full max-w-2xl p-6 rounded-3xl border border-white/10 bg-gray-900 text-white flex flex-col max-h-[90vh] shadow-2xl animate-in zoom-in-95">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold">{historyUserView.name}</h3>
                            <button onClick={() => setShowHistoryDetailsModal(false)} className="text-white"><X/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-3 pr-1 custom-scrollbar">
                            {allHistory.filter(h => h.userId === historyUserView.userId).map(rec => (
                                <div key={rec.id} className="p-4 rounded-2xl border bg-black/20 border-white/5 flex justify-between items-center">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-xl bg-white/5 ${typeColors[rec.type]}`}><CheckCircle2 size={18} /></div>
                                        <div><div className="font-bold text-sm">{typeLabels[rec.type]}</div><div className="text-[10px] opacity-50">{rec.date}</div></div>
                                    </div>
                                    <div className="font-black text-lg">{rec.days} يوم</div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {showAddLeaveModal && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
                    <div className="w-full max-w-md p-6 rounded-3xl border border-white/10 bg-gray-900 text-white shadow-2xl">
                        <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold">تسجيل إجازة / غياب</h3><button onClick={() => setShowAddLeaveModal(false)} className="text-white/50 hover:text-white"><X size={20}/></button></div>
                        <div className="space-y-4">
                            <select className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10 font-bold" value={selectedUser} onChange={e => setSelectedUser(e.target.value)}>
                                <option value="">-- اختر الموظف --</option>
                                {usersList.map(u => <option key={u.key} value={u.key}>{u.name}</option>)}
                            </select>
                            <input type="date" className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10" value={leaveDate} onChange={e => setLeaveDate(e.target.value)} />
                            <div className="grid grid-cols-2 gap-4">
                                <input type="number" step="0.5" className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10 text-center font-black" value={leaveDays} onChange={e => setLeaveDays(parseFloat(e.target.value))} />
                                <select className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10 font-bold" value={leaveType} onChange={e => setLeaveType(e.target.value as any)}>
                                    {Object.entries(typeLabels).map(([k,v]) => <option key={k} value={k}>{v}</option>)}
                                </select>
                            </div>
                            <button onClick={handleAddLeave} className="w-full bg-red-600 text-white font-bold py-4 rounded-2xl shadow-xl active:scale-95 transition mt-4">حفظ العملية</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default LeaveBalanceComponent;

import React, { useState, useEffect } from 'react';
import { ref, push, onValue, set, get, update } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem, UserTarget } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Calculator, Target, TrendingUp, AlertCircle } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [targetData, setTargetData] = useState<UserTarget | null>(null);

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        const categories = [
            { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
            { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
            { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
            { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
        ];

        categories.forEach(cat => {
            cat.items.forEach(name => {
                initialItems.push({ id: name, name, price: 0, qty: 0, category: cat.key });
            });
        });
        setSalesItems(initialItems);

        if (user.key) {
            onValue(ref(db, `targets/${user.key}`), (snapshot) => {
                if (snapshot.exists()) setTargetData(snapshot.val());
            });
        }
    }, [user.key]);

    const updateItem = (id: string, field: string, value: any) => {
        setSalesItems(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    const currentTotal = salesItems.reduce((sum, item) => sum + ((item.price || 0) * (item.qty || 0)), 0);

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const sold = salesItems.filter(i => i.qty > 0 && i.price > 0);
        if (!sold.length) return alert("أدخل بيانات صحيحة");

        await push(ref(db, 'sales'), {
            market: selectedMarket,
            employeeName: user.name,
            username: user.username,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: sold,
            total: currentTotal
        });

        if (user.key && targetData) {
            await update(ref(db, `targets/${user.key}`), { achieved: (targetData.achieved || 0) + currentTotal });
        }

        alert("تم الحفظ بنجاح");
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
    };

    const progressPercent = targetData ? Math.round((targetData.achieved / targetData.finalTarget) * 100) : 0;

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h2 className="text-2xl font-bold text-white">المبيعات اليومية</h2>

                <div className="flex flex-wrap gap-4">
                    <div className="bg-blue-600/20 border border-blue-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[180px]">
                        <div className="bg-blue-600 p-2 rounded-2xl text-white"><Calculator size={24} /></div>
                        <div>
                            <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">إجمالي الحالية</div>
                            <div className="text-xl font-black text-blue-400">{currentTotal.toLocaleString()} <span className="text-xs">ج.م</span></div>
                        </div>
                    </div>

                    {targetData && (
                        <div className="bg-purple-600/20 border border-purple-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[200px]">
                            <div className="bg-purple-600 p-2 rounded-2xl text-white"><Target size={24} /></div>
                            <div className="flex-1">
                                <div className="flex justify-between items-center mb-1">
                                    <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">تقدم التارجت</div>
                                    <div className="text-sm font-black text-purple-400">{progressPercent}%</div>
                                </div>
                                <div className="w-full bg-black/40 h-1.5 rounded-full overflow-hidden">
                                    <div className="bg-purple-500 h-full transition-all duration-1000" style={{ width: `${Math.min(100, progressPercent)}%` }}></div>
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            <select className="w-full p-4 rounded-2xl bg-gray-800 text-white border border-white/10" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                <option value="">اختر الماركت...</option>
                {markets.map(m => <option key={m} value={m}>{m}</option>)}
            </select>

            {['Facial', 'Kitchen', 'Toilet', 'Dolphin'].map(cat => (
                <div key={cat} className="bg-gray-800 p-4 rounded-3xl border border-white/5 shadow-xl">
                    <h3 className="font-bold text-blue-400 mb-4 border-b border-white/10 pb-2">{cat}</h3>
                    <div className="space-y-3">
                        {salesItems.filter(i => i.category === cat).map(item => (
                            <div key={item.id} className="grid grid-cols-12 gap-2 items-center bg-black/20 p-2 rounded-2xl">
                                <div className="col-span-5 text-xs font-bold text-white truncate">{item.name}</div>
                                <div className="col-span-3">
                                    <input type="number" placeholder="السعر" className="w-full bg-gray-700 p-2 rounded-xl text-white text-center text-xs" value={item.price || ''} onChange={e => updateItem(item.id, 'price', parseFloat(e.target.value))} />
                                </div>
                                <div className="col-span-2">
                                    <input type="number" placeholder="الكمية" className="w-full bg-gray-700 p-2 rounded-xl text-white text-center text-xs" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} />
                                </div>
                                <div className="col-span-2 text-center font-black text-xs text-green-400">{(item.price * item.qty).toLocaleString()}</div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 hover:bg-green-700 text-white py-4 rounded-3xl font-black shadow-2xl flex justify-center items-center gap-2 transform active:scale-95 transition">
                    <Save size={20} /> حفظ وترحيل المبيعات
                </button>
            </div>
        </div>
    );
};

export default DailySales;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove } from "firebase/database";
import { User, SaleRecord } from '../types';
import { Trash2, FileSpreadsheet, Calendar, User as UserIcon, Star, Download, Filter } from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');

    useEffect(() => {
        onValue(ref(db, 'sales'), (snapshot) => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                let list: SaleRecord[] = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                if (user.role !== 'admin' && !user.canViewAllSales) list = list.filter(s => s.employeeName === user.name);
                setSales(list.sort((a, b) => b.timestamp - a.timestamp));
            } else setSales([]);
        });
    }, [user]);

    useEffect(() => {
        let res = sales;
        if (filterDate) res = res.filter(s => s.date.includes(filterDate));
        if (filterEmployee) res = res.filter(s => s.employeeName.includes(filterEmployee));
        if (filterMarket) res = res.filter(s => s.market === filterMarket);
        setFilteredSales(res);
    }, [sales, filterDate, filterEmployee, filterMarket]);

    const handleExport = () => {
        if (filteredSales.length === 0) return alert("لا توجد بيانات");
        const exportData = filteredSales.map(s => ({
            "الموظف": s.employeeName,
            "التاريخ": s.date,
            "الماركت": s.market,
            "الإجمالي": s.total
        }));
        exportToCSV(exportData, "Sales_Log");
    };

    const getStarOfMonth = () => {
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
        const totals: Record<string, number> = {};
        sales.filter(s => s.timestamp >= start).forEach(s => totals[s.employeeName] = (totals[s.employeeName] || 0) + s.total);
        const sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);
        return sorted.length > 0 ? { name: sorted[0][0], total: sorted[0][1] } : null;
    };
    const star = getStarOfMonth();

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2 text-white"><FileSpreadsheet /> سجل المبيعات</h2>
                {user.role === 'admin' && (
                    <button onClick={handleExport} className="bg-green-600 text-white px-4 py-2 rounded-xl flex items-center gap-2 font-bold shadow-lg"><Download size={18}/> تصدير Excel</button>
                )}
            </div>

            {star && (
                <div className="bg-[#808080] p-6 rounded-3xl border border-white/20 shadow-2xl flex flex-col items-center justify-center space-y-2 relative overflow-hidden group text-white">
                    <Star className="text-yellow-400 animate-pulse" size={32} fill="currentColor" />
                    <h3 className="text-xl font-black uppercase tracking-widest">نجم الشهر</h3>
                    <div className="text-3xl font-black">{star.name}</div>
                    <div className="text-sm font-bold opacity-80">إجمالي المبيعات: <span className="text-green-300 font-black">{star.total.toLocaleString()} ج.م</span></div>
                </div>
            )}

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                {user.role === 'admin' && <input type="date" className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterDate} onChange={e => setFilterDate(e.target.value)} />}
                <input type="text" placeholder="بحث باسم الموظف..." className="p-3 rounded-xl bg-gray-700 text-white border border-white/20 text-xs" value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} />
                <select className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterMarket} onChange={e => setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {filteredSales.map(sale => (
                    <div key={sale.id} className="p-5 rounded-3xl border border-white/10 bg-gray-800 shadow-2xl text-white">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <div className="font-bold text-xl text-blue-400">{sale.market}</div>
                                <div className="flex items-center gap-3 text-[10px] opacity-60 font-bold mt-1">
                                    <span className="flex items-center gap-1"><Calendar size={12}/> {sale.date}</span>
                                    <span className="flex items-center gap-1"><UserIcon size={12}/> {sale.employeeName}</span>
                                </div>
                            </div>
                            {user.role === 'admin' && (
                                <button onClick={() => remove(ref(db, `sales/${sale.id!}`))} className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition"><Trash2 size={18}/></button>
                            )}
                        </div>
                        <div className="overflow-hidden rounded-2xl bg-black/20 border border-white/5">
                            <table className="w-full text-[11px] text-center">
                                <thead className="bg-white/5 text-white/50">
                                    <tr><th className="py-2 px-3 text-right">الصنف</th><th className="py-2">السعر</th><th className="py-2">الكمية</th><th className="py-2 px-3">المجموع</th></tr>
                                </thead>
                                <tbody>
                                    {(sale.items || []).map((item, idx) => (
                                        <tr key={idx} className="border-t border-white/5">
                                            <td className="py-2 px-3 text-right font-bold">{item.name}</td>
                                            <td className="py-2">{item.price}</td>
                                            <td className="py-2 font-black">{item.qty}</td>
                                            <td className="py-2 px-3 text-green-400 font-black">{(item.qty * item.price).toLocaleString()}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="mt-4 text-left font-black text-lg text-blue-400">إجمالي: {sale.total.toLocaleString()} ج.م</div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default SalesLog;

import React, { useState, useEffect } from 'react';
import { ref, push, set, onValue } from "firebase/database";
import { db } from '../firebase';
import { User } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

interface InventoryItem {
    id: string;
    name: string;
    qty: number;
    category: string;
    isCustom: boolean;
}

const InventoryRegistration: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [items, setItems] = useState<InventoryItem[]>([]);

    const allCategories = [
        { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial', allowAdd: true },
        { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen', allowAdd: true },
        { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet', allowAdd: false },
        { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin', allowAdd: true },
    ];

    useEffect(() => {
        const baseItems: InventoryItem[] = [];
        allCategories.forEach(cat => {
            cat.items.forEach(prod => {
                baseItems.push({
                    id: prod,
                    name: prod,
                    qty: 0,
                    category: cat.key,
                    isCustom: false
                });
            });
        });
        setItems(baseItems);
    }, []);

    const updateItem = (id: string, field: 'qty' | 'name', value: any) => {
        setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const inventoryData = {
            market: selectedMarket,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: items.filter(i => i.qty > 0).map(i => ({ name: i.name, qty: i.qty, category: i.category }))
        };
        if (inventoryData.items.length === 0) return alert("الكميات كلها صفر");
        await push(ref(db, 'inventory'), inventoryData);
        alert("تم حفظ المخزون");
        setItems(prev => prev.map(i => ({...i, qty: 0})));
    };

    return (
        <div className="pb-20">
            <div className="flex justify-between items-center mb-6 text-white">
                <h2 className="text-2xl font-bold">تسجيل المخزون</h2>
                <select className="w-48 bg-gray-700 text-white border border-white/20 p-2.5 rounded-xl font-bold" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                    <option value="">اختر الماركت</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            {allCategories.map(cat => (
                <div key={cat.key} className="mb-6 bg-white/5 p-4 rounded-lg">
                    <h3 className="text-xl font-bold text-blue-500 mb-4 border-b border-gray-500/20 pb-2">{cat.name}</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {items.filter(i => i.category === cat.key).map((item) => (
                            <div key={item.id} className="flex justify-between items-center gap-2 p-2 border-b border-gray-500/10">
                                <span className="text-sm font-medium text-white">{item.name}</span>
                                <input type="number" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} className="bg-white/10 border border-white/20 p-2 rounded text-white w-20 text-center" placeholder="الكمية" />
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 hover:bg-green-700 text-white py-4 rounded-3xl font-bold shadow-2xl flex justify-center items-center gap-2 active:scale-95 transition">
                    <Save size={20} /> حفظ المخزون
                </button>
            </div>
        </div>
    );
};

export default InventoryRegistration;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, set, onValue } from "firebase/database";
import { User } from '../types';
import { COMPANIES, PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, FINE_FACIAL, FINE_KITCHEN, FINE_TOILET, ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET, PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET, WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET } from '../constants';
import { Save, Plus } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [items, setItems] = useState<{category: string, name: string, price: number, isCustom?: boolean, id?: string}[]>([]);

    useEffect(() => {
        if (!selectedCompany) return;

        const generateBase = (facial: string[], kitchen: string[], toilet: string[]) => {
            return [
                ...facial.map(n => ({ category: 'Facial', name: n, price: 0, id: n })),
                ...kitchen.map(n => ({ category: 'Kitchen', name: n, price: 0, id: n })),
                ...toilet.map(n => ({ category: 'Toilet', name: n, price: 0, id: n })),
            ];
        };

        let base: any[] = [];
        switch(selectedCompany) {
            case 'Soft Rose': base = generateBase(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET); break;
            case 'Fine': base = generateBase(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET); break;
            case 'Zeina': base = generateBase(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET); break;
            case 'Papia Familia': base = generateBase(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET); break;
            case 'White': base = generateBase(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET); break;
            default: base = []; break;
        }
        setItems(base);
    }, [selectedCompany]);

    const handleSaveReport = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const validItems = items.filter(i => i.price > 0);
        if (validItems.length === 0) return alert("يرجى إدخال الأسعار");

        await push(ref(db, 'competitor_prices'), {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: validItems
        });
        alert("تم الحفظ بنجاح");
        setItems(prev => prev.map(i => ({...i, price: 0})));
    };

    return (
        <div className="space-y-6 pb-20 text-white">
            <h2 className="text-2xl font-bold">تسجيل أسعار المنافسين</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 bg-gray-800 p-6 rounded-3xl border border-white/10 shadow-lg">
                <select className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                    <option value="">اختر الماركت...</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <select className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10" value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                    <option value="">اختر الشركة...</option>
                    {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {items.length > 0 && ['Facial', 'Kitchen', 'Toilet'].map(cat => (
                    <div key={cat} className="bg-gray-800 p-4 rounded-3xl border border-white/5 shadow-md">
                        <h3 className="font-bold text-blue-400 mb-3 border-b border-white/10 pb-2">{cat}</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                            {items.filter(i => i.category === cat).map((item, idx) => (
                                <div key={idx} className="flex items-center gap-2 bg-black/20 p-2 rounded-xl">
                                    <span className="flex-1 text-xs font-bold truncate">{item.name}</span>
                                    <input type="number" placeholder="السعر" className="w-24 p-2 bg-gray-700 rounded-lg text-white text-center text-xs font-black" value={item.price || ''} onChange={e => {
                                        const newItems = [...items];
                                        const actualIdx = items.findIndex(it => it.name === item.name);
                                        newItems[actualIdx].price = parseFloat(e.target.value) || 0;
                                        setItems(newItems);
                                    }} />
                                </div>
                            ))}
                        </div>
                    </div>
                ))}
            </div>

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSaveReport} className="bg-green-600 hover:bg-green-700 w-full py-5 text-white rounded-3xl font-black shadow-2xl flex items-center justify-center gap-2 transform active:scale-95 transition">
                    <Save size={20}/> حفظ وترحيل أسعار المنافسين
                </button>
            </div>
        </div>
    );
};

export default CompetitorPrices;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { Trash2, CalendarPlus, X, Save, History, ChevronRight, ChevronLeft, CheckCircle2, Calendar as CalendarIcon, User as UserIcon } from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<Record<string, LeaveBalance>>({});
    const [usersList, setUsersList] = useState<User[]>([]);
    const [allHistory, setAllHistory] = useState<({id: string} & LeaveRecord)[]>([]);
    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [showHistoryDetailsModal, setShowHistoryDetailsModal] = useState(false);
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);

    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams' | 'unpaid'>('annual');

    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات', unpaid: 'غياب بدون إذن' };
    const typeColors = { annual: 'text-green-400', casual: 'text-yellow-400', sick: 'text-red-400', exams: 'text-purple-400', unpaid: 'text-orange-400' };

    useEffect(() => {
        onValue(ref(db, 'users'), snapshot => {
            if (snapshot.exists()) {
                const u: User[] = []; snapshot.forEach(c => { u.push({ key: c.key!, ...c.val() }); });
                setUsersList(u);
            }
        });

        onValue(ref(db, 'leave_balances'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val() as Record<string, LeaveBalance>;
                setBalances(data);

                const now = new Date();
                const currentMonthKey = `${now.getFullYear()}-${now.getMonth() + 1}`;
                if (now.getDate() >= 21) {
                    Object.keys(data).forEach(async (uKey) => {
                        const balance = data[uKey];
                        if (balance.lastUnpaidReset !== currentMonthKey) {
                            await update(ref(db, `leave_balances/${uKey}`), { unpaid: 0, lastUnpaidReset: currentMonthKey });
                        }
                    });
                }
            } else setBalances({});
        });

        onValue(ref(db, 'leave_history'), snapshot => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                const h: any = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                setAllHistory(h.sort((a,b) => b.timestamp - a.timestamp));
            } else setAllHistory([]);
        });
    }, []);

    const handleAddLeave = async () => {
        if (!selectedUser || !leaveDate) return alert("اكمل البيانات");
        const targetUser = usersList.find(u => u.key === selectedUser);
        if (!targetUser) return;

        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        const snap = await get(balanceRef);
        let cur = snap.exists() ? snap.val() : { userId: selectedUser, employeeName: targetUser.name, annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };

        const typeLogic = { annual: 'remaining', casual: 'remaining', sick: 'accrued', exams: 'accrued', unpaid: 'accrued' };
        let newValue = (typeLogic[leaveType] === 'remaining') ? (Number(cur[leaveType]) - Number(leaveDays)) : (Number(cur[leaveType]) + Number(leaveDays));

        await update(balanceRef, { ...cur, [leaveType]: newValue });
        await push(ref(db, 'leave_history'), { userId: selectedUser, employeeName: targetUser.name, date: leaveDate, days: Number(leaveDays), type: leaveType, timestamp: new Date(leaveDate).getTime() });
        setShowAddLeaveModal(false); alert("تم الحفظ بنجاح");
    };

    const displayedUsers = (user.role === 'admin' || user.canViewAllSales) ? usersList : usersList.filter(u => u.username === user.username);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center text-white">
                <h2 className="text-2xl font-bold flex items-center gap-2"><History className="text-blue-500" /> رصيد الإجازات والغياب</h2>
                {user.role === 'admin' && (
                    <button onClick={() => setShowAddLeaveModal(true)} className="bg-red-600 text-white px-5 py-2.5 rounded-2xl font-bold shadow-xl flex items-center gap-2 transition active:scale-95"><CalendarPlus size={18} /> تسجيل إجازة/غياب</button>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {displayedUsers.map(u => {
                    const balance = balances[u.key!] || { userId: u.key!, employeeName: u.name, annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };
                    return (
                        <div key={u.key} className="p-5 rounded-3xl border border-white/10 bg-gray-800 text-white shadow-xl relative overflow-hidden">
                            <div className="flex justify-between items-start mb-4">
                                <div><div className="font-bold text-lg text-blue-400">{u.name}</div><div className="text-[10px] opacity-40">@{u.username}</div></div>
                                <button onClick={() => { setHistoryUserView({userId: u.key!, name: u.name}); setShowHistoryDetailsModal(true); }} className="text-[10px] font-bold bg-white/5 px-3 py-1.5 rounded-xl hover:bg-white/10 transition">عرض السجل</button>
                            </div>
                            <div className="grid grid-cols-2 gap-2">
                                {Object.entries(typeLabels).map(([key, label]) => (
                                    <div key={key} className="p-3 bg-black/20 rounded-2xl border border-white/5 flex flex-col items-center">
                                        <span className="text-[10px] opacity-50 font-black text-center h-6 leading-3">{label}</span>
                                        <span className={`text-xl font-black ${typeColors[key as keyof typeof typeColors]}`}>{(balance as any)[key] || 0}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>

            {showHistoryDetailsModal && historyUserView && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
                    <div className="w-full max-w-2xl p-6 rounded-3xl border border-white/10 bg-gray-900 text-white flex flex-col max-h-[90vh] shadow-2xl animate-in zoom-in-95">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold">{historyUserView.name}</h3>
                            <button onClick={() => setShowHistoryDetailsModal(false)} className="text-white"><X/></button>
                        </div>
                        <div className="flex-1 overflow-y-auto space-y-3 pr-1 custom-scrollbar">
                            {allHistory.filter(h => h.userId === historyUserView.userId).map(rec => (
                                <div key={rec.id} className="p-4 rounded-2xl border bg-black/20 border-white/5 flex justify-between items-center">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-xl bg-white/5 ${typeColors[rec.type]}`}><CheckCircle2 size={18} /></div>
                                        <div><div className="font-bold text-sm">{typeLabels[rec.type]}</div><div className="text-[10px] opacity-50">{rec.date}</div></div>
                                    </div>
                                    <div className="font-black text-lg">{rec.days} يوم</div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {showAddLeaveModal && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
                    <div className="w-full max-w-md p-6 rounded-3xl border border-white/10 bg-gray-900 text-white shadow-2xl">
                        <div className="flex justify-between items-center mb-6"><h3 className="text-xl font-bold">تسجيل إجازة / غياب</h3><button onClick={() => setShowAddLeaveModal(false)} className="text-white/50 hover:text-white"><X size={20}/></button></div>
                        <div className="space-y-4">
                            <select className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10 font-bold" value={selectedUser} onChange={e => setSelectedUser(e.target.value)}>
                                <option value="">-- اختر الموظف --</option>
                                {usersList.map(u => <option key={u.key} value={u.key}>{u.name}</option>)}
                            </select>
                            <input type="date" className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10" value={leaveDate} onChange={e => setLeaveDate(e.target.value)} />
                            <div className="grid grid-cols-2 gap-4">
                                <input type="number" step="0.5" className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10 text-center font-black" value={leaveDays} onChange={e => setLeaveDays(parseFloat(e.target.value))} />
                                <select className="w-full p-4 rounded-2xl bg-gray-700 text-white border border-white/10 font-bold" value={leaveType} onChange={e => setLeaveType(e.target.value as any)}>
                                    {Object.entries(typeLabels).map(([k,v]) => <option key={k} value={k}>{v}</option>)}
                                </select>
                            </div>
                            <button onClick={handleAddLeave} className="w-full bg-red-600 text-white font-bold py-4 rounded-2xl shadow-xl active:scale-95 transition mt-4">حفظ العملية</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default LeaveBalanceComponent;

