import React, { useState, useEffect } from 'react';
import { ref, push, onValue, set, get, update, remove } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem, UserTarget } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Calculator, Target, TrendingUp, AlertCircle, Edit, Trash2, Check, X } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [userTarget, setUserTarget] = useState<UserTarget | null>(null);
    const [editingItemId, setEditingItemId] = useState<string | null>(null);
    const [tempName, setTempName] = useState('');

    useEffect(() => {
        const initialItems: ProductItem[] = [];
        const categories = [
            { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
            { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
            { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
            { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
        ];

        categories.forEach(cat => {
            cat.items.forEach(name => {
                initialItems.push({ id: name, name, price: 0, qty: 0, category: cat.key });
            });
        });

        // جلب الأصناف المضافة عالمياً
        onValue(ref(db, 'settings/global_products'), (snapshot) => {
            const extra: ProductItem[] = [];
            if (snapshot.exists()) {
                snapshot.forEach(child => {
                    const prod = child.val();
                    extra.push({ ...prod, price: 0, qty: 0 });
                });
            }

            const combined = [...initialItems];
            extra.forEach(ex => {
                const idx = combined.findIndex(c => c.id === ex.id);
                if (idx > -1) combined[idx] = ex;
                else combined.push(ex);
            });
            setSalesItems(combined);
        });

        if (user.key) {
            onValue(ref(db, `targets/${user.key}`), (snapshot) => {
                if (snapshot.exists()) setUserTarget(snapshot.val());
                else setUserTarget(null);
            });
        }
    }, [user.key]);

    const updateItem = (id: string, field: string, value: any) => {
        setSalesItems(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    const deleteItem = async (id: string) => {
        if (user.role !== 'admin') return alert("للمسؤول فقط");
        if (confirm("حذف الصنف نهائياً من النظام؟")) {
            await remove(ref(db, `settings/global_products/${id.replace(/[.#$/[\]]/g, "_")}`));
        }
    };

    const addCustomItem = async (category: string) => {
        if (user.role !== 'admin') return alert("إضافة الأصناف للمسؤول فقط");
        const name = prompt("اسم الصنف الجديد (English):");
        if (name) {
            if (/[\u0600-\u06FF]/.test(name)) return alert("الإنجليزية فقط");
            const safeId = name.replace(/[.#$/[\]]/g, "_");
            await set(ref(db, `settings/global_products/${safeId}`), { id: name, name, category, isCustom: true });
        }
    };

    const startEditing = (id: string, name: string) => {
        if (user.role !== 'admin') return;
        setEditingItemId(id); setTempName(name);
    };

    const saveName = async (id: string) => {
        if (/[\u0600-\u06FF]/.test(tempName)) return alert("الإنجليزية فقط");
        const safeId = id.replace(/[.#$/[\]]/g, "_");
        await update(ref(db, `settings/global_products/${safeId}`), { name: tempName });
        setEditingItemId(null);
    };

    const currentTotal = salesItems.reduce((sum, item) => sum + ((item.price || 0) * (item.qty || 0)), 0);

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const sold = salesItems.filter(i => i.qty > 0 && i.price > 0);
        if (!sold.length) return alert("أدخل بيانات");

        await push(ref(db, 'sales'), {
            market: selectedMarket, employeeName: user.name, username: user.username,
            date: new Date().toLocaleDateString('ar-EG'), timestamp: Date.now(),
            items: sold, total: currentTotal
        });

        if (user.key && userTarget) {
            await update(ref(db, `targets/${user.key}`), { achieved: (userTarget.achieved || 0) + currentTotal });
        }

        alert("تم الحفظ");
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
    };

    const progressPercent = userTarget ? Math.round((userTarget.achieved / userTarget.finalTarget) * 100) : 0;

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h2 className="text-2xl font-bold text-white">المبيعات اليومية</h2>
                <div className="flex flex-wrap gap-4">
                    <div className="bg-blue-600/20 border border-blue-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[180px]">
                        <div className="bg-blue-600 p-2 rounded-2xl text-white"><Calculator size={24} /></div>
                        <div>
                            <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">إجمالي الحالية</div>
                            <div className="text-xl font-black text-blue-400">{currentTotal.toLocaleString()} <span className="text-xs">ج.م</span></div>
                        </div>
                    </div>
                    {userTarget && (
                        <div className="bg-purple-600/20 border border-purple-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[250px]">
                            <div className="bg-purple-600 p-2 rounded-2xl text-white"><Target size={24} /></div>
                            <div className="flex-1">
                                <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">تارجت الموظف: {userTarget.achieved.toLocaleString()} / {userTarget.finalTarget.toLocaleString()}</div>
