                                        <div className="flex gap-1">
                                            <input type="text" className="bg-gray-700 p-1 rounded w-full outline-none" value={tempName} onChange={e => setTempName(e.target.value)} autoFocus />
                                            <button onClick={() => saveName(item.id)} className="text-green-400"><Check size={14}/></button>
                                        </div>
                                    ) : item.name}
                                </div>
                                <div className="col-span-2"><input type="number" placeholder="0" className="w-full bg-gray-700 p-2 rounded-xl text-white text-center text-xs" value={item.price || ''} onChange={e => updateItem(item.id, 'price', parseFloat(e.target.value))} /></div>
                                <div className="col-span-2"><input type="number" placeholder="0" className="w-full bg-gray-700 p-2 rounded-xl text-white text-center text-xs" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} /></div>
                                <div className="col-span-2 text-center font-black text-xs text-green-400">{(item.price * item.qty).toLocaleString()}</div>
                                <div className="col-span-1 flex gap-1">
                                    {user.role === 'admin' && (
                                        <>
                                            <button onClick={() => startEditing(item.id, item.name)} className="text-blue-400"><Edit size={12}/></button>
                                            <button onClick={() => deleteItem(item.id)} className="text-red-400"><Trash2 size={12}/></button>
                                        </>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 hover:bg-green-700 text-white py-4 rounded-3xl font-black shadow-2xl flex justify-center items-center gap-2 transform active:scale-95 transition"><Save size={20} /> حفظ وترحيل المبيعات</button>
            </div>
        </div>
    );
};

