import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance, LeaveRecord } from '../types';
import { Trash2, Edit, CalendarPlus, X, Save, History, CheckCircle2, Calendar as CalendarIcon, User as UserIcon } from 'lucide-react';

interface Props {
    user: User;
    theme: string;
}

const LeaveBalanceComponent: React.FC<Props> = ({ user, theme }) => {
    const [balances, setBalances] = useState<Record<string, LeaveBalance>>({});
    const [usersList, setUsersList] = useState<User[]>([]);
    const [allHistory, setAllHistory] = useState<({id: string} & LeaveRecord)[]>([]);
    const [showAddLeaveModal, setShowAddLeaveModal] = useState(false);
    const [editingRecord, setEditingRecord] = useState<({id: string} & LeaveRecord) | null>(null);
    const [historyUserView, setHistoryUserView] = useState<{userId: string, name: string} | null>(null);

    const [selectedUser, setSelectedUser] = useState('');
    const [leaveDate, setLeaveDate] = useState('');
    const [leaveDays, setLeaveDays] = useState(1);
    const [leaveType, setLeaveType] = useState<'annual' | 'casual' | 'sick' | 'exams' | 'unpaid'>('annual');

    const typeLabels = { annual: 'سنوي', casual: 'عارضة', sick: 'مرضي', exams: 'امتحانات', unpaid: 'غياب بدون إذن' };
    const typeColors = { annual: 'text-green-400', casual: 'text-yellow-400', sick: 'text-red-400', exams: 'text-purple-400', unpaid: 'text-orange-400' };

    useEffect(() => {
        onValue(ref(db, 'users'), s => { if (s.exists()) { const u: User[] = []; s.forEach(c => { u.push({ key: c.key!, ...c.val() }); }); setUsersList(u); } });
        onValue(ref(db, 'leave_balances'), s => { if (s.exists()) setBalances(s.val()); else setBalances({}); });
        onValue(ref(db, 'leave_history'), s => { if (s.exists()) { const h: any = Object.keys(s.val()).map(key => ({ id: key, ...s.val()[key] })); setAllHistory(h.sort((a:any,b:any) => b.timestamp - a.timestamp)); } else setAllHistory([]); });
    }, []);

    const handleAction = async () => {
        if (!selectedUser || !leaveDate) return alert("اكمل البيانات");
        const balanceRef = ref(db, `leave_balances/${selectedUser}`);
        const snap = await get(balanceRef);
        let bal = snap.val() || { annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };

        if (editingRecord) {
            // عكس العملية القديمة أولاً
            const mOld = ['annual', 'casual'].includes(editingRecord.type) ? 1 : -1;
            bal[editingRecord.type] += (mOld * editingRecord.days);
            await remove(ref(db, `leave_history/${editingRecord.id}`));
        }

        const mNew = ['annual', 'casual'].includes(leaveType) ? -1 : 1;
        bal[leaveType] += (mNew * leaveDays);

        await update(balanceRef, bal);
        await push(ref(db, 'leave_history'), { userId: selectedUser, employeeName: usersList.find(u => u.key === selectedUser)?.name, date: leaveDate, days: leaveDays, type: leaveType, timestamp: Date.now() });

        setShowAddLeaveModal(false); setEditingRecord(null); alert("تم الحفظ");
    };

    const startEdit = (rec: any) => {
        setEditingRecord(rec); setSelectedUser(rec.userId); setLeaveDate(rec.date); setLeaveDays(rec.days); setLeaveType(rec.type); setShowAddLeaveModal(true);
    };

    const periodDate = new Date();
    const periodStart = periodDate.getDate() >= 21 ? new Date(periodDate.getFullYear(), periodDate.getMonth(), 21) : new Date(periodDate.getFullYear(), periodDate.getMonth() - 1, 21);
    const periodEnd = new Date(periodStart.getFullYear(), periodStart.getMonth() + 1, 20);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center text-white">
                <h2 className="text-2xl font-bold flex items-center gap-2"><History className="text-blue-500" /> الإجازات</h2>
                {user.role === 'admin' && <button onClick={() => { setEditingRecord(null); setShowAddLeaveModal(true); }} className="bg-red-600 px-5 py-2.5 rounded-2xl font-bold flex items-center gap-2 transition active:scale-95"><CalendarPlus size={18} /> تسجيل إجازة</button>}
            </div>

            <div className="bg-white/5 p-4 rounded-3xl border border-white/10 text-center text-white">
                <span className="text-xs opacity-50 uppercase tracking-widest block mb-1">دورة الشهر الحالية</span>
                <span className="font-bold text-sm">من {periodStart.toLocaleDateString('ar-EG', {day: 'numeric', month: 'numeric', year: 'numeric'})} إلى {periodEnd.toLocaleDateString('ar-EG', {day: 'numeric', month: 'numeric', year: 'numeric'})}</span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                {usersList.filter(u => user.role === 'admin' || u.name === user.name).map(u => {
                    const balance = balances[u.key!] || { annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };
                    return (
                        <div key={u.key} className="p-5 rounded-3xl border border-white/10 bg-gray-800 text-white shadow-xl">
                            <div className="flex justify-between items-start mb-4 border-b border-white/5 pb-3">
                                <div className="font-bold text-blue-400">{u.name}</div>
                                <button onClick={() => { setHistoryUserView({userId: u.key!, name: u.name}); }} className="text-[10px] bg-white/5 px-3 py-1.5 rounded-xl">السجل</button>
                            </div>
                            <div className="grid grid-cols-2 gap-2 text-center">
                                {Object.entries(typeLabels).map(([key, label]) => (
                                    <div key={key} className="p-2 bg-black/20 rounded-xl border border-white/5">
                                        <div className="text-[10px] opacity-40 mb-1">{label}</div>
                                        <div className={`text-lg font-black ${typeColors[key as keyof typeof typeColors]}`}>{(balance as any)[key] || 0}</div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>

            {historyUserView && (
                <div className="fixed inset-0 z-[100] bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
                    <div className="bg-gray-900 p-6 rounded-3xl w-full max-w-lg shadow-2xl animate-in zoom-in-95 text-white">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="font-bold text-lg">سجل {historyUserView.name}</h3>
                            <button onClick={() => setHistoryUserView(null)}><X/></button>
                        </div>
                        <div className="space-y-3 max-h-80 overflow-y-auto custom-scrollbar">
                            {allHistory.filter(h => h.userId === historyUserView.userId).map(rec => (
                                <div key={rec.id} className="p-3 bg-black/30 rounded-2xl flex justify-between items-center">
                                    <div className="text-xs">
                                        <div className={`font-bold ${typeColors[rec.type]}`}>{typeLabels[rec.type]}</div>
                                        <div className="opacity-50">{rec.date}</div>
                                    </div>
                                    <div className="flex items-center gap-3">
                                        <span className="font-black">{rec.days} يوم</span>
                                        {user.role === 'admin' && (
                                            <div className="flex gap-2">
                                                <button onClick={() => startEdit(rec)} className="text-blue-400"><Edit size={16}/></button>
                                                <button onClick={async () => { if(confirm("حذف؟")) await remove(ref(db, `leave_history/${rec.id}`)); }} className="text-red-400"><Trash2 size={16}/></button>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

            {showAddLeaveModal && (
                <div className="fixed inset-0 z-[120] bg-black/90 flex items-center justify-center p-4">
                    <div className="bg-gray-900 border border-white/10 w-full max-w-md rounded-3xl p-6 text-white shadow-2xl">
                        <h3 className="text-xl font-bold mb-6">{editingRecord ? 'تعديل سجل' : 'تسجيل إجازة'}</h3>
                        <div className="space-y-4">
                            <select className="w-full p-4 rounded-xl bg-gray-700 text-white font-bold" value={selectedUser} onChange={e => setSelectedUser(e.target.value)}>
                                <option value="">اختر الموظف</option>
                                {usersList.map(u => <option key={u.key} value={u.key!}>{u.name}</option>)}
                            </select>
                            <input type="date" className="w-full p-4 rounded-xl bg-gray-700" value={leaveDate} onChange={e => setLeaveDate(e.target.value)} />
                            <div className="grid grid-cols-2 gap-4">
                                <input type="number" step="0.5" className="w-full p-4 rounded-xl bg-gray-700 text-center font-black" value={leaveDays} onChange={e => setLeaveDays(parseFloat(e.target.value))} />
                                <select className="w-full p-4 rounded-xl bg-gray-700" value={leaveType} onChange={e => setLeaveType(e.target.value as any)}>
                                    {Object.entries(typeLabels).map(([k,v]) => <option key={k} value={k}>{v}</option>)}
                                </select>
                            </div>
                            <div className="flex gap-2 mt-4">
                                <button onClick={handleAction} className="flex-1 bg-blue-600 py-4 rounded-2xl font-bold">حفظ</button>
                                <button onClick={() => setShowAddLeaveModal(false)} className="flex-1 bg-white/5 py-4 rounded-2xl">إلغاء</button>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default LeaveBalanceComponent;

import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove } from "firebase/database";
import { User, SaleRecord } from '../types';
import { Trash2, FileSpreadsheet, Calendar, User as UserIcon, Star, Download, Package, TrendingUp } from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const SalesLog: React.FC<Props> = ({ user, markets, theme }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filteredSales, setFilteredSales] = useState<SaleRecord[]>([]);
    const [filterDate, setFilterDate] = useState('');
    const [filterEmployee, setFilterEmployee] = useState('');
    const [filterMarket, setFilterMarket] = useState('');
    const [exportStart, setExportStart] = useState('');
    const [exportEnd, setExportEnd] = useState('');

    useEffect(() => {
        onValue(ref(db, 'sales'), (snapshot) => {
            if (snapshot.exists()) {
                const data = snapshot.val();
                let list: SaleRecord[] = Object.keys(data).map(key => ({ id: key, ...data[key] }));
                if (user.role !== 'admin' && !user.canViewAllSales) list = list.filter(s => s.employeeName === user.name);
                setSales(list.sort((a, b) => b.timestamp - a.timestamp));
            } else setSales([]);
        });
    }, [user]);

    useEffect(() => {
        let res = sales;
        if (filterDate) res = res.filter(s => s.date.includes(filterDate));
        if (filterEmployee) res = res.filter(s => s.employeeName.includes(filterEmployee));
        if (filterMarket) res = res.filter(s => s.market === filterMarket);
        setFilteredSales(res);
    }, [sales, filterDate, filterEmployee, filterMarket]);

    const handleExportFiltered = () => {
        if (!exportStart || !exportEnd) return alert("حدد الفترة");
        const start = new Date(exportStart).getTime();
        const end = new Date(exportEnd).getTime() + 86400000;

        const periodSales = sales.filter(s => s.timestamp >= start && s.timestamp <= end && (!filterMarket || s.market === filterMarket));

        const itemsMap = new Map<string, { employee: string, name: string, price: number, qty: number }>();
        periodSales.forEach(s => {
            s.items.forEach(i => {
                const key = `${s.employeeName}_${i.name}`;
                if (itemsMap.has(key)) {
                    const existing = itemsMap.get(key)!;
                    existing.qty += i.qty;
                } else {
                    itemsMap.set(key, { employee: s.employeeName, name: i.name, price: i.price, qty: i.qty });
                }
            });
        });

        const dataRows = Array.from(itemsMap.values()).map(r => ({
            "اسم الموظف": r.employee,
            "اسم الصنف": r.name,
            "سعر القطعة": r.price,
            "إجمالي الكمية": r.qty,
            "إجمالي المبيعات": r.qty * r.price
        }));

        const totalValue = dataRows.reduce((acc, r) => acc + r["إجمالي المبيعات"], 0);
        dataRows.push({ "اسم الموظف": "الإجمالي الكلي", "اسم الصنف": "", "سعر القطعة": 0, "إجمالي الكمية": 0, "إجمالي المبيعات": totalValue });

        exportToCSV(dataRows, `Sales_Detailed_${exportStart}_to_${exportEnd}`);
    };

    const topSellers = useMemo(() => {
        if (user.role !== 'admin') return null;
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
        const monthSales = sales.filter(s => s.timestamp >= start);

        const stats = new Map<string, { name: string, price: number, qty: number }>();
        monthSales.forEach(s => {
            s.items.forEach(i => {
                if (!stats.has(i.name)) stats.set(i.name, { name: i.name, price: i.price, qty: 0 });
                stats.get(i.name)!.qty += i.qty;
            });
        });

        return Array.from(stats.values()).sort((a,b) => (b.qty * b.price) - (a.qty * a.price)).slice(0, 5);
    }, [sales, user.role]);

    const star = useMemo(() => {
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
        const totals: Record<string, number> = {};
        sales.filter(s => s.timestamp >= start).forEach(s => totals[s.employeeName] = (totals[s.employeeName] || 0) + s.total);
        const sorted = Object.entries(totals).sort((a, b) => b[1] - a[1]);
        return sorted.length > 0 ? { name: sorted[0][0], total: sorted[0][1] } : null;
    }, [sales]);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center text-white">
                <h2 className="text-2xl font-bold flex items-center gap-2"><FileSpreadsheet /> سجل المبيعات</h2>
                {user.role === 'admin' && (
                    <div className="flex gap-2">
                        <input type="date" className="bg-gray-700 p-2 rounded-xl text-xs" value={exportStart} onChange={e => setExportStart(e.target.value)} />
                        <input type="date" className="bg-gray-700 p-2 rounded-xl text-xs" value={exportEnd} onChange={e => setExportEnd(e.target.value)} />
                        <button onClick={handleExportFiltered} className="bg-green-600 px-4 py-2 rounded-xl font-bold flex items-center gap-2"><Download size={18}/> تصدير</button>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {star && (
                    <div className="bg-[#808080] p-6 rounded-3xl border border-white/20 shadow-2xl flex flex-col items-center justify-center text-white relative">
                        <Star className="text-yellow-400 mb-2" size={32} fill="currentColor" />
                        <h3 className="text-lg font-black uppercase">نجم الشهر</h3>
                        <div className="text-3xl font-black">{star.name}</div>
                        <div className="text-sm font-bold opacity-80">{star.total.toLocaleString()} ج.م</div>
                    </div>
                )}
                {user.role === 'admin' && topSellers && (
                    <div className="bg-gray-800 p-6 rounded-3xl border border-white/10 shadow-2xl text-white">
                        <h3 className="font-bold flex items-center gap-2 text-blue-400 mb-4"><TrendingUp size={20}/> الأكثر مبيعاً (الشهر)</h3>
                        <div className="space-y-2">
                            {topSellers.map((item, i) => (
                                <div key={i} className="flex justify-between text-xs border-b border-white/5 pb-1">
                                    <span className="font-bold">{item.name}</span>
                                    <span className="text-green-400">{(item.qty * item.price).toLocaleString()} <span className="opacity-40 text-[10px]">({item.qty})</span></span>
                                </div>
                            ))}
                        </div>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
                <input type="text" placeholder="بحث باسم الموظف..." className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterEmployee} onChange={e => setFilterEmployee(e.target.value)} />
                <select className="p-3 rounded-xl bg-gray-700 text-white border border-white/20" value={filterMarket} onChange={e => setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>

            <div className="space-y-4">
                {filteredSales.map(sale => (
                    <div key={sale.id} className="p-5 rounded-3xl border border-white/10 bg-gray-800 shadow-xl text-white">
                        <div className="flex justify-between items-start mb-4">
                            <div>
                                <div className="font-bold text-xl text-blue-400">{sale.market}</div>
                                <div className="text-[10px] opacity-60 font-bold">{sale.date} - {sale.employeeName}</div>
                            </div>
                            {user.role === 'admin' && <button onClick={() => remove(ref(db, `sales/${sale.id!}`))} className="text-red-400"><Trash2 size={18}/></button>}
                        </div>
                        <div className="bg-black/20 rounded-2xl p-2">
                            <table className="w-full text-[11px]">
                                <thead className="opacity-50"><tr><th className="text-right">الصنف</th><th>السعر</th><th>الكمية</th><th>المجموع</th></tr></thead>
                                <tbody className="text-center font-bold">
                                    {sale.items.map((i,idx)=>(<tr key={idx}><td className="text-right">{i.name}</td><td>{i.price}</td><td>{i.qty}</td><td className="text-green-400">{i.qty*i.price}</td></tr>))}
                                </tbody>
                            </table>
                        </div>
                        <div className="mt-4 text-left font-black text-lg text-blue-400">إجمالي: {sale.total.toLocaleString()}</div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default SalesLog;

import React, { useState, useEffect } from 'react';
import { ref, push, set, onValue, remove } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Trash2 } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const InventoryRegistration: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [items, setItems] = useState<ProductItem[]>([]);

    useEffect(() => {
        const base: ProductItem[] = [];
        [PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN].forEach((list, i) => {
            const cat = ['Facial', 'Kitchen', 'Toilet', 'Dolphin'][i];
            list.forEach(n => base.push({ id: n, name: n, category: cat, qty: 0, price: 0 }));
        });

        onValue(ref(db, 'settings/global_products'), snap => {
            const extra: ProductItem[] = [];
            if(snap.exists()){ snap.forEach(c => { extra.push({...c.val(), qty: 0, price: 0}); }); }
            const combined = [...base];
            extra.forEach(e => {
                const idx = combined.findIndex(c => c.id === e.id);
                if(idx > -1) combined[idx] = e; else combined.push(e);
            });
            setItems(combined);
        });
    }, []);

    const updateQty = (id: string, qty: number) => {
        setItems(prev => prev.map(i => i.id === id ? {...i, qty} : i));
    };

    const addCustom = async (cat: string) => {
        if (user.role !== 'admin') return alert("للمسؤول فقط");
        const name = prompt("الصنف الجديد:");
        if (name && !/[\u0600-\u06FF]/.test(name)) {
            await set(ref(db, `settings/global_products/${name.replace(/[.#$/[\]]/g, "_")}`), { id: name, name, category: cat, isCustom: true });
        }
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const inv = items.filter(i => i.qty > 0).map(i => ({ name: i.name, qty: i.qty, category: i.category }));
        if (inv.length === 0) return alert("أدخل كميات");
        await push(ref(db, 'inventory'), { market: selectedMarket, date: new Date().toLocaleDateString('ar-EG'), timestamp: Date.now(), employeeName: user.name, items: inv });
        alert("تم الحفظ"); setItems(prev => prev.map(i => ({...i, qty: 0})));
    };

    return (
        <div className="pb-20 text-white">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold">تسجيل المخزون</h2>
                <select className="bg-gray-700 p-2.5 rounded-xl border border-white/20 font-bold" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                    <option value="">اختر الماركت</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>
            {['Facial', 'Kitchen', 'Toilet', 'Dolphin'].map(cat => (
                <div key={cat} className="mb-6 bg-white/5 p-4 rounded-3xl border border-white/10">
                    <div className="flex justify-between items-center mb-4 border-b border-white/10 pb-2">
                        <h3 className="font-bold text-blue-500">{cat}</h3>
                        {user.role === 'admin' && <button onClick={() => addCustom(cat)} className="text-xs bg-green-600 px-3 py-1.5 rounded-xl"><Plus size={14}/></button>}
                    </div>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                        {items.filter(i => i.category === cat).map(item => (
                            <div key={item.id} className="flex justify-between items-center p-2 border-b border-white/5">
                                <span className="text-xs font-bold">{item.name}</span>
                                <input type="number" className="bg-gray-700 w-20 text-center p-2 rounded-lg" value={item.qty || ''} onChange={e => updateQty(item.id, parseFloat(e.target.value))} />
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 py-4 rounded-3xl font-black shadow-2xl flex justify-center items-center gap-2"><Save size={20} /> حفظ المخزون</button>
