import React, { useState, useEffect } from 'react';
import { ref, push, onValue, set, get, update, remove } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem, UserTarget } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus, Calculator, Target, Edit, Trash2, Check, X } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const DailySales: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [salesItems, setSalesItems] = useState<ProductItem[]>([]);
    const [userTarget, setUserTarget] = useState<UserTarget | null>(null);
    const [editingItemId, setEditingItemId] = useState<string | null>(null);
    const [tempName, setTempName] = useState('');

    useEffect(() => {
        // تحميل الأصناف الأساسية
        const initialItems: ProductItem[] = [];
        const categories = [
            { name: 'مناديل السحب (Facial)', items: PRODUCTS_FACIAL, key: 'Facial' },
            { name: 'مناديل المطبخ (Kitchen)', items: PRODUCTS_KITCHEN, key: 'Kitchen' },
            { name: 'مناديل تواليت (Toilet)', items: PRODUCTS_TOILET, key: 'Toilet' },
            { name: 'مناديل دولفن (Dolphin)', items: PRODUCTS_DOLPHIN, key: 'Dolphin' },
        ];

        categories.forEach(cat => {
            cat.items.forEach(name => {
                initialItems.push({ 
                    id: name.replace(/[.#$/[\]]/g, "_"), 
                    name, 
                    price: 0, 
                    qty: 0, 
                    category: cat.key 
                });
            });
        });

        // الاستماع للأصناف المضافة عالمياً (Sync)
        const globalProdsRef = ref(db, 'settings/global_products');
        onValue(globalProdsRef, (snapshot) => {
            const currentItems = [...initialItems];
            if (snapshot.exists()) {
                snapshot.forEach(child => {
                    const prod = child.val();
                    const existingIdx = currentItems.findIndex(i => i.name === prod.name);
                    if (existingIdx === -1) {
                        currentItems.push({
                            id: child.key!,
                            name: prod.name,
                            category: prod.category,
                            price: 0,
                            qty: 0,
                            isCustom: true
                        });
                    }
                });
            }
            // دمج الكميات المدخلة حالياً إذا وجدت
            setSalesItems(prev => {
                const merged = currentItems.map(newItem => {
                    const prevItem = prev.find(p => p.name === newItem.name);
                    return prevItem ? { ...newItem, price: prevItem.price, qty: prevItem.qty } : newItem;
                });
                return merged;
            });
        });

        if (user.key) {
            const targetRef = ref(db, `targets/${user.key}`);
            onValue(targetRef, (snapshot) => {
                if (snapshot.exists()) {
                    setUserTarget(snapshot.val());
                } else {
                    setUserTarget(null);
                }
            });
        }
    }, [user.key]);

    const updateItem = (id: string, field: string, value: any) => {
        setSalesItems(prev => prev.map(i => i.id === id ? { ...i, [field]: value } : i));
    };

    // إضافة صنف جديد (Admin Only) - يتم الحفظ في DB للمزامنة
    const addCustomItem = async (category: string) => {
        if (user.role !== 'admin') return alert("هذه الخاصية للمسؤول فقط");
        const name = prompt("ادخل اسم الصنف الجديد (English Only):");
        if (name) {
            if (/[\u0600-\u06FF]/.test(name)) return alert("الإنجليزية فقط");
            const id = name.replace(/[.#$/[\]]/g, "_");
            await set(ref(db, `settings/global_products/${id}`), {
                name,
                category,
                createdAt: Date.now()
            });
        }
    };

    // تعديل اسم صنف (Admin Only) - يتم التعديل في DB للمزامنة
    const startEditing = (id: string, name: string) => {
        if (user.role !== 'admin') return;
        setEditingItemId(id);
        setTempName(name);
    };

    const saveName = async (id: string) => {
        if (/[\u0600-\u06FF]/.test(tempName)) return alert("الإنجليزية فقط");
        // البحث إذا كان الصنف مخصصاً أم أساسياً
        // للأصناف الأساسية لا يمكن تغييرها من هنا بسهولة إلا بإعادة هيكلة الثوابت، 
        // لكن سنفترض التعديل على الأصناف المضافة (custom)
        const item = salesItems.find(i => i.id === id);
        if(item?.isCustom) {
             await update(ref(db, `settings/global_products/${id}`), { name: tempName });
        } else {
             alert("لا يمكن تعديل الأصناف الأساسية من هنا");
        }
        setEditingItemId(null);
    };

    const deleteItem = async (id: string) => {
        if (user.role !== 'admin') return;
        if (confirm("حذف الصنف نهائياً من النظام؟")) {
            await remove(ref(db, `settings/global_products/${id}`));
        }
    };

    const currentTotal = salesItems.reduce((sum, item) => sum + ((item.price || 0) * (item.qty || 0)), 0);

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const sold = salesItems.filter(i => i.qty > 0 && i.price > 0);
        if (!sold.length) return alert("أدخل بيانات صحيحة");

        await push(ref(db, 'sales'), {
            market: selectedMarket,
            employeeName: user.name,
            username: user.username,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            items: sold,
            total: currentTotal
        });

        if (user.key && userTarget) {
            const targetRef = ref(db, `targets/${user.key}`);
            const newAchieved = (userTarget.achieved || 0) + currentTotal;
            await update(targetRef, { achieved: newAchieved });
        }

        alert("تم الحفظ بنجاح");
        setSalesItems(prev => prev.map(i => ({...i, price: 0, qty: 0})));
    };

    // Target Calculations
    const progressPercent = userTarget ? ((userTarget.achieved / userTarget.finalTarget) * 100) : 0;
    const isOverTarget = progressPercent > 100;

    return (
        <div className="space-y-6 pb-20">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                <h2 className="text-2xl font-bold text-white">المبيعات اليومية</h2>

                <div className="flex flex-wrap gap-4">
                    <div className="bg-blue-600/20 border border-blue-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg min-w-[200px]">
                        <div className="bg-blue-600 p-2 rounded-2xl text-white"><Calculator size={24} /></div>
                        <div>
                            <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">المبيعات الحالية</div>
                            <div className="text-2xl font-black text-blue-400">{currentTotal.toLocaleString()} <span className="text-xs">ج.م</span></div>
                        </div>
                    </div>

                    {userTarget && (
                        <div className="bg-purple-600/20 border border-purple-500/50 p-4 rounded-3xl flex items-center gap-4 shadow-lg flex-1 md:max-w-md">
                            <div className="bg-purple-600 p-2 rounded-2xl text-white"><Target size={24} /></div>
                            <div className="flex-1">
                                <div className="flex justify-between items-center mb-1">
                                    <div className="text-[10px] font-black opacity-60 text-white uppercase tracking-widest">الهدف: {userTarget.finalTarget.toLocaleString()}</div>
                                    <div className="text-sm font-black text-purple-400">
                                        {progressPercent.toFixed(1)}% {isOverTarget && <span className="text-green-400">(+{Math.round(progressPercent - 100)}%)</span>}
                                    </div>
                                </div>
                                <div className="text-xs font-bold text-white mb-2">
                                    المحقق: {userTarget.achieved.toLocaleString()} ج.م
                                </div>
                                <div className="w-full bg-black/40 h-2 rounded-full overflow-hidden flex">
                                    <div className="bg-purple-500 h-full transition-all duration-1000" style={{ width: `${Math.min(100, progressPercent)}%` }}></div>
                                    {isOverTarget && (
                                        <div className="bg-green-500 h-full transition-all duration-1000 animate-pulse" style={{ width: `${Math.min(100, progressPercent - 100)}%` }}></div>
                                    )}
                                </div>
                            </div>
                        </div>
                    )}
                </div>
            </div>

            <select className="w-full p-4 rounded-2xl bg-gray-800 text-white border border-white/10" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                <option value="">اختر الماركت...</option>
                {markets.map(m => <option key={m} value={m}>{m}</option>)}
            </select>

            {['Facial', 'Kitchen', 'Toilet', 'Dolphin'].map(cat => (
                <div key={cat} className="bg-gray-800 p-4 rounded-3xl border border-white/5 shadow-xl">
                    <div className="flex justify-between items-center mb-4 border-b border-white/10 pb-2">
                        <h3 className="font-bold text-blue-400">{cat}</h3>
                        {user.role === 'admin' && (
                            <button onClick={() => addCustomItem(cat)} className="bg-green-600 text-white px-3 py-1.5 rounded-xl text-xs font-bold flex items-center gap-1"><Plus size={14}/> أضف صنف</button>
                        )}
                    </div>

                    <div className="space-y-2">
                        {salesItems.filter(i => i.category === cat).map(item => (
                            <div key={item.id} className="grid grid-cols-12 gap-2 items-center bg-black/20 p-2 rounded-2xl border border-transparent hover:border-white/10 transition">
                                <div className="col-span-5 text-white pr-2">
                                    {editingItemId === item.id ? (
                                        <div className="flex gap-1">
                                            <input type="text" className="w-full bg-gray-700 p-1 text-xs rounded" value={tempName} onChange={e => setTempName(e.target.value)} autoFocus />
                                            <button onClick={() => saveName(item.id)} className="text-green-400"><Check size={14}/></button>
                                            <button onClick={() => setEditingItemId(null)} className="text-red-400"><X size={14}/></button>
                                        </div>
                                    ) : (
                                        <span className="text-xs font-bold block truncate">{item.name}</span>
                                    )}
                                </div>
                                <div className="col-span-2"><input type="number" placeholder="سعر" className="w-full bg-gray-700 p-2 rounded-xl text-white text-center text-xs" value={item.price || ''} onChange={e => updateItem(item.id, 'price', parseFloat(e.target.value))} /></div>
                                <div className="col-span-2"><input type="number" placeholder="كمية" className="w-full bg-gray-700 p-2 rounded-xl text-white text-center text-xs" value={item.qty || ''} onChange={e => updateItem(item.id, 'qty', parseFloat(e.target.value))} /></div>
                                <div className="col-span-2 text-center font-black text-xs text-green-400">{(item.price * item.qty).toLocaleString()}</div>
                                <div className="col-span-1 flex justify-center">
                                    {user.role === 'admin' && item.isCustom && (
                                        <div className="flex flex-col gap-1">
                                            <button onClick={() => startEditing(item.id, item.name)} className="text-blue-400"><Edit size={12}/></button>
                                            <button onClick={() => deleteItem(item.id)} className="text-red-400"><Trash2 size={12}/></button>
                                        </div>
                                    )}
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            ))}

            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 hover:bg-green-700 text-white py-4 rounded-3xl font-black shadow-2xl flex justify-center items-center gap-2 transform active:scale-95 transition">
                    <Save size={20} /> حفظ وترحيل المبيعات
                </button>
            </div>
        </div>
    );
};

export default DailySales;

import React, { useState, useEffect } from 'react';
import { ref, push, onValue } from "firebase/database";
import { db } from '../firebase';
import { User, ProductItem } from '../types';
import { PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, PRODUCTS_DOLPHIN } from '../constants';
import { Save, Plus } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const InventoryRegistration: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [items, setItems] = useState<ProductItem[]>([]);

    useEffect(() => {
        const base: ProductItem[] = [];
        const cats = [
            { k: 'Facial', l: PRODUCTS_FACIAL },
            { k: 'Kitchen', l: PRODUCTS_KITCHEN },
            { k: 'Toilet', l: PRODUCTS_TOILET },
            { k: 'Dolphin', l: PRODUCTS_DOLPHIN }
        ];

        cats.forEach(c => {
            c.l.forEach(n => base.push({ id: n, name: n, category: c.k, qty: 0, price: 0 }));
        });

        // المزامنة مع الأصناف المضافة في المبيعات
        onValue(ref(db, 'settings/global_products'), snap => {
            const list = [...base];
            if(snap.exists()){
                snap.forEach(c => {
                    const p = c.val();
                    if(!list.some(i => i.name === p.name)) {
                        list.push({ id: c.key!, name: p.name, category: p.category, qty: 0, price: 0, isCustom: true });
                    }
                });
            }
            setItems(list);
        });
    }, []);

    const updateQty = (name: string, qty: number) => {
        setItems(prev => prev.map(i => i.name === name ? {...i, qty} : i));
    };

    const handleSave = async () => {
        if (!selectedMarket) return alert("اختر الماركت");
        const inv = items.filter(i => i.qty > 0).map(i => ({ name: i.name, qty: i.qty, category: i.category }));
        if (inv.length === 0) return alert("الكميات صفر");
        await push(ref(db, 'inventory'), {
            market: selectedMarket,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: inv
        });
        alert("تم الحفظ");
        setItems(prev => prev.map(i => ({...i, qty: 0})));
    };

    return (
        <div className="pb-20 text-white">
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold">تسجيل المخزون</h2>
                <select className="bg-gray-700 p-2.5 rounded-xl border border-white/20 font-bold" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                    <option value="">اختر الماركت</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
            </div>
            {['Facial', 'Kitchen', 'Toilet', 'Dolphin'].map(cat => (
                <div key={cat} className="mb-6 bg-white/5 p-4 rounded-3xl border border-white/10">
                    <h3 className="font-bold text-blue-500 mb-4 border-b border-white/10 pb-2">{cat}</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                        {items.filter(i => i.category === cat).map(item => (
                            <div key={item.name} className="flex justify-between items-center p-2 border-b border-white/5">
                                <span className="text-xs font-bold">{item.name}</span>
                                <input type="number" className="bg-gray-700 w-20 text-center p-2 rounded-lg" value={item.qty || ''} onChange={e => updateQty(item.name, parseFloat(e.target.value))} />
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
                <button onClick={handleSave} className="w-full bg-green-600 py-4 rounded-3xl font-black shadow-2xl flex justify-center items-center gap-2"><Save size={20} /> حفظ المخزون</button>
            </div>
        </div>
    );
};

export default InventoryRegistration;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, push, onValue } from "firebase/database";
import { User } from '../types';
import { COMPANIES, PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET, FINE_FACIAL, FINE_KITCHEN, FINE_TOILET, ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET, PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET, WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET } from '../constants';
import { Save, Plus } from 'lucide-react';

interface Props {
    user: User;
    markets: string[];
    theme: string;
}

const CompetitorPrices: React.FC<Props> = ({ user, markets, theme }) => {
    const [selectedMarket, setSelectedMarket] = useState('');
    const [selectedCompany, setSelectedCompany] = useState('');
    const [items, setItems] = useState<{category: string, name: string, price: number}[]>([]);
    const [globalExtras, setGlobalExtras] = useState<any[]>([]);

    useEffect(() => {
        onValue(ref(db, 'settings/global_products'), snap => {
            const ex: any[] = [];
            if(snap.exists()) snap.forEach(c => ex.push(c.val()));
            setGlobalExtras(ex);
        });
    }, []);

    useEffect(() => {
        if (!selectedCompany) return;
        const gen = (f: string[], k: string[], t: string[]) => [
            ...f.map(n => ({ category: 'Facial', name: n, price: 0 })),
            ...k.map(n => ({ category: 'Kitchen', name: n, price: 0 })),
            ...t.map(n => ({ category: 'Toilet', name: n, price: 0 })),
        ];

        let base: any[] = [];
        if(selectedCompany === 'Soft Rose') {
            base = gen(PRODUCTS_FACIAL, PRODUCTS_KITCHEN, PRODUCTS_TOILET);
            // إضافة الأصناف المضافة عالمياً فقط لشركة Soft Rose
            globalExtras.forEach(e => {
                if(!base.find(b => b.name === e.name)) base.push({ category: e.category, name: e.name, price: 0 });
            });
        }
        else if(selectedCompany === 'Fine') base = gen(FINE_FACIAL, FINE_KITCHEN, FINE_TOILET);
        else if(selectedCompany === 'Zeina') base = gen(ZEINA_FACIAL, ZEINA_KITCHEN, ZEINA_TOILET);
        else if(selectedCompany === 'Papia Familia') base = gen(PAPIA_FACIAL, PAPIA_KITCHEN, PAPIA_TOILET);
        else if(selectedCompany === 'White') base = gen(WHITE_FACIAL, WHITE_KITCHEN, WHITE_TOILET);

        setItems(base);
    }, [selectedCompany, globalExtras]);

    const handleSave = async () => {
        if (!selectedMarket || !selectedCompany) return alert("اكمل البيانات");
        const valid = items.filter(i => i.price > 0);
        if (valid.length === 0) return alert("أدخل أسعار");
        await push(ref(db, 'competitor_prices'), {
            market: selectedMarket,
            company: selectedCompany,
            date: new Date().toLocaleDateString('ar-EG'),
            timestamp: Date.now(),
            employeeName: user.name,
            items: valid
        });
        alert("تم الحفظ");
        setItems(prev => prev.map(i => ({...i, price: 0})));
    };

    return (
        <div className="space-y-6 pb-20 text-white">
            <h2 className="text-2xl font-bold">أسعار المنافسين</h2>
            <div className="grid grid-cols-2 gap-4 bg-gray-800 p-4 rounded-3xl">
                <select className="w-full p-3 bg-gray-700 rounded-xl" value={selectedMarket} onChange={e => setSelectedMarket(e.target.value)}>
                    <option value="">الماركت...</option>
                    {markets.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
                <select className="w-full p-3 bg-gray-700 rounded-xl" value={selectedCompany} onChange={e => setSelectedCompany(e.target.value)}>
                    <option value="">الشركة...</option>
                    {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
            </div>
            {items.length > 0 && ['Facial', 'Kitchen', 'Toilet'].map(cat => (
                <div key={cat} className="bg-gray-800 p-4 rounded-3xl border border-white/5">
                    <h3 className="font-bold text-blue-400 mb-3">{cat}</h3>
                    <div className="grid grid-cols-2 gap-2">
                        {items.filter(i => i.category === cat).map((item, idx) => (
                            <div key={idx} className="flex items-center gap-2 bg-black/20 p-2 rounded-xl">
                                <span className="flex-1 text-xs font-bold truncate">{item.name}</span>
                                <input type="number" className="w-20 p-2 bg-gray-700 rounded-lg text-center text-xs" value={item.price || ''} onChange={e => {
                                    const n = [...items];
                                    const ix = items.findIndex(x => x.name === item.name);
                                    n[ix].price = parseFloat(e.target.value);
                                    setItems(n);
                                }} />
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <div className="fixed bottom-4 left-1/2 -translate-x-1/2 w-full max-w-md px-4 z-50">
