import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings } from '../types';
import { Save, Trash2, Plus, Settings as SettingsIcon, MapPin, Building2, Users } from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets }) => {
    const [users, setUsers] = useState<User[]>([]);
    const [marketList, setMarketList] = useState<{key: string, name: string}[]>([]);
    const [companyList, setCompanyList] = useState<{key: string, name: string}[]>([]);
    const [newMarket, setNewMarket] = useState('');
    const [newCompany, setNewCompany] = useState('');

    useEffect(() => {
        if (user.role !== 'admin') return;

        onValue(ref(db, 'users'), s => {
            const u: User[] = [];
            if(s.exists()) s.forEach(c => u.push({key: c.key!, ...c.val()}));
            setUsers(u);
        });

        onValue(ref(db, 'settings/markets'), s => {
            const m: any[] = [];
            if(s.exists()) s.forEach(c => m.push({key: c.key!, name: c.val().name}));
            setMarketList(m);
        });

        onValue(ref(db, 'settings/companies'), s => {
            const c: any[] = [];
            if(s.exists()) s.forEach(k => c.push({key: k.key!, name: k.val().name}));
            setCompanyList(c);
        });
    }, [user.role]);

    const addItem = async (type: 'markets' | 'companies', name: string, setter: any) => {
        if(!name) return;
        await push(ref(db, `settings/${type}`), { name });
        setter(''); alert('تمت الإضافة');
    };

    const deleteItem = async (type: 'markets' | 'companies', key: string) => {
        if(confirm('حذف؟')) await remove(ref(db, `settings/${type}/${key}`));
    };

    if(user.role !== 'admin') return <div className="text-white p-10 text-center">للمسؤول فقط</div>;

    return (
        <div className="max-w-4xl mx-auto space-y-6 pb-20 text-white">
            <h2 className="text-3xl font-bold flex items-center gap-3"><SettingsIcon className="text-blue-500"/> الإعدادات</h2>

            {/* الماركتات */}
            <div className="bg-gray-800 p-6 rounded-3xl border border-white/10">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2 text-blue-400"><MapPin size={20}/> إدارة الماركتات</h3>
                <div className="flex gap-2 mb-4">
                    <input className="flex-1 p-3 rounded-xl bg-gray-700 border border-white/10" placeholder="اسم ماركت جديد..." value={newMarket} onChange={e => setNewMarket(e.target.value)} />
                    <button onClick={() => addItem('markets', newMarket, setNewMarket)} className="bg-blue-600 p-3 rounded-xl"><Plus/></button>
                </div>
                <div className="space-y-2 max-h-40 overflow-y-auto">
                    {marketList.map(m => (
                        <div key={m.key} className="flex justify-between bg-black/20 p-2 px-4 rounded-xl items-center">
                            <span>{m.name}</span>
                            <button onClick={() => deleteItem('markets', m.key)} className="text-red-400"><Trash2 size={16}/></button>
                        </div>
                    ))}
                </div>
            </div>

            {/* الشركات */}
            <div className="bg-gray-800 p-6 rounded-3xl border border-white/10">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2 text-purple-400"><Building2 size={20}/> إدارة الشركات</h3>
                <div className="flex gap-2 mb-4">
                    <input className="flex-1 p-3 rounded-xl bg-gray-700 border border-white/10" placeholder="اسم شركة جديدة..." value={newCompany} onChange={e => setNewCompany(e.target.value)} />
                    <button onClick={() => addItem('companies', newCompany, setNewCompany)} className="bg-purple-600 p-3 rounded-xl"><Plus/></button>
                </div>
                <div className="space-y-2 max-h-40 overflow-y-auto">
                    {companyList.map(c => (
                        <div key={c.key} className="flex justify-between bg-black/20 p-2 px-4 rounded-xl items-center">
                            <span>{c.name}</span>
                            <button onClick={() => deleteItem('companies', c.key)} className="text-red-400"><Trash2 size={16}/></button>
                        </div>
                    ))}
                </div>
            </div>

            {/* الموظفين (عرض مبسط) */}
            <div className="bg-gray-800 p-6 rounded-3xl border border-white/10">
                <h3 className="text-xl font-bold mb-4 flex items-center gap-2 text-green-400"><Users size={20}/> الموظفين</h3>
                <div className="space-y-2 max-h-60 overflow-y-auto">
                    {users.map(u => (
                        <div key={u.key} className="flex justify-between bg-black/20 p-3 rounded-xl items-center">
                            <div><div className="font-bold">{u.name}</div><div className="text-xs opacity-50">{u.username}</div></div>
                            <button onClick={() => {if(confirm('حذف المستخدم؟')) remove(ref(db, `users/${u.key}`))}} className="text-red-400"><Trash2/></button>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

