import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, onValue, set, push, remove, update, get } from "firebase/database";
import { User, LeaveBalance } from '../types';
import { Trash2, Edit, CalendarPlus, X, History, Calendar } from 'lucide-react';

interface Props { user: User; theme: string; }

const LeaveBalanceComponent: React.FC<Props> = ({ user }) => {
    const [balances, setBalances] = useState<Record<string, LeaveBalance>>({});
    const [usersList, setUsersList] = useState<User[]>([]);
    const [showModal, setShowModal] = useState(false);
    const [editBalance, setEditBalance] = useState<LeaveBalance | null>(null); // For Admin Edit

    const [selectedUser, setSelectedUser] = useState('');
    const [date, setDate] = useState('');
    const [days, setDays] = useState(1);
    const [type, setType] = useState('annual');

    useEffect(() => {
        onValue(ref(db, 'users'), s => { const u:any[]=[]; s.forEach(c=>u.push({key:c.key,...c.val()})); setUsersList(u); });
        onValue(ref(db, 'leave_balances'), s => setBalances(s.val() || {}));
    }, []);

    const handleSave = async () => {
        if(!selectedUser || !date) return;
        const bRef = ref(db, `leave_balances/${selectedUser}`);
        const snap = await get(bRef);
        const bal = snap.val() || { annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };

        const isDeduct = ['annual', 'casual'].includes(type);
        const newVal = isDeduct ? (bal[type] - days) : (bal[type] + days);

        await update(bRef, { ...bal, [type]: newVal, userId: selectedUser, employeeName: usersList.find(u=>u.key===selectedUser)?.name });
        await push(ref(db, 'leave_history'), { userId: selectedUser, date, days, type, timestamp: Date.now() });
        setShowModal(false); alert('تم');
    };

    const handleAdminEdit = async () => {
        if(!editBalance) return;
        await update(ref(db, `leave_balances/${editBalance.userId}`), editBalance);
        setEditBalance(null); alert('تم تعديل الرصيد');
    };

    // حساب تواريخ الدورة (21 الشهر السابق - 20 الشهر الحالي)
    const now = new Date();
    const startCycle = now.getDate() >= 21 ? new Date(now.getFullYear(), now.getMonth(), 21) : new Date(now.getFullYear(), now.getMonth() - 1, 21);
    const endCycle = new Date(startCycle); endCycle.setMonth(endCycle.getMonth() + 1); endCycle.setDate(20);

    return (
        <div className="space-y-6 text-white">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex items-center gap-2"><History className="text-blue-500"/> الإجازات</h2>
                {user.role === 'admin' && <button onClick={() => setShowModal(true)} className="bg-red-600 px-4 py-2 rounded-xl font-bold flex gap-2"><CalendarPlus/> تسجيل</button>}
            </div>

            <div className="bg-white/5 p-4 rounded-xl text-center border border-white/10">
                <div className="text-xs opacity-50 uppercase mb-1">دورة الشهر الحالية</div>
                <div className="font-bold flex justify-center items-center gap-2">
                    <Calendar size={16}/> {startCycle.toLocaleDateString('en-GB')} - {endCycle.toLocaleDateString('en-GB')}
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                {usersList.filter(u => user.role === 'admin' || u.key === user.key).map(u => {
                    const b = balances[u.key!] || { annual: 21, casual: 7, sick: 0, exams: 0, unpaid: 0 };
                    return (
                        <div key={u.key} className="bg-gray-800 p-4 rounded-3xl border border-white/10 shadow-lg">
                            <div className="flex justify-between mb-4">
                                <span className="font-bold text-blue-400">{u.name}</span>
                                {user.role === 'admin' && <button onClick={() => setEditBalance({...b, userId: u.key!, employeeName: u.name})} className="text-xs bg-white/10 p-1 px-2 rounded hover:bg-white/20"><Edit size={14}/></button>}
                            </div>
                            <div className="grid grid-cols-2 gap-2 text-center">
                                {['annual', 'casual', 'sick', 'exams', 'unpaid'].map(t => (
                                    <div key={t} className="bg-black/20 p-2 rounded-xl">
                                        <div className="text-[10px] opacity-50 mb-1">{t}</div>
                                        <div className="font-black text-lg">{(b as any)[t] || 0}</div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* مودال تسجيل الإجازة */}
            {showModal && (
                <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4 z-50">
                    <div className="bg-gray-900 p-6 rounded-3xl w-full max-w-md border border-white/20">
                        <h3 className="font-bold text-xl mb-4">تسجيل حركة إجازة</h3>
                        <div className="space-y-3">
                            <select className="w-full p-3 bg-gray-700 rounded-xl" value={selectedUser} onChange={e=>setSelectedUser(e.target.value)}>
                                <option value="">الموظف...</option>
                                {usersList.map(u=><option key={u.key} value={u.key}>{u.name}</option>)}
                            </select>
                            <input type="date" className="w-full p-3 bg-gray-700 rounded-xl" value={date} onChange={e=>setDate(e.target.value)}/>
                            <input type="number" className="w-full p-3 bg-gray-700 rounded-xl" placeholder="عدد الأيام" value={days} onChange={e=>setDays(parseFloat(e.target.value))}/>
                            <select className="w-full p-3 bg-gray-700 rounded-xl" value={type} onChange={e=>setType(e.target.value)}>
                                <option value="annual">سنوي</option>
                                <option value="casual">عارضة</option>
                                <option value="sick">مرضي</option>
                                <option value="exams">امتحانات</option>
                                <option value="unpaid">غياب</option>
                            </select>
                            <button onClick={handleSave} className="w-full bg-blue-600 py-3 rounded-xl font-bold mt-2">حفظ</button>
                            <button onClick={()=>setShowModal(false)} className="w-full bg-white/10 py-3 rounded-xl font-bold">إلغاء</button>
                        </div>
                    </div>
                </div>
            )}

            {/* مودال تعديل الرصيد للآدمن */}
            {editBalance && (
                <div className="fixed inset-0 bg-black/80 flex items-center justify-center p-4 z-50">
                    <div className="bg-gray-900 p-6 rounded-3xl w-full max-w-md border border-white/20">
                        <h3 className="font-bold text-xl mb-4">تعديل رصيد: {editBalance.employeeName}</h3>
                        <div className="grid grid-cols-2 gap-3 mb-4">
                            {['annual', 'casual', 'sick', 'exams', 'unpaid'].map(t => (
                                <div key={t}>
                                    <label className="text-xs opacity-50 block mb-1">{t}</label>
                                    <input type="number" className="w-full p-2 bg-gray-700 rounded-lg text-center" value={(editBalance as any)[t]} onChange={e => setEditBalance({...editBalance, [t]: parseFloat(e.target.value)})}/>
                                </div>
                            ))}
                        </div>
                        <button onClick={handleAdminEdit} className="w-full bg-green-600 py-3 rounded-xl font-bold">حفظ التعديلات</button>
                        <button onClick={()=>setEditBalance(null)} className="w-full bg-white/10 py-3 rounded-xl font-bold mt-2">إلغاء</button>
                    </div>
                </div>
            )}
        </div>
    );
};

