import React, { useState, useEffect, useMemo } from 'react';
import { db } from '../firebase';
import { ref, onValue, remove } from "firebase/database";
import { User, SaleRecord } from '../types';
import { FileSpreadsheet, Trash2, Calendar, User as UserIcon, Download, Star, TrendingUp } from 'lucide-react';
import { exportToCSV } from '../utils';

interface Props { user: User; markets: string[]; theme: string; }

const SalesLog: React.FC<Props> = ({ user, markets }) => {
    const [sales, setSales] = useState<SaleRecord[]>([]);
    const [filtered, setFiltered] = useState<SaleRecord[]>([]);
    const [filterMarket, setFilterMarket] = useState('');
    const [filterUser, setFilterUser] = useState('');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    useEffect(() => {
        onValue(ref(db, 'sales'), s => {
            if (s.exists()) {
                let d = Object.keys(s.val()).map(k => ({id:k, ...s.val()[k]})) as SaleRecord[];
                if(user.role !== 'admin' && !user.canViewAllSales) d = d.filter(x => x.employeeName === user.name);
                setSales(d.sort((a,b) => b.timestamp - a.timestamp));
            } else setSales([]);
        });
    }, [user]);

    useEffect(() => {
        let res = sales;
        if(filterMarket) res = res.filter(s => s.market === filterMarket);
        if(filterUser) res = res.filter(s => s.employeeName.includes(filterUser));
        setFiltered(res);
    }, [sales, filterMarket, filterUser]);

    // الإحصائيات (Admin Only)
    const stats = useMemo(() => {
        if(user.role !== 'admin') return null;
        const now = new Date();
        const start = new Date(now.getFullYear(), now.getMonth(), 1).getTime();
        const end = new Date(now.getFullYear(), now.getMonth(), 30).getTime(); // 1-30 of current month logic

        const monthSales = sales.filter(s => s.timestamp >= start && s.timestamp <= end);

        // Star of Month
        const userTotals: Record<string, number> = {};
        monthSales.forEach(s => userTotals[s.employeeName] = (userTotals[s.employeeName] || 0) + s.total);
        const star = Object.entries(userTotals).sort((a,b) => b[1] - a[1])[0];

        // Top Selling Items (All Accounts)
        const itemStats: Record<string, {qty: number, val: number}> = {};
        monthSales.forEach(s => s.items.forEach(i => {
            if(!itemStats[i.name]) itemStats[i.name] = {qty: 0, val: 0};
            itemStats[i.name].qty += i.qty;
            itemStats[i.name].val += (i.qty * i.price);
        }));
        const topItems = Object.entries(itemStats).sort((a,b) => b[1].val - a[1].val).slice(0, 5);

        return { star, topItems };
    }, [sales, user.role]);

    const handleExport = () => {
        if(!startDate || !endDate) return alert("حدد الفترة");
        const start = new Date(startDate).getTime();
        const end = new Date(endDate).getTime() + 86400000;

        const targetSales = sales.filter(s => s.timestamp >= start && s.timestamp <= end && (!filterMarket || s.market === filterMarket));

        // تجميع البيانات
        const grouped: Record<string, {emp: string, name: string, price: number, qty: number, total: number}> = {};
        targetSales.forEach(s => {
            s.items.forEach(i => {
                const k = `${s.employeeName}_${i.name}`;
                if(!grouped[k]) grouped[k] = {emp: s.employeeName, name: i.name, price: i.price, qty: 0, total: 0};
                grouped[k].qty += i.qty;
                grouped[k].total += (i.qty * i.price);
            });
        });

        const rows = Object.values(grouped).map(g => ({
            "الموظف": g.emp,
            "الصنف": g.name,
            "سعر القطعة": g.price, // Number only
            "الكمية": g.qty,
            "الإجمالي": g.total // Number only
        }));

        // صف الإجمالي الكلي
        const grandTotal = rows.reduce((acc, r) => acc + r["الإجمالي"], 0);
        rows.push({ "الموظف": "الإجمالي الكلي", "الصنف": "", "سعر القطعة": 0, "الكمية": 0, "الإجمالي": grandTotal });

        exportToCSV(rows, `Sales_${startDate}_${endDate}`);
    };

    return (
        <div className="space-y-6 text-white">
            <div className="flex justify-between items-center">
                <h2 className="text-2xl font-bold flex gap-2"><FileSpreadsheet/> سجل المبيعات</h2>
                {user.role === 'admin' && (
                    <div className="flex gap-2">
                        <input type="date" className="bg-gray-700 p-2 rounded-xl text-xs" value={startDate} onChange={e=>setStartDate(e.target.value)}/>
                        <input type="date" className="bg-gray-700 p-2 rounded-xl text-xs" value={endDate} onChange={e=>setEndDate(e.target.value)}/>
                        <button onClick={handleExport} className="bg-green-600 px-4 py-2 rounded-xl font-bold flex gap-2 text-sm items-center"><Download size={16}/> تصدير (أرقام)</button>
                    </div>
                )}
            </div>

            {user.role === 'admin' && stats && (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {stats.star && (
                        <div className="bg-[#808080] p-6 rounded-3xl border border-white/20 flex flex-col items-center justify-center relative shadow-xl">
                            <Star className="text-yellow-400 mb-2" size={40} fill="currentColor"/>
                            <div className="text-xs uppercase tracking-widest font-black">نجم الشهر</div>
                            <div className="text-3xl font-black">{stats.star[0]}</div>
                            <div className="text-green-300 font-bold">{stats.star[1].toLocaleString()} ج.م</div>
                        </div>
                    )}
                    {stats.topItems && (
                        <div className="bg-gray-800 p-6 rounded-3xl border border-white/10 shadow-xl">
                            <h3 className="font-bold mb-4 flex items-center gap-2 text-blue-400"><TrendingUp size={20}/> الأكثر مبيعاً (الكل)</h3>
                            <div className="space-y-2">
                                {stats.topItems.map(([name, val], i) => (
                                    <div key={i} className="flex justify-between border-b border-white/5 pb-1 text-xs">
                                        <span className="font-bold">{name}</span>
                                        <span>{val.qty} ق / <span className="text-green-400">{val.val.toLocaleString()}</span></span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            )}

            <div className="flex gap-2">
                <select className="bg-gray-700 p-3 rounded-xl flex-1" value={filterMarket} onChange={e=>setFilterMarket(e.target.value)}>
                    <option value="">كل الماركتات</option>
                    {markets.map(m=><option key={m} value={m}>{m}</option>)}
                </select>
                <input className="bg-gray-700 p-3 rounded-xl flex-1" placeholder="اسم الموظف..." value={filterUser} onChange={e=>setFilterUser(e.target.value)}/>
            </div>

            <div className="space-y-4">
                {filtered.map(s => (
                    <div key={s.id} className="bg-gray-800 p-5 rounded-3xl border border-white/10 shadow-lg">
                        <div className="flex justify-between mb-4">
                            <div>
                                <div className="font-bold text-blue-400 text-lg">{s.market}</div>
                                <div className="text-[10px] opacity-60 flex gap-2 font-bold">
                                    <span className="flex items-center gap-1"><Calendar size={10}/> {s.date}</span>
                                    <span className="flex items-center gap-1"><UserIcon size={10}/> {s.employeeName}</span>
                                </div>
                            </div>
                            {user.role === 'admin' && <button onClick={()=>{if(confirm('حذف؟')) remove(ref(db, `sales/${s.id}`))}} className="text-red-400"><Trash2/></button>}
                        </div>
                        <div className="bg-black/20 rounded-xl overflow-hidden">
                            <table className="w-full text-center text-[10px]">
                                <thead className="bg-white/5 text-white/50"><tr><th className="py-2 text-right px-2">صنف</th><th>سعر</th><th>كمية</th><th>مجموع</th></tr></thead>
                                <tbody>
                                    {s.items.map((i,x)=>(
                                        <tr key={x} className="border-t border-white/5"><td className="py-2 text-right px-2 font-bold">{i.name}</td><td>{i.price}</td><td>{i.qty}</td><td className="text-green-400">{i.qty*i.price}</td></tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                        <div className="mt-2 text-left font-black text-blue-400">الإجمالي: {s.total.toLocaleString()}</div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default SalesLog;

