import LeaveBalanceComponent from './components/LeaveBalance';
import Settings from './components/Settings';
import { Home, LogOut, Phone, Wifi, WifiOff, Menu, X, Palette, Bell, MailOpen, Check, Trash2, Clock, Copy, ExternalLink, Sparkles, MessageCircle } from 'lucide-react';
import { INITIAL_MARKETS } from './constants';

const DEFAULT_SETTINGS: AppSettings = {
  appName: "Soft Rose Modern Trade",
  tickerText: "أهلاً بكم في نظام سوفت روز للتجارة الحديثة",
  tickerEnabled: true,
  whatsappNumber: "",
  permissions: {
    showSalesLog: true, 
    showInventoryLog: false, 
    showInventoryReg: false, 
    showCompetitorReports: false,
    showDailySales: true,
    showCompetitorPrices: true
  }
};

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);
  const [currentView, setCurrentView] = useState<string>('sales');
  const [theme, setTheme] = useState<'dark'>('dark');
  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);
  const [markets, setMarkets] = useState<string[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [welcomeToast, setWelcomeToast] = useState<string | null>(null);

  const [notifications, setNotifications] = useState<AppNotification[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [showNotifDropdown, setShowNotifDropdown] = useState(false);
  const [selectedNotif, setSelectedNotif] = useState<AppNotification | null>(null);

  useEffect(() => {
    const settingsRef = ref(db, 'settings/app');
    const marketsRef = ref(db, 'settings/markets');
    const connectedRef = ref(db, ".info/connected");

    onValue(settingsRef, (snapshot) => {
      if (snapshot.exists()) setSettings({...DEFAULT_SETTINGS, ...snapshot.val()});
    });

    onValue(marketsRef, (snapshot) => {
      const systemMarkets = INITIAL_MARKETS.map(name => ({ name, createdBy: 'system' }));
      const val = snapshot.exists() ? snapshot.val() : {};
      const dbMarkets = val ? Object.values(val as Record<string, any>).map((m: any) => 
        typeof m === 'string' ? { name: m, createdBy: 'system' } : m
      ) : [];
      const allCombined = [...systemMarkets, ...dbMarkets];

      if (user) {
        let filtered: any[];
        if (user.role === 'admin') {
          filtered = allCombined;
        } else {
          filtered = allCombined.filter((m: any) => m.createdBy === 'system' || m.createdBy === user.username);
        }
        const uniqueNames = Array.from(new Set(filtered.map((m: any) => String(m.name))));
        setMarkets(uniqueNames as string[]);
      }
    }, { onlyOnce: false });

    onValue(connectedRef, (snap) => setIsConnected(!!snap.val()));
  }, [user?.username, user?.role]);

  useEffect(() => {
    if (!user || !user.key || user.key === 'admin_root') return;
    const userRef = ref(db, `users/${user.key}`);
    const unsubscribe = onValue(userRef, (snapshot) => {
      if (snapshot.exists()) {
        const updatedData = { ...snapshot.val(), key: user.key };
        setUser(updatedData);
      }
    });
    return () => unsubscribe();
  }, [user?.key]);

  useEffect(() => {
    if (!user) return;
    setWelcomeToast(`مرحباً ${user.name}`);
    const timer = setTimeout(() => setWelcomeToast(null), 3000);

    const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
    const userStatusRef = ref(db, `status/${safeKey}`);
    set(userStatusRef, { online: true, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    onDisconnect(userStatusRef).set({ online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });

    onValue(ref(db, `notifications/${user.username}`), (snapshot) => {
        if(snapshot.exists()) {
            const data = snapshot.val();
            const list = Object.keys(data).map(key => ({ id: key, ...data[key] })).sort((a,b) => b.timestamp - a.timestamp);
            setNotifications(list);
            setUnreadCount(list.filter(n => !n.isRead).length);
        } else {
            setNotifications([]);
            setUnreadCount(0);
        }
    });

    return () => clearTimeout(timer);
  }, [user?.username]);

  const handleLogout = async () => {
    if (user) {
        const safeKey = user.username.replace(/[.#$/[\]]/g, "_");
        await set(ref(db, `status/${safeKey}`), { online: false, lastSeen: serverTimestamp(), name: user.name, username: user.username });
    }
    localStorage.removeItem('soft_rose_user');
    setUser(null);
  };

  const markAsRead = (id: string) => {
    if (!user) return;
    update(ref(db, `notifications/${user.username}/${id}`), { isRead: true });
  };

  const deleteNotif = (id: string) => {
    if (!user) return;
    remove(ref(db, `notifications/${user.username}/${id}`));
    setSelectedNotif(null);
  };

  const openWhatsApp = () => {
    if (settings.whatsappNumber) {
      window.open(`https://wa.me/${settings.whatsappNumber}`, '_blank');
    } else {
      alert("رقم الواتساب غير مسجل في الإعدادات");
    }
  };

  if (!user) return <Login onLogin={setUser} theme={theme} />;

  return (
    <div className="bg-black text-white min-h-screen flex flex-col overflow-hidden relative">
      {welcomeToast && (
        <div className="fixed top-5 left-1/2 -translate-x-1/2 z-[200] bg-blue-600 px-6 py-3 rounded-2xl shadow-2xl font-bold flex items-center gap-2 toast-in border border-white/20">
            <Sparkles size={18} />
            {welcomeToast}
        </div>
      )}

      {settings.tickerEnabled && (
        <div className="bg-black/90 text-yellow-400 py-1.5 overflow-hidden whitespace-nowrap border-b border-white/10 z-50">
           <div className="animate-marquee inline-block px-4 font-bold">{settings.tickerText}</div>
        </div>
      )}

      <header className="p-4 flex justify-between items-center z-50 bg-black/80 backdrop-blur-md border-b border-white/10 text-white shadow-lg">
        <div className="flex items-center gap-4">
            <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="md:hidden p-2 rounded-lg hover:bg-white/10">
                {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
            </button>
            <h1 className="text-lg md:text-2xl font-bold truncate">
                {settings.appName}
            </h1>
        </div>

        <div className="flex items-center gap-2 md:gap-4">
            {/* زر الواتساب */}
            <button onClick={openWhatsApp} className="p-2 rounded-full hover:bg-green-500/10 text-green-500 transition-colors" title="واتساب الدعم">
                <MessageCircle size={22} />
            </button>

            <div className="relative">
                <button onClick={() => setShowNotifDropdown(!showNotifDropdown)} className="relative p-2 rounded-full hover:bg-white/10">
                    <Bell size={20} />
                    {unreadCount > 0 && <span className="absolute top-1 right-1 bg-red-600 text-white text-[10px] w-4 h-4 flex items-center justify-center rounded-full">{unreadCount}</span>}
                </button>
                {showNotifDropdown && (
                    <div className="absolute left-0 mt-2 w-72 md:w-80 bg-gray-900 text-white rounded-2xl shadow-2xl border border-white/10 overflow-hidden z-[60]">
                        <div className="p-4 bg-black border-b border-white/10 flex justify-between items-center">
                            <h3 className="font-bold text-sm text-white">الإشعارات</h3>
                        </div>
                        <div className="max-h-80 overflow-y-auto custom-scrollbar">
                            {notifications.length === 0 ? (
                                <div className="p-10 text-center opacity-30 italic text-sm text-white">لا توجد إشعارات</div>
                            ) : (
                                notifications.map(n => (
                                    <div 
                                      key={n.id} 
                                      onClick={() => { setSelectedNotif(n); markAsRead(n.id!); setShowNotifDropdown(false); }}
                                      className={`p-4 border-b border-white/5 last:border-0 hover:bg-white/5 cursor-pointer ${!n.isRead ? 'bg-blue-600/10' : ''}`}
                                    >
                                        <div className="text-xs font-bold mb-0.5 text-white">{n.sender}</div>
                                        <div className="text-[11px] opacity-70 line-clamp-2 text-white">{n.message}</div>
                                    </div>
                                ))
                            )}
                        </div>
                    </div>
                )}
            </div>

            <button onClick={handleLogout} className="text-red-500 p-2 rounded-full hover:bg-red-500/10 transition-colors">
                <LogOut size={20} />
            </button>
        </div>
      </header>

      {/* نافذة تفاصيل الإشعار */}
      {selectedNotif && (
        <div className="fixed inset-0 z-[300] bg-black/80 backdrop-blur-md flex items-center justify-center p-4">
          <div className="bg-gray-900 border border-white/20 w-full max-w-md rounded-3xl p-6 shadow-2xl animate-in zoom-in-95">
            <div className="flex justify-between items-center mb-6">
              <div className="flex items-center gap-2">
                <Bell className="text-blue-500" size={20} />
                <h3 className="font-bold text-white">تفاصيل الإشعار</h3>
              </div>
              <button onClick={() => setSelectedNotif(null)} className="text-white/50 hover:text-white"><X size={20}/></button>
            </div>
            <div className="mb-8">
              <div className="text-xs font-black opacity-40 uppercase mb-2">المرسل: {selectedNotif.sender}</div>
              <div className="bg-white/5 p-4 rounded-2xl border border-white/5 text-sm leading-relaxed text-gray-200">
                {selectedNotif.message}
              </div>
            </div>
            <div className="flex gap-3">
              <button 
                onClick={() => {
                  navigator.clipboard.writeText(selectedNotif.message);
                  alert("تم النسخ بنجاح");
                }}
                className="flex-1 bg-white/10 hover:bg-white/20 py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition"
              >
                <Copy size={16}/> نسخ النص
              </button>
              <button 
                onClick={() => deleteNotif(selectedNotif.id!)}
                className="flex-1 bg-red-600/20 hover:bg-red-600 text-red-500 hover:text-white py-3 rounded-xl font-bold flex items-center justify-center gap-2 transition"
              >
                <Trash2 size={16}/> حذف الإشعار
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-1 overflow-hidden relative">
        <div className={`fixed md:relative top-0 bottom-0 right-0 z-50 h-full transition-transform duration-300 md:transform-none ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full md:translate-x-0'}`}>
            <Sidebar 
                currentView={currentView} 
                setView={(view) => { setCurrentView(view); setIsSidebarOpen(false); }} 
                user={user} 
                theme={theme} 
                settings={settings} 
                containerClass="bg-black/60 backdrop-blur-2xl border-l border-white/10 h-full shadow-2xl" 
            />
        </div>

        <main className="flex-1 p-2 md:p-4 overflow-y-auto w-full">
            <div className={`p-4 md:p-6 min-h-full rounded-2xl shadow-xl bg-gray-900/60 border border-white/5 backdrop-blur-md`}>
                {currentView === 'sales' && <DailySales user={user} markets={markets} theme={theme} />}
                {currentView === 'salesLog' && <SalesLog user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryReg' && <InventoryRegistration user={user} markets={markets} theme={theme} />}
                {currentView === 'inventoryLog' && <InventoryLog user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorPrices' && <CompetitorPrices user={user} markets={markets} theme={theme} />}
                {currentView === 'competitorReports' && <CompetitorReports user={user} markets={markets} theme={theme} />}
                {currentView === 'leaveBalance' && <LeaveBalanceComponent user={user} theme={theme} />}
                {currentView === 'settings' && <Settings user={user} settings={settings} markets={markets} theme={theme} setTheme={setTheme as any} />}
            </div>
        </main>
      </div>

      <footer className="py-2 px-4 text-center text-[10px] font-bold opacity-50 text-white border-t border-white/5">
          مع تحيات المطور Amir Lamay
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, get, child } from "firebase/database";
import { User } from '../types';
import { Lock, User as UserIcon, Loader2, ShieldCheck } from 'lucide-react';

interface Props {
    onLogin: (user: User) => void;
    theme: string;
}

const Login: React.FC<Props> = ({ onLogin, theme }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const savedUser = localStorage.getItem('soft_rose_user');
        if (savedUser) {
            try {
                onLogin(JSON.parse(savedUser));
            } catch (e) {
                localStorage.removeItem('soft_rose_user');
            }
        }
    }, [onLogin]);

    const handleLogin = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');
        setLoading(true);

        const cleanUsername = username.trim();
        const cleanPassword = password.trim();

        if (!cleanUsername || !cleanPassword) {
            setError('يرجى إدخال البيانات المطلوبة');
            setLoading(false);
            return;
        }

        try {
            if (cleanUsername === 'admin' && cleanPassword === 'admin') {
                const adminUser: User = {
                    key: 'admin_root',
                    username: 'admin',
                    name: 'Admin',
                    role: 'admin',
                    canViewAllSales: true
                };
                localStorage.setItem('soft_rose_user', JSON.stringify(adminUser));
                onLogin(adminUser);
                return;
            }

            // Using users_v2 as requested to retrieve updated data structure
            const dbRef = ref(db);
            const snapshot = await get(child(dbRef, `users_v2`));

            if (snapshot.exists()) {
                const users = snapshot.val();
                const userKey = Object.keys(users).find(key => 
                    users[key].username?.toString().trim() === cleanUsername && 
                    users[key].password?.toString().trim() === cleanPassword
                );

                if (userKey) {
                    const userData = { ...users[userKey], key: userKey };
                    localStorage.setItem('soft_rose_user', JSON.stringify(userData));
                    onLogin(userData);
                } else {
                    setError('بيانات الدخول غير صحيحة');
                }
            } else {
                setError('لا يوجد مستخدمين مسجلين');
            }
        } catch (err) {
            console.error(err);
            setError('خطأ في الاتصال بالخادم');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen flex items-center justify-center p-4 relative overflow-hidden bg-[#00182b]">
            {/* Background Image with Overlay */}
            <div 
                className="absolute inset-0 z-0 bg-cover bg-center bg-no-repeat scale-105"
                style={{ 
                    backgroundImage: `url('https://images.unsplash.com/photo-1620641788421-7a1c342ea42e?q=80&w=2548&auto=format&fit=crop')`,
                    filter: 'brightness(0.4) blur(3px)'
                }}
            />

            {/* Glassmorphism Card */}
            <div className="w-full max-w-md z-10 relative group">
                <div className="absolute -inset-1 bg-gradient-to-r from-blue-600 to-cyan-500 rounded-3xl blur opacity-20 group-hover:opacity-40 transition duration-1000 group-hover:duration-200"></div>

                <div className="relative bg-black/40 backdrop-blur-2xl border border-white/20 p-8 md:p-10 rounded-3xl shadow-2xl text-white">
                    <div className="flex flex-col items-center mb-10">
                        <div className="w-20 h-20 bg-gradient-to-br from-blue-500/80 to-cyan-400/80 rounded-2xl flex items-center justify-center mb-6 shadow-2xl border border-white/30 transform -rotate-6 group-hover:rotate-0 transition-transform duration-500">
                            <ShieldCheck size={42} className="text-white drop-shadow-lg" />
                        </div>
                        <h2 className="text-3xl font-black text-center tracking-tight mb-2">سوفت روز</h2>
                        <div className="h-1 w-12 bg-blue-500 rounded-full mb-2"></div>
                        <p className="text-xs font-bold uppercase tracking-[0.3em] opacity-60">Modern Trade System</p>
                    </div>

                    <form onSubmit={handleLogin} className="space-y-6">
                        <div className="space-y-2">
                            <label className="block text-[10px] font-bold uppercase tracking-widest opacity-70 mr-1">اسم المستخدم</label>
                            <div className="relative group/input">
                                <UserIcon className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40 group-focus-within/input:text-blue-400 transition-colors" size={18} />
                                <input 
                                    type="text"
                                    value={username}
                                    onChange={e => setUsername(e.target.value)}
                                    className="w-full pr-12 pl-4 py-4 rounded-xl bg-white/5 border border-white/10 focus:border-blue-500/50 focus:bg-white/10 outline-none text-white transition-all placeholder:text-white/20 text-sm font-medium"
                                    placeholder="Username"
                                    required
                                />
                            </div>
                        </div>

                        <div className="space-y-2">
                            <label className="block text-[10px] font-bold uppercase tracking-widest opacity-70 mr-1">كلمة المرور</label>
                            <div className="relative group/input">
                                <Lock className="absolute right-4 top-1/2 -translate-y-1/2 text-white/40 group-focus-within/input:text-blue-400 transition-colors" size={18} />
                                <input 
                                    type="password"
                                    value={password}
                                    onChange={e => setPassword(e.target.value)}
                                    className="w-full pr-12 pl-4 py-4 rounded-xl bg-white/5 border border-white/10 focus:border-blue-500/50 focus:bg-white/10 outline-none text-white transition-all placeholder:text-white/20 text-sm font-medium"
                                    placeholder="••••••••"
                                    required
                                />
                            </div>
                        </div>

                        {error && (
                            <div className="bg-red-500/20 border border-red-500/40 text-red-200 px-4 py-3 rounded-xl text-[11px] text-center font-bold animate-in fade-in slide-in-from-top-1">
                                {error}
                            </div>
                        )}

                        <button 
                            type="submit" 
                            disabled={loading}
                            className="w-full relative group/btn overflow-hidden bg-blue-600 hover:bg-blue-500 text-white font-bold py-4 rounded-xl transition-all duration-300 transform active:scale-[0.98] shadow-[0_0_20px_rgba(37,99,235,0.3)] hover:shadow-[0_0_30px_rgba(37,99,235,0.5)] flex items-center justify-center gap-3 mt-4"
                        >
                            <div className="absolute inset-0 w-1/2 h-full bg-white/20 -skew-x-[30deg] -translate-x-full group-hover/btn:animate-shine"></div>
                            {loading ? (
                                <>
                                    <Loader2 className="animate-spin" size={20} />
                                    <span className="text-sm">جاري المصادقة...</span>
                                </>
                            ) : (
                                <span className="text-sm tracking-wide">تسجيل الدخول</span>
                            )}
                        </button>
                    </form>

                    <div className="mt-10 pt-6 border-t border-white/10 text-center">
                        <p className="text-[10px] font-bold opacity-30 uppercase tracking-[0.2em]">
                            Soft Rose Trading © 2024
                        </p>
                        <p className="text-[11px] font-bold text-blue-400 mt-2 opacity-60">
                            مع تحيات المطور Amir Lamay
                        </p>
                    </div>
                </div>
            </div>

            {/* Decorative Elements */}
            <div className="absolute top-[-10%] left-[-5%] w-64 h-64 bg-blue-600/20 rounded-full blur-[100px] z-0"></div>
            <div className="absolute bottom-[-10%] right-[-5%] w-96 h-96 bg-cyan-600/10 rounded-full blur-[120px] z-0"></div>
        </div>
    );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { db } from '../firebase';
import { ref, set, push, onValue, remove, update } from "firebase/database";
import { User, AppSettings, UserPermissions, AppNotification } from '../types';
import { 
  Save, Trash2, UserPlus, Shield, Edit2, Plus, X, 
  Settings as SettingsIcon, Users, MapPin, Building2, 
  ToggleLeft, ToggleRight, Key, Send
} from 'lucide-react';

interface Props {
    user: User;
    settings: AppSettings;
    markets: string[];
    theme: string;
    setTheme: (t: any) => void;
}

const Settings: React.FC<Props> = ({ user, settings, markets, theme, setTheme }) => {
    const [localSettings, setLocalSettings] = useState<AppSettings>(settings);
    const [users, setUsers] = useState<User[]>([]);
    const [newUser, setNewUser] = useState<User>({ 
        name: '', 
        username: '', 
        password: '', 
        role: 'user', 
        canViewAllSales: false,
        permissions: {
            showSalesLog: true,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        }
    });

    // Modals
    const [passModal, setPassModal] = useState<{key: string, name: string} | null>(null);
    const [permModal, setPermModal] = useState<User | null>(null);
    const [notifModal, setNotifModal] = useState<{username: string, name: string} | null>(null);
    const [newPass, setNewPass] = useState('');
    const [notifMsg, setNotifMsg] = useState('');

    useEffect(() => {
        setLocalSettings(settings);
    }, [settings]);

    useEffect(() => {
        if (user.role !== 'admin') return;

        // UPDATED: Using users_v2 path to retrieve previous data
        onValue(ref(db, 'users_v2'), snapshot => {
            if (snapshot.exists()) {
                const u: User[] = [];
                snapshot.forEach(c => { u.push({ key: c.key || '', ...c.val() }); });
                setUsers(u);
            }
        });
    }, [user.role]);

    const saveAppSettings = async () => {
        try {
            await set(ref(db, 'settings/app'), localSettings);
            alert('تم حفظ إعدادات التطبيق بنجاح');
        } catch (e) { alert('خطأ في الحفظ'); }
    };

    const handleAddUser = async () => {
        if (!newUser.username || !newUser.password || !newUser.name) return alert("اكمل بيانات المستخدم");

        // إضافة المستخدم وحفظ المفتاح to users_v2
        const userRef = push(ref(db, 'users_v2'));
        const userKey = userRef.key;
        await set(userRef, newUser);

        // تهيئة رصيد الإجازات تلقائياً للمستخدم الجديد
        if (userKey) {
            await set(ref(db, `leave_balances/${userKey}`), {
                userId: userKey,
                employeeName: newUser.name,
                annual: 21,
                casual: 7,
                sick: 0,
                exams: 0,
                unpaid: 0
            });
        }

        alert("تمت إضافة المستخدم وتهيئة رصيد إجازاته بنجاح");
        setNewUser({ 
            name: '', 
            username: '', 
            password: '', 
            role: 'user', 
            canViewAllSales: false,
            permissions: {
                showSalesLog: true,
                showInventoryLog: false,
                showInventoryReg: false,
                showCompetitorReports: false,
                showDailySales: true,
                showCompetitorPrices: true
            }
        });
    };

    const handleDeleteUser = async (key: string) => {
        if (confirm("هل أنت متأكد من حذف هذا المستخدم؟ سيتم حذف حسابه وكافة بياناته المرتبطة.")) {
            await remove(ref(db, `users_v2/${key}`));
            await remove(ref(db, `leave_balances/${key}`));
            await remove(ref(db, `notifications/${key}`));
        }
    };

    const handleUpdatePassword = async () => {
        if(!passModal || !newPass) return;
        await update(ref(db, `users_v2/${passModal.key}`), { password: newPass });
        alert("تم تحديث كلمة المرور");
        setPassModal(null);
        setNewPass('');
    };

    const handleUpdatePermissions = async () => {
        if (!permModal || !permModal.key) return;
        const permissions = permModal.permissions || {
            showSalesLog: false,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        };
        await update(ref(db, `users_v2/${permModal.key}`), { 
            permissions: permissions,
            canViewAllSales: !!permModal.canViewAllSales
        });
        alert("تم تحديث الصلاحيات بنجاح");
        setPermModal(null);
    };

    const handleSendNotif = async () => {
        if (!notifModal || !notifMsg) return;
        const notification: AppNotification = {
            message: notifMsg,
            sender: user.name,
            timestamp: Date.now(),
            isRead: false
        };
        await push(ref(db, `notifications/${notifModal.username}`), notification);
        alert(`تم إرسال الرسالة بنجاح إلى ${notifModal.name}`);
        setNotifModal(null);
        setNotifMsg('');
    };

    const toggleUserPerm = (key: keyof UserPermissions) => {
        if (!permModal) return;
        const currentPermissions = permModal.permissions || {
            showSalesLog: false,
            showInventoryLog: false,
            showInventoryReg: false,
            showCompetitorReports: false,
            showDailySales: true,
            showCompetitorPrices: true
        };
        setPermModal({
            ...permModal,
            permissions: {
                ...currentPermissions,
                [key]: !currentPermissions[key]
            }
        });
    };

    if (user.role !== 'admin') {
        return <div className="p-10 text-center opacity-50">عذراً، هذه الصفحة متاحة للمسؤولين فقط.</div>;
    }

    const inputClass = "w-full p-2.5 rounded-lg border border-gray-300 bg-gray-600 text-white focus:ring-2 focus:ring-blue-500 outline-none font-bold";
    const sectionClass = `p-6 rounded-2xl mb-6 bg-gray-800 border-gray-700 border text-white`;

    return (
        <div className="max-w-5xl mx-auto space-y-8 pb-20">
            <div className="flex items-center gap-3 mb-2 text-white">
                <SettingsIcon className="text-blue-600" size={32} />
