                        </div>
                        <button 
                            onClick={handleUpdateBalance}
                            className="w-full mt-6 bg-blue-600 text-white py-4 rounded-2xl font-bold shadow-xl flex items-center justify-center gap-2 active:scale-95 transition"
                        >
